CREATE OR REPLACE FUNCTION "public"."CRM_AcceptCallActionCandidate"("p_candidate_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_candidate record;
  v_review record;
  v_task_id uuid;
BEGIN
  SELECT * INTO v_candidate
  FROM public."CRM_CallActionCandidates"
  WHERE "CRMCallAction_ID" = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Call action candidate % was not found.', p_candidate_id;
  END IF;

  SELECT * INTO v_review
  FROM public."CRM_CallReviews"
  WHERE "CRMCallReview_ID" = v_candidate."CRMCallAction_CallReviewID";

  INSERT INTO public."Workflow_Tasks" (
    "WorkflowTask_Title",
    "WorkflowTask_Description",
    "WorkflowTask_TypeCode",
    "WorkflowTask_StatusCode",
    "WorkflowTask_PriorityCode",
    "WorkflowTask_RecordTypeCode",
    "WorkflowTask_RecordID",
    "WorkflowTask_AssignedUserID",
    "WorkflowTask_DueAt",
    "WorkflowTask_IsSystemGenerated",
    "WorkflowTask_ContextJSON",
    "WorkflowTask_CreatedBy"
  )
  VALUES (
    v_candidate."CRMCallAction_Title",
    v_candidate."CRMCallAction_Description",
    'customer_update',
    'ready',
    'normal',
    'crm_call_review',
    v_candidate."CRMCallAction_CallReviewID",
    COALESCE(v_candidate."CRMCallAction_SuggestedOwnerUserID", v_review."CRMCallReview_OwnerUserID", p_user_id),
    v_candidate."CRMCallAction_SuggestedDueAt",
    true,
    jsonb_build_object('source', 'CRM_CallActionCandidates', 'candidate_id', p_candidate_id),
    p_user_id
  )
  RETURNING "WorkflowTask_ID" INTO v_task_id;

  UPDATE public."CRM_CallActionCandidates"
  SET "CRMCallAction_DecisionStatus" = 'accepted',
      "CRMCallAction_WorkflowTaskID" = v_task_id,
      "CRMCallAction_DecidedAt" = now(),
      "CRMCallAction_DecidedBy" = p_user_id
  WHERE "CRMCallAction_ID" = p_candidate_id;

  INSERT INTO public."CRM_CallReviewDecisions" (
    "CRMCallDecision_CallReviewID",
    "CRMCallDecision_ActionCandidateID",
    "CRMCallDecision_Decision",
    "CRMCallDecision_OriginalText",
    "CRMCallDecision_DecidedBy"
  )
  VALUES (
    v_candidate."CRMCallAction_CallReviewID",
    p_candidate_id,
    'accepted',
    v_candidate."CRMCallAction_Description",
    p_user_id
  );

  RETURN v_task_id;
END;
$$;


ALTER FUNCTION "public"."CRM_AcceptCallActionCandidate"("p_candidate_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_ApplyFieldUpdate"("p_field_update_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_force" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
  v_update record;
  v_cast_type text;
  v_old_value text;
  v_row_count integer;
  v_sql text;
BEGIN
  SELECT *
  INTO v_update
  FROM public."CRM_FieldUpdateQueue"
  WHERE "CRMFieldUpdate_ID" = p_field_update_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CRM field update % was not found.', p_field_update_id;
  END IF;

  IF NOT p_force AND v_update."CRMFieldUpdate_StatusCode" NOT IN ('ready', 'approved', 'needs_review', 'pending') THEN
    RAISE EXCEPTION 'CRM field update % is not in an applyable status (%).', p_field_update_id, v_update."CRMFieldUpdate_StatusCode";
  END IF;

  IF to_regclass(format('public.%I', v_update."CRMFieldUpdate_TargetTable")) IS NULL THEN
    RAISE EXCEPTION 'Target table public.% does not exist.', v_update."CRMFieldUpdate_TargetTable";
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = v_update."CRMFieldUpdate_TargetTable"
      AND column_name = v_update."CRMFieldUpdate_TargetPKColumn"
  ) THEN
    RAISE EXCEPTION 'Target primary key column public.%.% does not exist.', v_update."CRMFieldUpdate_TargetTable", v_update."CRMFieldUpdate_TargetPKColumn";
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = v_update."CRMFieldUpdate_TargetTable"
      AND column_name = v_update."CRMFieldUpdate_TargetColumn"
  ) THEN
    RAISE EXCEPTION 'Target update column public.%.% does not exist.', v_update."CRMFieldUpdate_TargetTable", v_update."CRMFieldUpdate_TargetColumn";
  END IF;

  SELECT COALESCE("CRMDataFieldType_PostgresCastType", 'text')
  INTO v_cast_type
  FROM public."sys_CRMDataFieldTypes"
  WHERE "CRMDataFieldType_Code" = v_update."CRMFieldUpdate_FieldTypeCode";

  EXECUTE format(
    'select %I::text from public.%I where %I = $1',
    v_update."CRMFieldUpdate_TargetColumn",
    v_update."CRMFieldUpdate_TargetTable",
    v_update."CRMFieldUpdate_TargetPKColumn"
  )
  USING v_update."CRMFieldUpdate_TargetID"
  INTO v_old_value;

  IF v_update."CRMFieldUpdate_FieldTypeCode" = 'json' THEN
    v_sql := format(
      'update public.%I set %I = $1::jsonb where %I = $2',
      v_update."CRMFieldUpdate_TargetTable",
      v_update."CRMFieldUpdate_TargetColumn",
      v_update."CRMFieldUpdate_TargetPKColumn"
    );
    EXECUTE v_sql USING v_update."CRMFieldUpdate_NewValueJSON", v_update."CRMFieldUpdate_TargetID";
  ELSE
    v_sql := format(
      'update public.%I set %I = $1::%s where %I = $2',
      v_update."CRMFieldUpdate_TargetTable",
      v_update."CRMFieldUpdate_TargetColumn",
      v_cast_type,
      v_update."CRMFieldUpdate_TargetPKColumn"
    );
    EXECUTE v_sql USING v_update."CRMFieldUpdate_NewValueText", v_update."CRMFieldUpdate_TargetID";
  END IF;

  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  IF v_row_count <> 1 THEN
    RAISE EXCEPTION 'Expected to update one row in public.% for target %, updated % rows.',
      v_update."CRMFieldUpdate_TargetTable",
      v_update."CRMFieldUpdate_TargetID",
      v_row_count;
  END IF;

  UPDATE public."CRM_FieldUpdateQueue"
  SET "CRMFieldUpdate_StatusCode" = 'applied',
      "CRMFieldUpdate_OldValueText" = v_old_value,
      "CRMFieldUpdate_AppliedAt" = now(),
      "CRMFieldUpdate_AppliedBy" = p_user_id,
      "CRMFieldUpdate_ErrorMessage" = NULL
  WHERE "CRMFieldUpdate_ID" = p_field_update_id;

  INSERT INTO public."CRM_FieldUpdateAudit" (
    "CRMFieldAudit_FieldUpdateID",
    "CRMFieldAudit_Action",
    "CRMFieldAudit_FromStatusCode",
    "CRMFieldAudit_ToStatusCode",
    "CRMFieldAudit_OldValueText",
    "CRMFieldAudit_NewValueText",
    "CRMFieldAudit_CreatedBy"
  )
  VALUES (
    p_field_update_id,
    'applied',
    v_update."CRMFieldUpdate_StatusCode",
    'applied',
    v_old_value,
    v_update."CRMFieldUpdate_NewValueText",
    p_user_id
  );

  RETURN true;
EXCEPTION WHEN OTHERS THEN
  UPDATE public."CRM_FieldUpdateQueue"
  SET "CRMFieldUpdate_StatusCode" = 'failed',
      "CRMFieldUpdate_ErrorMessage" = SQLERRM
  WHERE "CRMFieldUpdate_ID" = p_field_update_id;
  RAISE;
END;
$_$;


ALTER FUNCTION "public"."CRM_ApplyFieldUpdate"("p_field_update_id" "uuid", "p_user_id" "uuid", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_ApprovePersonalMessageDraft"("p_draft_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_recipient_address" character varying DEFAULT NULL::character varying, "p_queue_for_sending" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_draft record;
  v_send_id uuid;
  v_status varchar(40);
BEGIN
  SELECT *
  INTO v_draft
  FROM public."CRM_PersonalMessageDrafts"
  WHERE "CRMPMsg_ID" = p_draft_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Personal message draft % was not found.', p_draft_id;
  END IF;

  v_status := CASE WHEN p_queue_for_sending THEN 'queued' ELSE 'draft' END;

  INSERT INTO public."Comm_SendRequests" (
    "CommSend_ChannelCode",
    "CommSend_StatusCode",
    "CommSend_SourceTypeCode",
    "CommSend_PriorityCode",
    "CommSend_SensitivityCode",
    "CommSend_RequestedBy",
    "CommSend_ApprovedBy",
    "CommSend_ApprovedAt",
    "CommSend_Subject",
    "CommSend_BodyText",
    "CommSend_BodyHTML",
    "CommSend_PayloadJSON"
  )
  VALUES (
    v_draft."CRMPMsg_ChannelCode",
    v_status,
    'ai',
    'normal',
    'public',
    COALESCE(p_user_id, v_draft."CRMPMsg_AssignedUserID"),
    CASE WHEN p_queue_for_sending THEN COALESCE(p_user_id, v_draft."CRMPMsg_AssignedUserID") ELSE NULL END,
    CASE WHEN p_queue_for_sending THEN now() ELSE NULL END,
    v_draft."CRMPMsg_Subject",
    v_draft."CRMPMsg_BodyText",
    v_draft."CRMPMsg_BodyHTML",
    jsonb_build_object('source', 'CRM_PersonalMessageDrafts', 'draft_id', p_draft_id, 'intent', v_draft."CRMPMsg_MessageIntentCode")
  )
  RETURNING "CommSend_ID" INTO v_send_id;

  IF p_recipient_address IS NOT NULL THEN
    INSERT INTO public."Comm_SendRequestRecipients" (
      "CommSendRecipient_SendID",
      "CommSendRecipient_RecipientTypeCode",
      "CommSendRecipient_ChannelCode",
      "CommSendRecipient_Address",
      "CommSendRecipient_NormalizedAddress",
      "CommSendRecipient_OrgID",
      "CommSendRecipient_ContactID"
    )
    VALUES (
      v_send_id,
      'to',
      v_draft."CRMPMsg_ChannelCode",
      p_recipient_address,
      lower(p_recipient_address),
      v_draft."CRMPMsg_CustomerOrgID",
      v_draft."CRMPMsg_ContactID"
    );
  END IF;

  UPDATE public."CRM_PersonalMessageDrafts"
  SET "CRMPMsg_CommSendID" = v_send_id,
      "CRMPMsg_DecisionStatusCode" = CASE WHEN p_queue_for_sending THEN 'sent' ELSE 'accepted' END,
      "CRMPMsg_IsApprovedForSend" = p_queue_for_sending,
      "CRMPMsg_DecidedAt" = now(),
      "CRMPMsg_DecidedBy" = p_user_id,
      "CRMPMsg_UpdatedAt" = now(),
      "CRMPMsg_UpdatedBy" = p_user_id
  WHERE "CRMPMsg_ID" = p_draft_id;

  UPDATE public."CRM_MessageVariationHistory"
  SET "CRMPVar_CommSendID" = v_send_id,
      "CRMPVar_WasSent" = p_queue_for_sending,
      "CRMPVar_SentAt" = CASE WHEN p_queue_for_sending THEN now() ELSE NULL END
  WHERE "CRMPVar_MessageDraftID" = p_draft_id;

  RETURN v_send_id;
END;
$$;


ALTER FUNCTION "public"."CRM_ApprovePersonalMessageDraft"("p_draft_id" "uuid", "p_user_id" "uuid", "p_recipient_address" character varying, "p_queue_for_sending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_ConvertLeadToOpportunity"("p_lead_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_lead record;
  v_org_id uuid;
  v_account_id uuid;
  v_opportunity_id uuid;
  v_name varchar(240);
BEGIN
  SELECT * INTO v_lead
  FROM public."CRM_Leads"
  WHERE "CRMLead_ID" = p_lead_id
    AND "CRMLead_IsDeleted" = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead % was not found.', p_lead_id;
  END IF;

  v_org_id := v_lead."CRMLead_OrgID";
  v_name := COALESCE(NULLIF(v_lead."CRMLead_CompanyName", ''), NULLIF(v_lead."CRMLead_PersonName", ''), 'Converted CRM lead');

  IF v_org_id IS NULL THEN
    INSERT INTO public."Org_Master" (
      "Org_Name",
      "Org_CRMRelationshipStatusCode",
      "Org_CRMIsLead",
      "Org_CRMIsPotentialCustomer"
    )
    VALUES (v_name, 'prospect', true, true)
    RETURNING "Org_ID" INTO v_org_id;

    UPDATE public."CRM_Leads"
    SET "CRMLead_OrgID" = v_org_id,
        "CRMLead_UpdatedAt" = now(),
        "CRMLead_UpdatedBy" = p_user_id
    WHERE "CRMLead_ID" = p_lead_id;
  ELSE
    UPDATE public."Org_Master"
    SET "Org_CRMRelationshipStatusCode" = COALESCE("Org_CRMRelationshipStatusCode", 'prospect'),
        "Org_CRMIsLead" = true,
        "Org_CRMIsPotentialCustomer" = true,
        "Org_CRMUpdatedAt" = now()
    WHERE "Org_ID" = v_org_id;
  END IF;

  INSERT INTO public."CRM_AccountProfiles" (
    "CRMAccount_OrgID",
    "CRMAccount_RelationshipStatusCode",
    "CRMAccount_OwnerUserID",
    "CRMAccount_OrgOfficeID",
    "CRMAccount_LegalEntityID",
    "CRMAccount_BrandID",
    "CRMAccount_PrimaryModeCode",
    "CRMAccount_PrimaryTradeLane",
    "CRMAccount_CustomerCentricSummary",
    "CRMAccount_CreatedBy"
  )
  VALUES (
    v_org_id,
    'prospect',
    COALESCE(v_lead."CRMLead_OwnerUserID", p_user_id),
    v_lead."CRMLead_OrgOfficeID",
    v_lead."CRMLead_LegalEntityID",
    v_lead."CRMLead_BrandID",
    v_lead."CRMLead_ModeCode",
    v_lead."CRMLead_TradeLane",
    v_lead."CRMLead_CustomerCentricNeed",
    p_user_id
  )
  ON CONFLICT ("CRMAccount_OrgID") DO UPDATE
  SET "CRMAccount_RelationshipStatusCode" = excluded."CRMAccount_RelationshipStatusCode",
      "CRMAccount_OwnerUserID" = COALESCE(public."CRM_AccountProfiles"."CRMAccount_OwnerUserID", excluded."CRMAccount_OwnerUserID"),
      "CRMAccount_UpdatedAt" = now(),
      "CRMAccount_UpdatedBy" = p_user_id
  RETURNING "CRMAccount_ID" INTO v_account_id;

  INSERT INTO public."CRM_OrgLifecycleTags" (
    "CRMOrgLifeTag_OrgID",
    "CRMOrgLifeTag_TagCode",
    "CRMOrgLifeTag_SourceTable",
    "CRMOrgLifeTag_SourceID",
    "CRMOrgLifeTag_CreatedBy"
  )
  VALUES
    (v_org_id, 'potential_customer', 'CRM_Leads', p_lead_id, p_user_id),
    (v_org_id, 'prospect', 'CRM_Leads', p_lead_id, p_user_id)
  ON CONFLICT ("CRMOrgLifeTag_OrgID", "CRMOrgLifeTag_TagCode") DO UPDATE
  SET "CRMOrgLifeTag_IsActive" = true;

  INSERT INTO public."CRM_Opportunities" (
    "CRMOppty_AccountID",
    "CRMOppty_OrgID",
    "CRMOppty_PrimaryContactID",
    "CRMOppty_SourceLeadID",
    "CRMOppty_OwnerUserID",
    "CRMOppty_OrgOfficeID",
    "CRMOppty_LegalEntityID",
    "CRMOppty_BrandID",
    "CRMOppty_Name",
    "CRMOppty_ModeCode",
    "CRMOppty_DirectionCode",
    "CRMOppty_TradeLane",
    "CRMOppty_ServiceInterest",
    "CRMOppty_ExpectedValueAmount",
    "CRMOppty_CurrencyCode",
    "CRMOppty_CustomerNeed",
    "CRMOppty_CreatedBy"
  )
  VALUES (
    v_account_id,
    v_org_id,
    v_lead."CRMLead_PrimaryContactID",
    p_lead_id,
    COALESCE(v_lead."CRMLead_OwnerUserID", p_user_id),
    v_lead."CRMLead_OrgOfficeID",
    v_lead."CRMLead_LegalEntityID",
    v_lead."CRMLead_BrandID",
    v_name || ' opportunity',
    v_lead."CRMLead_ModeCode",
    v_lead."CRMLead_DirectionCode",
    v_lead."CRMLead_TradeLane",
    v_lead."CRMLead_ServiceInterest",
    v_lead."CRMLead_EstimatedValueAmount",
    v_lead."CRMLead_EstimatedValueCurrencyCode",
    v_lead."CRMLead_CustomerCentricNeed",
    p_user_id
  )
  RETURNING "CRMOppty_ID" INTO v_opportunity_id;

  UPDATE public."CRM_Leads"
  SET "CRMLead_StatusCode" = 'converted',
      "CRMLead_UpdatedAt" = now(),
      "CRMLead_UpdatedBy" = p_user_id
  WHERE "CRMLead_ID" = p_lead_id;

  INSERT INTO public."CRM_LeadStatusHistory" (
    "CRMLeadStatus_LeadID",
    "CRMLeadStatus_ToStatusCode",
    "CRMLeadStatus_Reason",
    "CRMLeadStatus_ChangedBy"
  )
  VALUES (p_lead_id, 'converted', 'Converted to opportunity.', p_user_id);

  INSERT INTO public."CRM_LeadConversions" (
    "CRMLeadConv_LeadID",
    "CRMLeadConv_OrgID",
    "CRMLeadConv_AccountID",
    "CRMLeadConv_OpportunityID",
    "CRMLeadConv_ConvertedBy"
  )
  VALUES (p_lead_id, v_org_id, v_account_id, v_opportunity_id, p_user_id);

  RETURN v_opportunity_id;
END;
$$;


ALTER FUNCTION "public"."CRM_ConvertLeadToOpportunity"("p_lead_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateDataCaptureSession"("p_run_id" "uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_method_code" character varying DEFAULT 'wizard'::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_session_id uuid;
BEGIN
  INSERT INTO public."CRM_DataCaptureSessions" (
    "CRMDataCapSession_RunID",
    "CRMDataCapSession_MethodCode",
    "CRMDataCapSession_StatusCode",
    "CRMDataCapSession_AssignedUserID"
  )
  VALUES (p_run_id, p_method_code, 'ready', p_assigned_user_id)
  RETURNING "CRMDataCapSession_ID" INTO v_session_id;

  RETURN v_session_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateDataCaptureSession"("p_run_id" "uuid", "p_assigned_user_id" "uuid", "p_method_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateDataRequestFromRun"("p_run_id" "uuid", "p_request_text" "text", "p_channel_code" character varying DEFAULT 'email'::character varying, "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_run record;
  v_request_id uuid;
BEGIN
  SELECT *
  INTO v_run
  FROM public."CRM_AutomationRuns"
  WHERE "CRMAutoRun_ID" = p_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Automation run % was not found.', p_run_id;
  END IF;

  INSERT INTO public."CRM_DataRequests" (
    "CRMDataReq_RunID",
    "CRMDataReq_StatusCode",
    "CRMDataReq_MethodCode",
    "CRMDataReq_ChannelCode",
    "CRMDataReq_CustomerOrgID",
    "CRMDataReq_AssignedUserID",
    "CRMDataReq_RequestText",
    "CRMDataReq_DueAt",
    "CRMDataReq_CreatedBy"
  )
  VALUES (
    p_run_id,
    'draft',
    CASE
      WHEN p_channel_code = 'whatsapp' THEN 'whatsapp_reply'
      WHEN p_channel_code = 'sms' THEN 'sms_reply'
      ELSE 'email_reply'
    END,
    p_channel_code,
    v_run."CRMAutoRun_CustomerOrgID",
    COALESCE(p_assigned_user_id, v_run."CRMAutoRun_AssignedUserID"),
    p_request_text,
    p_due_at,
    p_created_by
  )
  RETURNING "CRMDataReq_ID" INTO v_request_id;

  INSERT INTO public."CRM_DataRequestFields" (
    "CRMDataReqField_RequestID",
    "CRMDataReqField_FieldDefID",
    "CRMDataReqField_TargetTable",
    "CRMDataReqField_TargetPKColumn",
    "CRMDataReqField_TargetColumn",
    "CRMDataReqField_TargetID",
    "CRMDataReqField_QuestionText",
    "CRMDataReqField_IsRequired",
    "CRMDataReqField_SortOrder"
  )
  SELECT
    v_request_id,
    field."CRMAutoField_ID",
    field."CRMAutoField_TargetTable",
    field."CRMAutoField_TargetPKColumn",
    field."CRMAutoField_TargetColumn",
    v_run."CRMAutoRun_TargetID",
    field."CRMAutoField_QuestionText",
    field."CRMAutoField_IsRequired",
    field."CRMAutoField_SortOrder"
  FROM public."CRM_AutomationFieldDefinitions" field
  WHERE field."CRMAutoField_PlaybookID" = v_run."CRMAutoRun_PlaybookID"
    AND field."CRMAutoField_IsActive" = true
  ORDER BY field."CRMAutoField_SortOrder";

  UPDATE public."CRM_AutomationRuns"
  SET "CRMAutoRun_StatusCode" = 'waiting_reply'
  WHERE "CRMAutoRun_ID" = p_run_id;

  RETURN v_request_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateDataRequestFromRun"("p_run_id" "uuid", "p_request_text" "text", "p_channel_code" character varying, "p_assigned_user_id" "uuid", "p_due_at" timestamp with time zone, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreatePersonalMessageDraft"("p_run_id" "uuid", "p_quick_task_id" "uuid", "p_intent_code" character varying, "p_channel_code" character varying, "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_subject" character varying DEFAULT NULL::character varying, "p_body_text" "text" DEFAULT NULL::"text", "p_personalisation_prompt" "text" DEFAULT NULL::"text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_draft_id uuid;
  v_hash varchar(64);
BEGIN
  v_hash := encode(digest(coalesce(p_body_text, ''), 'sha256'), 'hex');

  INSERT INTO public."CRM_PersonalMessageDrafts" (
    "CRMPMsg_RunID",
    "CRMPMsg_QuickTaskID",
    "CRMPMsg_MessageIntentCode",
    "CRMPMsg_ChannelCode",
    "CRMPMsg_PersonalisationModeCode",
    "CRMPMsg_CustomerOrgID",
    "CRMPMsg_ContactID",
    "CRMPMsg_AssignedUserID",
    "CRMPMsg_Subject",
    "CRMPMsg_BodyText",
    "CRMPMsg_PersonalisationPrompt",
    "CRMPMsg_PersonalisationEvidenceJSON",
    "CRMPMsg_BodyHashSHA256",
    "CRMPMsg_IsTemplateBased",
    "CRMPMsg_CreatedBy"
  )
  VALUES (
    p_run_id,
    p_quick_task_id,
    p_intent_code,
    p_channel_code,
    'ai_personal',
    p_customer_org_id,
    p_contact_id,
    p_assigned_user_id,
    p_subject,
    p_body_text,
    p_personalisation_prompt,
    COALESCE(p_evidence_json, '{}'::jsonb),
    v_hash,
    false,
    p_created_by
  )
  RETURNING "CRMPMsg_ID" INTO v_draft_id;

  INSERT INTO public."CRM_MessageVariationHistory" (
    "CRMPVar_MessageDraftID",
    "CRMPVar_CustomerOrgID",
    "CRMPVar_UserID",
    "CRMPVar_MessageIntentCode",
    "CRMPVar_ChannelCode",
    "CRMPVar_BodyHashSHA256",
    "CRMPVar_BodyPreview",
    "CRMPVar_WasSent"
  )
  VALUES (
    v_draft_id,
    p_customer_org_id,
    p_assigned_user_id,
    p_intent_code,
    p_channel_code,
    v_hash,
    left(coalesce(p_body_text, ''), 1000),
    false
  );

  RETURN v_draft_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreatePersonalMessageDraft"("p_run_id" "uuid", "p_quick_task_id" "uuid", "p_intent_code" character varying, "p_channel_code" character varying, "p_assigned_user_id" "uuid", "p_customer_org_id" "uuid", "p_contact_id" "uuid", "p_subject" character varying, "p_body_text" "text", "p_personalisation_prompt" "text", "p_evidence_json" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateQuickTask"("p_task_type_code" character varying, "p_title" character varying, "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_description" "text" DEFAULT NULL::"text", "p_priority_code" character varying DEFAULT 'normal'::character varying, "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_run_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_quote_followup_id" "uuid" DEFAULT NULL::"uuid", "p_call_review_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_action_target_table" character varying DEFAULT NULL::character varying, "p_action_target_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_quick_task_id uuid;
  v_workflow_task_id uuid;
  v_workflow_task_type varchar(60);
BEGIN
  SELECT COALESCE("CRMQuickTaskType_DefaultWorkflowTaskTypeCode", 'general_task')
  INTO v_workflow_task_type
  FROM public."sys_CRMQuickTaskTypes"
  WHERE "CRMQuickTaskType_Code" = p_task_type_code;

  INSERT INTO public."CRM_QuickTasks" (
    "CRMQuickTask_RunID",
    "CRMQuickTask_TaskTypeCode",
    "CRMQuickTask_AccountID",
    "CRMQuickTask_LeadID",
    "CRMQuickTask_OpportunityID",
    "CRMQuickTask_QuoteFollowupID",
    "CRMQuickTask_CallReviewID",
    "CRMQuickTask_JobID",
    "CRMQuickTask_CustomerOrgID",
    "CRMQuickTask_AssignedUserID",
    "CRMQuickTask_Title",
    "CRMQuickTask_Description",
    "CRMQuickTask_PriorityCode",
    "CRMQuickTask_DueAt",
    "CRMQuickTask_ActionTargetTable",
    "CRMQuickTask_ActionTargetID",
    "CRMQuickTask_CreatedBy"
  )
  VALUES (
    p_run_id,
    p_task_type_code,
    p_account_id,
    p_lead_id,
    p_opportunity_id,
    p_quote_followup_id,
    p_call_review_id,
    p_job_id,
    p_customer_org_id,
    p_assigned_user_id,
    p_title,
    p_description,
    COALESCE(p_priority_code, 'normal'),
    p_due_at,
    p_action_target_table,
    p_action_target_id,
    p_created_by
  )
  RETURNING "CRMQuickTask_ID" INTO v_quick_task_id;

  INSERT INTO public."Workflow_Tasks" (
    "WorkflowTask_Title",
    "WorkflowTask_Description",
    "WorkflowTask_TypeCode",
    "WorkflowTask_StatusCode",
    "WorkflowTask_PriorityCode",
    "WorkflowTask_RecordTypeCode",
    "WorkflowTask_RecordID",
    "WorkflowTask_AssignedUserID",
    "WorkflowTask_DueAt",
    "WorkflowTask_IsSystemGenerated",
    "WorkflowTask_SourceTriggerTypeCode",
    "WorkflowTask_ContextJSON",
    "WorkflowTask_CreatedBy"
  )
  VALUES (
    p_title,
    p_description,
    COALESCE(v_workflow_task_type, 'general_task'),
    'ready',
    COALESCE(p_priority_code, 'normal'),
    'crm_quick_task',
    v_quick_task_id,
    p_assigned_user_id,
    p_due_at,
    true,
    'crm_activity',
    jsonb_build_object(
      'run_id', p_run_id,
      'task_type', p_task_type_code,
      'action_target_table', p_action_target_table,
      'action_target_id', p_action_target_id
    ),
    p_created_by
  )
  RETURNING "WorkflowTask_ID" INTO v_workflow_task_id;

  UPDATE public."CRM_QuickTasks"
  SET "CRMQuickTask_WorkflowTaskID" = v_workflow_task_id
  WHERE "CRMQuickTask_ID" = v_quick_task_id;

  RETURN v_quick_task_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateQuickTask"("p_task_type_code" character varying, "p_title" character varying, "p_assigned_user_id" "uuid", "p_description" "text", "p_priority_code" character varying, "p_due_at" timestamp with time zone, "p_run_id" "uuid", "p_account_id" "uuid", "p_lead_id" "uuid", "p_opportunity_id" "uuid", "p_quote_followup_id" "uuid", "p_call_review_id" "uuid", "p_job_id" "uuid", "p_customer_org_id" "uuid", "p_action_target_table" character varying, "p_action_target_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateQuoteFollowup"("p_cusquote_header_id" "uuid", "p_cusquote_rev_id" "uuid" DEFAULT NULL::"uuid", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_followup_id uuid;
  v_customer_org_id uuid;
  v_customer_contact_id uuid;
  v_due_at timestamptz;
BEGIN
  SELECT
    "CusQuoteHeader_CustomerID",
    "CusQuoteHeader_CustomerContact",
    COALESCE("CusQuoteHeader_Deadline"::timestamptz, now() + interval '24 hours')
  INTO v_customer_org_id, v_customer_contact_id, v_due_at
  FROM public."CusQuote_Header"
  WHERE "CusQuoteHeader_ID" = p_cusquote_header_id;

  IF v_customer_org_id IS NULL THEN
    RAISE EXCEPTION 'Quote header % was not found or has no customer.', p_cusquote_header_id;
  END IF;

  INSERT INTO public."CRM_QuoteFollowups" (
    "CRMQF_CusQuoteHeaderID",
    "CRMQF_CusQuoteRevID",
    "CRMQF_CustomerOrgID",
    "CRMQF_CustomerContactID",
    "CRMQF_OwnerUserID",
    "CRMQF_StatusCode",
    "CRMQF_NextActionDueAt",
    "CRMQF_CreatedBy"
  )
  VALUES (
    p_cusquote_header_id,
    p_cusquote_rev_id,
    v_customer_org_id,
    v_customer_contact_id,
    p_owner_user_id,
    'pending',
    v_due_at,
    p_owner_user_id
  )
  RETURNING "CRMQF_ID" INTO v_followup_id;

  RETURN v_followup_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateQuoteFollowup"("p_cusquote_header_id" "uuid", "p_cusquote_rev_id" "uuid", "p_owner_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_LinkQuoteToOpportunity"("p_opportunity_id" "uuid", "p_quote_header_id" "uuid", "p_quote_rev_id" "uuid" DEFAULT NULL::"uuid", "p_cost_revenue_link_id" "uuid" DEFAULT NULL::"uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_link_id uuid;
  v_cost_opt_id uuid;
  v_revenue_opt_id uuid;
BEGIN
  IF p_cost_revenue_link_id IS NOT NULL THEN
    SELECT "CQCRL_CostOptID", "CQCRL_RevenueOptID"
    INTO v_cost_opt_id, v_revenue_opt_id
    FROM public."CusQuote_CostRevenueLinks"
    WHERE "CQCRL_ID" = p_cost_revenue_link_id;
  END IF;

  INSERT INTO public."CRM_OpportunityQuoteLinks" (
    "CRMOpptyQuote_OpportunityID",
    "CRMOpptyQuote_CusQuoteHeaderID",
    "CRMOpptyQuote_CusQuoteRevID",
    "CRMOpptyQuote_CostOptID",
    "CRMOpptyQuote_RevenueOptID",
    "CRMOpptyQuote_CostRevenueLinkID",
    "CRMOpptyQuote_LinkedBy"
  )
  VALUES (
    p_opportunity_id,
    p_quote_header_id,
    p_quote_rev_id,
    v_cost_opt_id,
    v_revenue_opt_id,
    p_cost_revenue_link_id,
    p_user_id
  )
  RETURNING "CRMOpptyQuote_ID" INTO v_link_id;

  RETURN v_link_id;
END;
$$;


ALTER FUNCTION "public"."CRM_LinkQuoteToOpportunity"("p_opportunity_id" "uuid", "p_quote_header_id" "uuid", "p_quote_rev_id" "uuid", "p_cost_revenue_link_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_QueueFieldUpdate"("p_run_id" "uuid", "p_field_def_id" "uuid", "p_target_id" "uuid", "p_value_text" "text" DEFAULT NULL::"text", "p_value_json" "jsonb" DEFAULT NULL::"jsonb", "p_confidence_score" numeric DEFAULT NULL::numeric, "p_reason" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_data_request_id" "uuid" DEFAULT NULL::"uuid", "p_data_request_field_id" "uuid" DEFAULT NULL::"uuid", "p_capture_response_id" "uuid" DEFAULT NULL::"uuid", "p_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_field record;
  v_update_id uuid;
  v_status varchar(60);
BEGIN
  SELECT *
  INTO v_field
  FROM public."CRM_AutomationFieldDefinitions"
  WHERE "CRMAutoField_ID" = p_field_def_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Automation field definition % was not found.', p_field_def_id;
  END IF;

  v_status := CASE WHEN v_field."CRMAutoField_AutoApplyAllowed" THEN 'ready' ELSE 'needs_review' END;

  INSERT INTO public."CRM_FieldUpdateQueue" (
    "CRMFieldUpdate_RunID",
    "CRMFieldUpdate_DataRequestID",
    "CRMFieldUpdate_DataRequestFieldID",
    "CRMFieldUpdate_CaptureResponseID",
    "CRMFieldUpdate_ResponseID",
    "CRMFieldUpdate_FieldDefID",
    "CRMFieldUpdate_StatusCode",
    "CRMFieldUpdate_TargetRecordTypeCode",
    "CRMFieldUpdate_TargetTable",
    "CRMFieldUpdate_TargetPKColumn",
    "CRMFieldUpdate_TargetColumn",
    "CRMFieldUpdate_TargetID",
    "CRMFieldUpdate_FieldTypeCode",
    "CRMFieldUpdate_NewValueText",
    "CRMFieldUpdate_NewValueJSON",
    "CRMFieldUpdate_ConfidenceScore",
    "CRMFieldUpdate_RequiresApproval",
    "CRMFieldUpdate_Reason",
    "CRMFieldUpdate_CreatedBy"
  )
  VALUES (
    p_run_id,
    p_data_request_id,
    p_data_request_field_id,
    p_capture_response_id,
    p_response_id,
    p_field_def_id,
    v_status,
    v_field."CRMAutoField_TargetRecordTypeCode",
    v_field."CRMAutoField_TargetTable",
    v_field."CRMAutoField_TargetPKColumn",
    v_field."CRMAutoField_TargetColumn",
    p_target_id,
    v_field."CRMAutoField_FieldTypeCode",
    p_value_text,
    p_value_json,
    p_confidence_score,
    NOT v_field."CRMAutoField_AutoApplyAllowed",
    p_reason,
    p_created_by
  )
  RETURNING "CRMFieldUpdate_ID" INTO v_update_id;

  RETURN v_update_id;
END;
$$;


ALTER FUNCTION "public"."CRM_QueueFieldUpdate"("p_run_id" "uuid", "p_field_def_id" "uuid", "p_target_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_confidence_score" numeric, "p_reason" "text", "p_created_by" "uuid", "p_data_request_id" "uuid", "p_data_request_field_id" "uuid", "p_capture_response_id" "uuid", "p_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordActivity"("p_activity_type_code" character varying, "p_subject" character varying, "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_quote_followup_id" "uuid" DEFAULT NULL::"uuid", "p_summary" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_activity_id uuid;
BEGIN
  INSERT INTO public."CRM_Activities" (
    "CRMActivity_ActivityTypeCode",
    "CRMActivity_AccountID",
    "CRMActivity_LeadID",
    "CRMActivity_OpportunityID",
    "CRMActivity_QuoteFollowupID",
    "CRMActivity_Subject",
    "CRMActivity_Summary",
    "CRMActivity_OwnerUserID",
    "CRMActivity_CreatedBy"
  )
  VALUES (
    p_activity_type_code,
    p_account_id,
    p_lead_id,
    p_opportunity_id,
    p_quote_followup_id,
    p_subject,
    p_summary,
    p_user_id,
    p_user_id
  )
  RETURNING "CRMActivity_ID" INTO v_activity_id;

  IF p_lead_id IS NOT NULL THEN
    UPDATE public."CRM_Leads"
    SET "CRMLead_LastInteractionAt" = now(),
        "CRMLead_UpdatedAt" = now(),
        "CRMLead_UpdatedBy" = p_user_id
    WHERE "CRMLead_ID" = p_lead_id;
  END IF;

  IF p_opportunity_id IS NOT NULL THEN
    UPDATE public."CRM_Opportunities"
    SET "CRMOppty_LastActivityAt" = now(),
        "CRMOppty_UpdatedAt" = now(),
        "CRMOppty_UpdatedBy" = p_user_id
    WHERE "CRMOppty_ID" = p_opportunity_id;
  END IF;

  RETURN v_activity_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordActivity"("p_activity_type_code" character varying, "p_subject" character varying, "p_account_id" "uuid", "p_lead_id" "uuid", "p_opportunity_id" "uuid", "p_quote_followup_id" "uuid", "p_summary" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordDataRequestFieldValue"("p_request_field_id" "uuid", "p_value_text" "text" DEFAULT NULL::"text", "p_value_json" "jsonb" DEFAULT NULL::"jsonb", "p_method_code" character varying DEFAULT 'email_reply'::character varying, "p_raw_text" "text" DEFAULT NULL::"text", "p_confidence_score" numeric DEFAULT NULL::numeric, "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_field record;
  v_request record;
  v_response_id uuid;
  v_update_id uuid;
BEGIN
  SELECT rf.*, fd."CRMAutoField_ID"
  INTO v_field
  FROM public."CRM_DataRequestFields" rf
  JOIN public."CRM_AutomationFieldDefinitions" fd ON fd."CRMAutoField_ID" = rf."CRMDataReqField_FieldDefID"
  WHERE rf."CRMDataReqField_ID" = p_request_field_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Data request field % was not found.', p_request_field_id;
  END IF;

  SELECT *
  INTO v_request
  FROM public."CRM_DataRequests"
  WHERE "CRMDataReq_ID" = v_field."CRMDataReqField_RequestID";

  INSERT INTO public."CRM_DataRequestResponses" (
    "CRMDataReqResp_RequestID",
    "CRMDataReqResp_MethodCode",
    "CRMDataReqResp_RawText",
    "CRMDataReqResp_RawJSON",
    "CRMDataReqResp_ConfidenceScore",
    "CRMDataReqResp_CreatedBy"
  )
  VALUES (
    v_request."CRMDataReq_ID",
    p_method_code,
    p_raw_text,
    jsonb_build_object('field_id', p_request_field_id, 'value_text', p_value_text, 'value_json', p_value_json),
    p_confidence_score,
    p_user_id
  )
  RETURNING "CRMDataReqResp_ID" INTO v_response_id;

  v_update_id := public."CRM_QueueFieldUpdate"(
    v_request."CRMDataReq_RunID",
    v_field."CRMDataReqField_FieldDefID",
    v_field."CRMDataReqField_TargetID",
    p_value_text,
    p_value_json,
    p_confidence_score,
    'Captured from data request response.',
    p_user_id,
    v_request."CRMDataReq_ID",
    p_request_field_id,
    NULL,
    v_response_id
  );

  UPDATE public."CRM_DataRequestFields"
  SET "CRMDataReqField_StatusCode" = 'received',
      "CRMDataReqField_ResponseValueText" = p_value_text,
      "CRMDataReqField_ResponseValueJSON" = p_value_json,
      "CRMDataReqField_FieldUpdateID" = v_update_id,
      "CRMDataReqField_ReceivedAt" = now()
  WHERE "CRMDataReqField_ID" = p_request_field_id;

  UPDATE public."CRM_DataRequests"
  SET "CRMDataReq_StatusCode" = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public."CRM_DataRequestFields" f
          WHERE f."CRMDataReqField_RequestID" = v_request."CRMDataReq_ID"
            AND f."CRMDataReqField_StatusCode" <> 'received'
        ) THEN 'partially_received'
        ELSE 'received'
      END,
      "CRMDataReq_ReceivedAt" = now()
  WHERE "CRMDataReq_ID" = v_request."CRMDataReq_ID";

  RETURN v_update_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordDataRequestFieldValue"("p_request_field_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_method_code" character varying, "p_raw_text" "text", "p_confidence_score" numeric, "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordQuickTaskDecision"("p_quick_task_id" "uuid", "p_decision_status_code" character varying, "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_option_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_snoozed_until" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_decision_id uuid;
  v_task_status varchar(60);
BEGIN
  v_task_status := CASE
    WHEN p_decision_status_code IN ('accepted', 'edited', 'sent') THEN 'completed'
    WHEN p_decision_status_code = 'ignored' THEN 'ignored'
    WHEN p_decision_status_code = 'snoozed' THEN 'snoozed'
    WHEN p_decision_status_code = 'rejected' THEN 'cancelled'
    ELSE 'pending'
  END;

  INSERT INTO public."CRM_QuickTaskDecisions" (
    "CRMQuickDecision_QuickTaskID",
    "CRMQuickDecision_OptionID",
    "CRMQuickDecision_DecisionStatusCode",
    "CRMQuickDecision_DecisionReason",
    "CRMQuickDecision_DecidedBy"
  )
  VALUES (
    p_quick_task_id,
    p_option_id,
    p_decision_status_code,
    p_reason,
    p_user_id
  )
  RETURNING "CRMQuickDecision_ID" INTO v_decision_id;

  UPDATE public."CRM_QuickTasks"
  SET "CRMQuickTask_StatusCode" = v_task_status,
      "CRMQuickTask_DecisionStatusCode" = p_decision_status_code,
      "CRMQuickTask_SnoozedUntil" = p_snoozed_until,
      "CRMQuickTask_UserDecisionReason" = p_reason,
      "CRMQuickTask_CompletedAt" = CASE WHEN v_task_status IN ('completed', 'ignored', 'cancelled') THEN now() ELSE "CRMQuickTask_CompletedAt" END,
      "CRMQuickTask_CompletedBy" = CASE WHEN v_task_status IN ('completed', 'ignored', 'cancelled') THEN p_user_id ELSE "CRMQuickTask_CompletedBy" END,
      "CRMQuickTask_UpdatedAt" = now(),
      "CRMQuickTask_UpdatedBy" = p_user_id
  WHERE "CRMQuickTask_ID" = p_quick_task_id;

  IF p_option_id IS NOT NULL THEN
    UPDATE public."CRM_QuickTaskOptions"
    SET "CRMQuickOpt_DecisionStatusCode" = p_decision_status_code,
        "CRMQuickOpt_DecidedAt" = now(),
        "CRMQuickOpt_DecidedBy" = p_user_id
    WHERE "CRMQuickOpt_ID" = p_option_id;
  END IF;

  RETURN v_decision_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordQuickTaskDecision"("p_quick_task_id" "uuid", "p_decision_status_code" character varying, "p_user_id" "uuid", "p_option_id" "uuid", "p_reason" "text", "p_snoozed_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordWizardFieldValue"("p_session_id" "uuid", "p_field_def_id" "uuid", "p_value_text" "text" DEFAULT NULL::"text", "p_value_json" "jsonb" DEFAULT NULL::"jsonb", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_confidence_score" numeric DEFAULT 1) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_session record;
  v_run record;
  v_response_id uuid;
  v_update_id uuid;
BEGIN
  SELECT *
  INTO v_session
  FROM public."CRM_DataCaptureSessions"
  WHERE "CRMDataCapSession_ID" = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Data capture session % was not found.', p_session_id;
  END IF;

  SELECT *
  INTO v_run
  FROM public."CRM_AutomationRuns"
  WHERE "CRMAutoRun_ID" = v_session."CRMDataCapSession_RunID";

  INSERT INTO public."CRM_DataCaptureResponses" (
    "CRMDataCapResp_SessionID",
    "CRMDataCapResp_FieldDefID",
    "CRMDataCapResp_ValueText",
    "CRMDataCapResp_ValueJSON",
    "CRMDataCapResp_ConfidenceScore",
    "CRMDataCapResp_IsConfirmed",
    "CRMDataCapResp_CapturedBy"
  )
  VALUES (
    p_session_id,
    p_field_def_id,
    p_value_text,
    p_value_json,
    p_confidence_score,
    true,
    p_user_id
  )
  RETURNING "CRMDataCapResp_ID" INTO v_response_id;

  v_update_id := public."CRM_QueueFieldUpdate"(
    v_run."CRMAutoRun_ID",
    p_field_def_id,
    v_run."CRMAutoRun_TargetID",
    p_value_text,
    p_value_json,
    p_confidence_score,
    'Captured by quick wizard.',
    p_user_id,
    NULL,
    NULL,
    v_response_id,
    NULL
  );

  UPDATE public."CRM_DataCaptureResponses"
  SET "CRMDataCapResp_FieldUpdateID" = v_update_id
  WHERE "CRMDataCapResp_ID" = v_response_id;

  UPDATE public."CRM_AutomationRuns"
  SET "CRMAutoRun_StatusCode" = 'in_review'
  WHERE "CRMAutoRun_ID" = v_run."CRMAutoRun_ID";

  RETURN v_update_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordWizardFieldValue"("p_session_id" "uuid", "p_field_def_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_user_id" "uuid", "p_confidence_score" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RegisterActivityWorkflowEvent"("p_trigger_type_code" character varying, "p_source_table" character varying, "p_source_id" "uuid", "p_activity_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_quote_followup_id" "uuid" DEFAULT NULL::"uuid", "p_call_review_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid", "p_context_json" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_rule record;
  v_run_id uuid;
  v_quick_task_id uuid;
  v_email_draft_id uuid;
  v_whatsapp_draft_id uuid;
  v_due_at timestamptz;
  v_message_count integer := 0;
  v_task_count integer := 0;
BEGIN
  SELECT *
  INTO v_rule
  FROM public."CRM_ActivityWorkflowRules"
  WHERE "CRMAWRule_TriggerTypeCode" = p_trigger_type_code
    AND "CRMAWRule_IsActive" = true
    AND ("CRMAWRule_SourceTable" IS NULL OR "CRMAWRule_SourceTable" = p_source_table)
  ORDER BY "CRMAWRule_SortOrder", "CRMAWRule_CreatedAt"
  LIMIT 1;

  v_due_at := now() + make_interval(mins => COALESCE(v_rule."CRMAWRule_DueOffsetMinutes", 0));

  INSERT INTO public."CRM_ActivityWorkflowRuns" (
    "CRMAWRun_RuleID",
    "CRMAWRun_TriggerTypeCode",
    "CRMAWRun_SourceTable",
    "CRMAWRun_SourceID",
    "CRMAWRun_ActivityID",
    "CRMAWRun_AccountID",
    "CRMAWRun_LeadID",
    "CRMAWRun_OpportunityID",
    "CRMAWRun_QuoteFollowupID",
    "CRMAWRun_CallReviewID",
    "CRMAWRun_JobID",
    "CRMAWRun_CustomerOrgID",
    "CRMAWRun_OwnerUserID",
    "CRMAWRun_ContextJSON",
    "CRMAWRun_CreatedBy"
  )
  VALUES (
    v_rule."CRMAWRule_ID",
    p_trigger_type_code,
    p_source_table,
    p_source_id,
    p_activity_id,
    p_account_id,
    p_lead_id,
    p_opportunity_id,
    p_quote_followup_id,
    p_call_review_id,
    p_job_id,
    p_customer_org_id,
    COALESCE(p_owner_user_id, v_rule."CRMAWRule_DefaultOwnerUserID"),
    COALESCE(p_context_json, '{}'::jsonb),
    p_created_by
  )
  RETURNING "CRMAWRun_ID" INTO v_run_id;

  IF p_trigger_type_code IN ('booking_created', 'booking_confirmed') THEN
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'send_personal_booking_thanks',
      'Send a personal thank-you for the booking',
      p_owner_user_id,
      'Customer has made a booking. Review the suggested note, send by the best channel, or ignore if it is not appropriate.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      p_source_table,
      p_source_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    v_email_draft_id := public."CRM_CreatePersonalMessageDraft"(
      v_run_id,
      v_quick_task_id,
      'booking_thank_you',
      'email',
      p_owner_user_id,
      p_customer_org_id,
      NULL,
      'Thank you for the booking',
      'Thanks for the booking. I will keep an eye on this and make sure you are updated as it moves.',
      'Rewrite this so it sounds personal to the customer, job, lane, mode and recent conversation. Do not reuse standard wording.',
      COALESCE(p_context_json, '{}'::jsonb),
      p_created_by
    );
    v_message_count := v_message_count + 1;

    v_whatsapp_draft_id := public."CRM_CreatePersonalMessageDraft"(
      v_run_id,
      v_quick_task_id,
      'booking_thank_you',
      'whatsapp',
      p_owner_user_id,
      p_customer_org_id,
      NULL,
      NULL,
      'Thanks for the booking. I will keep this moving and update you shortly.',
      'Rewrite as a short personal WhatsApp using the customer and job context. Do not use fixed template wording.',
      COALESCE(p_context_json, '{}'::jsonb),
      p_created_by
    );
    v_message_count := v_message_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_ChannelCode", "CRMQuickOpt_MessageDraftID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'send_email', 'Review/send email', 'email', v_email_draft_id, true, 10),
      (v_quick_task_id, 'send_whatsapp', 'Review/send WhatsApp', 'whatsapp', v_whatsapp_draft_id, false, 20),
      (v_quick_task_id, 'open_record', 'Open booking/job', NULL, NULL, false, 30),
      (v_quick_task_id, 'ignore', 'No message needed', NULL, NULL, false, 90);

  ELSIF p_trigger_type_code = 'phone_call_completed' THEN
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'review_call_summary',
      'Review call summary and action points',
      p_owner_user_id,
      'Open the call summary, check the AI action points and decide what should become real work.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      'CRM_CallReviews',
      p_call_review_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_TargetTable", "CRMQuickOpt_TargetID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'open_call_review', 'Open call review', 'CRM_CallReviews', p_call_review_id, true, 10),
      (v_quick_task_id, 'create_task', 'Create follow-up task', 'CRM_CallReviews', p_call_review_id, false, 20),
      (v_quick_task_id, 'ignore', 'No action needed', 'CRM_CallReviews', p_call_review_id, false, 90);

  ELSIF p_trigger_type_code = 'quote_sent' THEN
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'follow_up_quote',
      'Follow up sent quote',
      p_owner_user_id,
      'Review whether this quote should be followed up personally, then send/edit/ignore.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      p_source_table,
      p_source_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    v_email_draft_id := public."CRM_CreatePersonalMessageDraft"(
      v_run_id,
      v_quick_task_id,
      'quote_followup',
      'email',
      p_owner_user_id,
      p_customer_org_id,
      NULL,
      'Following up on the quote',
      'I wanted to check whether the quote works for you or if you would like me to adjust anything.',
      'Rewrite this follow-up personally using quote, customer, mode, lane and previous interaction context. Avoid generic chasing wording.',
      COALESCE(p_context_json, '{}'::jsonb),
      p_created_by
    );
    v_message_count := v_message_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_ChannelCode", "CRMQuickOpt_MessageDraftID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'send_email', 'Review/send follow-up email', 'email', v_email_draft_id, true, 10),
      (v_quick_task_id, 'snooze', 'Snooze follow-up', NULL, NULL, false, 30),
      (v_quick_task_id, 'ignore', 'No follow-up needed', NULL, NULL, false, 90);

  ELSE
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'manual_quick_task',
      'Review CRM activity',
      p_owner_user_id,
      'Review this activity and decide whether any follow-up is needed.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      p_source_table,
      p_source_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_TargetTable", "CRMQuickOpt_TargetID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'open_record', 'Open record', p_source_table, p_source_id, true, 10),
      (v_quick_task_id, 'ignore', 'No action needed', p_source_table, p_source_id, false, 90);
  END IF;

  UPDATE public."CRM_ActivityWorkflowRuns"
  SET "CRMAWRun_GeneratedQuickTaskCount" = v_task_count,
      "CRMAWRun_GeneratedMessageDraftCount" = v_message_count
  WHERE "CRMAWRun_ID" = v_run_id;

  RETURN v_run_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RegisterActivityWorkflowEvent"("p_trigger_type_code" character varying, "p_source_table" character varying, "p_source_id" "uuid", "p_activity_id" "uuid", "p_account_id" "uuid", "p_lead_id" "uuid", "p_opportunity_id" "uuid", "p_quote_followup_id" "uuid", "p_call_review_id" "uuid", "p_job_id" "uuid", "p_customer_org_id" "uuid", "p_owner_user_id" "uuid", "p_context_json" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_StartAutomationRun"("p_playbook_code" character varying, "p_target_table" character varying, "p_target_pk_column" character varying, "p_target_id" "uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_quick_task_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_context_json" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_playbook record;
  v_run_id uuid;
BEGIN
  SELECT *
  INTO v_playbook
  FROM public."CRM_AutomationPlaybooks"
  WHERE "CRMAutoPlaybook_Code" = p_playbook_code
    AND "CRMAutoPlaybook_IsActive" = true
    AND ("CRMAutoPlaybook_CustomerOrgID" IS NULL OR "CRMAutoPlaybook_CustomerOrgID" = p_customer_org_id)
  ORDER BY "CRMAutoPlaybook_CustomerOrgID" NULLS LAST,
           "CRMAutoPlaybook_OrgOfficeID" NULLS LAST,
           "CRMAutoPlaybook_CreatedAt"
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CRM automation playbook % was not found.', p_playbook_code;
  END IF;

  INSERT INTO public."CRM_AutomationRuns" (
    "CRMAutoRun_PlaybookID",
    "CRMAutoRun_StatusCode",
    "CRMAutoRun_QuickTaskID",
    "CRMAutoRun_AccountID",
    "CRMAutoRun_JobID",
    "CRMAutoRun_CustomerOrgID",
    "CRMAutoRun_TargetTable",
    "CRMAutoRun_TargetPKColumn",
    "CRMAutoRun_TargetID",
    "CRMAutoRun_AssignedUserID",
    "CRMAutoRun_ContextJSON",
    "CRMAutoRun_StartedBy"
  )
  VALUES (
    v_playbook."CRMAutoPlaybook_ID",
    CASE WHEN v_playbook."CRMAutoPlaybook_RequiresWizard" THEN 'needs_data' ELSE 'ready' END,
    p_quick_task_id,
    p_account_id,
    p_job_id,
    p_customer_org_id,
    p_target_table,
    p_target_pk_column,
    p_target_id,
    p_assigned_user_id,
    COALESCE(p_context_json, '{}'::jsonb),
    p_created_by
  )
  RETURNING "CRMAutoRun_ID" INTO v_run_id;

  INSERT INTO public."CRM_AutomationRunSteps" (
    "CRMAutoRunStep_RunID",
    "CRMAutoRunStep_PlaybookStepID",
    "CRMAutoRunStep_ActionTypeCode",
    "CRMAutoRunStep_StatusCode",
    "CRMAutoRunStep_SortOrder"
  )
  SELECT
    v_run_id,
    step."CRMAutoStep_ID",
    step."CRMAutoStep_ActionTypeCode",
    'ready',
    step."CRMAutoStep_SortOrder"
  FROM public."CRM_AutomationPlaybookSteps" step
  WHERE step."CRMAutoStep_PlaybookID" = v_playbook."CRMAutoPlaybook_ID"
  ORDER BY step."CRMAutoStep_SortOrder";

  RETURN v_run_id;
END;
$$;


ALTER FUNCTION "public"."CRM_StartAutomationRun"("p_playbook_code" character varying, "p_target_table" character varying, "p_target_pk_column" character varying, "p_target_id" "uuid", "p_assigned_user_id" "uuid", "p_quick_task_id" "uuid", "p_customer_org_id" "uuid", "p_job_id" "uuid", "p_account_id" "uuid", "p_context_json" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_AcquireMailboxSyncLease"("p_mailbox_id" "uuid", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 180) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  affected_rows integer;
begin
  update public."Comm_Mailboxes"
  set
    "CommMailbox_SyncLeaseToken" = p_lease_token,
    "CommMailbox_SyncLeaseUntil" = now() + make_interval(secs => greatest(15, least(p_lease_seconds, 300)))
  where "CommMailbox_ID" = p_mailbox_id
    and "CommMailbox_IsDeleted" = false
    and (
      "CommMailbox_SyncLeaseUntil" is null
      or "CommMailbox_SyncLeaseUntil" <= now()
      or "CommMailbox_SyncLeaseToken" = p_lease_token
    );

  get diagnostics affected_rows = row_count;
  return affected_rows = 1;
end;
$$;


ALTER FUNCTION "public"."Comm_AcquireMailboxSyncLease"("p_mailbox_id" "uuid", "p_lease_token" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_CreateNotification"("p_user_id" "uuid", "p_title" character varying, "p_body" "text" DEFAULT NULL::"text", "p_target_table" character varying DEFAULT NULL::character varying, "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_link_type_code" character varying DEFAULT NULL::character varying, "p_thread_id" "uuid" DEFAULT NULL::"uuid", "p_message_id" "uuid" DEFAULT NULL::"uuid", "p_workflow_task_id" "uuid" DEFAULT NULL::"uuid", "p_priority_code" character varying DEFAULT 'normal'::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_notification_id uuid;
BEGIN
  INSERT INTO public."Comm_Notifications" (
    "CommNotif_UserID",
    "CommNotif_Title",
    "CommNotif_Body",
    "CommNotif_TargetTable",
    "CommNotif_TargetID",
    "CommNotif_LinkTypeCode",
    "CommNotif_ThreadID",
    "CommNotif_MessageID",
    "CommNotif_WorkflowTaskID",
    "CommNotif_PriorityCode"
  )
  VALUES (
    p_user_id,
    p_title,
    p_body,
    p_target_table,
    p_target_id,
    p_link_type_code,
    p_thread_id,
    p_message_id,
    p_workflow_task_id,
    coalesce(p_priority_code, 'normal')
  )
  RETURNING "CommNotif_ID" INTO v_notification_id;

  RETURN v_notification_id;
END;
$$;


ALTER FUNCTION "public"."Comm_CreateNotification"("p_user_id" "uuid", "p_title" character varying, "p_body" "text", "p_target_table" character varying, "p_target_id" "uuid", "p_link_type_code" character varying, "p_thread_id" "uuid", "p_message_id" "uuid", "p_workflow_task_id" "uuid", "p_priority_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_LinkThreadRecord"("p_thread_id" "uuid", "p_link_type_code" character varying, "p_target_table" character varying, "p_target_id" "uuid", "p_target_display_snapshot" character varying DEFAULT NULL::character varying, "p_role" character varying DEFAULT NULL::character varying, "p_is_primary" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_link_id uuid;
BEGIN
  INSERT INTO public."Comm_ThreadLinks" (
    "CommThreadLink_ThreadID",
    "CommThreadLink_LinkTypeCode",
    "CommThreadLink_TargetTable",
    "CommThreadLink_TargetID",
    "CommThreadLink_TargetDisplaySnapshot",
    "CommThreadLink_Role",
    "CommThreadLink_IsPrimary"
  )
  VALUES (
    p_thread_id,
    p_link_type_code,
    p_target_table,
    p_target_id,
    p_target_display_snapshot,
    p_role,
    coalesce(p_is_primary, false)
  )
  ON CONFLICT ("CommThreadLink_ThreadID", "CommThreadLink_LinkTypeCode", "CommThreadLink_TargetTable", "CommThreadLink_TargetID", "CommThreadLink_Role")
  DO UPDATE SET
    "CommThreadLink_TargetDisplaySnapshot" = excluded."CommThreadLink_TargetDisplaySnapshot",
    "CommThreadLink_IsPrimary" = excluded."CommThreadLink_IsPrimary"
  RETURNING "CommThreadLink_ID" INTO v_link_id;

  RETURN v_link_id;
END;
$$;


ALTER FUNCTION "public"."Comm_LinkThreadRecord"("p_thread_id" "uuid", "p_link_type_code" character varying, "p_target_table" character varying, "p_target_id" "uuid", "p_target_display_snapshot" character varying, "p_role" character varying, "p_is_primary" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_NormalizeAddress"("p_channel_code" character varying, "p_address" "text") RETURNS character varying
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_address IS NULL THEN NULL
    WHEN p_channel_code = 'email' THEN lower(trim(p_address))
    WHEN p_channel_code IN ('sms', 'whatsapp', 'phone_call', 'fax') THEN regexp_replace(trim(p_address), '[^0-9+]', '', 'g')
    ELSE lower(trim(p_address))
  END::varchar;
$$;


ALTER FUNCTION "public"."Comm_NormalizeAddress"("p_channel_code" character varying, "p_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_RecordDeliveryEvent"("p_message_id" "uuid", "p_send_id" "uuid", "p_event_type_code" character varying, "p_status_code" character varying, "p_provider_event_id" character varying DEFAULT NULL::character varying, "p_payload_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_delivery_id uuid;
BEGIN
  INSERT INTO public."Comm_DeliveryEvents" (
    "CommDelivery_MessageID",
    "CommDelivery_SendID",
    "CommDelivery_EventTypeCode",
    "CommDelivery_StatusCode",
    "CommDelivery_ProviderEventID",
    "CommDelivery_PayloadJSON"
  )
  VALUES (
    p_message_id,
    p_send_id,
    p_event_type_code,
    p_status_code,
    p_provider_event_id,
    coalesce(p_payload_json, '{}'::jsonb)
  )
  RETURNING "CommDelivery_ID" INTO v_delivery_id;

  IF p_message_id IS NOT NULL AND p_status_code IS NOT NULL THEN
    UPDATE public."Comm_Messages"
    SET
      "CommMessage_StatusCode" = p_status_code,
      "CommMessage_DeliveredAt" = CASE WHEN p_status_code = 'delivered' THEN now() ELSE "CommMessage_DeliveredAt" END,
      "CommMessage_ReadAt" = CASE WHEN p_status_code = 'read' THEN now() ELSE "CommMessage_ReadAt" END,
      "CommMessage_UpdatedAt" = now()
    WHERE "CommMessage_ID" = p_message_id;
  END IF;

  IF p_send_id IS NOT NULL AND p_status_code IS NOT NULL THEN
    UPDATE public."Comm_SendRequests"
    SET
      "CommSend_StatusCode" = p_status_code,
      "CommSend_UpdatedAt" = now()
    WHERE "CommSend_ID" = p_send_id;
  END IF;

  RETURN v_delivery_id;
END;
$$;


ALTER FUNCTION "public"."Comm_RecordDeliveryEvent"("p_message_id" "uuid", "p_send_id" "uuid", "p_event_type_code" character varying, "p_status_code" character varying, "p_provider_event_id" character varying, "p_payload_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_ReleaseMailboxSyncLease"("p_mailbox_id" "uuid", "p_lease_token" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  update public."Comm_Mailboxes"
  set
    "CommMailbox_SyncLeaseToken" = null,
    "CommMailbox_SyncLeaseUntil" = null
  where "CommMailbox_ID" = p_mailbox_id
    and "CommMailbox_SyncLeaseToken" = p_lease_token;
$$;


ALTER FUNCTION "public"."Comm_ReleaseMailboxSyncLease"("p_mailbox_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCB_FindAssetCandidates"("p_asset_type_code" character varying DEFAULT NULL::character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_language_code" character varying DEFAULT 'en'::character varying) RETURNS TABLE("DOCBAS_ID" "uuid", "DOCBAS_Code" character varying, "DOCBAS_Name" character varying, "DOCBAS_AssetTypeCode" character varying, "DOCBAS_LanguageCode" character varying, "DOCBAS_FileName" character varying, "DOCBAS_StorageBucket" character varying, "DOCBAS_StoragePath" "text", "DOCBAS_FileURL" "text", "DOCBAS_IsApproved" boolean, "MatchScore" integer, "MatchLevel" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    asset."DOCBAS_ID",
    asset."DOCBAS_Code",
    asset."DOCBAS_Name",
    asset."DOCBAS_AssetTypeCode",
    asset."DOCBAS_LanguageCode",
    asset."DOCBAS_FileName",
    asset."DOCBAS_StorageBucket",
    asset."DOCBAS_StoragePath",
    asset."DOCBAS_FileURL",
    asset."DOCBAS_IsApproved",
    (
      CASE WHEN asset."DOCBAS_CustomerOrgID" IS NOT NULL AND asset."DOCBAS_CustomerOrgID" = p_customer_org_id THEN 64 ELSE 0 END +
      CASE WHEN asset."DOCBAS_BrandID" IS NOT NULL AND asset."DOCBAS_BrandID" = p_brand_id THEN 32 ELSE 0 END +
      CASE WHEN asset."DOCBAS_LegalEntityID" IS NOT NULL AND asset."DOCBAS_LegalEntityID" = p_legal_entity_id THEN 16 ELSE 0 END +
      CASE WHEN asset."DOCBAS_OrgOfficeID" IS NOT NULL AND asset."DOCBAS_OrgOfficeID" = p_org_office_id THEN 8 ELSE 0 END +
      CASE WHEN p_language_code IS NOT NULL AND asset."DOCBAS_LanguageCode" = p_language_code THEN 4 ELSE 0 END
    )::int AS "MatchScore",
    CASE
      WHEN asset."DOCBAS_CustomerOrgID" IS NOT NULL AND asset."DOCBAS_CustomerOrgID" = p_customer_org_id THEN 'customer'
      WHEN asset."DOCBAS_BrandID" IS NOT NULL AND asset."DOCBAS_BrandID" = p_brand_id THEN 'brand'
      WHEN asset."DOCBAS_LegalEntityID" IS NOT NULL AND asset."DOCBAS_LegalEntityID" = p_legal_entity_id THEN 'legal_entity'
      WHEN asset."DOCBAS_OrgOfficeID" IS NOT NULL AND asset."DOCBAS_OrgOfficeID" = p_org_office_id THEN 'office'
      ELSE 'system'
    END AS "MatchLevel"
  FROM public."DOCB_AssetLibrary" asset
  WHERE asset."DOCBAS_IsActive" = true
    AND (p_asset_type_code IS NULL OR asset."DOCBAS_AssetTypeCode" = p_asset_type_code)
    AND (p_language_code IS NULL OR asset."DOCBAS_LanguageCode" = p_language_code OR asset."DOCBAS_LanguageCode" = 'en')
    AND (asset."DOCBAS_CustomerOrgID" IS NULL OR asset."DOCBAS_CustomerOrgID" = p_customer_org_id)
    AND (asset."DOCBAS_BrandID" IS NULL OR asset."DOCBAS_BrandID" = p_brand_id)
    AND (asset."DOCBAS_LegalEntityID" IS NULL OR asset."DOCBAS_LegalEntityID" = p_legal_entity_id)
    AND (asset."DOCBAS_OrgOfficeID" IS NULL OR asset."DOCBAS_OrgOfficeID" = p_org_office_id)
  ORDER BY "MatchScore" DESC,
           asset."DOCBAS_IsApproved" DESC,
           asset."DOCBAS_UpdatedAt" DESC NULLS LAST,
           asset."DOCBAS_Code";
$$;


ALTER FUNCTION "public"."DOCB_FindAssetCandidates"("p_asset_type_code" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_customer_org_id" "uuid", "p_language_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCB_FindLibraryPackCandidates"("p_pack_code" character varying DEFAULT NULL::character varying, "p_data_scope_code" character varying DEFAULT NULL::character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_language_code" character varying DEFAULT 'en'::character varying) RETURNS TABLE("DOCBLP_ID" "uuid", "DOCBLP_Code" character varying, "DOCBLP_Name" character varying, "DOCBLP_DataScopeCode" character varying, "DOCBLP_LanguageCode" character varying, "DOCBLP_OrgOfficeID" "uuid", "DOCBLP_LegalEntityID" "uuid", "DOCBLP_BrandID" "uuid", "DOCBLP_CustomerOrgID" "uuid", "ItemCount" integer, "RequiredItemCount" integer, "GeneratedByDefaultCount" integer, "MatchScore" integer, "MatchLevel" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    pack."DOCBLP_ID",
    pack."DOCBLP_Code",
    pack."DOCBLP_Name",
    pack."DOCBLP_DataScopeCode",
    pack."DOCBLP_LanguageCode",
    pack."DOCBLP_OrgOfficeID",
    pack."DOCBLP_LegalEntityID",
    pack."DOCBLP_BrandID",
    pack."DOCBLP_CustomerOrgID",
    pack."ItemCount",
    pack."RequiredItemCount",
    pack."GeneratedByDefaultCount",
    (
      CASE WHEN pack."DOCBLP_CustomerOrgID" IS NOT NULL AND pack."DOCBLP_CustomerOrgID" = p_customer_org_id THEN 64 ELSE 0 END +
      CASE WHEN pack."DOCBLP_BrandID" IS NOT NULL AND pack."DOCBLP_BrandID" = p_brand_id THEN 32 ELSE 0 END +
      CASE WHEN pack."DOCBLP_LegalEntityID" IS NOT NULL AND pack."DOCBLP_LegalEntityID" = p_legal_entity_id THEN 16 ELSE 0 END +
      CASE WHEN pack."DOCBLP_OrgOfficeID" IS NOT NULL AND pack."DOCBLP_OrgOfficeID" = p_org_office_id THEN 8 ELSE 0 END +
      CASE WHEN p_language_code IS NOT NULL AND pack."DOCBLP_LanguageCode" = p_language_code THEN 4 ELSE 0 END +
      CASE WHEN p_pack_code IS NOT NULL AND pack."DOCBLP_Code" = p_pack_code THEN 4 ELSE 0 END
    )::int AS "MatchScore",
    CASE
      WHEN pack."DOCBLP_CustomerOrgID" IS NOT NULL AND pack."DOCBLP_CustomerOrgID" = p_customer_org_id THEN 'customer'
      WHEN pack."DOCBLP_BrandID" IS NOT NULL AND pack."DOCBLP_BrandID" = p_brand_id THEN 'brand'
      WHEN pack."DOCBLP_LegalEntityID" IS NOT NULL AND pack."DOCBLP_LegalEntityID" = p_legal_entity_id THEN 'legal_entity'
      WHEN pack."DOCBLP_OrgOfficeID" IS NOT NULL AND pack."DOCBLP_OrgOfficeID" = p_org_office_id THEN 'office'
      ELSE 'system'
    END AS "MatchLevel"
  FROM public."DOCB_LibraryPackSummary" pack
  WHERE pack."DOCBLP_IsActive" = true
    AND pack."DOCBLP_StatusCode" = 'published'
    AND (p_pack_code IS NULL OR pack."DOCBLP_Code" = p_pack_code)
    AND (p_data_scope_code IS NULL OR pack."DOCBLP_DataScopeCode" = p_data_scope_code)
    AND (p_language_code IS NULL OR pack."DOCBLP_LanguageCode" = p_language_code OR pack."DOCBLP_LanguageCode" = 'en')
    AND (pack."DOCBLP_CustomerOrgID" IS NULL OR pack."DOCBLP_CustomerOrgID" = p_customer_org_id)
    AND (pack."DOCBLP_BrandID" IS NULL OR pack."DOCBLP_BrandID" = p_brand_id)
    AND (pack."DOCBLP_LegalEntityID" IS NULL OR pack."DOCBLP_LegalEntityID" = p_legal_entity_id)
    AND (pack."DOCBLP_OrgOfficeID" IS NULL OR pack."DOCBLP_OrgOfficeID" = p_org_office_id)
  ORDER BY "MatchScore" DESC,
           CASE WHEN p_language_code IS NOT NULL AND pack."DOCBLP_LanguageCode" = p_language_code THEN 0 ELSE 1 END,
           pack."DOCBLP_UpdatedAt" DESC NULLS LAST,
           pack."DOCBLP_Code";
$$;


ALTER FUNCTION "public"."DOCB_FindLibraryPackCandidates"("p_pack_code" character varying, "p_data_scope_code" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_customer_org_id" "uuid", "p_language_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCB_FindTemplateCandidates"("p_doc_type_id" "uuid" DEFAULT NULL::"uuid", "p_document_code" character varying DEFAULT NULL::character varying, "p_data_scope_code" character varying DEFAULT NULL::character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_language_code" character varying DEFAULT 'en'::character varying) RETURNS TABLE("DOCBT_ID" "uuid", "DOCBT_Code" character varying, "DOCBT_Name" character varying, "DOCBT_LibraryDocumentCode" character varying, "DOCBT_DocTypeID" "uuid", "DOCBT_DataScopeCode" character varying, "DOCBT_LanguageCode" character varying, "DOCBT_OrgOfficeID" "uuid", "DOCBT_LegalEntityID" "uuid", "DOCBT_BrandID" "uuid", "DOCBT_CustomerOrgID" "uuid", "CurrentTemplateVersionID" "uuid", "DefaultRenderEngineCode" character varying, "DefaultOutputFormatCode" character varying, "MatchScore" integer, "MatchLevel" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    template."DOCBT_ID",
    template."DOCBT_Code",
    template."DOCBT_Name",
    template."DOCBT_LibraryDocumentCode",
    template."DOCBT_DocTypeID",
    template."DOCBT_DataScopeCode",
    template."DOCBT_LanguageCode",
    template."DOCBT_OrgOfficeID",
    template."DOCBT_LegalEntityID",
    template."DOCBT_BrandID",
    template."DOCBT_CustomerOrgID",
    template."CurrentTemplateVersionID",
    template."DOCBT_DefaultRenderEngineCode" AS "DefaultRenderEngineCode",
    template."DOCBT_DefaultOutputFormatCode" AS "DefaultOutputFormatCode",
    (
      CASE WHEN template."DOCBT_CustomerOrgID" IS NOT NULL AND template."DOCBT_CustomerOrgID" = p_customer_org_id THEN 64 ELSE 0 END +
      CASE WHEN template."DOCBT_BrandID" IS NOT NULL AND template."DOCBT_BrandID" = p_brand_id THEN 32 ELSE 0 END +
      CASE WHEN template."DOCBT_LegalEntityID" IS NOT NULL AND template."DOCBT_LegalEntityID" = p_legal_entity_id THEN 16 ELSE 0 END +
      CASE WHEN template."DOCBT_OrgOfficeID" IS NOT NULL AND template."DOCBT_OrgOfficeID" = p_org_office_id THEN 8 ELSE 0 END +
      CASE WHEN p_language_code IS NOT NULL AND template."DOCBT_LanguageCode" = p_language_code THEN 4 ELSE 0 END +
      CASE WHEN p_doc_type_id IS NOT NULL AND template."DOCBT_DocTypeID" = p_doc_type_id THEN 2 ELSE 0 END +
      CASE WHEN p_document_code IS NOT NULL AND (
        template."DOCBT_Code" = p_document_code OR
        template."DOCBT_LibraryDocumentCode" = p_document_code OR
        template."DOCBT_DocTypeCodeSnapshot" = p_document_code OR
        template."DocTypeCode" = p_document_code
      ) THEN 2 ELSE 0 END
    )::int AS "MatchScore",
    CASE
      WHEN template."DOCBT_CustomerOrgID" IS NOT NULL AND template."DOCBT_CustomerOrgID" = p_customer_org_id THEN 'customer'
      WHEN template."DOCBT_BrandID" IS NOT NULL AND template."DOCBT_BrandID" = p_brand_id THEN 'brand'
      WHEN template."DOCBT_LegalEntityID" IS NOT NULL AND template."DOCBT_LegalEntityID" = p_legal_entity_id THEN 'legal_entity'
      WHEN template."DOCBT_OrgOfficeID" IS NOT NULL AND template."DOCBT_OrgOfficeID" = p_org_office_id THEN 'office'
      ELSE 'system'
    END AS "MatchLevel"
  FROM public."DOCB_TemplateSummary" template
  WHERE template."DOCBT_IsActive" = true
    AND template."DOCBT_StatusCode" = 'published'
    AND (p_data_scope_code IS NULL OR template."DOCBT_DataScopeCode" = p_data_scope_code)
    AND (p_doc_type_id IS NULL OR template."DOCBT_DocTypeID" = p_doc_type_id)
    AND (
      p_document_code IS NULL OR
      template."DOCBT_Code" = p_document_code OR
      template."DOCBT_LibraryDocumentCode" = p_document_code OR
      template."DOCBT_DocTypeCodeSnapshot" = p_document_code OR
      template."DocTypeCode" = p_document_code
    )
    AND (p_language_code IS NULL OR template."DOCBT_LanguageCode" = p_language_code OR template."DOCBT_LanguageCode" = 'en')
    AND (template."DOCBT_CustomerOrgID" IS NULL OR template."DOCBT_CustomerOrgID" = p_customer_org_id)
    AND (template."DOCBT_BrandID" IS NULL OR template."DOCBT_BrandID" = p_brand_id)
    AND (template."DOCBT_LegalEntityID" IS NULL OR template."DOCBT_LegalEntityID" = p_legal_entity_id)
    AND (template."DOCBT_OrgOfficeID" IS NULL OR template."DOCBT_OrgOfficeID" = p_org_office_id)
  ORDER BY "MatchScore" DESC,
           CASE WHEN p_language_code IS NOT NULL AND template."DOCBT_LanguageCode" = p_language_code THEN 0 ELSE 1 END,
           template."DOCBT_UpdatedAt" DESC NULLS LAST,
           template."DOCBT_Code";
$$;


ALTER FUNCTION "public"."DOCB_FindTemplateCandidates"("p_doc_type_id" "uuid", "p_document_code" character varying, "p_data_scope_code" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_customer_org_id" "uuid", "p_language_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCB_SectionGridIssues"("p_section_version_id" "uuid") RETURNS TABLE("DOCBSLR_ID" "uuid", "RowNo" integer, "IssueCode" character varying, "IssueMessage" "text")
    LANGUAGE "sql" STABLE
    AS $$
  WITH cells AS (
    SELECT
      row_def."DOCBSLR_ID",
      row_def."DOCBSLR_RowNo",
      cell."DOCBSLC_ID",
      cell."DOCBSLC_ColumnStart",
      (cell."DOCBSLC_ColumnStart" + cell."DOCBSLC_ColumnSpan" - 1) AS column_end
    FROM public."DOCB_SectionLayoutRows" row_def
    JOIN public."DOCB_SectionLayoutCells" cell
      ON cell."DOCBSLC_RowID" = row_def."DOCBSLR_ID"
    WHERE row_def."DOCBSLR_SectionVersionID" = p_section_version_id
  )
  SELECT DISTINCT
    a."DOCBSLR_ID",
    a."DOCBSLR_RowNo",
    'overlapping_cells'::varchar AS "IssueCode",
    ('Cells overlap in row ' || a."DOCBSLR_RowNo")::text AS "IssueMessage"
  FROM cells a
  JOIN cells b
    ON b."DOCBSLR_ID" = a."DOCBSLR_ID"
   AND b."DOCBSLC_ID" <> a."DOCBSLC_ID"
   AND a."DOCBSLC_ColumnStart" <= b.column_end
   AND b."DOCBSLC_ColumnStart" <= a.column_end;
$$;


ALTER FUNCTION "public"."DOCB_SectionGridIssues"("p_section_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCSEC_FindVerification"("p_public_code" character varying) RETURNS TABLE("PublicCode" character varying, "TokenStatusCode" character varying, "TokenStatusName" character varying, "IsValidForPublicVerification" boolean, "DocumentNumber" character varying, "TargetTable" character varying, "BLNumber" character varying, "BLStatus" character varying, "FileSHA256" character varying, "CanonicalPayloadSHA256" character varying, "SignatureIsValid" boolean, "ValidFrom" timestamp with time zone, "ExpiresAt" timestamp with time zone, "RevokedAt" timestamp with time zone, "VerificationCount" integer, "LastVerifiedAt" timestamp with time zone, "OpenIssueCount" integer)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    public_summary."DOCSECVT_PublicCode",
    public_summary."DOCSECVT_StatusCode",
    public_summary."TokenStatusName",
    public_summary."TokenIsValidForPublicVerification",
    public_summary."DOCSECVT_DocumentNumberSnapshot",
    public_summary."DOCSECVT_TargetTable",
    public_summary."BLNumber",
    public_summary."BLStatus",
    public_summary."DOCSECF_FileSHA256",
    public_summary."DOCSECF_CanonicalPayloadSHA256",
    public_summary."SignatureIsValid",
    public_summary."DOCSECVT_ValidFrom",
    public_summary."DOCSECVT_ExpiresAt",
    public_summary."DOCSECVT_RevokedAt",
    public_summary."DOCSECVT_VerificationCount",
    public_summary."DOCSECVT_LastVerifiedAt",
    public_summary."OpenIssueCount"
  FROM public."DOCSEC_PublicVerificationSummary" public_summary
  WHERE public_summary."DOCSECVT_PublicCode" = p_public_code
  LIMIT 1;
$$;


ALTER FUNCTION "public"."DOCSEC_FindVerification"("p_public_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCSEC_RecordVerificationEvent"("p_public_code" character varying, "p_status_code" character varying, "p_verification_method" character varying DEFAULT 'scan'::character varying, "p_document_hash_submitted_sha256" character varying DEFAULT NULL::character varying, "p_ip_address_hash_sha256" character varying DEFAULT NULL::character varying, "p_user_agent" "text" DEFAULT NULL::"text", "p_country_code" character varying DEFAULT NULL::character varying, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_token_id uuid;
  v_risk_level varchar(40);
  v_fingerprint_id uuid;
  v_event_id uuid;
BEGIN
  SELECT
    token."DOCSECVT_ID",
    status."DOCSECVS_RiskLevelCode",
    token."DOCSECVT_FingerprintID"
  INTO v_token_id, v_risk_level, v_fingerprint_id
  FROM public."DOCSEC_VerificationTokens" token
  LEFT JOIN public."sys_DocumentSecurityVerificationStatuses" status
    ON status."DOCSECVS_Code" = p_status_code
  WHERE token."DOCSECVT_PublicCode" = p_public_code
  LIMIT 1;

  IF v_risk_level IS NULL THEN
    SELECT status."DOCSECVS_RiskLevelCode"
    INTO v_risk_level
    FROM public."sys_DocumentSecurityVerificationStatuses" status
    WHERE status."DOCSECVS_Code" = p_status_code
    LIMIT 1;
  END IF;

  INSERT INTO public."DOCSEC_VerificationEvents" (
    "DOCSECVE_VerificationTokenID",
    "DOCSECVE_PublicCodeSnapshot",
    "DOCSECVE_StatusCode",
    "DOCSECVE_RiskLevelCode",
    "DOCSECVE_VerificationMethod",
    "DOCSECVE_DocumentHashSubmittedSHA256",
    "DOCSECVE_MatchedFingerprintID",
    "DOCSECVE_IPAddressHashSHA256",
    "DOCSECVE_UserAgent",
    "DOCSECVE_CountryCode",
    "DOCSECVE_MetadataJSON"
  )
  VALUES (
    v_token_id,
    p_public_code,
    p_status_code,
    coalesce(v_risk_level, 'medium'),
    coalesce(p_verification_method, 'scan'),
    p_document_hash_submitted_sha256,
    v_fingerprint_id,
    p_ip_address_hash_sha256,
    p_user_agent,
    p_country_code,
    coalesce(p_metadata_json, '{}'::jsonb)
  )
  RETURNING "DOCSECVE_ID" INTO v_event_id;

  IF v_token_id IS NOT NULL THEN
    UPDATE public."DOCSEC_VerificationTokens"
    SET
      "DOCSECVT_VerificationCount" = "DOCSECVT_VerificationCount" + 1,
      "DOCSECVT_LastVerifiedAt" = now(),
      "DOCSECVT_UpdatedAt" = now()
    WHERE "DOCSECVT_ID" = v_token_id;

    UPDATE public."BL_SecurityControls" bl_security
    SET
      "BLSC_VerificationCount" = "BLSC_VerificationCount" + 1,
      "BLSC_LastVerificationAt" = now(),
      "BLSC_UpdatedAt" = now()
    WHERE bl_security."BLSC_CurrentVerificationTokenID" = v_token_id;
  END IF;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."DOCSEC_RecordVerificationEvent"("p_public_code" character varying, "p_status_code" character varying, "p_verification_method" character varying, "p_document_hash_submitted_sha256" character varying, "p_ip_address_hash_sha256" character varying, "p_user_agent" "text", "p_country_code" character varying, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCSEC_VerifyDocumentHash"("p_public_code" character varying, "p_file_sha256" character varying) RETURNS TABLE("StatusCode" character varying, "RiskLevelCode" character varying, "Message" "text", "FingerprintID" "uuid")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    CASE
      WHEN token."DOCSECVT_ID" IS NULL THEN 'not_found'
      WHEN token."DOCSECVT_StatusCode" = 'revoked' THEN 'revoked'
      WHEN token."DOCSECVT_StatusCode" = 'superseded' THEN 'superseded'
      WHEN token."DOCSECVT_StatusCode" = 'expired' OR (token."DOCSECVT_ExpiresAt" IS NOT NULL AND token."DOCSECVT_ExpiresAt" < now()) THEN 'expired'
      WHEN lower(fingerprint."DOCSECF_FileSHA256") = lower(p_file_sha256) THEN 'valid_hash_match'
      ELSE 'hash_mismatch'
    END::varchar AS "StatusCode",
    CASE
      WHEN token."DOCSECVT_ID" IS NULL THEN 'high'
      WHEN token."DOCSECVT_StatusCode" IN ('revoked', 'blocked') THEN 'critical'
      WHEN token."DOCSECVT_StatusCode" = 'superseded' THEN 'medium'
      WHEN token."DOCSECVT_StatusCode" = 'expired' OR (token."DOCSECVT_ExpiresAt" IS NOT NULL AND token."DOCSECVT_ExpiresAt" < now()) THEN 'medium'
      WHEN lower(fingerprint."DOCSECF_FileSHA256") = lower(p_file_sha256) THEN 'none'
      ELSE 'critical'
    END::varchar AS "RiskLevelCode",
    CASE
      WHEN token."DOCSECVT_ID" IS NULL THEN 'Verification code was not found.'
      WHEN token."DOCSECVT_StatusCode" = 'revoked' THEN 'Document verification token has been revoked.'
      WHEN token."DOCSECVT_StatusCode" = 'superseded' THEN 'Document has been superseded by a later version.'
      WHEN token."DOCSECVT_StatusCode" = 'expired' OR (token."DOCSECVT_ExpiresAt" IS NOT NULL AND token."DOCSECVT_ExpiresAt" < now()) THEN 'Document verification token has expired.'
      WHEN lower(fingerprint."DOCSECF_FileSHA256") = lower(p_file_sha256) THEN 'Document hash matches the issued fingerprint.'
      ELSE 'Document hash does not match the issued fingerprint.'
    END::text AS "Message",
    fingerprint."DOCSECF_ID" AS "FingerprintID"
  FROM (SELECT 1) seed
  LEFT JOIN public."DOCSEC_VerificationTokens" token
    ON token."DOCSECVT_PublicCode" = p_public_code
  LEFT JOIN public."DOCSEC_DocumentFingerprints" fingerprint
    ON fingerprint."DOCSECF_ID" = token."DOCSECVT_FingerprintID";
$$;


ALTER FUNCTION "public"."DOCSEC_VerifyDocumentHash"("p_public_code" character varying, "p_file_sha256" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."EDI_QueueOutboundMessage"("p_message_profile_id" "uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_generated_from_table" character varying DEFAULT NULL::character varying, "p_generated_from_id" "uuid" DEFAULT NULL::"uuid", "p_document_reference" character varying DEFAULT NULL::character varying, "p_payload_json" "jsonb" DEFAULT '{}'::"jsonb", "p_payload_text" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_profile record;
  v_message_id uuid;
  v_ack_status varchar(60);
BEGIN
  SELECT *
  INTO v_profile
  FROM public."EDI_MessageProfiles"
  WHERE "EDIMP_ID" = p_message_profile_id
    AND "EDIMP_IsActive" = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EDI message profile % was not found or is inactive.', p_message_profile_id;
  END IF;

  IF v_profile."EDIMP_DirectionCode" NOT IN ('outbound', 'bidirectional') THEN
    RAISE EXCEPTION 'EDI message profile % is not outbound-capable.', p_message_profile_id;
  END IF;

  v_ack_status := CASE WHEN v_profile."EDIMP_RequiresAcknowledgement" THEN 'pending' ELSE 'not_required' END;

  INSERT INTO public."EDI_Messages" (
    "EDIMessage_MessageProfileID",
    "EDIMessage_ConnectionID",
    "EDIMessage_TradingPartnerID",
    "EDIMessage_DirectionCode",
    "EDIMessage_MessageTypeCode",
    "EDIMessage_StandardCode",
    "EDIMessage_StatusCode",
    "EDIMessage_AcknowledgementStatusCode",
    "EDIMessage_DocumentReference",
    "EDIMessage_JobID",
    "EDIMessage_RawPayloadText",
    "EDIMessage_CanonicalJSON",
    "EDIMessage_GeneratedFromTable",
    "EDIMessage_GeneratedFromID",
    "EDIMessage_AckDueAt",
    "EDIMessage_CreatedBy"
  )
  VALUES (
    v_profile."EDIMP_ID",
    v_profile."EDIMP_ConnectionID",
    v_profile."EDIMP_TradingPartnerID",
    'outbound',
    v_profile."EDIMP_MessageTypeCode",
    v_profile."EDIMP_StandardCode",
    'queued',
    v_ack_status,
    p_document_reference,
    p_job_id,
    p_payload_text,
    COALESCE(p_payload_json, '{}'::jsonb),
    p_generated_from_table,
    p_generated_from_id,
    CASE
      WHEN v_profile."EDIMP_RequiresAcknowledgement" AND v_profile."EDIMP_AcknowledgementDueMinutes" IS NOT NULL
      THEN now() + make_interval(mins => v_profile."EDIMP_AcknowledgementDueMinutes")
      ELSE NULL
    END,
    p_created_by
  )
  RETURNING "EDIMessage_ID" INTO v_message_id;

  INSERT INTO public."EDI_OutboundQueue" (
    "EDIOutQ_MessageID",
    "EDIOutQ_MessageProfileID",
    "EDIOutQ_ConnectionID",
    "EDIOutQ_StatusCode"
  )
  VALUES (
    v_message_id,
    v_profile."EDIMP_ID",
    v_profile."EDIMP_ConnectionID",
    'queued'
  );

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    v_message_id,
    'queued',
    'queued',
    'Outbound EDI message queued.',
    p_created_by
  );

  RETURN v_message_id;
END;
$$;


ALTER FUNCTION "public"."EDI_QueueOutboundMessage"("p_message_profile_id" "uuid", "p_job_id" "uuid", "p_generated_from_table" character varying, "p_generated_from_id" "uuid", "p_document_reference" character varying, "p_payload_json" "jsonb", "p_payload_text" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."EDI_RecordAcknowledgement"("p_original_message_id" "uuid", "p_ack_type_code" character varying, "p_ack_status_code" character varying, "p_direction_code" character varying DEFAULT 'inbound'::character varying, "p_control_number" character varying DEFAULT NULL::character varying, "p_response_code" character varying DEFAULT NULL::character varying, "p_response_text" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_ack_id uuid;
BEGIN
  INSERT INTO public."EDI_Acknowledgements" (
    "EDIAck_OriginalMessageID",
    "EDIAck_AcknowledgementTypeCode",
    "EDIAck_StatusCode",
    "EDIAck_DirectionCode",
    "EDIAck_ControlNumber",
    "EDIAck_ResponseCode",
    "EDIAck_ResponseText",
    "EDIAck_ReceivedAt",
    "EDIAck_SentAt",
    "EDIAck_CreatedBy"
  )
  VALUES (
    p_original_message_id,
    p_ack_type_code,
    p_ack_status_code,
    p_direction_code,
    p_control_number,
    p_response_code,
    p_response_text,
    CASE WHEN p_direction_code = 'inbound' THEN now() ELSE NULL END,
    CASE WHEN p_direction_code = 'outbound' THEN now() ELSE NULL END,
    p_created_by
  )
  RETURNING "EDIAck_ID" INTO v_ack_id;

  UPDATE public."EDI_Messages"
  SET "EDIMessage_AcknowledgementStatusCode" = p_ack_status_code,
      "EDIMessage_StatusCode" = CASE
        WHEN p_ack_status_code IN ('accepted', 'accepted_with_errors') THEN 'acknowledged'
        WHEN p_ack_status_code = 'rejected' THEN 'rejected'
        ELSE "EDIMessage_StatusCode"
      END,
      "EDIMessage_UpdatedAt" = now(),
      "EDIMessage_UpdatedBy" = p_created_by
  WHERE "EDIMessage_ID" = p_original_message_id;

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    p_original_message_id,
    'acknowledged',
    CASE WHEN p_ack_status_code = 'rejected' THEN 'rejected' ELSE 'acknowledged' END,
    COALESCE(p_response_text, 'EDI acknowledgement recorded.'),
    p_created_by
  );

  RETURN v_ack_id;
END;
$$;


ALTER FUNCTION "public"."EDI_RecordAcknowledgement"("p_original_message_id" "uuid", "p_ack_type_code" character varying, "p_ack_status_code" character varying, "p_direction_code" character varying, "p_control_number" character varying, "p_response_code" character varying, "p_response_text" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."EDI_RecordValidationIssue"("p_message_id" "uuid", "p_severity_code" character varying, "p_issue_code" character varying, "p_description" "text", "p_field_path" "text" DEFAULT NULL::"text", "p_segment_ref" character varying DEFAULT NULL::character varying, "p_suggested_fix" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_issue_id uuid;
  v_is_blocking boolean;
BEGIN
  SELECT "EDIVS_IsBlocking"
  INTO v_is_blocking
  FROM public."sys_EDIValidationSeverities"
  WHERE "EDIVS_Code" = p_severity_code;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EDI validation severity % was not found.', p_severity_code;
  END IF;

  INSERT INTO public."EDI_ValidationIssues" (
    "EDIVI_MessageID",
    "EDIVI_SeverityCode",
    "EDIVI_IssueCode",
    "EDIVI_FieldPath",
    "EDIVI_SegmentRef",
    "EDIVI_Description",
    "EDIVI_SuggestedFix",
    "EDIVI_IsBlocking",
    "EDIVI_CreatedBy"
  )
  VALUES (
    p_message_id,
    p_severity_code,
    p_issue_code,
    p_field_path,
    p_segment_ref,
    p_description,
    p_suggested_fix,
    v_is_blocking,
    p_created_by
  )
  RETURNING "EDIVI_ID" INTO v_issue_id;

  IF v_is_blocking THEN
    UPDATE public."EDI_Messages"
    SET "EDIMessage_StatusCode" = 'failed',
        "EDIMessage_LastErrorText" = p_description,
        "EDIMessage_UpdatedAt" = now(),
        "EDIMessage_UpdatedBy" = p_created_by
    WHERE "EDIMessage_ID" = p_message_id;
  END IF;

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    p_message_id,
    CASE WHEN v_is_blocking THEN 'error' ELSE 'validated' END,
    CASE WHEN v_is_blocking THEN 'failed' ELSE 'validated' END,
    p_description,
    p_created_by
  );

  RETURN v_issue_id;
END;
$$;


