CREATE OR REPLACE FUNCTION "public"."EDI_RegisterInboundMessage"("p_connection_id" "uuid", "p_message_type_code" character varying, "p_standard_code" character varying, "p_payload_text" "text" DEFAULT NULL::"text", "p_file_name" character varying DEFAULT NULL::character varying, "p_control_number" character varying DEFAULT NULL::character varying, "p_received_at" timestamp with time zone DEFAULT "now"(), "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_connection record;
  v_profile_id uuid;
  v_batch_id uuid;
  v_message_id uuid;
BEGIN
  SELECT *
  INTO v_connection
  FROM public."EDI_Connections"
  WHERE "EDIC_ID" = p_connection_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EDI connection % was not found.', p_connection_id;
  END IF;

  SELECT "EDIMP_ID"
  INTO v_profile_id
  FROM public."EDI_MessageProfiles"
  WHERE "EDIMP_ConnectionID" = p_connection_id
    AND "EDIMP_MessageTypeCode" = p_message_type_code
    AND "EDIMP_StandardCode" = p_standard_code
    AND "EDIMP_DirectionCode" IN ('inbound', 'bidirectional')
    AND "EDIMP_IsActive" = true
  ORDER BY "EDIMP_CreatedAt" DESC
  LIMIT 1;

  INSERT INTO public."EDI_Batches" (
    "EDIBatch_ConnectionID",
    "EDIBatch_TradingPartnerID",
    "EDIBatch_DirectionCode",
    "EDIBatch_StandardCode",
    "EDIBatch_StatusCode",
    "EDIBatch_InterchangeControlNumber",
    "EDIBatch_FileName",
    "EDIBatch_PayloadStorageTypeCode",
    "EDIBatch_ReceivedAt",
    "EDIBatch_MessageCount",
    "EDIBatch_CreatedBy"
  )
  VALUES (
    p_connection_id,
    v_connection."EDIC_TradingPartnerID",
    'inbound',
    p_standard_code,
    'received',
    p_control_number,
    p_file_name,
    'database_text',
    COALESCE(p_received_at, now()),
    1,
    p_created_by
  )
  RETURNING "EDIBatch_ID" INTO v_batch_id;

  INSERT INTO public."EDI_Messages" (
    "EDIMessage_BatchID",
    "EDIMessage_MessageProfileID",
    "EDIMessage_ConnectionID",
    "EDIMessage_TradingPartnerID",
    "EDIMessage_DirectionCode",
    "EDIMessage_MessageTypeCode",
    "EDIMessage_StandardCode",
    "EDIMessage_StatusCode",
    "EDIMessage_AcknowledgementStatusCode",
    "EDIMessage_ControlNumber",
    "EDIMessage_RawPayloadText",
    "EDIMessage_ReceivedAt",
    "EDIMessage_CreatedBy"
  )
  VALUES (
    v_batch_id,
    v_profile_id,
    p_connection_id,
    v_connection."EDIC_TradingPartnerID",
    'inbound',
    p_message_type_code,
    p_standard_code,
    'received',
    'not_required',
    p_control_number,
    p_payload_text,
    COALESCE(p_received_at, now()),
    p_created_by
  )
  RETURNING "EDIMessage_ID" INTO v_message_id;

  INSERT INTO public."EDI_InboundQueue" (
    "EDIInQ_ConnectionID",
    "EDIInQ_BatchID",
    "EDIInQ_MessageID",
    "EDIInQ_StatusCode",
    "EDIInQ_SourceFileName",
    "EDIInQ_RawPayloadText",
    "EDIInQ_ReceivedAt"
  )
  VALUES (
    p_connection_id,
    v_batch_id,
    v_message_id,
    'received',
    p_file_name,
    p_payload_text,
    COALESCE(p_received_at, now())
  );

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_BatchID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    v_message_id,
    v_batch_id,
    'received',
    'received',
    'Inbound EDI message registered.',
    p_created_by
  );

  RETURN v_message_id;
END;
$$;


