CREATE OR REPLACE FUNCTION "public"."FIN_CalculatePulledRate"("p_base_rate" numeric, "p_adjustment_method_code" "text", "p_adjustment_amount" numeric DEFAULT 0, "p_adjustment_percent" numeric DEFAULT 0, "p_rounding_precision" integer DEFAULT 6) RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_method text := coalesce(lower(p_adjustment_method_code), 'none');
  v_rate numeric;
BEGIN
  IF p_base_rate IS NULL THEN
    RETURN NULL;
  END IF;

  v_rate := CASE v_method
    WHEN 'amount_add' THEN p_base_rate + coalesce(p_adjustment_amount, 0)
    WHEN 'amount_subtract' THEN p_base_rate - coalesce(p_adjustment_amount, 0)
    WHEN 'percent_add' THEN p_base_rate * (1 + coalesce(p_adjustment_percent, 0) / 100)
    WHEN 'percent_subtract' THEN p_base_rate * (1 - coalesce(p_adjustment_percent, 0) / 100)
    WHEN 'spread_buy_sell' THEN p_base_rate + coalesce(p_adjustment_amount, 0) + (p_base_rate * coalesce(p_adjustment_percent, 0) / 100)
    ELSE p_base_rate
  END;

  RETURN round(v_rate, greatest(coalesce(p_rounding_precision, 6), 0));
END;
$$;


ALTER FUNCTION "public"."FIN_CalculatePulledRate"("p_base_rate" numeric, "p_adjustment_method_code" "text", "p_adjustment_amount" numeric, "p_adjustment_percent" numeric, "p_rounding_precision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."FIN_GetNextOpenPeriod"("p_legal_entity_id" "uuid", "p_org_office_id" "uuid", "p_ledger_type_code" "text", "p_accounting_date" "date") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT p."FINPeriod_ID"
  FROM public."FIN_Periods" p
  WHERE p."FINPeriod_StatusCode" = 'open'
    AND (p_legal_entity_id IS NULL OR p."FINPeriod_LegalEntityID" IS NULL OR p."FINPeriod_LegalEntityID" = p_legal_entity_id)
    AND (p_org_office_id IS NULL OR p."FINPeriod_OrgOfficeID" IS NULL OR p."FINPeriod_OrgOfficeID" = p_org_office_id)
    AND p."FINPeriod_EndDate" >= coalesce(p_accounting_date, current_date)
  ORDER BY
    CASE WHEN coalesce(p_accounting_date, current_date) BETWEEN p."FINPeriod_StartDate" AND p."FINPeriod_EndDate" THEN 0 ELSE 1 END,
    p."FINPeriod_StartDate"
  LIMIT 1;
$$;


