CREATE OR REPLACE FUNCTION "public"."LOC_GetUTCOffsetMinutes"("p_utc_value" timestamp with time zone, "p_time_zone" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  tz varchar(80);
  local_ts timestamp;
  utc_ts timestamp;
BEGIN
  tz := public."LOC_ResolveTimeZoneCode"(p_time_zone);
  local_ts := p_utc_value AT TIME ZONE tz;
  utc_ts := p_utc_value AT TIME ZONE 'UTC';
  RETURN round(extract(epoch from (local_ts - utc_ts)) / 60)::integer;
END;
$$;


ALTER FUNCTION "public"."LOC_GetUTCOffsetMinutes"("p_utc_value" timestamp with time zone, "p_time_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."LOC_LocalToUTC"("p_local_date" "date", "p_local_time" time without time zone, "p_time_zone" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  tz varchar(80);
BEGIN
  IF p_local_date IS NULL OR p_local_time IS NULL THEN
    RETURN NULL;
  END IF;

  tz := public."LOC_ResolveTimeZoneCode"(p_time_zone);
  RETURN (p_local_date + p_local_time)::timestamp AT TIME ZONE tz;
END;
$$;


ALTER FUNCTION "public"."LOC_LocalToUTC"("p_local_date" "date", "p_local_time" time without time zone, "p_time_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."LOC_ResolveTimeZoneCode"("p_time_zone" "text") RETURNS character varying
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  resolved varchar(80);
BEGIN
  IF p_time_zone IS NULL OR btrim(p_time_zone) = '' THEN
    RETURN 'UTC';
  END IF;

  SELECT "LOCTZ_Code"
    INTO resolved
  FROM public."sys_LOCTimeZones"
  WHERE lower("LOCTZ_Code") = lower(btrim(p_time_zone))
    AND "LOCTZ_IsActive" = true
  LIMIT 1;

  IF resolved IS NOT NULL THEN
    RETURN resolved;
  END IF;

  SELECT a."LOCTZA_TimeZoneCode"
    INTO resolved
  FROM public."sys_LOCTimeZoneAliases" a
  JOIN public."sys_LOCTimeZones" z
    ON z."LOCTZ_Code" = a."LOCTZA_TimeZoneCode"
  WHERE lower(a."LOCTZA_AliasCode") = lower(btrim(p_time_zone))
    AND a."LOCTZA_IsActive" = true
    AND z."LOCTZ_IsActive" = true
  LIMIT 1;

  IF resolved IS NOT NULL THEN
    RETURN resolved;
  END IF;

  RAISE EXCEPTION 'Unknown or inactive time zone: %', p_time_zone
    USING ERRCODE = '22023';
END;
$$;


ALTER FUNCTION "public"."LOC_ResolveTimeZoneCode"("p_time_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."LOC_UTCToLocal"("p_utc_value" timestamp with time zone, "p_time_zone" "text") RETURNS TABLE("TimeZoneCode" character varying, "LocalDateTime" timestamp without time zone, "LocalDate" "date", "LocalTime" time without time zone, "UTCOffsetMinutes" integer)
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  tz varchar(80);
  local_ts timestamp;
BEGIN
  IF p_utc_value IS NULL THEN
    RETURN;
  END IF;

  tz := public."LOC_ResolveTimeZoneCode"(p_time_zone);
  local_ts := p_utc_value AT TIME ZONE tz;

  RETURN QUERY
  SELECT
    tz::varchar,
    local_ts,
    local_ts::date,
    local_ts::time without time zone,
    public."LOC_GetUTCOffsetMinutes"(p_utc_value, tz);
END;
$$;


ALTER FUNCTION "public"."LOC_UTCToLocal"("p_utc_value" timestamp with time zone, "p_time_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."LOC_UpsertRecordDateTimeContext"("p_source_table" character varying, "p_source_record_id" "uuid", "p_source_field" character varying, "p_local_date" "date", "p_local_time" time without time zone, "p_time_zone" "text", "p_source_locale" character varying DEFAULT NULL::character varying, "p_source_text" "text" DEFAULT NULL::"text", "p_confidence" numeric DEFAULT NULL::numeric, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  tz varchar(80);
  utc_value timestamptz;
  local_ts timestamp;
  offset_minutes integer;
BEGIN
  IF p_source_table IS NULL OR btrim(p_source_table) = '' THEN
    RAISE EXCEPTION 'Source table is required' USING ERRCODE = '22023';
  END IF;
  IF p_source_record_id IS NULL THEN
    RAISE EXCEPTION 'Source record ID is required' USING ERRCODE = '22023';
  END IF;
  IF p_source_field IS NULL OR btrim(p_source_field) = '' THEN
    RAISE EXCEPTION 'Source field is required' USING ERRCODE = '22023';
  END IF;

  tz := public."LOC_ResolveTimeZoneCode"(p_time_zone);
  utc_value := public."LOC_LocalToUTC"(p_local_date, p_local_time, tz);
  local_ts := utc_value AT TIME ZONE tz;
  offset_minutes := public."LOC_GetUTCOffsetMinutes"(utc_value, tz);

  UPDATE public."LOC_RecordDateTimeContexts"
  SET "LOCDTContext_IsCurrent" = false
  WHERE "LOCDTContext_SourceTable" = p_source_table
    AND "LOCDTContext_SourceRecordID" = p_source_record_id
    AND "LOCDTContext_SourceField" = p_source_field
    AND "LOCDTContext_IsCurrent" = true;

  INSERT INTO public."LOC_RecordDateTimeContexts" (
    "LOCDTContext_SourceTable",
    "LOCDTContext_SourceRecordID",
    "LOCDTContext_SourceField",
    "LOCDTContext_UTCValue",
    "LOCDTContext_LocalDate",
    "LOCDTContext_LocalTime",
    "LOCDTContext_LocalDateTime",
    "LOCDTContext_TimeZoneCode",
    "LOCDTContext_UTCOffsetMinutes",
    "LOCDTContext_SourceLocaleCode",
    "LOCDTContext_SourceText",
    "LOCDTContext_Confidence",
    "LOCDTContext_CreatedBy"
  )
  VALUES (
    p_source_table,
    p_source_record_id,
    p_source_field,
    utc_value,
    local_ts::date,
    local_ts::time without time zone,
    local_ts,
    tz,
    offset_minutes,
    p_source_locale,
    p_source_text,
    p_confidence,
    p_created_by
  );

  RETURN utc_value;
END;
$$;


ALTER FUNCTION "public"."LOC_UpsertRecordDateTimeContext"("p_source_table" character varying, "p_source_record_id" "uuid", "p_source_field" character varying, "p_local_date" "date", "p_local_time" time without time zone, "p_time_zone" "text", "p_source_locale" character varying, "p_source_text" "text", "p_confidence" numeric, "p_created_by" "uuid") OWNER TO "postgres";


