CREATE OR REPLACE FUNCTION "public"."Portal_CreateRecordShare"("p_site_id" "uuid", "p_resource_type_code" character varying, "p_target_table" character varying, "p_target_id" "uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_portal_user_id" "uuid" DEFAULT NULL::"uuid", "p_role_id" "uuid" DEFAULT NULL::"uuid", "p_allowed_actions" "jsonb" DEFAULT '["view"]'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_share_id uuid;
BEGIN
  IF p_org_id IS NULL AND p_contact_id IS NULL AND p_portal_user_id IS NULL AND p_role_id IS NULL THEN
    RAISE EXCEPTION 'Portal_CreateRecordShare requires org, contact, portal user or role';
  END IF;

  INSERT INTO public."Portal_RecordShares" (
    "PortalShare_SiteID",
    "PortalShare_ResourceTypeCode",
    "PortalShare_TargetTable",
    "PortalShare_TargetID",
    "PortalShare_JobID",
    "PortalShare_OrgID",
    "PortalShare_ContactID",
    "PortalShare_PortalUserID",
    "PortalShare_RoleID",
    "PortalShare_AllowedActionsJSON",
    "PortalShare_SourceType",
    "PortalShare_CreatedBy"
  ) VALUES (
    p_site_id,
    p_resource_type_code,
    p_target_table,
    p_target_id,
    p_job_id,
    p_org_id,
    p_contact_id,
    p_portal_user_id,
    p_role_id,
    COALESCE(p_allowed_actions, '["view"]'::jsonb),
    'manual',
    p_created_by
  )
  RETURNING "PortalShare_ID" INTO v_share_id;

  PERFORM public."Portal_RecordAuditEvent"(
    'permission_changed',
    p_site_id,
    p_portal_user_id,
    NULL,
    p_org_id,
    p_resource_type_code,
    p_target_table,
    p_target_id,
    'Portal record share created',
    jsonb_build_object('PortalShare_ID', v_share_id)
  );

  RETURN v_share_id;
END;
$$;


