CREATE OR REPLACE FUNCTION "public"."RATE_CreateRateRequest"("p_code" character varying, "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_carrier_org_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_cus_quote_rev_id" "uuid" DEFAULT NULL::"uuid", "p_mode_code" character varying DEFAULT NULL::character varying, "p_shipment_type_code" character varying DEFAULT NULL::character varying, "p_direction_code" character varying DEFAULT 'any'::character varying, "p_origin_unlocode" character varying DEFAULT NULL::character varying, "p_destination_unlocode" character varying DEFAULT NULL::character varying, "p_currency_code" character varying DEFAULT NULL::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_request_id uuid;
BEGIN
  INSERT INTO public."RATE_RateRequests" (
    "RATERequest_Code",
    "RATERequest_StatusCode",
    "RATERequest_CustomerOrgID",
    "RATERequest_CarrierOrgID",
    "RATERequest_JobID",
    "RATERequest_CusQuoteRevID",
    "RATERequest_ModeCode",
    "RATERequest_ShipmentTypeCode",
    "RATERequest_DirectionCode",
    "RATERequest_OriginUNLocode",
    "RATERequest_DestinationUNLocode",
    "RATERequest_CurrencyCodeSnapshot",
    "RATERequest_CreatedBy"
  ) VALUES (
    p_code,
    'draft',
    p_customer_org_id,
    p_carrier_org_id,
    p_job_id,
    p_cus_quote_rev_id,
    p_mode_code,
    p_shipment_type_code,
    COALESCE(p_direction_code, 'any'),
    p_origin_unlocode,
    p_destination_unlocode,
    p_currency_code,
    p_created_by
  )
  RETURNING "RATERequest_ID" INTO v_request_id;

  PERFORM public."RATE_RecordAuditEvent"(
    'rate_request_created',
    'RATE_RateRequests',
    v_request_id,
    NULL,
    v_request_id,
    NULL,
    'Rate request created',
    '{}'::jsonb,
    p_created_by
  );

  RETURN v_request_id;
END;
$$;


ALTER FUNCTION "public"."RATE_CreateRateRequest"("p_code" character varying, "p_customer_org_id" "uuid", "p_carrier_org_id" "uuid", "p_job_id" "uuid", "p_cus_quote_rev_id" "uuid", "p_mode_code" character varying, "p_shipment_type_code" character varying, "p_direction_code" character varying, "p_origin_unlocode" character varying, "p_destination_unlocode" character varying, "p_currency_code" character varying, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."RATE_CreateRateResult"("p_request_id" "uuid", "p_source_type_code" character varying DEFAULT 'manual'::character varying, "p_contract_id" "uuid" DEFAULT NULL::"uuid", "p_contract_ver_id" "uuid" DEFAULT NULL::"uuid", "p_rate_sheet_id" "uuid" DEFAULT NULL::"uuid", "p_carrier_org_id" "uuid" DEFAULT NULL::"uuid", "p_carrier_name_snapshot" character varying DEFAULT NULL::character varying, "p_currency_code" character varying DEFAULT NULL::character varying, "p_buy_total" numeric DEFAULT 0, "p_sell_total" numeric DEFAULT 0, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_result_id uuid;
  v_margin numeric(18,4);
  v_margin_percent numeric(9,6);
BEGIN
  v_margin := COALESCE(p_sell_total, 0) - COALESCE(p_buy_total, 0);
  IF COALESCE(p_sell_total, 0) <> 0 THEN
    v_margin_percent := ROUND((v_margin / p_sell_total)::numeric, 6);
  ELSE
    v_margin_percent := NULL;
  END IF;

  INSERT INTO public."RATE_RateResults" (
    "RATEResult_RequestID",
    "RATEResult_StatusCode",
    "RATEResult_SourceTypeCode",
    "RATEResult_ContractID",
    "RATEResult_ContractVerID",
    "RATEResult_RateSheetID",
    "RATEResult_CarrierOrgID",
    "RATEResult_CarrierNameSnapshot",
    "RATEResult_CurrencyCodeSnapshot",
    "RATEResult_BuyTotal",
    "RATEResult_SellTotal",
    "RATEResult_MarginAmount",
    "RATEResult_MarginPercent",
    "RATEResult_CreatedBy"
  ) VALUES (
    p_request_id,
    'candidate',
    COALESCE(p_source_type_code, 'manual'),
    p_contract_id,
    p_contract_ver_id,
    p_rate_sheet_id,
    p_carrier_org_id,
    p_carrier_name_snapshot,
    p_currency_code,
    COALESCE(p_buy_total, 0),
    COALESCE(p_sell_total, 0),
    v_margin,
    v_margin_percent,
    p_created_by
  )
  RETURNING "RATEResult_ID" INTO v_result_id;

  UPDATE public."RATE_RateRequests"
  SET "RATERequest_StatusCode" = 'rated',
      "RATERequest_UpdatedAt" = now(),
      "RATERequest_UpdatedBy" = p_created_by
  WHERE "RATERequest_ID" = p_request_id;

  PERFORM public."RATE_RecordAuditEvent"(
    'rate_result_created',
    'RATE_RateResults',
    v_result_id,
    p_contract_id,
    p_request_id,
    v_result_id,
    'Rate result created',
    jsonb_build_object('buy_total', COALESCE(p_buy_total, 0), 'sell_total', COALESCE(p_sell_total, 0)),
    p_created_by
  );

  RETURN v_result_id;
END;
$$;


ALTER FUNCTION "public"."RATE_CreateRateResult"("p_request_id" "uuid", "p_source_type_code" character varying, "p_contract_id" "uuid", "p_contract_ver_id" "uuid", "p_rate_sheet_id" "uuid", "p_carrier_org_id" "uuid", "p_carrier_name_snapshot" character varying, "p_currency_code" character varying, "p_buy_total" numeric, "p_sell_total" numeric, "p_created_by" "uuid") OWNER TO "postgres";


