    "SECCred_ModuleCode" = EXCLUDED."SECCred_ModuleCode",
    "SECCred_ProviderCode" = EXCLUDED."SECCred_ProviderCode",
    "SECCred_VaultProvider" = EXCLUDED."SECCred_VaultProvider",
