CREATE OR REPLACE FUNCTION "public"."SEC_UserHasPermission"("p_user_id" "uuid", "p_permission_code" "text", "p_org_office_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM public."SEC_UserEffectivePermissions" ep
    WHERE ep."UserID" = p_user_id
      AND ep."PermissionCode" = p_permission_code
      AND ep."GrantActionCode" = 'allow'
      AND (
        p_org_office_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public."SEC_UserOfficeAccess" uo
          WHERE uo."SECUserOffice_UserID" = p_user_id
            AND uo."SECUserOffice_OrgOfficeID" = p_org_office_id
            AND uo."SECUserOffice_StatusCode" = 'active'
            AND uo."SECUserOffice_CanView" = true
            AND now() >= uo."SECUserOffice_EffectiveFrom"
            AND (uo."SECUserOffice_EffectiveTo" IS NULL OR now() < uo."SECUserOffice_EffectiveTo")
        )
        OR EXISTS (
          SELECT 1
          FROM public."SEC_RoleScopes" rs
          WHERE rs."SECRoleScope_RoleID" = ep."RoleID"
            AND rs."SECRoleScope_StatusCode" = 'active'
            AND (
              rs."SECRoleScope_ScopeTypeCode" = 'all_company'
              OR (rs."SECRoleScope_ScopeTypeCode" = 'office' AND rs."SECRoleScope_OrgOfficeID" = p_org_office_id)
            )
        )
      )
  );
END;
$$;


ALTER FUNCTION "public"."SEC_UserHasPermission"("p_user_id" "uuid", "p_permission_code" "text", "p_org_office_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_AddCaseDecision"("p_case_id" "uuid", "p_decision_type_code" character varying, "p_status_to_code" character varying, "p_reason" "text", "p_decided_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_decision_id uuid;
  v_case public."TCE_ComplianceCases"%ROWTYPE;
  v_is_blocking boolean;
  v_hold_id uuid;
  v_checklist_id uuid;
BEGIN
  SELECT * INTO v_case
  FROM public."TCE_ComplianceCases"
  WHERE "TCECase_ID" = p_case_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Compliance case % not found', p_case_id;
  END IF;

  SELECT "TCEDecisionType_IsBlocking"
  INTO v_is_blocking
  FROM public."sys_TCEDecisionTypes"
  WHERE "TCEDecisionType_Code" = p_decision_type_code;

  INSERT INTO public."TCE_CaseDecisions" (
    "TCEDecision_CaseID",
    "TCEDecision_DecisionTypeCode",
    "TCEDecision_StatusToCode",
    "TCEDecision_Reason",
    "TCEDecision_DecidedBy"
  )
  VALUES (
    p_case_id,
    p_decision_type_code,
    p_status_to_code,
    p_reason,
    p_decided_by
  )
  RETURNING "TCEDecision_ID" INTO v_decision_id;

  UPDATE public."TCE_ComplianceCases"
  SET
    "TCECase_StatusCode" = coalesce(p_status_to_code, "TCECase_StatusCode"),
    "TCECase_ClosedAt" = CASE WHEN p_status_to_code IN ('cleared', 'closed') THEN now() ELSE "TCECase_ClosedAt" END,
    "TCECase_ClosedBy" = CASE WHEN p_status_to_code IN ('cleared', 'closed') THEN p_decided_by ELSE "TCECase_ClosedBy" END,
    "TCECase_UpdatedAt" = now(),
    "TCECase_UpdatedBy" = p_decided_by
  WHERE "TCECase_ID" = p_case_id;

  IF coalesce(v_is_blocking, false) AND v_case."TCECase_JobID" IS NOT NULL THEN
    INSERT INTO public."TCE_ComplianceHolds" (
      "TCEHold_StatusCode",
      "TCEHold_ActionTypeCode",
      "TCEHold_CaseID",
      "TCEHold_RunID",
      "TCEHold_JobID",
      "TCEHold_SourceRecordTypeCode",
      "TCEHold_SourceTable",
      "TCEHold_SourceID",
      "TCEHold_Reason",
      "TCEHold_HeldBy"
    )
    VALUES (
      'active',
      CASE WHEN p_decision_type_code = 'block' THEN 'put_job_on_hold' ELSE 'escalate' END,
      p_case_id,
      v_case."TCECase_RunID",
      v_case."TCECase_JobID",
      'tce_case',
      'TCE_ComplianceCases',
      p_case_id,
      p_reason,
      p_decided_by
    )
    RETURNING "TCEHold_ID" INTO v_hold_id;

    UPDATE public."TCE_ComplianceCheckItems"
    SET
      "TCECheckItem_StatusCode" = 'blocked',
      "TCECheckItem_HoldID" = v_hold_id,
      "TCECheckItem_IsBlocking" = true,
      "TCECheckItem_ResultSummary" = p_reason,
      "TCECheckItem_CompletedAt" = now(),
      "TCECheckItem_CompletedBy" = p_decided_by,
      "TCECheckItem_UpdatedAt" = now(),
      "TCECheckItem_UpdatedBy" = p_decided_by
    WHERE "TCECheckItem_CaseID" = p_case_id
       OR "TCECheckItem_ScreeningRunID" = v_case."TCECase_RunID";

    UPDATE public."TCE_ReleaseGates" gate
    SET
      "TCEGate_StatusCode" = 'blocked',
      "TCEGate_HoldID" = v_hold_id,
      "TCEGate_BlockReason" = p_reason,
      "TCEGate_UpdatedAt" = now(),
      "TCEGate_UpdatedBy" = p_decided_by
    WHERE gate."TCEGate_StatusCode" IN ('pending', 'required', 'in_progress', 'review_required', 'blocked')
      AND (
        gate."TCEGate_JobID" = v_case."TCECase_JobID"
        OR gate."TCEGate_ChecklistID" IN (
          SELECT item."TCECheckItem_ChecklistID"
          FROM public."TCE_ComplianceCheckItems" item
          WHERE item."TCECheckItem_CaseID" = p_case_id
             OR item."TCECheckItem_ScreeningRunID" = v_case."TCECase_RunID"
        )
      );

    UPDATE public."TCE_ScreeningRuns"
    SET "TCERun_StatusCode" = 'blocked'
    WHERE "TCERun_ID" = v_case."TCECase_RunID";
  ELSIF p_decision_type_code IN ('clear', 'false_positive', 'release') THEN
    UPDATE public."TCE_ComplianceCheckItems"
    SET
      "TCECheckItem_StatusCode" = 'clear',
      "TCECheckItem_IsBlocking" = false,
      "TCECheckItem_ResultSummary" = p_reason,
      "TCECheckItem_CompletedAt" = now(),
      "TCECheckItem_CompletedBy" = p_decided_by,
      "TCECheckItem_UpdatedAt" = now(),
      "TCECheckItem_UpdatedBy" = p_decided_by
    WHERE "TCECheckItem_CaseID" = p_case_id
       OR "TCECheckItem_ScreeningRunID" = v_case."TCECase_RunID";

    UPDATE public."TCE_ReleaseGates" gate
    SET
      "TCEGate_StatusCode" = 'clear',
      "TCEGate_ClearedAt" = now(),
      "TCEGate_ClearedBy" = p_decided_by,
      "TCEGate_UpdatedAt" = now(),
      "TCEGate_UpdatedBy" = p_decided_by
    WHERE gate."TCEGate_StatusCode" IN ('pending', 'required', 'in_progress', 'review_required')
      AND (
        gate."TCEGate_JobID" = v_case."TCECase_JobID"
        OR gate."TCEGate_ChecklistID" IN (
          SELECT item."TCECheckItem_ChecklistID"
          FROM public."TCE_ComplianceCheckItems" item
          WHERE item."TCECheckItem_CaseID" = p_case_id
             OR item."TCECheckItem_ScreeningRunID" = v_case."TCECase_RunID"
        )
      );

    UPDATE public."TCE_ScreeningRuns"
    SET "TCERun_StatusCode" = 'released'
    WHERE "TCERun_ID" = v_case."TCECase_RunID"
      AND "TCERun_StatusCode" <> 'blocked';
  END IF;

  FOR v_checklist_id IN
    SELECT DISTINCT item."TCECheckItem_ChecklistID"
    FROM public."TCE_ComplianceCheckItems" item
    WHERE item."TCECheckItem_CaseID" = p_case_id
       OR item."TCECheckItem_ScreeningRunID" = v_case."TCECase_RunID"
  LOOP
    PERFORM public."TCE_RefreshChecklistStatus"(v_checklist_id, p_decided_by);
  END LOOP;

  RETURN v_decision_id;
END;
$$;


ALTER FUNCTION "public"."TCE_AddCaseDecision"("p_case_id" "uuid", "p_decision_type_code" character varying, "p_status_to_code" character varying, "p_reason" "text", "p_decided_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_AddComplianceCheckItem"("p_checklist_id" "uuid", "p_check_type_code" character varying, "p_status_code" character varying DEFAULT 'required'::character varying, "p_source_table" character varying DEFAULT NULL::character varying, "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_job_cargo_id" "uuid" DEFAULT NULL::"uuid", "p_job_document_id" "uuid" DEFAULT NULL::"uuid", "p_screening_run_id" "uuid" DEFAULT NULL::"uuid", "p_required_before_action_code" character varying DEFAULT NULL::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_item_id uuid;
  v_action_type varchar(60);
  v_job_id uuid;
  v_is_blocking boolean;
BEGIN
  SELECT "TCECheckType_DefaultActionTypeCode", "TCECheckType_IsBlockingCandidate"
  INTO v_action_type, v_is_blocking
  FROM public."sys_TCECheckTypes"
  WHERE "TCECheckType_Code" = p_check_type_code;

  IF v_action_type IS NULL THEN
    RAISE EXCEPTION 'Compliance check type % not found', p_check_type_code;
  END IF;

  SELECT coalesce(p_job_id, "TCEChecklist_JobID")
  INTO v_job_id
  FROM public."TCE_ComplianceChecklists"
  WHERE "TCEChecklist_ID" = p_checklist_id;

  INSERT INTO public."TCE_ComplianceCheckItems" (
    "TCECheckItem_ChecklistID",
    "TCECheckItem_CheckTypeCode",
    "TCECheckItem_StatusCode",
    "TCECheckItem_ActionTypeCode",
    "TCECheckItem_JobID",
    "TCECheckItem_JobCargoID",
    "TCECheckItem_JobDocumentID",
    "TCECheckItem_OrgID",
    "TCECheckItem_ScreeningRunID",
    "TCECheckItem_SourceTable",
    "TCECheckItem_SourceID",
    "TCECheckItem_RequiredBeforeActionCode",
    "TCECheckItem_IsBlocking",
    "TCECheckItem_CreatedBy"
  )
  VALUES (
    p_checklist_id,
    p_check_type_code,
    coalesce(p_status_code, 'required'),
    v_action_type,
    v_job_id,
    p_job_cargo_id,
    p_job_document_id,
    p_org_id,
    p_screening_run_id,
    p_source_table,
    p_source_id,
    p_required_before_action_code,
    coalesce(v_is_blocking, false) AND coalesce(p_status_code, 'required') IN ('review_required', 'blocked'),
    p_created_by
  )
  RETURNING "TCECheckItem_ID" INTO v_item_id;

  PERFORM public."TCE_RefreshChecklistStatus"(p_checklist_id, p_created_by);

  RETURN v_item_id;
END;
$$;


ALTER FUNCTION "public"."TCE_AddComplianceCheckItem"("p_checklist_id" "uuid", "p_check_type_code" character varying, "p_status_code" character varying, "p_source_table" character varying, "p_source_id" "uuid", "p_job_id" "uuid", "p_org_id" "uuid", "p_job_cargo_id" "uuid", "p_job_document_id" "uuid", "p_screening_run_id" "uuid", "p_required_before_action_code" character varying, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_AddScreeningSubject"("p_run_id" "uuid", "p_role_code" character varying, "p_entity_type_code" character varying, "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_name" character varying DEFAULT NULL::character varying, "p_country_code" character varying DEFAULT NULL::character varying, "p_identifier_type" character varying DEFAULT NULL::character varying, "p_identifier_value" character varying DEFAULT NULL::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_subject_id uuid;
  v_name varchar(420);
BEGIN
  IF p_name IS NULL AND p_org_id IS NOT NULL THEN
    SELECT "Org_Name" INTO v_name
    FROM public."Org_Master"
    WHERE "Org_ID" = p_org_id;
  ELSE
    v_name := p_name;
  END IF;

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'Screening subject name is required.';
  END IF;

  INSERT INTO public."TCE_ScreeningSubjects" (
    "TCESubject_RunID",
    "TCESubject_RoleCode",
    "TCESubject_EntityTypeCode",
    "TCESubject_StatusCode",
    "TCESubject_OrgID",
    "TCESubject_Name",
    "TCESubject_NormalizedName",
    "TCESubject_CountryCode",
    "TCESubject_IdentifierType",
    "TCESubject_IdentifierValue",
    "TCESubject_CreatedBy"
  )
  VALUES (
    p_run_id,
    p_role_code,
    p_entity_type_code,
    'pending',
    p_org_id,
    v_name,
    public."TCE_NormalizeName"(v_name),
    p_country_code,
    p_identifier_type,
    p_identifier_value,
    p_created_by
  )
  RETURNING "TCESubject_ID" INTO v_subject_id;

  UPDATE public."TCE_ScreeningRuns"
  SET "TCERun_SubjectCount" = "TCERun_SubjectCount" + 1
  WHERE "TCERun_ID" = p_run_id;

  RETURN v_subject_id;
END;
$$;


ALTER FUNCTION "public"."TCE_AddScreeningSubject"("p_run_id" "uuid", "p_role_code" character varying, "p_entity_type_code" character varying, "p_org_id" "uuid", "p_name" character varying, "p_country_code" character varying, "p_identifier_type" character varying, "p_identifier_value" character varying, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_CreateComplianceChecklist"("p_job_id" "uuid", "p_touchpoint_type_code" character varying, "p_policy_id" "uuid" DEFAULT NULL::"uuid", "p_source_table" character varying DEFAULT NULL::character varying, "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_required_before_action_code" character varying DEFAULT NULL::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_checklist_id uuid;
  v_number varchar(80);
  v_customer_org_id uuid;
  v_office_id uuid;
  v_rule_count integer := 0;
  v_rule record;
  v_default_check varchar(60);
BEGIN
  IF p_job_id IS NOT NULL THEN
    SELECT "Job_Customer", "Job_OrgOfficeID"
    INTO v_customer_org_id, v_office_id
    FROM public."Job_Header"
    WHERE "Job_ID" = p_job_id;
  END IF;

  v_number := 'TCE-CHK-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' || upper(substr(gen_random_uuid()::text, 1, 8));

  INSERT INTO public."TCE_ComplianceChecklists" (
    "TCEChecklist_Number",
    "TCEChecklist_StatusCode",
    "TCEChecklist_TouchpointTypeCode",
    "TCEChecklist_PolicyID",
    "TCEChecklist_JobID",
    "TCEChecklist_CustomerOrgID",
    "TCEChecklist_OrgOfficeID",
    "TCEChecklist_SourceRecordTypeCode",
    "TCEChecklist_SourceTable",
    "TCEChecklist_SourceID",
    "TCEChecklist_CreatedBy"
  )
  VALUES (
    v_number,
    'pending',
    p_touchpoint_type_code,
    p_policy_id,
    p_job_id,
    v_customer_org_id,
    v_office_id,
    CASE WHEN p_source_table = 'Job_Header' OR p_job_id IS NOT NULL THEN 'job' ELSE NULL END,
    coalesce(p_source_table, CASE WHEN p_job_id IS NOT NULL THEN 'Job_Header' ELSE NULL END),
    coalesce(p_source_id, p_job_id),
    p_created_by
  )
  RETURNING "TCEChecklist_ID" INTO v_checklist_id;

  IF p_policy_id IS NOT NULL THEN
    FOR v_rule IN
      SELECT *
      FROM public."TCE_ScreeningTouchpointRules"
      WHERE "TCETouchRule_PolicyID" = p_policy_id
        AND "TCETouchRule_TouchpointTypeCode" = p_touchpoint_type_code
        AND "TCETouchRule_IsActive"
        AND coalesce("TCETouchRule_CreateChecklistItem", true)
      ORDER BY "TCETouchRule_SortOrder", "TCETouchRule_CheckTypeCode"
    LOOP
      v_rule_count := v_rule_count + 1;
      PERFORM public."TCE_AddComplianceCheckItem"(
        v_checklist_id,
        v_rule."TCETouchRule_CheckTypeCode",
        'required',
        coalesce(v_rule."TCETouchRule_AppliesToSourceTable", p_source_table),
        p_source_id,
        p_job_id,
        NULL,
        NULL,
        NULL,
        NULL,
        coalesce(v_rule."TCETouchRule_RequiredBeforeActionCode", p_required_before_action_code),
        p_created_by
      );
    END LOOP;
  END IF;

  IF v_rule_count = 0 THEN
    FOREACH v_default_check IN ARRAY CASE
      WHEN p_touchpoint_type_code IN ('cargo_changed', 'customs_created', 'customs_submission') THEN ARRAY['party_screening', 'country_control', 'goods_control', 'licence_check', 'hs_classification', 'origin_check']
      WHEN p_touchpoint_type_code IN ('document_issued', 'document_uploaded') THEN ARRAY['party_screening', 'document_security']
      WHEN p_touchpoint_type_code IN ('finance_transaction') THEN ARRAY['finance_sanctions', 'party_screening']
      WHEN p_touchpoint_type_code IN ('route_changed') THEN ARRAY['party_screening', 'vessel_screening', 'country_control']
      ELSE ARRAY['party_screening', 'country_control']
    END
    LOOP
      PERFORM public."TCE_AddComplianceCheckItem"(
        v_checklist_id,
        v_default_check,
        'required',
        p_source_table,
        p_source_id,
        p_job_id,
        NULL,
        NULL,
        NULL,
        NULL,
        p_required_before_action_code,
        p_created_by
      );
    END LOOP;
  END IF;

  IF p_required_before_action_code IS NOT NULL THEN
    INSERT INTO public."TCE_ReleaseGates" (
      "TCEGate_StatusCode",
      "TCEGate_GateCode",
      "TCEGate_Name",
      "TCEGate_JobID",
      "TCEGate_ChecklistID",
      "TCEGate_SourceRecordTypeCode",
      "TCEGate_SourceTable",
      "TCEGate_SourceID",
      "TCEGate_ActionCode",
      "TCEGate_IsBlocking",
      "TCEGate_CreatedBy"
    )
    VALUES (
      'pending',
      p_required_before_action_code,
      initcap(replace(p_required_before_action_code, '_', ' ')),
      p_job_id,
      v_checklist_id,
      CASE WHEN p_source_table = 'Job_Header' OR p_job_id IS NOT NULL THEN 'job' ELSE NULL END,
      coalesce(p_source_table, CASE WHEN p_job_id IS NOT NULL THEN 'Job_Header' ELSE NULL END),
      coalesce(p_source_id, p_job_id),
      p_required_before_action_code,
      true,
      p_created_by
    );
  END IF;

  PERFORM public."TCE_RefreshChecklistStatus"(v_checklist_id, p_created_by);

  RETURN v_checklist_id;
END;
$$;


ALTER FUNCTION "public"."TCE_CreateComplianceChecklist"("p_job_id" "uuid", "p_touchpoint_type_code" character varying, "p_policy_id" "uuid", "p_source_table" character varying, "p_source_id" "uuid", "p_required_before_action_code" character varying, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_CreateScreeningRun"("p_job_id" "uuid", "p_run_type_code" character varying DEFAULT 'job'::character varying, "p_policy_id" "uuid" DEFAULT NULL::"uuid", "p_triggered_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_run_id uuid;
  v_number varchar(80);
  v_customer_org_id uuid;
  v_office_id uuid;
BEGIN
  IF p_job_id IS NOT NULL THEN
    SELECT "Job_Customer", "Job_OrgOfficeID"
    INTO v_customer_org_id, v_office_id
    FROM public."Job_Header"
    WHERE "Job_ID" = p_job_id;
  END IF;

  v_number := 'TCE-RUN-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' || upper(substr(gen_random_uuid()::text, 1, 8));

  INSERT INTO public."TCE_ScreeningRuns" (
    "TCERun_Number",
    "TCERun_RunTypeCode",
    "TCERun_StatusCode",
    "TCERun_PolicyID",
    "TCERun_JobID",
    "TCERun_CustomerOrgID",
    "TCERun_OrgOfficeID",
    "TCERun_SourceRecordTypeCode",
    "TCERun_SourceTable",
    "TCERun_SourceID",
    "TCERun_TriggeredBy",
    "TCERun_CreatedBy"
  )
  VALUES (
    v_number,
    coalesce(p_run_type_code, 'job'),
    'pending',
    p_policy_id,
    p_job_id,
    v_customer_org_id,
    v_office_id,
    CASE WHEN p_job_id IS NOT NULL THEN 'job' ELSE NULL END,
    CASE WHEN p_job_id IS NOT NULL THEN 'Job_Header' ELSE NULL END,
    p_job_id,
    p_triggered_by,
    p_triggered_by
  )
  RETURNING "TCERun_ID" INTO v_run_id;

  RETURN v_run_id;
END;
$$;


ALTER FUNCTION "public"."TCE_CreateScreeningRun"("p_job_id" "uuid", "p_run_type_code" character varying, "p_policy_id" "uuid", "p_triggered_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_NormalizeName"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT nullif(regexp_replace(upper(coalesce(p_name, '')), '[^A-Z0-9]+', ' ', 'g'), '');
$$;


ALTER FUNCTION "public"."TCE_NormalizeName"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_RecordIntegrationEvent"("p_touchpoint_type_code" character varying, "p_source_table" character varying DEFAULT NULL::character varying, "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_policy_id" "uuid" DEFAULT NULL::"uuid", "p_payload_json" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_event_id uuid;
  v_customer_org_id uuid;
  v_office_id uuid;
  v_event_key varchar(180);
BEGIN
  IF p_job_id IS NOT NULL THEN
    SELECT "Job_Customer", "Job_OrgOfficeID"
    INTO v_customer_org_id, v_office_id
    FROM public."Job_Header"
    WHERE "Job_ID" = p_job_id;
  END IF;

  v_event_key := coalesce(
    nullif(p_payload_json->>'event_key', ''),
    p_touchpoint_type_code || ':' || coalesce(p_source_table, 'manual') || ':' || coalesce(p_source_id::text, gen_random_uuid()::text)
  );

  INSERT INTO public."TCE_IntegrationEvents" (
    "TCEEvent_StatusCode",
    "TCEEvent_TouchpointTypeCode",
    "TCEEvent_PolicyID",
    "TCEEvent_JobID",
    "TCEEvent_CustomerOrgID",
    "TCEEvent_OrgOfficeID",
    "TCEEvent_SourceRecordTypeCode",
    "TCEEvent_SourceTable",
    "TCEEvent_SourceID",
    "TCEEvent_EventKey",
    "TCEEvent_PayloadJSON",
    "TCEEvent_CreatedBy"
  )
  VALUES (
    'pending',
    p_touchpoint_type_code,
    p_policy_id,
    p_job_id,
    v_customer_org_id,
    v_office_id,
    CASE WHEN p_source_table = 'Job_Header' OR p_job_id IS NOT NULL THEN 'job' ELSE NULL END,
    p_source_table,
    p_source_id,
    v_event_key,
    coalesce(p_payload_json, '{}'::jsonb),
    p_created_by
  )
  ON CONFLICT ("TCEEvent_EventKey") DO UPDATE SET
    "TCEEvent_PayloadJSON" = EXCLUDED."TCEEvent_PayloadJSON",
    "TCEEvent_StatusCode" = CASE
      WHEN public."TCE_IntegrationEvents"."TCEEvent_StatusCode" IN ('completed', 'ignored') THEN public."TCE_IntegrationEvents"."TCEEvent_StatusCode"
      ELSE 'pending'
    END,
    "TCEEvent_RetryCount" = 0,
    "TCEEvent_NextAttemptAt" = NULL
  RETURNING "TCEEvent_ID" INTO v_event_id;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."TCE_RecordIntegrationEvent"("p_touchpoint_type_code" character varying, "p_source_table" character varying, "p_source_id" "uuid", "p_job_id" "uuid", "p_policy_id" "uuid", "p_payload_json" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_RecordLicenseUsage"("p_license_id" "uuid", "p_job_id" "uuid", "p_job_cargo_id" "uuid" DEFAULT NULL::"uuid", "p_quantity_used" numeric DEFAULT 0, "p_value_used" numeric DEFAULT 0, "p_currency_code" character varying DEFAULT 'GBP'::character varying, "p_used_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_usage_id uuid;
BEGIN
  INSERT INTO public."TCE_LicenseUsages" (
    "TCELicUse_LicenseID",
    "TCELicUse_JobID",
    "TCELicUse_JobCargoID",
    "TCELicUse_QuantityUsed",
    "TCELicUse_ValueUsedAmount",
    "TCELicUse_CurrencyCodeSnapshot",
    "TCELicUse_UsedBy"
  )
  VALUES (
    p_license_id,
    p_job_id,
    p_job_cargo_id,
    coalesce(p_quantity_used, 0),
    coalesce(p_value_used, 0),
    coalesce(p_currency_code, 'GBP'),
    p_used_by
  )
  RETURNING "TCELicUse_ID" INTO v_usage_id;

  UPDATE public."TCE_Licenses"
  SET
    "TCELicense_QuantityUsed" = "TCELicense_QuantityUsed" + coalesce(p_quantity_used, 0),
    "TCELicense_ValueUsedAmount" = "TCELicense_ValueUsedAmount" + coalesce(p_value_used, 0),
    "TCELicense_UpdatedAt" = now(),
    "TCELicense_UpdatedBy" = p_used_by
  WHERE "TCELicense_ID" = p_license_id;

  RETURN v_usage_id;
END;
$$;


ALTER FUNCTION "public"."TCE_RecordLicenseUsage"("p_license_id" "uuid", "p_job_id" "uuid", "p_job_cargo_id" "uuid", "p_quantity_used" numeric, "p_value_used" numeric, "p_currency_code" character varying, "p_used_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_RecordScreeningMatch"("p_subject_id" "uuid", "p_entry_id" "uuid", "p_score" numeric, "p_matched_name" character varying, "p_matched_field" character varying, "p_match_reason" "text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_match_id uuid;
  v_case_id uuid;
  v_run_id uuid;
  v_job_id uuid;
  v_customer_org_id uuid;
  v_office_id uuid;
  v_policy_id uuid;
  v_min_review numeric(9,4);
  v_min_block numeric(9,4);
  v_status varchar(60);
  v_strength varchar(60);
  v_risk varchar(60);
  v_entry public."TCE_WatchlistEntries"%ROWTYPE;
  v_subject public."TCE_ScreeningSubjects"%ROWTYPE;
BEGIN
  SELECT * INTO v_subject
  FROM public."TCE_ScreeningSubjects"
  WHERE "TCESubject_ID" = p_subject_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Screening subject % not found', p_subject_id;
  END IF;

  SELECT * INTO v_entry
  FROM public."TCE_WatchlistEntries"
  WHERE "TCEEntry_ID" = p_entry_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Watchlist entry % not found', p_entry_id;
  END IF;

  SELECT run."TCERun_ID", run."TCERun_JobID", run."TCERun_CustomerOrgID", run."TCERun_OrgOfficeID", run."TCERun_PolicyID",
         coalesce(policy."TCEPolicy_MinReviewScore", 70), coalesce(policy."TCEPolicy_MinBlockScore", 95)
  INTO v_run_id, v_job_id, v_customer_org_id, v_office_id, v_policy_id, v_min_review, v_min_block
  FROM public."TCE_ScreeningRuns" run
  LEFT JOIN public."TCE_ScreeningPolicies" policy ON policy."TCEPolicy_ID" = run."TCERun_PolicyID"
  WHERE run."TCERun_ID" = v_subject."TCESubject_RunID";

  v_strength := CASE
    WHEN coalesce(p_score, 0) >= 99 THEN 'exact'
    WHEN coalesce(p_score, 0) >= 90 THEN 'strong'
    WHEN coalesce(p_score, 0) >= 70 THEN 'possible'
    ELSE 'weak'
  END;

  v_risk := CASE
    WHEN coalesce(p_score, 0) >= v_min_block THEN 'critical'
    WHEN coalesce(p_score, 0) >= 90 THEN 'high'
    WHEN coalesce(p_score, 0) >= 70 THEN 'medium'
    ELSE 'low'
  END;

  v_status := CASE
    WHEN coalesce(p_score, 0) >= v_min_block THEN 'strong_match'
    WHEN coalesce(p_score, 0) >= v_min_review THEN 'possible_match'
    ELSE 'clear'
  END;

  INSERT INTO public."TCE_ScreeningMatches" (
    "TCEMatch_RunID",
    "TCEMatch_SubjectID",
    "TCEMatch_EntryID",
    "TCEMatch_SourceID",
    "TCEMatch_ListTypeCode",
    "TCEMatch_StatusCode",
    "TCEMatch_StrengthCode",
    "TCEMatch_RiskLevelCode",
    "TCEMatch_Score",
    "TCEMatch_MatchedName",
    "TCEMatch_MatchedField",
    "TCEMatch_MatchReason",
    "TCEMatch_CreatedBy"
  )
  VALUES (
    v_run_id,
    p_subject_id,
    p_entry_id,
    v_entry."TCEEntry_SourceID",
    v_entry."TCEEntry_ListTypeCode",
    CASE WHEN coalesce(p_score, 0) >= v_min_review THEN 'open' ELSE 'false_positive' END,
    v_strength,
    v_risk,
    coalesce(p_score, 0),
    p_matched_name,
    p_matched_field,
    p_match_reason,
    p_created_by
  )
  RETURNING "TCEMatch_ID" INTO v_match_id;

  UPDATE public."TCE_ScreeningSubjects"
  SET
    "TCESubject_StatusCode" = v_status,
    "TCESubject_MatchCount" = "TCESubject_MatchCount" + 1,
    "TCESubject_HighestScore" = greatest("TCESubject_HighestScore", coalesce(p_score, 0))
  WHERE "TCESubject_ID" = p_subject_id;

  UPDATE public."TCE_ScreeningRuns"
  SET
    "TCERun_StatusCode" = CASE
      WHEN v_status = 'strong_match' THEN 'review_required'
      WHEN v_status = 'possible_match' AND "TCERun_StatusCode" NOT IN ('blocked', 'review_required') THEN 'possible_match'
      ELSE "TCERun_StatusCode"
    END,
    "TCERun_MatchCount" = "TCERun_MatchCount" + 1,
    "TCERun_HighestScore" = greatest("TCERun_HighestScore", coalesce(p_score, 0)),
    "TCERun_HighestRiskLevelCode" = CASE
      WHEN v_risk = 'critical' THEN 'critical'
      WHEN v_risk = 'high' AND "TCERun_HighestRiskLevelCode" IN ('low', 'medium') THEN 'high'
      WHEN v_risk = 'medium' AND "TCERun_HighestRiskLevelCode" = 'low' THEN 'medium'
      ELSE "TCERun_HighestRiskLevelCode"
    END
  WHERE "TCERun_ID" = v_run_id;

  IF coalesce(p_score, 0) >= v_min_review THEN
    INSERT INTO public."TCE_ComplianceCases" (
      "TCECase_Number",
      "TCECase_StatusCode",
      "TCECase_RiskLevelCode",
      "TCECase_RunID",
      "TCECase_SubjectID",
      "TCECase_JobID",
      "TCECase_CustomerOrgID",
      "TCECase_OrgOfficeID",
      "TCECase_Title",
      "TCECase_Summary",
      "TCECase_CreatedBy"
    )
    VALUES (
      'TCE-CASE-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' || upper(substr(gen_random_uuid()::text, 1, 8)),
      'open',
      v_risk,
      v_run_id,
      p_subject_id,
      v_job_id,
      v_customer_org_id,
      v_office_id,
      'Compliance match review: ' || v_subject."TCESubject_Name",
      p_match_reason,
      p_created_by
    )
    RETURNING "TCECase_ID" INTO v_case_id;

    UPDATE public."TCE_ScreeningMatches"
    SET "TCEMatch_CaseID" = v_case_id
    WHERE "TCEMatch_ID" = v_match_id;

    UPDATE public."TCE_ScreeningRuns"
    SET "TCERun_OpenCaseCount" = "TCERun_OpenCaseCount" + 1
    WHERE "TCERun_ID" = v_run_id;
  END IF;

  RETURN v_match_id;
END;
$$;


ALTER FUNCTION "public"."TCE_RecordScreeningMatch"("p_subject_id" "uuid", "p_entry_id" "uuid", "p_score" numeric, "p_matched_name" character varying, "p_matched_field" character varying, "p_match_reason" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."TCE_RefreshChecklistStatus"("p_checklist_id" "uuid", "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS character varying
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_required_count integer;
  v_clear_count integer;
  v_review_count integer;
  v_blocked_count integer;
  v_open_count integer;
  v_new_status varchar(60);
BEGIN
  SELECT
    count(*) FILTER (WHERE item."TCECheckItem_IsMandatory")::int,
    count(*) FILTER (WHERE item."TCECheckItem_StatusCode" IN ('clear', 'waived', 'not_required'))::int,
    count(*) FILTER (WHERE item."TCECheckItem_StatusCode" = 'review_required')::int,
    count(*) FILTER (WHERE item."TCECheckItem_StatusCode" = 'blocked')::int,
    count(*) FILTER (WHERE status."TCECheckStatus_IsOpen")::int
  INTO v_required_count, v_clear_count, v_review_count, v_blocked_count, v_open_count
  FROM public."TCE_ComplianceCheckItems" item
  LEFT JOIN public."sys_TCECheckStatuses" status ON status."TCECheckStatus_Code" = item."TCECheckItem_StatusCode"
  WHERE item."TCECheckItem_ChecklistID" = p_checklist_id;

  v_new_status := CASE
    WHEN coalesce(v_blocked_count, 0) > 0 THEN 'blocked'
    WHEN coalesce(v_review_count, 0) > 0 THEN 'review_required'
    WHEN coalesce(v_open_count, 0) > 0 THEN 'in_progress'
    WHEN coalesce(v_required_count, 0) = 0 THEN 'not_required'
    ELSE 'clear'
  END;

  UPDATE public."TCE_ComplianceChecklists"
  SET
    "TCEChecklist_StatusCode" = v_new_status,
    "TCEChecklist_RequiredItemCount" = coalesce(v_required_count, 0),
    "TCEChecklist_ClearItemCount" = coalesce(v_clear_count, 0),
    "TCEChecklist_ReviewItemCount" = coalesce(v_review_count, 0),
    "TCEChecklist_BlockedItemCount" = coalesce(v_blocked_count, 0),
    "TCEChecklist_CompletedAt" = CASE WHEN v_new_status IN ('clear', 'waived', 'not_required') THEN now() ELSE "TCEChecklist_CompletedAt" END,
    "TCEChecklist_UpdatedAt" = now(),
    "TCEChecklist_UpdatedBy" = p_updated_by
  WHERE "TCEChecklist_ID" = p_checklist_id;

  RETURN v_new_status;
END;
$$;


ALTER FUNCTION "public"."TCE_RefreshChecklistStatus"("p_checklist_id" "uuid", "p_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."WMS_ApplyInventoryHold"("p_balance_id" "uuid", "p_hold_type_code" character varying, "p_reason" "text", "p_quantity" numeric DEFAULT NULL::numeric, "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_balance public."WMS_InventoryBalances"%ROWTYPE;
  v_hold_id uuid;
  v_quantity numeric(18,6);
BEGIN
  SELECT *
    INTO v_balance
  FROM public."WMS_InventoryBalances"
  WHERE "WMSBalance_ID" = p_balance_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WMS inventory balance % not found.', p_balance_id;
  END IF;

  v_quantity := COALESCE(p_quantity, v_balance."WMSBalance_AvailableQuantity");
  IF v_quantity <= 0 THEN
    RAISE EXCEPTION 'WMS hold quantity must be positive.';
  END IF;

  INSERT INTO public."WMS_InventoryHolds" (
    "WMSHold_FacilityID",
    "WMSHold_BalanceID",
    "WMSHold_ItemID",
    "WMSHold_LotID",
    "WMSHold_HU_ID",
    "WMSHold_OrderID",
    "WMSHold_JobID",
    "WMSHold_TypeCode",
    "WMSHold_StatusCode",
    "WMSHold_Quantity",
    "WMSHold_UOMCode",
    "WMSHold_Reason",
    "WMSHold_PlacedBy"
  )
  VALUES (
    v_balance."WMSBalance_FacilityID",
    p_balance_id,
    v_balance."WMSBalance_ItemID",
    v_balance."WMSBalance_LotID",
    v_balance."WMSBalance_HU_ID",
    p_order_id,
    p_job_id,
    p_hold_type_code,
    'open',
    v_quantity,
    v_balance."WMSBalance_UOMCode",
    p_reason,
    p_created_by
  )
  RETURNING "WMSHold_ID" INTO v_hold_id;

  UPDATE public."WMS_InventoryBalances"
  SET
    "WMSBalance_HeldQuantity" = COALESCE("WMSBalance_HeldQuantity", 0) + v_quantity,
    "WMSBalance_AvailableQuantity" = COALESCE("WMSBalance_OnHandQuantity", 0)
      - COALESCE("WMSBalance_ReservedQuantity", 0)
      - COALESCE("WMSBalance_AllocatedQuantity", 0)
      - COALESCE("WMSBalance_HeldQuantity", 0)
      - v_quantity,
    "WMSBalance_UpdatedAt" = now()
  WHERE "WMSBalance_ID" = p_balance_id;

  RETURN v_hold_id;
END;
$$;


ALTER FUNCTION "public"."WMS_ApplyInventoryHold"("p_balance_id" "uuid", "p_hold_type_code" character varying, "p_reason" "text", "p_quantity" numeric, "p_job_id" "uuid", "p_order_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."WMS_CreateBillingEvent"("p_facility_id" "uuid", "p_customer_org_id" "uuid", "p_event_type_code" character varying, "p_description" "text", "p_billing_basis_code" character varying, "p_quantity" numeric, "p_unit_rate" numeric, "p_currency_code" character varying DEFAULT 'GBP'::character varying, "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_contract_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_event_id uuid;
BEGIN
  INSERT INTO public."WMS_BillingEvents" (
    "WMSBillEvent_FacilityID",
    "WMSBillEvent_CustomerOrgID",
    "WMSBillEvent_ContractID",
    "WMSBillEvent_OrderID",
    "WMSBillEvent_JobID",
    "WMSBillEvent_StatusCode",
    "WMSBillEvent_EventTypeCode",
    "WMSBillEvent_Description",
    "WMSBillEvent_BillingBasisCode",
    "WMSBillEvent_Quantity",
    "WMSBillEvent_UnitRate",
    "WMSBillEvent_NetAmount",
    "WMSBillEvent_CurrencyCode",
    "WMSBillEvent_CreatedBy"
  )
  VALUES (
    p_facility_id,
    p_customer_org_id,
    p_contract_id,
    p_order_id,
    p_job_id,
    'ready',
    p_event_type_code,
    p_description,
    p_billing_basis_code,
    p_quantity,
    p_unit_rate,
    COALESCE(p_quantity, 0) * COALESCE(p_unit_rate, 0),
    p_currency_code,
    p_created_by
  )
  RETURNING "WMSBillEvent_ID" INTO v_event_id;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."WMS_CreateBillingEvent"("p_facility_id" "uuid", "p_customer_org_id" "uuid", "p_event_type_code" character varying, "p_description" "text", "p_billing_basis_code" character varying, "p_quantity" numeric, "p_unit_rate" numeric, "p_currency_code" character varying, "p_order_id" "uuid", "p_job_id" "uuid", "p_contract_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."WMS_FindOrCreateInventoryBalance"("p_facility_id" "uuid", "p_item_id" "uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_lot_id" "uuid" DEFAULT NULL::"uuid", "p_serial_id" "uuid" DEFAULT NULL::"uuid", "p_handling_unit_id" "uuid" DEFAULT NULL::"uuid", "p_inventory_status_code" character varying DEFAULT 'available'::character varying, "p_customs_status_code" character varying DEFAULT 'free_circulation'::character varying, "p_uom_code" character varying DEFAULT 'EA'::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_balance_id uuid;
  v_is_bonded boolean;
BEGIN
  SELECT "WMSBalance_ID"
    INTO v_balance_id
  FROM public."WMS_InventoryBalances"
  WHERE "WMSBalance_FacilityID" = p_facility_id
    AND "WMSBalance_ItemID" = p_item_id
    AND "WMSBalance_CustomerOrgID" IS NOT DISTINCT FROM p_customer_org_id
    AND "WMSBalance_LocationID" IS NOT DISTINCT FROM p_location_id
    AND "WMSBalance_LotID" IS NOT DISTINCT FROM p_lot_id
    AND "WMSBalance_SerialID" IS NOT DISTINCT FROM p_serial_id
    AND "WMSBalance_HU_ID" IS NOT DISTINCT FROM p_handling_unit_id
    AND "WMSBalance_InventoryStatusCode" = p_inventory_status_code
    AND "WMSBalance_CustomsStatusCode" = p_customs_status_code
    AND "WMSBalance_UOMCode" = p_uom_code
  LIMIT 1;

  IF v_balance_id IS NOT NULL THEN
    RETURN v_balance_id;
  END IF;

  v_is_bonded := p_customs_status_code IN ('bonded', 'free_zone', 'transit', 'inward_processing', 'temporary_admission', 'excise_suspended');

  INSERT INTO public."WMS_InventoryBalances" (
    "WMSBalance_FacilityID",
    "WMSBalance_CustomerOrgID",
    "WMSBalance_ItemID",
    "WMSBalance_LocationID",
    "WMSBalance_LotID",
    "WMSBalance_SerialID",
    "WMSBalance_HU_ID",
    "WMSBalance_InventoryStatusCode",
    "WMSBalance_CustomsStatusCode",
    "WMSBalance_UOMCode",
    "WMSBalance_IsBonded"
  )
  VALUES (
    p_facility_id,
    p_customer_org_id,
    p_item_id,
    p_location_id,
    p_lot_id,
    p_serial_id,
    p_handling_unit_id,
    p_inventory_status_code,
    p_customs_status_code,
    p_uom_code,
    v_is_bonded
  )
  RETURNING "WMSBalance_ID" INTO v_balance_id;

  RETURN v_balance_id;
END;
$$;


ALTER FUNCTION "public"."WMS_FindOrCreateInventoryBalance"("p_facility_id" "uuid", "p_item_id" "uuid", "p_customer_org_id" "uuid", "p_location_id" "uuid", "p_lot_id" "uuid", "p_serial_id" "uuid", "p_handling_unit_id" "uuid", "p_inventory_status_code" character varying, "p_customs_status_code" character varying, "p_uom_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."WMS_PostInventoryTransaction"("p_facility_id" "uuid", "p_item_id" "uuid", "p_transaction_type_code" character varying, "p_quantity" numeric, "p_uom_code" character varying DEFAULT 'EA'::character varying, "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_from_location_id" "uuid" DEFAULT NULL::"uuid", "p_to_location_id" "uuid" DEFAULT NULL::"uuid", "p_lot_id" "uuid" DEFAULT NULL::"uuid", "p_serial_id" "uuid" DEFAULT NULL::"uuid", "p_handling_unit_id" "uuid" DEFAULT NULL::"uuid", "p_inventory_status_code" character varying DEFAULT 'available'::character varying, "p_customs_status_code" character varying DEFAULT 'free_circulation'::character varying, "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_order_line_id" "uuid" DEFAULT NULL::"uuid", "p_receipt_id" "uuid" DEFAULT NULL::"uuid", "p_task_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_source_table" character varying DEFAULT NULL::character varying, "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_reference" character varying DEFAULT NULL::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_balance_id uuid;
  v_transaction_id uuid;
  v_before numeric(18,6);
  v_after numeric(18,6);
BEGIN
  IF p_quantity IS NULL OR p_quantity = 0 THEN
    RAISE EXCEPTION 'WMS inventory transaction quantity must not be zero.';
  END IF;

  v_balance_id := public."WMS_FindOrCreateInventoryBalance"(
    p_facility_id,
    p_item_id,
    p_customer_org_id,
    p_to_location_id,
    p_lot_id,
    p_serial_id,
    p_handling_unit_id,
    p_inventory_status_code,
    p_customs_status_code,
    p_uom_code
  );

  SELECT "WMSBalance_OnHandQuantity"
    INTO v_before
  FROM public."WMS_InventoryBalances"
  WHERE "WMSBalance_ID" = v_balance_id
  FOR UPDATE;

  v_after := COALESCE(v_before, 0) + p_quantity;

  INSERT INTO public."WMS_InventoryTransactions" (
    "WMSTransaction_FacilityID",
    "WMSTransaction_BalanceID",
    "WMSTransaction_TypeCode",
    "WMSTransaction_ItemID",
    "WMSTransaction_CustomerOrgID",
    "WMSTransaction_FromLocationID",
    "WMSTransaction_ToLocationID",
    "WMSTransaction_LotID",
    "WMSTransaction_SerialID",
    "WMSTransaction_HU_ID",
    "WMSTransaction_Quantity",
    "WMSTransaction_UOMCode",
    "WMSTransaction_BeforeOnHandQuantity",
    "WMSTransaction_AfterOnHandQuantity",
    "WMSTransaction_InventoryStatusCode",
    "WMSTransaction_CustomsStatusCode",
    "WMSTransaction_OrderID",
    "WMSTransaction_OrderLineID",
    "WMSTransaction_ReceiptID",
    "WMSTransaction_TaskID",
    "WMSTransaction_JobID",
    "WMSTransaction_SourceTable",
    "WMSTransaction_SourceID",
    "WMSTransaction_Reference",
    "WMSTransaction_CreatedBy"
  )
  VALUES (
    p_facility_id,
    v_balance_id,
    p_transaction_type_code,
    p_item_id,
    p_customer_org_id,
    p_from_location_id,
    p_to_location_id,
    p_lot_id,
    p_serial_id,
    p_handling_unit_id,
    p_quantity,
    p_uom_code,
    v_before,
    v_after,
    p_inventory_status_code,
    p_customs_status_code,
    p_order_id,
    p_order_line_id,
    p_receipt_id,
    p_task_id,
    p_job_id,
    p_source_table,
    p_source_id,
    p_reference,
    p_created_by
  )
  RETURNING "WMSTransaction_ID" INTO v_transaction_id;

  UPDATE public."WMS_InventoryBalances"
  SET
    "WMSBalance_OnHandQuantity" = v_after,
    "WMSBalance_AvailableQuantity" = v_after
      - COALESCE("WMSBalance_ReservedQuantity", 0)
      - COALESCE("WMSBalance_AllocatedQuantity", 0)
      - COALESCE("WMSBalance_HeldQuantity", 0),
    "WMSBalance_FirstReceiptAt" = COALESCE("WMSBalance_FirstReceiptAt", now()),
    "WMSBalance_LastMovementAt" = now(),
    "WMSBalance_UpdatedAt" = now()
  WHERE "WMSBalance_ID" = v_balance_id;

  RETURN v_transaction_id;
END;
$$;


ALTER FUNCTION "public"."WMS_PostInventoryTransaction"("p_facility_id" "uuid", "p_item_id" "uuid", "p_transaction_type_code" character varying, "p_quantity" numeric, "p_uom_code" character varying, "p_customer_org_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_lot_id" "uuid", "p_serial_id" "uuid", "p_handling_unit_id" "uuid", "p_inventory_status_code" character varying, "p_customs_status_code" character varying, "p_order_id" "uuid", "p_order_line_id" "uuid", "p_receipt_id" "uuid", "p_task_id" "uuid", "p_job_id" "uuid", "p_source_table" character varying, "p_source_id" "uuid", "p_reference" character varying, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."WMS_RecalculateInventoryBalance"("p_balance_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE public."WMS_InventoryBalances"
  SET
    "WMSBalance_AvailableQuantity" =
      COALESCE("WMSBalance_OnHandQuantity", 0)
      - COALESCE("WMSBalance_ReservedQuantity", 0)
      - COALESCE("WMSBalance_AllocatedQuantity", 0)
      - COALESCE("WMSBalance_HeldQuantity", 0),
    "WMSBalance_UpdatedAt" = now()
  WHERE "WMSBalance_ID" = p_balance_id;
END;
$$;


ALTER FUNCTION "public"."WMS_RecalculateInventoryBalance"("p_balance_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."WMS_ReleaseInventoryHold"("p_hold_id" "uuid", "p_released_by" "uuid" DEFAULT NULL::"uuid", "p_release_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_hold public."WMS_InventoryHolds"%ROWTYPE;
BEGIN
  SELECT *
    INTO v_hold
  FROM public."WMS_InventoryHolds"
  WHERE "WMSHold_ID" = p_hold_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WMS hold % not found.', p_hold_id;
  END IF;

  IF v_hold."WMSHold_StatusCode" <> 'open' THEN
    RETURN;
  END IF;

  UPDATE public."WMS_InventoryHolds"
  SET
    "WMSHold_StatusCode" = 'released',
    "WMSHold_ReleasedAt" = now(),
    "WMSHold_ReleasedBy" = p_released_by,
    "WMSHold_ReleaseReason" = p_release_reason
  WHERE "WMSHold_ID" = p_hold_id;

  IF v_hold."WMSHold_BalanceID" IS NOT NULL THEN
    UPDATE public."WMS_InventoryBalances"
    SET
      "WMSBalance_HeldQuantity" = GREATEST(0, COALESCE("WMSBalance_HeldQuantity", 0) - COALESCE(v_hold."WMSHold_Quantity", 0)),
      "WMSBalance_AvailableQuantity" = COALESCE("WMSBalance_OnHandQuantity", 0)
        - COALESCE("WMSBalance_ReservedQuantity", 0)
        - COALESCE("WMSBalance_AllocatedQuantity", 0)
        - GREATEST(0, COALESCE("WMSBalance_HeldQuantity", 0) - COALESCE(v_hold."WMSHold_Quantity", 0)),
      "WMSBalance_UpdatedAt" = now()
    WHERE "WMSBalance_ID" = v_hold."WMSHold_BalanceID";
  END IF;
END;
$$;


ALTER FUNCTION "public"."WMS_ReleaseInventoryHold"("p_hold_id" "uuid", "p_released_by" "uuid", "p_release_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Workflow_FindDefinitionCandidates"("p_record_type_code" character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_mode_code" character varying DEFAULT NULL::character varying, "p_direction_code" character varying DEFAULT NULL::character varying, "p_language_code" character varying DEFAULT 'en'::character varying) RETURNS TABLE("WorkflowDef_ID" "uuid", "WorkflowDefVer_ID" "uuid", "WorkflowDef_Code" character varying, "WorkflowDef_Name" character varying, "WorkflowDef_Score" integer)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    d."WorkflowDef_ID",
    v."WorkflowDefVer_ID",
    d."WorkflowDef_Code",
    d."WorkflowDef_Name",
    (
      CASE WHEN d."WorkflowDef_CustomerOrgID" = p_customer_org_id THEN 64 WHEN d."WorkflowDef_CustomerOrgID" IS NULL THEN 0 ELSE -1000 END +
      CASE WHEN d."WorkflowDef_BrandID" = p_brand_id THEN 32 WHEN d."WorkflowDef_BrandID" IS NULL THEN 0 ELSE -1000 END +
      CASE WHEN d."WorkflowDef_LegalEntityID" = p_legal_entity_id THEN 16 WHEN d."WorkflowDef_LegalEntityID" IS NULL THEN 0 ELSE -1000 END +
      CASE WHEN d."WorkflowDef_OrgOfficeID" = p_org_office_id THEN 8 WHEN d."WorkflowDef_OrgOfficeID" IS NULL THEN 0 ELSE -1000 END +
      CASE WHEN d."WorkflowDef_ModeCode" = p_mode_code THEN 4 WHEN d."WorkflowDef_ModeCode" IS NULL THEN 0 ELSE -1000 END +
      CASE WHEN d."WorkflowDef_DirectionCode" = p_direction_code THEN 2 WHEN d."WorkflowDef_DirectionCode" IS NULL THEN 0 ELSE -1000 END +
      CASE WHEN d."WorkflowDef_LanguageCode" = coalesce(p_language_code, 'en') THEN 1 WHEN d."WorkflowDef_LanguageCode" = 'en' THEN 0 ELSE -1000 END
    )::integer AS "WorkflowDef_Score"
  FROM public."Workflow_Definitions" d
  JOIN public."Workflow_DefinitionVersions" v
    ON v."WorkflowDefVer_ID" = d."WorkflowDef_CurrentVersionID"
  WHERE d."WorkflowDef_RecordTypeCode" = p_record_type_code
    AND d."WorkflowDef_StatusCode" IN ('approved', 'active')
    AND v."WorkflowDefVer_StatusCode" = 'published'
    AND d."WorkflowDef_IsActive" = true
    AND d."WorkflowDef_IsDeleted" = false
  ORDER BY "WorkflowDef_Score" DESC, d."WorkflowDef_IsDefault" DESC, d."WorkflowDef_UpdatedAt" DESC;
$$;


ALTER FUNCTION "public"."Workflow_FindDefinitionCandidates"("p_record_type_code" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_customer_org_id" "uuid", "p_mode_code" character varying, "p_direction_code" character varying, "p_language_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Workflow_GetReadyTasks"("p_instance_id" "uuid") RETURNS TABLE("WorkflowTask_ID" "uuid", "WorkflowTask_Title" character varying, "WorkflowTask_StatusCode" character varying, "WorkflowTask_DueAt" timestamp with time zone, "WorkflowTask_OpenBlockingDependencyCount" integer)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    w."WorkflowTask_ID",
    w."WorkflowTask_Title",
    w."WorkflowTask_StatusCode",
    w."WorkflowTask_DueAt",
    w."WorkflowTask_OpenBlockingDependencyCount"
  FROM public."Workflow_TaskWorklist" w
  WHERE w."WorkflowTask_InstanceID" = p_instance_id
    AND w."WorkflowTaskStatus_IsOpen" = true
    AND w."WorkflowTask_OpenBlockingDependencyCount" = 0
  ORDER BY w."WorkflowPriority_Weight" DESC, w."WorkflowTask_DueAt" ASC NULLS LAST, w."WorkflowTask_Title";
$$;


ALTER FUNCTION "public"."Workflow_GetReadyTasks"("p_instance_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_context"() RETURNS TABLE("user_id" "uuid", "company_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Sign in again to use CRM.' using errcode = '42501';
  end if;

  return query
  select u."User_ID", u."Company_ID"
  from public."cmp_Users" u
  where u."Auth_User_ID" = auth.uid()
  limit 1;

  if not found then
    raise exception 'Your signed-in account is not linked to this Multideck workspace.' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_deal_json"("p_deal_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'id', deal."CRMOppty_ID",
    'organisationId', deal."CRMOppty_OrgID",
    'companyName', coalesce(
      nullif(btrim(source_lead."CRMLead_CompanyName"), ''),
      nullif(btrim(organisation."Org_Name"), ''),
      'Organisation'
    ),
    'sourceLeadId', coalesce(deal."CRMOppty_SourceLeadID", '00000000-0000-0000-0000-000000000000'::uuid),
    'name', deal."CRMOppty_Name",
    'pipelineId', deal."CRMOppty_PipelineID",
    'pipelineName', pipeline."CRMPipeline_Name",
    'pipelineStageId', deal."CRMOppty_PipelineStageID",
    'pipelineStageName', pipeline_stage."CRMPipelineStage_Name",
    'opportunityTypeCode', deal."CRMOppty_TypeCode",
    'opportunityTypeName', opportunity_type."CRMOpptyType_Name",
    'stageCode', deal."CRMOppty_StageCode",
    'stageName', opportunity_stage."CRMStage_Name",
    'statusCode', deal."CRMOppty_StatusCode",
    'statusName', opportunity_status."CRMOpptyStatus_Name",
    'primaryContactId', deal."CRMOppty_PrimaryContactID",
    'primaryContactName', nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''),
    'ownerId', deal."CRMOppty_OwnerUserID",
    'ownerName', coalesce(
      nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
      nullif(btrim(owner."User_Email"), '')
    ),
    'expectedCloseDate', deal."CRMOppty_ExpectedCloseDate",
    'expectedValueAmount', deal."CRMOppty_ExpectedValueAmount",
    'expectedMarginAmount', deal."CRMOppty_ExpectedMarginAmount",
    'currencyCode', nullif(btrim(deal."CRMOppty_CurrencyCode"), ''),
    'probabilityPct', deal."CRMOppty_ProbabilityPct",
    'modeCode', nullif(btrim(deal."CRMOppty_ModeCode"), ''),
    'directionCode', nullif(btrim(deal."CRMOppty_DirectionCode"), ''),
    'originName', nullif(btrim(deal."CRMOppty_OriginNameSnapshot"), ''),
    'destinationName', nullif(btrim(deal."CRMOppty_DestinationNameSnapshot"), ''),
    'tradeLane', nullif(btrim(deal."CRMOppty_TradeLane"), ''),
    'serviceInterest', nullif(btrim(deal."CRMOppty_ServiceInterest"), ''),
    'customerNeed', nullif(btrim(deal."CRMOppty_CustomerNeed"), ''),
    'valueProposition', nullif(btrim(deal."CRMOppty_ValueProposition"), ''),
    'nextActionDueAt', deal."CRMOppty_NextActionDueAt",
    'createdAt', deal."CRMOppty_CreatedAt",
    'wasAlreadyConverted', false
  )
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
    and pipeline."Company_ID" = p_company_id
    and not pipeline."Is_Deleted"
  join public."CRM_PipelineStages" pipeline_stage
    on pipeline_stage."CRMPipelineStage_ID" = deal."CRMOppty_PipelineStageID"
    and pipeline_stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
    and not pipeline_stage."Is_Deleted"
  join public."sys_CRMOpportunityTypes" opportunity_type
    on opportunity_type."CRMOpptyType_Code" = deal."CRMOppty_TypeCode"
  join public."sys_CRMOpportunityStages" opportunity_stage
    on opportunity_stage."CRMStage_Code" = deal."CRMOppty_StageCode"
  join public."sys_CRMOpportunityStatuses" opportunity_status
    on opportunity_status."CRMOpptyStatus_Code" = deal."CRMOppty_StatusCode"
  left join public."CRM_Leads" source_lead
    on source_lead."CRMLead_ID" = deal."CRMOppty_SourceLeadID"
  left join public."Org_Master" organisation
    on organisation."Org_id" = deal."CRMOppty_OrgID"
  left join public."Org_Contacts" contact
    on contact."OrgContact_ID" = deal."CRMOppty_PrimaryContactID"
  left join public."cmp_Users" owner
    on owner."User_ID" = deal."CRMOppty_OwnerUserID"
  where deal."CRMOppty_ID" = p_deal_id
    and not deal."CRMOppty_IsDeleted";
$$;


ALTER FUNCTION "public"."_multideck_crm_deal_json"("p_deal_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_initials"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select upper(
    coalesce(left((regexp_split_to_array(btrim(coalesce(p_value, '')), '\s+'))[1], 1), '') ||
    coalesce(left((regexp_split_to_array(btrim(coalesce(p_value, '')), '\s+'))[2], 1), '')
  );
$$;


ALTER FUNCTION "public"."_multideck_crm_initials"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_lead_field_json"("p_field_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'id', field."CRMLeadField_ID",
    'label', field."CRMLeadField_Label",
    'type', field."CRMLeadField_TypeCode",
    'options', coalesce(field."CRMLeadField_OptionsJSON", '[]'::jsonb),
    'activeOptions', coalesce(field."CRMLeadField_ActiveOptionsJSON", '[]'::jsonb),
    'sortOrder', field."CRMLeadField_SortOrder"
  )
  from public."CRM_LeadFieldSettings" field
  where field."CRMLeadField_ID" = p_field_id
    and field."Company_ID" = p_company_id
    and not field."Is_Deleted";
$$;


ALTER FUNCTION "public"."_multideck_crm_lead_field_json"("p_field_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_lead_json"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'id', l."CRMLead_ID",
    'companyName', names.company_name,
    'initials', public._multideck_crm_initials(names.company_name),
    'primaryContactName', names.contact_name,
    'primaryContactEmail', coalesce(nullif(btrim(l."CRMLead_Email"), ''), contact_email.email),
    'countryCode', upper(nullif(btrim(l."CRMLead_CountryCode"), '')),
    'sourceCode', l."CRMLead_SourceCode",
    'sourceName', source."CRMLeadSource_Name",
    'ownerId', l."CRMLead_OwnerUserID",
    'ownerName', names.owner_name,
    'ownerInitials', case when names.owner_name is null then null else public._multideck_crm_initials(names.owner_name) end,
    'statusCode', l."CRMLead_StatusCode",
    'statusName', status."CRMLeadStatus_Name",
    'isOpen', status."CRMLeadStatus_IsOpen",
    'isConverted', status."CRMLeadStatus_IsConverted",
    'isDisqualified', status."CRMLeadStatus_IsDisqualified",
    'ratingCode', l."CRMLead_RatingCode",
    'ratingName', rating."CRMLeadRating_Name",
    'qualificationScore', coalesce(qualification.score, l."CRMLead_Score"),
    'qualificationCriteriaMet', coalesce(qualification.criteria_met, 0),
    'conversionProbability', l."CRMLead_AIProbabilityToConvert",
    'lastActivityAt',
      case
        when l."CRMLead_LastInteractionAt" is null then activity.activity_at
        when activity.activity_at is null then l."CRMLead_LastInteractionAt"
        else greatest(l."CRMLead_LastInteractionAt", activity.activity_at)
      end,
    'lastActivitySubject',
      case
        when activity.activity_at is not null
          and (l."CRMLead_LastInteractionAt" is null or activity.activity_at >= l."CRMLead_LastInteractionAt")
        then activity.subject
        else null
      end,
    'nextFollowUpAt', l."CRMLead_NextActionDueAt",
    'createdAt', l."CRMLead_CreatedAt",
    'valueAmount', coalesce(l."CRMLead_EstimatedValueAmount", valued_opportunity.value_amount),
    'valueCurrencyCode',
      upper(coalesce(
        case when l."CRMLead_EstimatedValueAmount" is not null then nullif(btrim(l."CRMLead_EstimatedValueCurrencyCode"), '') end,
        nullif(btrim(valued_opportunity.currency_code), '')
      )),
    'valueContext',
      coalesce(
        nullif(concat_ws(' · ', valued_opportunity.name, valued_opportunity.stage_name), ''),
        nullif(btrim(l."CRMLead_ServiceInterest"), ''),
        nullif(btrim(l."CRMLead_TradeLane"), '')
      ),
    'tradeLane', nullif(btrim(l."CRMLead_TradeLane"), ''),
    'serviceInterest', nullif(btrim(l."CRMLead_ServiceInterest"), ''),
    'openOpportunityCount', coalesce(open_opportunities.open_count, 0)
  )
  from public."CRM_Leads" l
  join public."sys_CRMLeadSources" source
    on source."CRMLeadSource_Code" = l."CRMLead_SourceCode"
  join public."sys_CRMLeadStatuses" status
    on status."CRMLeadStatus_Code" = l."CRMLead_StatusCode"
  join public."sys_CRMLeadRatings" rating
    on rating."CRMLeadRating_Code" = l."CRMLead_RatingCode"
  left join public."Org_Contacts" contact
    on contact."OrgContact_ID" = l."CRMLead_PrimaryContactID"
  left join public."cmp_Users" owner
    on owner."User_ID" = l."CRMLead_OwnerUserID"
  cross join lateral (
    select
      coalesce(
        nullif(btrim(l."CRMLead_PersonName"), ''),
        nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '')
      ) as contact_name,
      coalesce(
        nullif(btrim(l."CRMLead_CompanyName"), ''),
        nullif(btrim(l."CRMLead_PersonName"), ''),
        nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''),
        'Unnamed lead'
      ) as company_name,
      coalesce(
        nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
        nullif(btrim(owner."User_Email"), '')
      ) as owner_name
  ) names
  left join lateral (
    select nullif(btrim(email."OrgContactEmail_Email"), '') as email
    from public."OrgContact_Emails" email
    where email."OrgContact_ID" = contact."OrgContact_ID"
    order by email."OrgContactEmail_Type", email."OrgContactEmail_ID"
    limit 1
  ) contact_email on true
  left join lateral (
    select
      a."CRMActivity_ActivityAt" as activity_at,
      a."CRMActivity_Subject" as subject
    from public."CRM_Activities" a
    where a."CRMActivity_LeadID" = l."CRMLead_ID"
      and not a."CRMActivity_IsDeleted"
    order by a."CRMActivity_ActivityAt" desc
    limit 1
  ) activity on true
  left join lateral (
    select
      q."CRMLeadQual_QualificationScore" as score,
      (
        (q."CRMLeadQual_HasAuthority" is true)::integer +
        (q."CRMLeadQual_HasBudget" is true)::integer +
        (q."CRMLeadQual_HasNeed" is true)::integer +
        (q."CRMLeadQual_HasTimeline" is true)::integer
      ) as criteria_met
    from public."CRM_LeadQualification" q
    where q."CRMLeadQual_LeadID" = l."CRMLead_ID"
    order by coalesce(q."CRMLeadQual_QualifiedAt", q."CRMLeadQual_CreatedAt") desc
    limit 1
  ) qualification on true
  left join lateral (
    select count(*)::integer as open_count
    from public."CRM_Opportunities" opportunity
    where opportunity."CRMOppty_SourceLeadID" = l."CRMLead_ID"
      and not opportunity."CRMOppty_IsDeleted"
      and opportunity."CRMOppty_WonAt" is null
      and opportunity."CRMOppty_LostAt" is null
  ) open_opportunities on true
  left join lateral (
    select
      opportunity."CRMOppty_ExpectedValueAmount" as value_amount,
      opportunity."CRMOppty_CurrencyCode" as currency_code,
      nullif(btrim(opportunity."CRMOppty_Name"), '') as name,
      stage."CRMStage_Name" as stage_name
    from public."CRM_Opportunities" opportunity
    join public."sys_CRMOpportunityStages" stage
      on stage."CRMStage_Code" = opportunity."CRMOppty_StageCode"
    where opportunity."CRMOppty_SourceLeadID" = l."CRMLead_ID"
      and not opportunity."CRMOppty_IsDeleted"
      and opportunity."CRMOppty_WonAt" is null
      and opportunity."CRMOppty_LostAt" is null
      and opportunity."CRMOppty_ExpectedValueAmount" is not null
    order by coalesce(opportunity."CRMOppty_LastActivityAt", opportunity."CRMOppty_CreatedAt") desc
    limit 1
  ) valued_opportunity on true
  where l."CRMLead_ID" = p_lead_id
    and not l."CRMLead_IsDeleted";
$$;


ALTER FUNCTION "public"."_multideck_crm_lead_json"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_pipeline_json"("p_pipeline_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'id', pipeline."CRMPipeline_ID",
    'name', pipeline."CRMPipeline_Name",
    'owner', coalesce(pipeline."CRMPipeline_Owner", ''),
    'automation', coalesce(pipeline."CRMPipeline_Automation", ''),
    'sortOrder', pipeline."CRMPipeline_SortOrder",
    'defaultStage', coalesce(
      (
        select stage."CRMPipelineStage_Name"
        from public."CRM_PipelineStages" stage
        where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
          and not stage."Is_Deleted"
        order by stage."CRMPipelineStage_IsDefaultEntry" desc, stage."CRMPipelineStage_SortOrder"
        limit 1
      ),
      ''
    ),
    'conversionStage', coalesce(
      (
        select stage."CRMPipelineStage_Name"
        from public."CRM_PipelineStages" stage
        where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
          and not stage."Is_Deleted"
        order by stage."CRMPipelineStage_IsConversion" desc, stage."CRMPipelineStage_SortOrder" desc
        limit 1
      ),
      ''
    ),
    'stages', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', stage."CRMPipelineStage_ID",
            'name', stage."CRMPipelineStage_Name",
            'tone', stage."CRMPipelineStage_Tone",
            'rule', coalesce(stage."CRMPipelineStage_EntryRule", ''),
            'probability', stage."CRMPipelineStage_ProbabilityPct",
            'sortOrder', stage."CRMPipelineStage_SortOrder",
            'isDefaultEntry', stage."CRMPipelineStage_IsDefaultEntry",
            'isConversion', stage."CRMPipelineStage_IsConversion"
          )
          order by stage."CRMPipelineStage_SortOrder"
        )
        from public."CRM_PipelineStages" stage
        where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
          and not stage."Is_Deleted"
      ),
      '[]'::jsonb
    )
  )
  from public."CRM_Pipelines" pipeline
  where pipeline."CRMPipeline_ID" = p_pipeline_id
    and pipeline."Company_ID" = p_company_id
    and not pipeline."Is_Deleted";
$$;


ALTER FUNCTION "public"."_multideck_crm_pipeline_json"("p_pipeline_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_require_settings_manage"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (
    select 1
    from public."cmp_Users_Roles" user_role
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = 'Settings.Manage'
  ) then
    raise exception 'You do not have permission to manage CRM settings.' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_require_settings_manage"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_can_manage"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."cmp_Users_Roles" user_role
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = 'AgentDexter.Manage'
  );
$$;


ALTER FUNCTION "public"."_multideck_dexter_can_manage"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_context"() RETURNS TABLE("user_id" "uuid", "company_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Sign in again to use Agent Dexter.' using errcode = '42501';
  end if;

  return query
  select profile."User_ID", profile."Company_ID"
  from public."cmp_Users" profile
  where profile."Auth_User_ID" = auth.uid()
    and profile."Company_ID" is not null
  limit 1;

  if not found then
    raise exception 'Your signed-in account is not linked to this Multideck workspace.'
      using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_conversation_json"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  select jsonb_build_object(
    'id', conversation."AICNV_ID",
    'title', coalesce(conversation."AICNV_Title", 'Dexter conversation'),
    'summary', coalesce(conversation."AICNV_SummaryText", ''),
    'updatedAt', conversation."AICNV_UpdatedAt",
    'messages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', message."AIMSG_ID",
          'role', message."AIMSG_Role",
          'content', message."AIMSG_ContentText",
          'createdAt', message."AIMSG_CreatedAt",
          'specialist', nullif(message."AIMSG_ContentJSON" ->> 'specialist', ''),
          'parentResponseMessageId', nullif(
            message."AIMSG_ContentJSON" #>> '{metadata,parentResponseMessageId}',
            ''
          ),
          'pendingAction', case
            when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,pendingAction}') = 'object'
              then message."AIMSG_ContentJSON" #> '{metadata,pendingAction}'
            else null
          end,
          'reasoningSummary', nullif(
            message."AIMSG_ContentJSON" #>> '{metadata,reasoningSummary}',
            ''
          ),
          'emailAttachments', case
            when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}') = 'array'
              then message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}'
            else '[]'::jsonb
          end,
          'responseToUserMessageId', nullif(
            message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}',
            ''
          ),
          'responseVersion', case
            when coalesce(
              message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}',
              ''
            ) ~ '^[1-9][0-9]*$'
              then (message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer
            else null
          end
        )
        order by message."AIMSG_CreatedAt", message."AIMSG_ID"
      )
      from public."AI_Messages" message
      where message."AIMSG_ConversationID" = conversation."AICNV_ID"
        and message."AIMSG_ContentText" is not null
    ), '[]'::jsonb)
  )
  from public."AI_Conversations" conversation
  where conversation."AICNV_ID" = p_conversation_id
    and conversation."AICNV_CompanyID" = p_company_id
    and conversation."AICNV_OwnerUserID" = p_user_id
    and conversation."AICNV_Channel" = 'chat'
    and conversation."AICNV_EndedAt" is null
    and conversation."AICNV_DomainCode" in ('multideck', 'warehouse');
$_$;


ALTER FUNCTION "public"."_multideck_dexter_conversation_json"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_email_mailboxes"("p_user_id" "uuid", "p_company_id" "uuid") RETURNS TABLE("mailbox_id" "uuid", "provider" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with readable as (
    select access."CommMailboxAccess_MailboxID" as mailbox_id
    from public."Comm_MailboxAccess" access
    where access."CommMailboxAccess_UserID" = p_user_id
      and access."CommMailboxAccess_CanRead"
      and access."CommMailboxAccess_RevokedAt" is null
      and (
        access."CommMailboxAccess_ExpiresAt" is null
        or access."CommMailboxAccess_ExpiresAt" > now()
      )

    union

    select mailbox."CommMailbox_ID"
    from public."Comm_Mailboxes" mailbox
    join public."Comm_ProviderConnections" connection
      on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
     and connection."CommConn_UserID" = p_user_id
     and connection."CommConn_StatusCode" = 'active'
     and connection."CommConn_InboundEnabled"
     and not connection."CommConn_IsDeleted"
    where mailbox."CommMailbox_UserID" = p_user_id
      and mailbox."CommMailbox_TypeCode" = 'personal'
      and mailbox."CommMailbox_InboundEnabled"
      and not mailbox."CommMailbox_IsDeleted"
  )
  select distinct
    mailbox."CommMailbox_ID",
    case connection."CommConn_ProviderTypeCode"
      when 'google_workspace' then 'gmail'
      when 'microsoft_365' then 'outlook'
    end
  from readable
  join public."Comm_Mailboxes" mailbox
    on mailbox."CommMailbox_ID" = readable.mailbox_id
   and mailbox."CommMailbox_InboundEnabled"
   and not mailbox."CommMailbox_IsDeleted"
  join public."Comm_ProviderConnections" connection
    on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
   and connection."CommConn_StatusCode" = 'active'
   and connection."CommConn_InboundEnabled"
   and not connection."CommConn_IsDeleted"
  join public."cmp_Users" connection_owner
    on connection_owner."User_ID" = connection."CommConn_UserID"
   and connection_owner."Company_ID" = p_company_id
  where connection."CommConn_ProviderTypeCode" in ('google_workspace', 'microsoft_365');
$$;


ALTER FUNCTION "public"."_multideck_dexter_email_mailboxes"("p_user_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_has_permission"("p_user_id" "uuid", "p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."cmp_Users_Roles" user_role
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = p_permission
  );
$$;


ALTER FUNCTION "public"."_multideck_dexter_has_permission"("p_user_id" "uuid", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_refresh_dexter_email_search_document"("p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public."AI_DexterEmailSearchDocuments" (
    "AIDexterEmailSearch_MessageID",
    "AIDexterEmailSearch_Document",
    "AIDexterEmailSearch_UpdatedAt"
  )
  select
    message."CommMessage_ID",
    setweight(to_tsvector('simple'::regconfig, coalesce(message."CommMessage_Subject", '')), 'A') ||
    setweight(to_tsvector('simple'::regconfig, coalesce(participants.participant_text, '')), 'B') ||
    setweight(to_tsvector(
      'simple'::regconfig,
      coalesce(message."CommMessage_BodyPreview", '') || ' ' ||
      coalesce(message."CommMessage_BodyText", '')
    ), 'C'),
    now()
  from public."Comm_Messages" message
  left join lateral (
    select string_agg(
      coalesce(recipient."CommRecipient_Address", '') || ' ' ||
      coalesce(recipient."CommRecipient_NormalizedAddress", '') || ' ' ||
      coalesce(recipient."CommRecipient_DisplayNameSnapshot", ''),
      ' '
    ) as participant_text
    from public."Comm_MessageRecipients" recipient
    where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
  ) participants on true
  where message."CommMessage_ID" = p_message_id
  on conflict ("AIDexterEmailSearch_MessageID") do update
  set
    "AIDexterEmailSearch_Document" = excluded."AIDexterEmailSearch_Document",
    "AIDexterEmailSearch_UpdatedAt" = excluded."AIDexterEmailSearch_UpdatedAt";

  if not found then
    delete from public."AI_DexterEmailSearchDocuments"
    where "AIDexterEmailSearch_MessageID" = p_message_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_refresh_dexter_email_search_document"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_refresh_dexter_email_search_from_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  perform public._multideck_refresh_dexter_email_search_document(new."CommMessage_ID");
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_refresh_dexter_email_search_from_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_refresh_dexter_email_search_from_recipient"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_old_message_id uuid := case when tg_op in ('UPDATE', 'DELETE') then old."CommRecipient_MessageID" else null end;
  v_new_message_id uuid := case when tg_op in ('INSERT', 'UPDATE') then new."CommRecipient_MessageID" else null end;
begin
  if v_old_message_id is not null then
    perform public._multideck_refresh_dexter_email_search_document(v_old_message_id);
  end if;
  if v_new_message_id is not null and v_new_message_id is distinct from v_old_message_id then
    perform public._multideck_refresh_dexter_email_search_document(v_new_message_id);
  end if;
  return null;
end;
$$;


