CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_delete"("p_card_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record;
begin
  select * into v_context from public._multideck_crm_context();
  update public."CRM_ContactCards" set "ContactCard_DeletedAt" = now(), "ContactCard_Status" = 'paused', "ContactCard_UpdatedAt" = now()
  where "ContactCard_ID" = p_card_id and "Company_ID" = v_context.company_id and "ContactCard_DeletedAt" is null;
  if not found then raise exception 'Contact card not found.' using errcode = 'P0002'; end if;
end;
$$;


ALTER FUNCTION "public"."multideck_contact_card_delete"("p_card_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_mark_started"("p_scan_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  update public."CRM_ContactCardScans" set "Scan_StartedAt" = coalesce("Scan_StartedAt", now()) where "Scan_ID" = p_scan_id and "Scan_At" > now() - interval '24 hours';
$$;


ALTER FUNCTION "public"."multideck_contact_card_mark_started"("p_scan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_record_scan"("p_slug" "text", "p_device" "text", "p_browser" "text", "p_channel" "text", "p_country" "text", "p_region" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_card uuid; v_scan uuid;
begin
  select "ContactCard_ID" into v_card from public."CRM_ContactCards" where "ContactCard_Slug" = lower(btrim(p_slug)) and "ContactCard_Status" = 'published' and "ContactCard_DeletedAt" is null limit 1;
  if v_card is null then return null; end if;
  insert into public."CRM_ContactCardScans" ("ContactCard_ID", "Scan_Device", "Scan_Browser", "Scan_Channel", "Scan_Country", "Scan_Region")
  values (v_card, case when p_device in ('mobile','tablet','desktop') then p_device else 'desktop' end, left(coalesce(p_browser,'Other'),80), case when p_channel in ('direct-scan','shared-link','in-app-browser','unknown') then p_channel else 'unknown' end, left(coalesce(p_country,''),80), left(coalesce(p_region,''),80)) returning "Scan_ID" into v_scan;
  return v_scan;
end;
$$;


ALTER FUNCTION "public"."multideck_contact_card_record_scan"("p_slug" "text", "p_device" "text", "p_browser" "text", "p_channel" "text", "p_country" "text", "p_region" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_save"("p_card" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_id uuid;
  v_automation jsonb := coalesce(p_card -> 'automation', '{}'::jsonb);
  v_item jsonb;
  v_index integer;
  v_pipeline uuid;
  v_stage uuid;
  v_owner uuid;
begin
  select * into v_context from public._multideck_crm_context();
  begin v_id := nullif(p_card ->> 'id', '')::uuid; exception when invalid_text_representation then v_id := null; end;

  if v_id is null then
    insert into public."CRM_ContactCards" (
      "Company_ID", "Owner_User_ID", "ContactCard_Slug", "ContactCard_Label", "ContactCard_Context", "ContactCard_Status",
      "ContactCard_Person", "ContactCard_Branding", "ContactCard_LeadSource", "ContactCard_PublicHeading", "ContactCard_PublicSubheading",
      "ContactCard_SubmitLabel", "ContactCard_ThanksHeading", "ContactCard_ThanksBody", "ContactCard_PhoneField", "ContactCard_ShowPhone",
      "ContactCard_ShowWebsite", "ContactCard_ConsentEnabled", "ContactCard_ConsentCopy", "ContactCard_PrivacyUrl"
    ) values (
      v_context.company_id, coalesce(nullif(p_card ->> 'ownerUserId', '')::uuid, v_context.user_id), lower(p_card ->> 'slug'), p_card ->> 'label', coalesce(p_card ->> 'context', ''), coalesce(p_card ->> 'status', 'draft'),
      coalesce(p_card -> 'person', '{}'::jsonb), coalesce(p_card -> 'branding', '{}'::jsonb), coalesce(p_card ->> 'leadSource', ''), coalesce(p_card ->> 'publicHeading', ''), coalesce(p_card ->> 'publicSubheading', ''),
      coalesce(p_card ->> 'submitLabel', 'Continue'), coalesce(p_card ->> 'thanksHeading', ''), coalesce(p_card ->> 'thanksBody', ''), coalesce(p_card ->> 'phoneField', 'optional'), coalesce((p_card ->> 'showPhone')::boolean, true),
      coalesce((p_card ->> 'showWebsite')::boolean, true), coalesce((p_card ->> 'consentEnabled')::boolean, false), coalesce(p_card ->> 'consentCopy', ''), coalesce(p_card ->> 'privacyUrl', '')
    ) returning "ContactCard_ID" into v_id;
  else
    update public."CRM_ContactCards" set
      "Owner_User_ID" = coalesce(nullif(p_card ->> 'ownerUserId', '')::uuid, "Owner_User_ID"),
      "ContactCard_Slug" = lower(p_card ->> 'slug'), "ContactCard_Label" = p_card ->> 'label', "ContactCard_Context" = coalesce(p_card ->> 'context', ''), "ContactCard_Status" = coalesce(p_card ->> 'status', 'draft'),
      "ContactCard_Person" = coalesce(p_card -> 'person', '{}'::jsonb), "ContactCard_Branding" = coalesce(p_card -> 'branding', '{}'::jsonb), "ContactCard_LeadSource" = coalesce(p_card ->> 'leadSource', ''),
      "ContactCard_PublicHeading" = coalesce(p_card ->> 'publicHeading', ''), "ContactCard_PublicSubheading" = coalesce(p_card ->> 'publicSubheading', ''), "ContactCard_SubmitLabel" = coalesce(p_card ->> 'submitLabel', 'Continue'),
      "ContactCard_ThanksHeading" = coalesce(p_card ->> 'thanksHeading', ''), "ContactCard_ThanksBody" = coalesce(p_card ->> 'thanksBody', ''), "ContactCard_PhoneField" = coalesce(p_card ->> 'phoneField', 'optional'),
      "ContactCard_ShowPhone" = coalesce((p_card ->> 'showPhone')::boolean, true), "ContactCard_ShowWebsite" = coalesce((p_card ->> 'showWebsite')::boolean, true), "ContactCard_ConsentEnabled" = coalesce((p_card ->> 'consentEnabled')::boolean, false),
      "ContactCard_ConsentCopy" = coalesce(p_card ->> 'consentCopy', ''), "ContactCard_PrivacyUrl" = coalesce(p_card ->> 'privacyUrl', ''), "ContactCard_UpdatedAt" = now()
    where "ContactCard_ID" = v_id and "Company_ID" = v_context.company_id and "ContactCard_DeletedAt" is null;
    if not found then raise exception 'Contact card not found.' using errcode = 'P0002'; end if;
  end if;

  insert into public."CRM_ContactCardAutomations" ("ContactCard_ID", "Automation_State", "Automation_HasUnpublishedChanges", "Automation_LastRunAt", "Automation_AutoPausedReason", "Automation_UpdatedAt")
  values (v_id, coalesce(v_automation ->> 'state', 'off'), coalesce((v_automation ->> 'hasUnpublishedChanges')::boolean, false), nullif(v_automation ->> 'lastRunAt', '')::timestamptz, nullif(v_automation ->> 'autoPausedReason', ''), now())
  on conflict ("ContactCard_ID") do update set "Automation_State" = excluded."Automation_State", "Automation_HasUnpublishedChanges" = excluded."Automation_HasUnpublishedChanges", "Automation_LastRunAt" = excluded."Automation_LastRunAt", "Automation_AutoPausedReason" = excluded."Automation_AutoPausedReason", "Automation_UpdatedAt" = now();

  delete from public."CRM_ContactCardAutomationConditions" where "ContactCard_ID" = v_id;
  for v_item, v_index in select value, ordinality - 1 from jsonb_array_elements(coalesce(v_automation -> 'conditions', '[]'::jsonb)) with ordinality loop
    insert into public."CRM_ContactCardAutomationConditions" ("ContactCard_ID", "Condition_Kind", "Condition_Negated", "Condition_Value", "Condition_Enabled", "Condition_SortOrder")
    values (v_id, v_item ->> 'kind', coalesce((v_item ->> 'negated')::boolean, false), coalesce(v_item ->> 'value', ''), coalesce((v_item ->> 'enabled')::boolean, true), v_index);
  end loop;

  delete from public."CRM_ContactCardAutomationActions" where "ContactCard_ID" = v_id;
  for v_item, v_index in select value, ordinality - 1 from jsonb_array_elements(coalesce(v_automation -> 'actions', '[]'::jsonb)) with ordinality loop
    v_pipeline := nullif(v_item #>> '{config,pipelineId}', '')::uuid;
    v_stage := nullif(v_item #>> '{config,stageId}', '')::uuid;
    v_owner := nullif(v_item #>> '{config,ownerId}', '')::uuid;
    if v_item ->> 'kind' = 'pipeline-stage' and not exists (
      select 1 from public."CRM_Pipelines" p join public."CRM_PipelineStages" s on s."CRMPipeline_ID" = p."CRMPipeline_ID"
      where p."Company_ID" = v_context.company_id and p."CRMPipeline_ID" = v_pipeline and s."CRMPipelineStage_ID" = v_stage and not p."Is_Deleted" and not s."Is_Deleted"
    ) then raise exception 'Choose a valid pipeline and stage.' using errcode = '22023'; end if;
    if v_owner is not null and not exists (select 1 from public."cmp_Users" where "User_ID" = v_owner and "Company_ID" = v_context.company_id) then raise exception 'Choose a valid owner.' using errcode = '22023'; end if;
    insert into public."CRM_ContactCardAutomationActions" ("ContactCard_ID", "Action_Kind", "Action_Enabled", "Action_Config", "Action_DelayMinutes", "Action_PipelineID", "Action_PipelineStageID", "Action_OwnerUserID", "Action_SortOrder")
    values (v_id, v_item ->> 'kind', coalesce((v_item ->> 'enabled')::boolean, true), coalesce(v_item -> 'config', '{}'::jsonb), coalesce((v_item ->> 'delayMinutes')::integer, 0), v_pipeline, v_stage, v_owner, v_index);
  end loop;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."multideck_contact_card_save"("p_card" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_submit_exchange"("p_slug" "text", "p_scan_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_card record; v_automation record; v_email text; v_lead uuid; v_existing boolean := false; v_action record; v_actions integer := 0; v_exchange uuid; v_outcome text;
begin
  select * into v_card from public."CRM_ContactCards" where "ContactCard_Slug" = lower(btrim(p_slug)) and "ContactCard_Status" = 'published' and "ContactCard_DeletedAt" is null limit 1;
  if not found then raise exception 'This contact card is not active.' using errcode = 'P0002'; end if;
  v_email := lower(btrim(p_input ->> 'email'));
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'Enter a valid email address.' using errcode = '22023'; end if;
  select "CRMLead_ID" into v_lead from public."CRM_Leads" where lower("CRMLead_Email") = v_email and not "CRMLead_IsDeleted" order by "CRMLead_CreatedAt" limit 1;
  v_existing := v_lead is not null;
  if not v_existing then
    insert into public."CRM_Leads" ("CRMLead_SourceCode", "CRMLead_StatusCode", "CRMLead_RatingCode", "CRMLead_OwnerUserID", "CRMLead_CompanyName", "CRMLead_PersonName", "CRMLead_Email", "CRMLead_Phone", "CRMLead_MetadataJSON", "CRMLead_CreatedBy", "CRMLead_UpdatedBy")
    values ('website', 'new', 'unrated', v_card."Owner_User_ID", left(btrim(p_input ->> 'company'),255), left(btrim(concat_ws(' ', p_input ->> 'firstName', p_input ->> 'lastName')),255), left(v_email,255), left(coalesce(p_input ->> 'phone',''),80), jsonb_build_object('contactCardId', v_card."ContactCard_ID", 'contactCardSlug', v_card."ContactCard_Slug", 'leadSource', v_card."ContactCard_LeadSource", 'marketingConsent', coalesce((p_input ->> 'marketingConsent')::boolean,false)), v_card."Owner_User_ID", v_card."Owner_User_ID")
    returning "CRMLead_ID" into v_lead;
  end if;

  select * into v_automation from public."CRM_ContactCardAutomations" where "ContactCard_ID" = v_card."ContactCard_ID";
  if p_scan_id is not null and not exists (select 1 from public."CRM_ContactCardScans" where "Scan_ID" = p_scan_id and "ContactCard_ID" = v_card."ContactCard_ID" and "Scan_At" > now() - interval '24 hours') then
    p_scan_id := null;
  end if;
  if v_automation."Automation_State" = 'active' then
    for v_action in select * from public."CRM_ContactCardAutomationActions" where "ContactCard_ID" = v_card."ContactCard_ID" and "Action_Enabled" order by "Action_SortOrder" loop
      if v_action."Action_Kind" = 'assign-owner' and v_action."Action_OwnerUserID" is not null then
        update public."CRM_Leads" set "CRMLead_OwnerUserID" = v_action."Action_OwnerUserID", "CRMLead_UpdatedAt" = now(), "CRMLead_UpdatedBy" = v_card."Owner_User_ID" where "CRMLead_ID" = v_lead;
        v_actions := v_actions + 1;
      elsif v_action."Action_Kind" = 'pipeline-stage' and v_action."Action_PipelineID" is not null and v_action."Action_PipelineStageID" is not null then
        insert into public."CRM_LeadPipelinePlacements" ("CRMLead_ID", "CRMPipeline_ID", "CRMPipelineStage_ID", "ContactCard_ID") values (v_lead, v_action."Action_PipelineID", v_action."Action_PipelineStageID", v_card."ContactCard_ID")
        on conflict ("CRMLead_ID") do update set "CRMPipeline_ID" = excluded."CRMPipeline_ID", "CRMPipelineStage_ID" = excluded."CRMPipelineStage_ID", "ContactCard_ID" = excluded."ContactCard_ID", "Placed_At" = now();
        v_actions := v_actions + 1;
      end if;
    end loop;
  end if;
  v_outcome := case when v_existing then 'matched' else 'created' end;
  insert into public."CRM_ContactCardExchanges" ("ContactCard_ID", "Scan_ID", "CRMLead_ID", "Exchange_FirstName", "Exchange_LastName", "Exchange_Email", "Exchange_Company", "Exchange_Phone", "Exchange_MarketingConsent", "Exchange_Outcome", "Exchange_AutomationOutcome", "Exchange_AutomationDetail")
  values (v_card."ContactCard_ID", p_scan_id, v_lead, btrim(p_input ->> 'firstName'), btrim(p_input ->> 'lastName'), v_email, btrim(p_input ->> 'company'), btrim(coalesce(p_input ->> 'phone','')), coalesce((p_input ->> 'marketingConsent')::boolean,false), v_outcome, case when v_actions > 0 then 'ran' when v_automation."Automation_State" = 'active' then 'skipped' else 'none' end, case when v_actions > 0 then v_actions || ' connected CRM actions ran.' when v_automation."Automation_State" = 'active' then 'No connected action applied.' else 'Automation is off for this card.' end)
  returning "Exchange_ID" into v_exchange;
  update public."CRM_ContactCardScans" set "Scan_StartedAt" = coalesce("Scan_StartedAt",now()), "Scan_ExchangedAt" = now() where "Scan_ID" = p_scan_id and "ContactCard_ID" = v_card."ContactCard_ID";
  update public."CRM_ContactCardAutomations" set "Automation_LastRunAt" = case when v_actions > 0 then now() else "Automation_LastRunAt" end where "ContactCard_ID" = v_card."ContactCard_ID";
  return jsonb_build_object('outcome', v_outcome, 'exchangeId', v_exchange, 'leadId', v_lead, 'automationActionsRun', v_actions);
end;
$_$;


ALTER FUNCTION "public"."multideck_contact_card_submit_exchange"("p_slug" "text", "p_scan_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_contact_cards_workspace"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select jsonb_build_object(
    'cards', coalesce((select jsonb_agg(to_jsonb(c) order by c."ContactCard_UpdatedAt" desc) from public."CRM_ContactCards" c where c."Company_ID" = v_context.company_id and c."ContactCard_DeletedAt" is null), '[]'::jsonb),
    'automations', coalesce((select jsonb_agg(to_jsonb(a)) from public."CRM_ContactCardAutomations" a join public."CRM_ContactCards" c using ("ContactCard_ID") where c."Company_ID" = v_context.company_id and c."ContactCard_DeletedAt" is null), '[]'::jsonb),
    'conditions', coalesce((select jsonb_agg(to_jsonb(x) order by x."Condition_SortOrder") from public."CRM_ContactCardAutomationConditions" x join public."CRM_ContactCards" c using ("ContactCard_ID") where c."Company_ID" = v_context.company_id and c."ContactCard_DeletedAt" is null), '[]'::jsonb),
    'actions', coalesce((select jsonb_agg(to_jsonb(x) order by x."Action_SortOrder") from public."CRM_ContactCardAutomationActions" x join public."CRM_ContactCards" c using ("ContactCard_ID") where c."Company_ID" = v_context.company_id and c."ContactCard_DeletedAt" is null), '[]'::jsonb),
    'scans', coalesce((select jsonb_agg(to_jsonb(s) order by s."Scan_At") from public."CRM_ContactCardScans" s join public."CRM_ContactCards" c using ("ContactCard_ID") where c."Company_ID" = v_context.company_id and c."ContactCard_DeletedAt" is null), '[]'::jsonb),
    'exchanges', coalesce((select jsonb_agg(to_jsonb(e) order by e."Exchange_At") from public."CRM_ContactCardExchanges" e join public."CRM_ContactCards" c using ("ContactCard_ID") where c."Company_ID" = v_context.company_id and c."ContactCard_DeletedAt" is null), '[]'::jsonb),
    'pipelines', coalesce((select jsonb_agg(jsonb_build_object(
      'id', p."CRMPipeline_ID", 'name', p."CRMPipeline_Name",
      'stages', (select coalesce(jsonb_agg(jsonb_build_object('id', s."CRMPipelineStage_ID", 'name', s."CRMPipelineStage_Name", 'isDefaultEntry', s."CRMPipelineStage_IsDefaultEntry") order by s."CRMPipelineStage_SortOrder"), '[]'::jsonb) from public."CRM_PipelineStages" s where s."CRMPipeline_ID" = p."CRMPipeline_ID" and not s."Is_Deleted")
    ) order by p."CRMPipeline_SortOrder") from public."CRM_Pipelines" p where p."Company_ID" = v_context.company_id and not p."Is_Deleted"), '[]'::jsonb),
    'owners', coalesce((select jsonb_agg(jsonb_build_object('id', u."User_ID", 'name', btrim(concat_ws(' ', u."User_Firstname", u."User_Lastname")), 'email', u."User_Email") order by u."User_Firstname", u."User_Lastname") from public."cmp_Users" u where u."Company_ID" = v_context.company_id and u."Auth_User_ID" is not null), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_contact_cards_workspace"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_convert_lead"("p_lead_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_lead record;
  v_existing_id uuid;
  v_deal_id uuid := gen_random_uuid();
  v_name text := nullif(btrim(p_input ->> 'name'), '');
  v_type_code text := nullif(btrim(p_input ->> 'opportunityTypeCode'), '');
  v_primary_contact_id uuid := nullif(p_input ->> 'primaryContactId', '')::uuid;
  v_expected_close_date date := nullif(p_input ->> 'expectedCloseDate', '')::date;
  v_expected_value numeric := nullif(p_input ->> 'expectedValueAmount', '')::numeric;
  v_expected_margin numeric := nullif(p_input ->> 'expectedMarginAmount', '')::numeric;
  v_currency text := upper(nullif(btrim(p_input ->> 'currencyCode'), ''));
  v_probability numeric := coalesce(nullif(p_input ->> 'probabilityPct', '')::numeric, 0);
  v_next_action timestamptz := nullif(p_input ->> 'nextActionDueAt', '')::timestamptz;
  v_customer_need text := nullif(btrim(p_input ->> 'customerNeed'), '');
  v_pipeline record;
  v_pipeline_stage record;
  v_stage_code text;
  v_status_code text;
  v_forecast_code text;
  v_converted_status text;
  v_account_id uuid;
begin
  select * into v_context from public._multideck_crm_context();
  perform pg_advisory_xact_lock(hashtextextended(p_lead_id::text, 0));

  select deal."CRMOppty_ID" into v_existing_id
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
  where deal."CRMOppty_SourceLeadID" = p_lead_id
    and not deal."CRMOppty_IsDeleted"
    and pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted"
  limit 1;

  if v_existing_id is not null then
    return public._multideck_crm_deal_json(v_existing_id, v_context.company_id)
      || jsonb_build_object('wasAlreadyConverted', true);
  end if;

  select * into v_lead
  from public."CRM_Leads"
  where "CRMLead_ID" = p_lead_id and not "CRMLead_IsDeleted"
  for update;

  if not found then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;
  if v_lead."CRMLead_OrgID" is null then
    raise exception 'Add a company to this lead before converting it to a deal.' using errcode = '22023';
  end if;
  if v_name is null then
    raise exception 'Give the deal a name.' using errcode = '22023';
  end if;
  if length(v_name) > 240 then
    raise exception 'Deal names must be 240 characters or fewer.' using errcode = '22023';
  end if;
  if v_type_code is null then
    raise exception 'Choose a deal type.' using errcode = '22023';
  end if;
  if v_expected_close_date is null or v_expected_close_date < current_date then
    raise exception 'Expected close date cannot be in the past.' using errcode = '22023';
  end if;
  if coalesce(v_expected_value, 0) < 0 then
    raise exception 'Expected value cannot be negative.' using errcode = '22023';
  end if;
  if coalesce(v_expected_margin, 0) < 0 then
    raise exception 'Expected margin cannot be negative.' using errcode = '22023';
  end if;
  if (v_expected_value is not null or v_expected_margin is not null) and v_currency is null then
    raise exception 'Choose a currency for the commercial values.' using errcode = '22023';
  end if;
  if v_probability < 0 or v_probability > 100 then
    raise exception 'Probability must be between 0 and 100.' using errcode = '22023';
  end if;
  if v_customer_need is null then
    raise exception 'Describe what the customer needs from this deal.' using errcode = '22023';
  end if;
  if v_next_action is null or v_next_action <= now() then
    raise exception 'Next action must be in the future.' using errcode = '22023';
  end if;

  if v_primary_contact_id is not null and not exists (
    select 1
    from public."Org_Contacts"
    where "OrgContact_ID" = v_primary_contact_id
      and "Org_ID" = v_lead."CRMLead_OrgID"
  ) then
    raise exception 'Choose a contact linked to this lead''s company.' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public."sys_CRMOpportunityTypes"
    where "CRMOpptyType_Code" = v_type_code
      and "CRMOpptyType_IsActive"
  ) then
    raise exception 'Choose an active deal type.' using errcode = '22023';
  end if;

  select * into v_pipeline
  from public."CRM_Pipelines"
  where "Company_ID" = v_context.company_id and not "Is_Deleted"
  order by "CRMPipeline_SortOrder"
  limit 1;
  if not found then
    raise exception 'Create a deal pipeline before converting this lead.' using errcode = '22023';
  end if;

  select * into v_pipeline_stage
  from public."CRM_PipelineStages"
  where "Company_ID" = v_context.company_id
    and "CRMPipeline_ID" = v_pipeline."CRMPipeline_ID"
    and not "Is_Deleted"
  order by "CRMPipelineStage_IsDefaultEntry" desc, "CRMPipelineStage_SortOrder"
  limit 1;
  if not found then
    raise exception 'Add an entry stage to this deal pipeline before converting this lead.' using errcode = '22023';
  end if;

  select "CRMStage_Code" into v_stage_code
  from public."sys_CRMOpportunityStages"
  where "CRMStage_IsActive" and "CRMStage_IsOpen"
  order by "CRMStage_SortOrder"
  limit 1;

  select "CRMOpptyStatus_Code" into v_status_code
  from public."sys_CRMOpportunityStatuses"
  where "CRMOpptyStatus_IsActive" and "CRMOpptyStatus_IsOpen"
  order by "CRMOpptyStatus_SortOrder"
  limit 1;

  select "CRMForecast_Code" into v_forecast_code
  from public."sys_CRMForecastCategories"
  where "CRMForecast_IsActive" and "CRMForecast_IsIncluded"
  order by "CRMForecast_SortOrder"
  limit 1;

  select "CRMLeadStatus_Code" into v_converted_status
  from public."sys_CRMLeadStatuses"
  where "CRMLeadStatus_IsActive" and "CRMLeadStatus_IsConverted"
  order by "CRMLeadStatus_SortOrder"
  limit 1;

  if v_stage_code is null or v_status_code is null or v_forecast_code is null or v_converted_status is null then
    raise exception 'The workspace CRM lookups are incomplete.' using errcode = '55000';
  end if;

  select "CRMAccount_ID" into v_account_id
  from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = v_lead."CRMLead_OrgID"
    and not "CRMAccount_IsDeleted"
  limit 1;

  insert into public."CRM_Opportunities" (
    "CRMOppty_ID",
    "CRMOppty_AccountID",
    "CRMOppty_OrgID",
    "CRMOppty_PrimaryContactID",
    "CRMOppty_SourceLeadID",
    "CRMOppty_OwnerUserID",
    "CRMOppty_OrgOfficeID",
    "CRMOppty_LegalEntityID",
    "CRMOppty_BrandID",
    "CRMOppty_PipelineID",
    "CRMOppty_PipelineStageID",
    "CRMOppty_Name",
    "CRMOppty_TypeCode",
    "CRMOppty_StageCode",
    "CRMOppty_StatusCode",
    "CRMOppty_ForecastCategoryCode",
    "CRMOppty_ModeCode",
    "CRMOppty_DirectionCode",
    "CRMOppty_OriginNameSnapshot",
    "CRMOppty_DestinationNameSnapshot",
    "CRMOppty_TradeLane",
    "CRMOppty_ServiceInterest",
    "CRMOppty_ExpectedCloseDate",
    "CRMOppty_ProbabilityPct",
    "CRMOppty_ExpectedValueAmount",
    "CRMOppty_ExpectedMarginAmount",
    "CRMOppty_CurrencyCode",
    "CRMOppty_WeightedValueAmount",
    "CRMOppty_NextActionDueAt",
    "CRMOppty_LastActivityAt",
    "CRMOppty_CustomerNeed",
    "CRMOppty_ValueProposition",
    "CRMOppty_MetadataJSON",
    "CRMOppty_CreatedAt",
    "CRMOppty_CreatedBy",
    "CRMOppty_UpdatedAt",
    "CRMOppty_UpdatedBy",
    "CRMOppty_IsDeleted"
  )
  values (
    v_deal_id,
    v_account_id,
    v_lead."CRMLead_OrgID",
    coalesce(v_primary_contact_id, v_lead."CRMLead_PrimaryContactID"),
    p_lead_id,
    coalesce(v_lead."CRMLead_OwnerUserID", v_context.user_id),
    v_lead."CRMLead_OrgOfficeID",
    v_lead."CRMLead_LegalEntityID",
    v_lead."CRMLead_BrandID",
    v_pipeline."CRMPipeline_ID",
    v_pipeline_stage."CRMPipelineStage_ID",
    v_name,
    v_type_code,
    v_stage_code,
    v_status_code,
    v_forecast_code,
    coalesce(nullif(btrim(p_input ->> 'modeCode'), ''), v_lead."CRMLead_ModeCode"),
    coalesce(nullif(btrim(p_input ->> 'directionCode'), ''), v_lead."CRMLead_DirectionCode"),
    nullif(btrim(p_input ->> 'originName'), ''),
    nullif(btrim(p_input ->> 'destinationName'), ''),
    coalesce(nullif(btrim(p_input ->> 'tradeLane'), ''), v_lead."CRMLead_TradeLane"),
    coalesce(nullif(btrim(p_input ->> 'serviceInterest'), ''), v_lead."CRMLead_ServiceInterest"),
    v_expected_close_date,
    round(v_probability, 2),
    v_expected_value,
    v_expected_margin,
    v_currency,
    case when v_expected_value is null then null else round(v_expected_value * v_probability / 100, 4) end,
    v_next_action,
    v_lead."CRMLead_LastInteractionAt",
    v_customer_need,
    nullif(btrim(p_input ->> 'valueProposition'), ''),
    jsonb_build_object('convertedFromLeadId', p_lead_id, 'conversionSource', 'lead_conversion_wizard'),
    now(),
    v_context.user_id,
    now(),
    v_context.user_id,
    false
  );

  insert into public."CRM_OpportunityStageHistory" (
    "CRMOpptyStage_ID",
    "CRMOpptyStage_OpportunityID",
    "CRMOpptyStage_ToStageCode",
    "CRMOpptyStage_ProbabilityPct",
    "CRMOpptyStage_Reason",
    "CRMOpptyStage_ChangedAt",
    "CRMOpptyStage_ChangedBy"
  )
  values (
    gen_random_uuid(),
    v_deal_id,
    v_stage_code,
    v_probability,
    'Created from lead conversion',
    now(),
    v_context.user_id
  );

  insert into public."CRM_LeadConversions" (
    "CRMLeadConv_ID",
    "CRMLeadConv_LeadID",
    "CRMLeadConv_OrgID",
    "CRMLeadConv_AccountID",
    "CRMLeadConv_OpportunityID",
    "CRMLeadConv_ConvertedAt",
    "CRMLeadConv_ConvertedBy",
    "CRMLeadConv_ConversionNotes"
  )
  values (
    gen_random_uuid(),
    p_lead_id,
    v_lead."CRMLead_OrgID",
    v_account_id,
    v_deal_id,
    now(),
    v_context.user_id,
    nullif(btrim(p_input ->> 'conversionNotes'), '')
  );

  insert into public."CRM_LeadStatusHistory" (
    "CRMLeadStatus_ID",
    "CRMLeadStatus_LeadID",
    "CRMLeadStatus_FromStatusCode",
    "CRMLeadStatus_ToStatusCode",
    "CRMLeadStatus_Reason",
    "CRMLeadStatus_ChangedAt",
    "CRMLeadStatus_ChangedBy"
  )
  values (
    gen_random_uuid(),
    p_lead_id,
    v_lead."CRMLead_StatusCode",
    v_converted_status,
    'Converted to deal',
    now(),
    v_context.user_id
  );

  update public."CRM_Leads"
  set
    "CRMLead_StatusCode" = v_converted_status,
    "CRMLead_UpdatedAt" = now(),
    "CRMLead_UpdatedBy" = v_context.user_id
  where "CRMLead_ID" = p_lead_id;

  return public._multideck_crm_deal_json(v_deal_id, v_context.company_id);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_convert_lead"("p_lead_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_deal_conversion_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select jsonb_build_object(
    'opportunityTypes',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'code', type."CRMOpptyType_Code",
          'name', type."CRMOpptyType_Name",
          'description', type."CRMOpptyType_Description"
        )
        order by type."CRMOpptyType_SortOrder", type."CRMOpptyType_Name"
      ),
      '[]'::jsonb
    )
  )
  into v_result
  from public."sys_CRMOpportunityTypes" type
  where type."CRMOpptyType_IsActive";

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_deal_conversion_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_get_lead"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_lead record;
  v_summary jsonb;
  v_company jsonb;
  v_contacts jsonb;
  v_activities jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select * into v_lead
  from public."CRM_Leads"
  where "CRMLead_ID" = p_lead_id and not "CRMLead_IsDeleted";

  if not found then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  v_summary := public._multideck_crm_lead_json(p_lead_id);

  select jsonb_build_object(
    'organisationId', v_lead."CRMLead_OrgID",
    'email', coalesce(
      address."OrgAdd_MainEmail",
      v_lead."CRMLead_MetadataJSON" ->> 'companyEmail',
      v_lead."CRMLead_MetadataJSON" ->> 'organisationEmail'
    ),
    'website', coalesce(
      v_lead."CRMLead_MetadataJSON" ->> 'companyWebsite',
      v_lead."CRMLead_MetadataJSON" ->> 'website',
      v_lead."CRMLead_MetadataJSON" ->> 'websiteUrl'
    ),
    'phone', coalesce(
      address."OrgAdd_MainPhone",
      v_lead."CRMLead_MetadataJSON" ->> 'companyPhone',
      v_lead."CRMLead_MetadataJSON" ->> 'organisationPhone'
    ),
    'address', coalesce(
      nullif(concat_ws(', ',
        nullif(btrim(address."Org_NameOverride"), ''),
        nullif(btrim(address."OrgAdd_Line1"), ''),
        nullif(btrim(address."OrgAdd_Line2"), ''),
        nullif(btrim(concat_ws(' ',
          address."OrgAdd_TownCity",
          address."OrgAdd_CountyState",
          address."OrgAdd_PostZipCode"
        )), ''),
        nullif(btrim(address."OrgAdd_Country"), '')
      ), ''),
      v_lead."CRMLead_MetadataJSON" ->> 'companyAddress',
      v_lead."CRMLead_MetadataJSON" ->> 'address'
    )
  )
  into v_company
  from (select 1) seed
  left join lateral (
    select a.*
    from public."Org_Addresses" a
    where a."Org_ID" = v_lead."CRMLead_OrgID"
    order by (a."OrgAdd_MainEmail" is not null) desc, a."OrgAdd_ID"
    limit 1
  ) address on true;

  with linked_contacts as (
    select
      contact."OrgContact_ID" as id,
      nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '') as name,
      profile."CRMContact_RoleCode" as role_code,
      email.email,
      phone.phone,
      contact."OrgContact_ID" = v_lead."CRMLead_PrimaryContactID" as is_primary,
      coalesce(
        profile."CRMContact_LastContactAt",
        case when contact."OrgContact_ID" = v_lead."CRMLead_PrimaryContactID"
          then (v_summary ->> 'lastActivityAt')::timestamptz
        end
      ) as last_contact_at
    from public."Org_Contacts" contact
    left join public."CRM_ContactProfiles" profile
      on profile."CRMContact_OrgContactID" = contact."OrgContact_ID"
    left join lateral (
      select nullif(btrim(e."OrgContactEmail_Email"), '') as email
      from public."OrgContact_Emails" e
      where e."OrgContact_ID" = contact."OrgContact_ID"
      order by e."OrgContactEmail_Type", e."OrgContactEmail_ID"
      limit 1
    ) email on true
    left join lateral (
      select nullif(btrim(i."CommIdentity_Address"), '') as phone
      from public."Comm_Identities" i
      where i."CommIdentity_ContactID" = contact."OrgContact_ID"
        and not i."CommIdentity_IsDeleted"
        and i."CommIdentity_ChannelCode" in ('phone', 'sms', 'whatsapp')
      order by coalesce(i."CommIdentity_LastSeenAt", i."CommIdentity_UpdatedAt") desc
      limit 1
    ) phone on true
    where contact."Org_ID" = v_lead."CRMLead_OrgID"
  ),
  contact_rows as (
    select * from linked_contacts
    union all
    select
      coalesce(v_lead."CRMLead_PrimaryContactID", v_lead."CRMLead_ID") as id,
      nullif(btrim(v_lead."CRMLead_PersonName"), '') as name,
      null::varchar as role_code,
      nullif(btrim(v_lead."CRMLead_Email"), '') as email,
      nullif(btrim(v_lead."CRMLead_Phone"), '') as phone,
      true as is_primary,
      (v_summary ->> 'lastActivityAt')::timestamptz as last_contact_at
    where (
      nullif(btrim(v_lead."CRMLead_PersonName"), '') is not null
      or nullif(btrim(v_lead."CRMLead_Email"), '') is not null
      or nullif(btrim(v_lead."CRMLead_Phone"), '') is not null
    )
    and not exists (
      select 1
      from linked_contacts existing
      where existing.id = v_lead."CRMLead_PrimaryContactID"
         or (
           existing.email is not null
           and lower(existing.email) = lower(nullif(btrim(v_lead."CRMLead_Email"), ''))
         )
    )
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', id,
        'name', name,
        'initials', public._multideck_crm_initials(coalesce(name, email, '?')),
        'roleCode', role_code,
        'email', email,
        'phone', phone,
        'isPrimary', is_primary,
        'lastContactAt', last_contact_at
      )
      order by is_primary desc, name nulls last
    ),
    '[]'::jsonb
  )
  into v_contacts
  from contact_rows;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', activity."CRMActivity_ID",
        'typeCode', activity."CRMActivity_ActivityTypeCode",
        'subject', activity."CRMActivity_Subject",
        'summary', nullif(btrim(activity."CRMActivity_Summary"), ''),
        'activityAt', activity."CRMActivity_ActivityAt"
      )
      order by activity."CRMActivity_ActivityAt" desc
    ),
    '[]'::jsonb
  )
  into v_activities
  from (
    select *
    from public."CRM_Activities"
    where "CRMActivity_LeadID" = p_lead_id
      and not "CRMActivity_IsDeleted"
    order by "CRMActivity_ActivityAt" desc
    limit 8
  ) activity;

  return v_summary || jsonb_build_object(
    'company', v_company,
    'contacts', v_contacts,
    'activities', v_activities
  );
end;
$$;


ALTER FUNCTION "public"."multideck_crm_get_lead"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_list_deals"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select coalesce(
    jsonb_agg(
      public._multideck_crm_deal_json(deal."CRMOppty_ID", v_context.company_id)
      order by
        (deal."CRMOppty_ExpectedCloseDate" is null),
        deal."CRMOppty_ExpectedCloseDate",
        deal."CRMOppty_CreatedAt" desc
    ),
    '[]'::jsonb
  )
  into v_result
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
    and pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted"
  join public."CRM_PipelineStages" stage
    on stage."CRMPipelineStage_ID" = deal."CRMOppty_PipelineStageID"
    and not stage."Is_Deleted"
  where not deal."CRMOppty_IsDeleted";

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_list_deals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_list_leads"("p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_search text := nullif(btrim(p_search), '');
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select coalesce(
    jsonb_agg(
      public._multideck_crm_lead_json(l."CRMLead_ID")
      order by
        (l."CRMLead_NextActionDueAt" is null),
        l."CRMLead_NextActionDueAt",
        l."CRMLead_LastInteractionAt" desc nulls last,
        l."CRMLead_CreatedAt" desc
    ),
    '[]'::jsonb
  )
  into v_result
  from public."CRM_Leads" l
  left join public."cmp_Users" owner on owner."User_ID" = l."CRMLead_OwnerUserID"
  where not l."CRMLead_IsDeleted"
    and (
      v_search is null
      or l."CRMLead_CompanyName" ilike '%' || v_search || '%'
      or l."CRMLead_PersonName" ilike '%' || v_search || '%'
      or l."CRMLead_Email" ilike '%' || v_search || '%'
      or owner."User_Email" ilike '%' || v_search || '%'
    );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_list_leads"("p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_move_deal_stage"("p_deal_id" "uuid", "p_pipeline_id" "uuid", "p_pipeline_stage_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_stage record;
  v_deal record;
begin
  select * into v_context from public._multideck_crm_context();

  select stage.* into v_stage
  from public."CRM_PipelineStages" stage
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = stage."CRMPipeline_ID"
  where stage."CRMPipelineStage_ID" = p_pipeline_stage_id
    and stage."CRMPipeline_ID" = p_pipeline_id
    and stage."Company_ID" = v_context.company_id
    and pipeline."Company_ID" = v_context.company_id
    and not stage."Is_Deleted"
    and not pipeline."Is_Deleted";

  if not found then
    raise exception 'Choose a stage from an active pipeline in this workspace.' using errcode = '22023';
  end if;

  select deal.* into v_deal
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
  where deal."CRMOppty_ID" = p_deal_id
    and not deal."CRMOppty_IsDeleted"
    and pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted"
  for update of deal;

  if not found then
    raise exception 'Deal not found.' using errcode = 'P0002';
  end if;

  update public."CRM_Opportunities"
  set
    "CRMOppty_PipelineID" = p_pipeline_id,
    "CRMOppty_PipelineStageID" = p_pipeline_stage_id,
    "CRMOppty_ProbabilityPct" = v_stage."CRMPipelineStage_ProbabilityPct",
    "CRMOppty_WeightedValueAmount" =
      case
        when v_deal."CRMOppty_ExpectedValueAmount" is null then null
        else round(
          v_deal."CRMOppty_ExpectedValueAmount" * v_stage."CRMPipelineStage_ProbabilityPct" / 100,
          4
        )
      end,
    "CRMOppty_UpdatedAt" = now(),
    "CRMOppty_UpdatedBy" = v_context.user_id
  where "CRMOppty_ID" = p_deal_id;

  insert into public."CRM_OpportunityStageHistory" (
    "CRMOpptyStage_ID",
    "CRMOpptyStage_OpportunityID",
    "CRMOpptyStage_FromStageCode",
    "CRMOpptyStage_ToStageCode",
    "CRMOpptyStage_ProbabilityPct",
    "CRMOpptyStage_Reason",
    "CRMOpptyStage_ChangedAt",
    "CRMOpptyStage_ChangedBy"
  )
  values (
    gen_random_uuid(),
    p_deal_id,
    v_deal."CRMOppty_StageCode",
    v_deal."CRMOppty_StageCode",
    v_stage."CRMPipelineStage_ProbabilityPct",
    'Moved to ' || v_stage."CRMPipelineStage_Name",
    now(),
    v_context.user_id
  );

  return public._multideck_crm_deal_json(p_deal_id, v_context.company_id);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_move_deal_stage"("p_deal_id" "uuid", "p_pipeline_id" "uuid", "p_pipeline_stage_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_mutate_pipeline_settings"("p_action" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_now timestamptz := now();
  v_name text;
  v_owner text;
  v_automation text;
  v_stages jsonb;
  v_stage jsonb;
  v_stage_id uuid;
  v_pipeline_id uuid;
  v_field_id uuid;
  v_sort_order integer;
  v_options jsonb;
  v_active_options jsonb;
  v_type text;
  v_result jsonb;
  v_ids uuid[];
begin
  select * into v_context from public._multideck_crm_context();
  perform public._multideck_crm_require_settings_manage(v_context.user_id);

  if v_action in ('create_pipeline', 'save_pipeline') then
    if jsonb_typeof(p_payload) is distinct from 'object' then
      raise exception 'Pipeline details are required.' using errcode = '22023';
    end if;

    v_name := btrim(coalesce(p_payload->>'name', ''));
    v_owner := nullif(btrim(coalesce(p_payload->>'owner', '')), '');
    v_automation := nullif(btrim(coalesce(p_payload->>'automation', '')), '');
    v_stages := coalesce(p_payload->'stages', '[]'::jsonb);

    if v_name = '' then
      raise exception 'Give the pipeline a name before saving.' using errcode = '22023';
    end if;
    if jsonb_typeof(v_stages) is distinct from 'array' or jsonb_array_length(v_stages) = 0 then
      raise exception 'A pipeline needs at least one stage.' using errcode = '22023';
    end if;
    if jsonb_array_length(v_stages) > 24 then
      raise exception 'A pipeline can hold up to 24 stages.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_stages) stage
      where btrim(coalesce(stage->>'name', '')) = ''
    ) then
      raise exception 'Every stage needs a name.' using errcode = '22023';
    end if;
    if exists (
      select 1
      from jsonb_array_elements(v_stages) stage
      group by lower(btrim(stage->>'name'))
      having count(*) > 1
    ) then
      raise exception 'A stage name is used more than once.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_stages) stage
      where lower(coalesce(stage->>'tone', '')) not in ('green', 'amber', 'red', 'blue', 'neutral', 'teal')
    ) then
      raise exception 'Choose a supported stage colour.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_stages) stage
      where coalesce((stage->>'probability')::numeric, 0) < 0
         or coalesce((stage->>'probability')::numeric, 0) > 100
    ) then
      raise exception 'Win probability must be between 0 and 100.' using errcode = '22023';
    end if;
    if (
      select count(*) from jsonb_array_elements(v_stages) stage
      where coalesce((stage->>'isDefaultEntry')::boolean, false)
    ) > 1 then
      raise exception 'Only one stage can be the default entry point.' using errcode = '22023';
    end if;
    if (
      select count(*) from jsonb_array_elements(v_stages) stage
      where coalesce((stage->>'isConversion')::boolean, false)
    ) > 1 then
      raise exception 'Only one stage can be the conversion trigger.' using errcode = '22023';
    end if;

    if exists (
      select 1
      from public."CRM_Pipelines" pipeline
      where pipeline."Company_ID" = v_context.company_id
        and not pipeline."Is_Deleted"
        and lower(pipeline."CRMPipeline_Name") = lower(v_name)
        and (v_action = 'create_pipeline' or pipeline."CRMPipeline_ID" <> p_id)
    ) then
      raise exception 'Another pipeline already uses that name.' using errcode = '23505';
    end if;

    if v_action = 'create_pipeline' then
      if (
        select count(*)
        from public."CRM_Pipelines" pipeline
        where pipeline."Company_ID" = v_context.company_id
          and not pipeline."Is_Deleted"
      ) >= 24 then
        raise exception 'A workspace can hold up to 24 pipelines.' using errcode = '22023';
      end if;

      select coalesce(max(pipeline."CRMPipeline_SortOrder") + 1, 0)
      into v_sort_order
      from public."CRM_Pipelines" pipeline
      where pipeline."Company_ID" = v_context.company_id
        and not pipeline."Is_Deleted";

      v_pipeline_id := gen_random_uuid();
      insert into public."CRM_Pipelines" (
        "CRMPipeline_ID", "Company_ID", "CRMPipeline_Name", "CRMPipeline_Owner",
        "CRMPipeline_Automation", "CRMPipeline_SortOrder", "Created_At", "Updated_At",
        "Created_By_User_ID", "Updated_By_User_ID", "Is_Deleted"
      ) values (
        v_pipeline_id, v_context.company_id, v_name, v_owner, v_automation, v_sort_order,
        v_now, v_now, v_context.user_id, v_context.user_id, false
      );
    else
      select pipeline."CRMPipeline_ID"
      into v_pipeline_id
      from public."CRM_Pipelines" pipeline
      where pipeline."CRMPipeline_ID" = p_id
        and pipeline."Company_ID" = v_context.company_id
        and not pipeline."Is_Deleted"
      for update;

      if v_pipeline_id is null then
        raise exception 'That pipeline no longer exists.' using errcode = 'P0002';
      end if;

      if exists (
        select 1
        from jsonb_array_elements(v_stages) stage
        where nullif(stage->>'id', '') is not null
          and not exists (
            select 1
            from public."CRM_PipelineStages" existing
            where existing."CRMPipelineStage_ID" = (stage->>'id')::uuid
              and existing."CRMPipeline_ID" = v_pipeline_id
              and existing."Company_ID" = v_context.company_id
              and not existing."Is_Deleted"
          )
      ) then
        raise exception 'A pipeline stage changed while you were editing. Reload and try again.' using errcode = '55000';
      end if;

      update public."CRM_PipelineStages" stage
      set
        "CRMPipelineStage_Name" = stage."CRMPipelineStage_ID"::text,
        "CRMPipelineStage_IsDefaultEntry" = false,
        "CRMPipelineStage_IsConversion" = false,
        "Is_Deleted" = not exists (
          select 1
          from jsonb_array_elements(v_stages) incoming
          where nullif(incoming->>'id', '')::uuid = stage."CRMPipelineStage_ID"
        ),
        "Updated_At" = v_now
      where stage."CRMPipeline_ID" = v_pipeline_id
        and stage."Company_ID" = v_context.company_id
        and not stage."Is_Deleted";

      update public."CRM_Pipelines"
      set
        "CRMPipeline_Name" = v_name,
        "CRMPipeline_Owner" = v_owner,
        "CRMPipeline_Automation" = v_automation,
        "Updated_At" = v_now,
        "Updated_By_User_ID" = v_context.user_id
      where "CRMPipeline_ID" = v_pipeline_id;
    end if;

    v_sort_order := 0;
    for v_stage in select value from jsonb_array_elements(v_stages)
    loop
      v_stage_id := nullif(v_stage->>'id', '')::uuid;

      if v_stage_id is null then
        v_stage_id := gen_random_uuid();
        insert into public."CRM_PipelineStages" (
          "CRMPipelineStage_ID", "Company_ID", "CRMPipeline_ID", "CRMPipelineStage_Name",
          "CRMPipelineStage_Tone", "CRMPipelineStage_EntryRule",
          "CRMPipelineStage_ProbabilityPct", "CRMPipelineStage_SortOrder",
          "CRMPipelineStage_IsDefaultEntry", "CRMPipelineStage_IsConversion",
          "Created_At", "Updated_At", "Is_Deleted"
        ) values (
          v_stage_id, v_context.company_id, v_pipeline_id, btrim(v_stage->>'name'),
          lower(v_stage->>'tone'), nullif(btrim(coalesce(v_stage->>'rule', '')), ''),
          round(coalesce((v_stage->>'probability')::numeric, 0), 2), v_sort_order,
          coalesce((v_stage->>'isDefaultEntry')::boolean, false),
          coalesce((v_stage->>'isConversion')::boolean, false),
          v_now, v_now, false
        );
      else
        update public."CRM_PipelineStages"
        set
          "CRMPipelineStage_Name" = btrim(v_stage->>'name'),
          "CRMPipelineStage_Tone" = lower(v_stage->>'tone'),
          "CRMPipelineStage_EntryRule" = nullif(btrim(coalesce(v_stage->>'rule', '')), ''),
          "CRMPipelineStage_ProbabilityPct" = round(coalesce((v_stage->>'probability')::numeric, 0), 2),
          "CRMPipelineStage_SortOrder" = v_sort_order,
          "CRMPipelineStage_IsDefaultEntry" = coalesce((v_stage->>'isDefaultEntry')::boolean, false),
          "CRMPipelineStage_IsConversion" = coalesce((v_stage->>'isConversion')::boolean, false),
          "Updated_At" = v_now,
          "Is_Deleted" = false
        where "CRMPipelineStage_ID" = v_stage_id
          and "CRMPipeline_ID" = v_pipeline_id
          and "Company_ID" = v_context.company_id;
      end if;

      v_sort_order := v_sort_order + 1;
    end loop;

    return public._multideck_crm_pipeline_json(v_pipeline_id, v_context.company_id);
  end if;

  if v_action = 'delete_pipeline' then
    update public."CRM_Pipelines"
    set
      "Is_Deleted" = true,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    where "CRMPipeline_ID" = p_id
      and "Company_ID" = v_context.company_id
      and not "Is_Deleted"
    returning "CRMPipeline_ID" into v_pipeline_id;

    if v_pipeline_id is null then
      raise exception 'That pipeline no longer exists.' using errcode = 'P0002';
    end if;

    update public."CRM_PipelineStages"
    set "Is_Deleted" = true, "Updated_At" = v_now
    where "CRMPipeline_ID" = v_pipeline_id
      and "Company_ID" = v_context.company_id
      and not "Is_Deleted";

    return null;
  end if;

  if v_action = 'reorder_pipelines' then
    if jsonb_typeof(p_payload) is distinct from 'array' then
      raise exception 'The complete pipeline order is required.' using errcode = '22023';
    end if;

    select coalesce(array_agg((item.value #>> '{}')::uuid order by item.ordinality), '{}'::uuid[])
    into v_ids
    from jsonb_array_elements(p_payload) with ordinality item(value, ordinality);

    if cardinality(v_ids) <> (
      select count(*) from public."CRM_Pipelines"
      where "Company_ID" = v_context.company_id and not "Is_Deleted"
    ) or cardinality(v_ids) <> (
      select count(distinct id) from unnest(v_ids) id
    ) or exists (
      select 1 from unnest(v_ids) id
      where not exists (
        select 1 from public."CRM_Pipelines"
        where "CRMPipeline_ID" = id
          and "Company_ID" = v_context.company_id
          and not "Is_Deleted"
      )
    ) then
      raise exception 'The pipeline list changed while you were reordering. Reload and try again.' using errcode = '55000';
    end if;

    update public."CRM_Pipelines" pipeline
    set
      "CRMPipeline_SortOrder" = ordered.ordinality - 1,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    from unnest(v_ids) with ordinality ordered(id, ordinality)
    where pipeline."CRMPipeline_ID" = ordered.id;

    select coalesce(
      jsonb_agg(public._multideck_crm_pipeline_json(id, v_context.company_id) order by ordinality),
      '[]'::jsonb
    )
    into v_result
    from unnest(v_ids) with ordinality ordered(id, ordinality);

    return v_result;
  end if;

  if v_action in ('create_field', 'save_field') then
    if jsonb_typeof(p_payload) is distinct from 'object' then
      raise exception 'Lead field details are required.' using errcode = '22023';
    end if;

    if v_action = 'save_field' then
      select field."CRMLeadField_ID", field."CRMLeadField_Label", field."CRMLeadField_TypeCode",
        field."CRMLeadField_OptionsJSON"
      into v_field_id, v_name, v_type, v_options
      from public."CRM_LeadFieldSettings" field
      where field."CRMLeadField_ID" = p_id
        and field."Company_ID" = v_context.company_id
        and not field."Is_Deleted"
      for update;

      if v_field_id is null then
        raise exception 'That lead field no longer exists.' using errcode = 'P0002';
      end if;
    else
      v_name := '';
      v_type := '';
      v_options := '[]'::jsonb;
    end if;

    if p_payload ? 'label' then v_name := btrim(coalesce(p_payload->>'label', '')); end if;
    if p_payload ? 'type' then v_type := btrim(coalesce(p_payload->>'type', '')); end if;
    if p_payload ? 'options' then v_options := coalesce(p_payload->'options', '[]'::jsonb); end if;
    v_active_options := coalesce(p_payload->'activeOptions', '[]'::jsonb);

    if v_name = '' then
      raise exception 'Give the field a name before saving.' using errcode = '22023';
    end if;
    if lower(v_type) = 'dropdown' then
      v_type := 'Dropdown';
    elsif lower(v_type) = 'multi-select dropdown' then
      v_type := 'Multi-select dropdown';
    else
      raise exception 'Choose a supported field type.' using errcode = '22023';
    end if;
    if jsonb_typeof(v_options) is distinct from 'array' or jsonb_array_length(v_options) = 0 then
      raise exception 'Give the field at least one option.' using errcode = '22023';
    end if;
    if jsonb_array_length(v_options) > 40 then
      raise exception 'A field can hold up to 40 options.' using errcode = '22023';
    end if;
    if jsonb_typeof(v_active_options) is distinct from 'array' then
      raise exception 'Selected options must be a list.' using errcode = '22023';
    end if;
    if exists (
      select 1
      from jsonb_array_elements_text(v_active_options) active(value)
      where not exists (
        select 1 from jsonb_array_elements_text(v_options) option(value)
        where lower(btrim(option.value)) = lower(btrim(active.value))
      )
    ) then
      raise exception 'A selected value is not an option on this field.' using errcode = '22023';
    end if;
    if exists (
      select 1
      from public."CRM_LeadFieldSettings" field
      where field."Company_ID" = v_context.company_id
        and not field."Is_Deleted"
        and lower(field."CRMLeadField_Label") = lower(v_name)
        and (v_action = 'create_field' or field."CRMLeadField_ID" <> p_id)
    ) then
      raise exception 'Another lead field already uses that name.' using errcode = '23505';
    end if;

    if v_action = 'create_field' then
      if (
        select count(*) from public."CRM_LeadFieldSettings"
        where "Company_ID" = v_context.company_id and not "Is_Deleted"
      ) >= 40 then
        raise exception 'A workspace can hold up to 40 lead fields.' using errcode = '22023';
      end if;

      select coalesce(max(field."CRMLeadField_SortOrder") + 1, 0)
      into v_sort_order
      from public."CRM_LeadFieldSettings" field
      where field."Company_ID" = v_context.company_id
        and not field."Is_Deleted";

      v_field_id := gen_random_uuid();
      insert into public."CRM_LeadFieldSettings" (
        "CRMLeadField_ID", "Company_ID", "CRMLeadField_Label", "CRMLeadField_TypeCode",
        "CRMLeadField_OptionsJSON", "CRMLeadField_ActiveOptionsJSON", "CRMLeadField_SortOrder",
        "Created_At", "Updated_At", "Updated_By_User_ID", "Is_Deleted"
      ) values (
        v_field_id, v_context.company_id, v_name, v_type, v_options, v_active_options,
        v_sort_order, v_now, v_now, v_context.user_id, false
      );
    else
      update public."CRM_LeadFieldSettings"
      set
        "CRMLeadField_Label" = v_name,
        "CRMLeadField_TypeCode" = v_type,
        "CRMLeadField_OptionsJSON" = v_options,
        "CRMLeadField_ActiveOptionsJSON" = v_active_options,
        "Updated_At" = v_now,
        "Updated_By_User_ID" = v_context.user_id
      where "CRMLeadField_ID" = v_field_id;
    end if;

    return public._multideck_crm_lead_field_json(v_field_id, v_context.company_id);
  end if;

  if v_action = 'delete_field' then
    update public."CRM_LeadFieldSettings"
    set
      "Is_Deleted" = true,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    where "CRMLeadField_ID" = p_id
      and "Company_ID" = v_context.company_id
      and not "Is_Deleted"
    returning "CRMLeadField_ID" into v_field_id;

    if v_field_id is null then
      raise exception 'That lead field no longer exists.' using errcode = 'P0002';
    end if;

    return null;
  end if;

  if v_action = 'reorder_fields' then
    if jsonb_typeof(p_payload) is distinct from 'array' then
      raise exception 'The complete field order is required.' using errcode = '22023';
    end if;

    select coalesce(array_agg((item.value #>> '{}')::uuid order by item.ordinality), '{}'::uuid[])
    into v_ids
    from jsonb_array_elements(p_payload) with ordinality item(value, ordinality);

    if cardinality(v_ids) <> (
      select count(*) from public."CRM_LeadFieldSettings"
      where "Company_ID" = v_context.company_id and not "Is_Deleted"
    ) or cardinality(v_ids) <> (
      select count(distinct id) from unnest(v_ids) id
    ) or exists (
      select 1 from unnest(v_ids) id
      where not exists (
        select 1 from public."CRM_LeadFieldSettings"
        where "CRMLeadField_ID" = id
          and "Company_ID" = v_context.company_id
          and not "Is_Deleted"
      )
    ) then
      raise exception 'The field list changed while you were reordering. Reload and try again.' using errcode = '55000';
    end if;

    update public."CRM_LeadFieldSettings" field
    set
      "CRMLeadField_SortOrder" = ordered.ordinality - 1,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    from unnest(v_ids) with ordinality ordered(id, ordinality)
    where field."CRMLeadField_ID" = ordered.id;

    select coalesce(
      jsonb_agg(public._multideck_crm_lead_field_json(id, v_context.company_id) order by ordinality),
      '[]'::jsonb
    )
    into v_result
    from unnest(v_ids) with ordinality ordered(id, ordinality);

    return v_result;
  end if;

  raise exception 'That CRM settings action is not supported.' using errcode = '22023';
end;
$$;


ALTER FUNCTION "public"."multideck_crm_mutate_pipeline_settings"("p_action" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_pipeline_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_pipelines jsonb;
  v_fields jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pipeline."CRMPipeline_ID",
        'name', pipeline."CRMPipeline_Name",
        'owner', coalesce(pipeline."CRMPipeline_Owner", ''),
        'automation', coalesce(pipeline."CRMPipeline_Automation", ''),
        'sortOrder', pipeline."CRMPipeline_SortOrder",
        'defaultStage', coalesce(
          (
            select stage."CRMPipelineStage_Name"
            from public."CRM_PipelineStages" stage
            where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
              and not stage."Is_Deleted"
            order by stage."CRMPipelineStage_IsDefaultEntry" desc, stage."CRMPipelineStage_SortOrder"
            limit 1
          ),
          ''
        ),
        'conversionStage', coalesce(
          (
            select stage."CRMPipelineStage_Name"
            from public."CRM_PipelineStages" stage
            where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
              and not stage."Is_Deleted"
            order by stage."CRMPipelineStage_IsConversion" desc, stage."CRMPipelineStage_SortOrder" desc
            limit 1
          ),
          ''
        ),
        'stages', coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id', stage."CRMPipelineStage_ID",
                'name', stage."CRMPipelineStage_Name",
                'tone', stage."CRMPipelineStage_Tone",
                'rule', coalesce(stage."CRMPipelineStage_EntryRule", ''),
                'probability', stage."CRMPipelineStage_ProbabilityPct",
                'sortOrder', stage."CRMPipelineStage_SortOrder",
                'isDefaultEntry', stage."CRMPipelineStage_IsDefaultEntry",
                'isConversion', stage."CRMPipelineStage_IsConversion"
              )
              order by stage."CRMPipelineStage_SortOrder"
            )
            from public."CRM_PipelineStages" stage
            where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
              and not stage."Is_Deleted"
          ),
          '[]'::jsonb
        )
      )
      order by pipeline."CRMPipeline_SortOrder", pipeline."CRMPipeline_Name"
    ),
    '[]'::jsonb
  )
  into v_pipelines
  from public."CRM_Pipelines" pipeline
  where pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted";

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', field."CRMLeadField_ID",
        'label', field."CRMLeadField_Label",
        'type', field."CRMLeadField_TypeCode",
        'options', coalesce(field."CRMLeadField_OptionsJSON", '[]'::jsonb),
        'activeOptions', coalesce(field."CRMLeadField_ActiveOptionsJSON", '[]'::jsonb),
        'sortOrder', field."CRMLeadField_SortOrder"
      )
      order by field."CRMLeadField_SortOrder", field."CRMLeadField_Label"
    ),
    '[]'::jsonb
  )
  into v_fields
  from public."CRM_LeadFieldSettings" field
  where field."Company_ID" = v_context.company_id
    and not field."Is_Deleted";

  return jsonb_build_object('pipelines', v_pipelines, 'fields', v_fields);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_pipeline_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_deal"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_target_id uuid := (p_arguments ->> 'target_id')::uuid;
  v_probability numeric := nullif(btrim(coalesce(p_arguments ->> 'probability_pct', '')), '')::numeric;
  v_result jsonb;
begin
  if v_probability is not null and (v_probability < 0 or v_probability > 100) then
    raise exception 'Deal probability must be between 0 and 100.' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_arguments ->> 'expected_close_date', '')), '') is null
     and v_probability is null
     and nullif(btrim(coalesce(p_arguments ->> 'next_action_due_at', '')), '') is null
     and nullif(btrim(coalesce(p_arguments ->> 'value_proposition', '')), '') is null then
    raise exception 'Choose at least one deal field to update.' using errcode = '22023';
  end if;

  update public."CRM_Opportunities" deal
  set
    "CRMOppty_ExpectedCloseDate" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'expected_close_date', '')), '')::date,
      deal."CRMOppty_ExpectedCloseDate"
    ),
    "CRMOppty_ProbabilityPct" = coalesce(v_probability, deal."CRMOppty_ProbabilityPct"),
    "CRMOppty_WeightedValueAmount" = case
      when v_probability is not null and deal."CRMOppty_ExpectedValueAmount" is not null
      then round(deal."CRMOppty_ExpectedValueAmount" * v_probability / 100, 4)
      else deal."CRMOppty_WeightedValueAmount"
    end,
    "CRMOppty_NextActionDueAt" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'next_action_due_at', '')), '')::timestamptz,
      deal."CRMOppty_NextActionDueAt"
    ),
    "CRMOppty_ValueProposition" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'value_proposition', '')), ''),
      deal."CRMOppty_ValueProposition"
    ),
    "CRMOppty_UpdatedAt" = now(),
    "CRMOppty_UpdatedBy" = p_user_id
  from public."CRM_Pipelines" pipeline
  where deal."CRMOppty_ID" = v_target_id
    and deal."CRMOppty_PipelineID" = pipeline."CRMPipeline_ID"
    and pipeline."Company_ID" = p_company_id
    and not pipeline."Is_Deleted"
    and not deal."CRMOppty_IsDeleted"
  returning jsonb_build_object(
    'name', deal."CRMOppty_Name",
    'expectedCloseDate', deal."CRMOppty_ExpectedCloseDate",
    'probabilityPct', deal."CRMOppty_ProbabilityPct",
    'nextActionDueAt', deal."CRMOppty_NextActionDueAt",
    'valueProposition', deal."CRMOppty_ValueProposition"
  ) into v_result;

  if v_result is null then
    raise exception 'That deal is outside this workspace or no longer exists.' using errcode = 'P0002';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_action_update_deal"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_lead"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_target_id uuid := (p_arguments ->> 'target_id')::uuid;
  v_company_name text := nullif(btrim(coalesce(p_arguments ->> 'company_name', '')), '');
  v_result jsonb;
begin
  if v_company_name is null
     and nullif(btrim(coalesce(p_arguments ->> 'next_action_due_at', '')), '') is null
     and nullif(btrim(coalesce(p_arguments ->> 'service_interest', '')), '') is null then
    raise exception 'Choose at least one lead field to update.' using errcode = '22023';
  end if;

  if length(v_company_name) > 240 then
    raise exception 'Lead name must be 240 characters or fewer.' using errcode = '22023';
  end if;

  update public."CRM_Leads" lead
  set
    "CRMLead_CompanyName" = coalesce(v_company_name, lead."CRMLead_CompanyName"),
    "CRMLead_NextActionDueAt" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'next_action_due_at', '')), '')::timestamptz,
      lead."CRMLead_NextActionDueAt"
    ),
    "CRMLead_ServiceInterest" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'service_interest', '')), ''),
      lead."CRMLead_ServiceInterest"
    ),
    "CRMLead_UpdatedAt" = now(),
    "CRMLead_UpdatedBy" = p_user_id
  where lead."CRMLead_ID" = v_target_id
    and not lead."CRMLead_IsDeleted"
    and exists (
      select 1
      from public."cmp_Users" workspace_user
      where workspace_user."Company_ID" = p_company_id
        and workspace_user."User_ID" in (
          lead."CRMLead_OwnerUserID",
          lead."CRMLead_CreatedBy"
        )
    )
  returning jsonb_build_object(
    'companyName', lead."CRMLead_CompanyName",
    'nextActionDueAt', lead."CRMLead_NextActionDueAt",
    'serviceInterest', lead."CRMLead_ServiceInterest"
  ) into v_result;

  if v_result is null then
    raise exception 'That lead is outside this workspace or no longer exists.' using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_action_update_lead"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_quote"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_target_id uuid := (p_arguments ->> 'target_id')::uuid;
  v_result jsonb;
begin
  if nullif(btrim(coalesce(p_arguments ->> 'deadline', '')), '') is null
     and nullif(btrim(coalesce(p_arguments ->> 'service_level', '')), '') is null
     and nullif(btrim(coalesce(p_arguments ->> 'internal_notes', '')), '') is null
     and nullif(btrim(coalesce(p_arguments ->> 'valid_from', '')), '') is null
     and nullif(btrim(coalesce(p_arguments ->> 'valid_to', '')), '') is null then
    raise exception 'Choose at least one quote field to update.' using errcode = '22023';
  end if;

  update public."CusQuote_Header" quote
  set
    "CusQuoteHeader_Deadline" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'deadline', '')), '')::timestamp,
      quote."CusQuoteHeader_Deadline"
    ),
    "CusQuoteHeader_ServiceLevel" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'service_level', '')), ''),
      quote."CusQuoteHeader_ServiceLevel"
    ),
    "CusQuoteHeader_InternalNotes" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'internal_notes', '')), ''),
      quote."CusQuoteHeader_InternalNotes"
    ),
    "CusQuoteHeader_ValidFrom" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'valid_from', '')), '')::date,
      quote."CusQuoteHeader_ValidFrom"
    ),
    "CusQuoteHeader_ValidTo" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'valid_to', '')), '')::date,
      quote."CusQuoteHeader_ValidTo"
    ),
    "CusQuoteHeader_LastEditedDate" = now(),
    "CusQuoteHeader_LastEditedBy" = p_user_id
  where quote."CusQuoteHeader_ID" = v_target_id
    and (
      quote."Org_ID" = p_company_id
      or exists (
        select 1
        from public."cmp_Offices" office
        where office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
          and office."Company_ID" = p_company_id
      )
    )
    and not quote."CusQuoteHeader_IsDeleted"
  returning jsonb_build_object(
    'quoteNumber', quote."CusQuoteHeader_Number",
    'deadline', quote."CusQuoteHeader_Deadline",
    'serviceLevel', quote."CusQuoteHeader_ServiceLevel",
    'validFrom', quote."CusQuoteHeader_ValidFrom",
    'validTo', quote."CusQuoteHeader_ValidTo"
  ) into v_result;

  if v_result is null then
    raise exception 'That quote is outside this workspace or no longer exists.' using errcode = 'P0002';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_action_update_quote"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_warehouse_order"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_target_id uuid := (p_arguments ->> 'target_id')::uuid;
  v_result jsonb;
begin
  if nullif(btrim(coalesce(p_arguments ->> 'requested_date', '')), '') is null
     and nullif(btrim(coalesce(p_arguments ->> 'instructions', '')), '') is null then
    raise exception 'Choose at least one warehouse order field to update.' using errcode = '22023';
  end if;

  update public."WMS_Orders" orders
  set
    "WMSOrder_RequestedDate" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'requested_date', '')), '')::date,
      orders."WMSOrder_RequestedDate"
    ),
    "WMSOrder_Instructions" = coalesce(
      nullif(btrim(coalesce(p_arguments ->> 'instructions', '')), ''),
      orders."WMSOrder_Instructions"
    ),
    "WMSOrder_UpdatedAt" = now(),
    "WMSOrder_UpdatedBy" = p_user_id
  from public."WMS_Facilities" facility
  join public."cmp_Offices" office on office."Office_ID" = facility."WMSFacility_OrgOfficeID"
  where orders."WMSOrder_ID" = v_target_id
    and orders."WMSOrder_FacilityID" = facility."WMSFacility_ID"
    and office."Company_ID" = p_company_id
    and not orders."WMSOrder_IsDeleted"
  returning jsonb_build_object(
    'orderNumber', orders."WMSOrder_OrderNumber",
    'requestedDate', orders."WMSOrder_RequestedDate",
    'instructions', orders."WMSOrder_Instructions"
  ) into v_result;

  if v_result is null then
    raise exception 'That warehouse order is outside this workspace or no longer exists.' using errcode = 'P0002';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_action_update_warehouse_order"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_close_conversation"("p_conversation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_now timestamptz := clock_timestamp();
begin
  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  update public."AI_Conversations" conversation
  set
    "AICNV_Status" = 'closed',
    "AICNV_EndedAt" = v_now,
    "AICNV_UpdatedAt" = v_now,
    "AICNV_UpdatedBy" = v_user_id
  where conversation."AICNV_ID" = p_conversation_id
    and conversation."AICNV_CompanyID" = v_company_id
    and conversation."AICNV_OwnerUserID" = v_user_id
    and conversation."AICNV_Channel" = 'chat'
    and conversation."AICNV_EndedAt" is null
    and conversation."AICNV_DomainCode" in ('multideck', 'warehouse');

  if not found then
    raise exception 'This conversation does not exist or is outside your workspace.'
      using errcode = 'P0002';
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_close_conversation"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_conversation_email_context"("p_conversation_id" "uuid", "p_history_message_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_context record;
  v_attachments jsonb;
  v_providers jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if p_conversation_id is null then
    return jsonb_build_object('attachments', '[]'::jsonb, 'providers', '[]'::jsonb);
  end if;

  if not exists (
    select 1
    from public."AI_Conversations" conversation
    where conversation."AICNV_ID" = p_conversation_id
      and conversation."AICNV_CompanyID" = v_context.company_id
      and conversation."AICNV_OwnerUserID" = v_context.user_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_EndedAt" is null
  ) then
    raise exception 'This conversation does not exist or is outside your workspace.' using errcode = 'P0002';
  end if;

  select coalesce(jsonb_agg(context_row.attachment order by context_row.created_at desc, context_row.ordinality), '[]'::jsonb)
  into v_attachments
  from (
    select attachment.value as attachment, message."AIMSG_CreatedAt" as created_at, attachment.ordinality
    from public."AI_Messages" message
    cross join lateral jsonb_array_elements(
      case
        when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}') = 'array'
          then message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}'
        else '[]'::jsonb
      end
    ) with ordinality attachment(value, ordinality)
    where message."AIMSG_ConversationID" = p_conversation_id
      and message."AIMSG_Role" = 'assistant'
      and (p_history_message_ids is null or message."AIMSG_ID" = any(p_history_message_ids))
      and jsonb_typeof(attachment.value) = 'object'
      and coalesce(attachment.value ->> 'id', '') ~ '^[0-9a-fA-F-]{36}$'
      and attachment.value ->> 'provider' in ('gmail', 'outlook')
    order by message."AIMSG_CreatedAt" desc, attachment.ordinality
    limit 5
  ) context_row;

  select coalesce(jsonb_agg(provider_rows.provider order by provider_rows.provider), '[]'::jsonb)
  into v_providers
  from (
    select distinct lower(regexp_replace(attachment.value ->> 'id', '^email:', '')) as provider
    from public."AI_Messages" message
    cross join lateral jsonb_array_elements(
      case
        when jsonb_typeof(message."AIMSG_ContentJSON" -> 'attachments') = 'array'
          then message."AIMSG_ContentJSON" -> 'attachments'
        else '[]'::jsonb
      end
    ) attachment(value)
    where message."AIMSG_ConversationID" = p_conversation_id
      and message."AIMSG_Role" = 'user'
      and (p_history_message_ids is null or message."AIMSG_ID" = any(p_history_message_ids))
      and jsonb_typeof(attachment.value) = 'object'
      and attachment.value ->> 'type' = 'email'
      and lower(regexp_replace(attachment.value ->> 'id', '^email:', '')) in ('gmail', 'outlook')
  ) provider_rows;

  return jsonb_build_object(
    'attachments', v_attachments,
    'providers', v_providers
  );
end;
$_$;


ALTER FUNCTION "public"."multideck_dexter_conversation_email_context"("p_conversation_id" "uuid", "p_history_message_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_deals"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(row_data order by sort_close nulls last, sort_created desc), '[]'::jsonb)
  from (
    select
      jsonb_build_object(
        'recordId', deal."CRMOppty_ID",
        'name', deal."CRMOppty_Name",
        'pipeline', pipeline."CRMPipeline_Name",
        'stage', stage."CRMPipelineStage_Name",
        'status', deal."CRMOppty_StatusCode",
        'type', deal."CRMOppty_TypeCode",
        'mode', deal."CRMOppty_ModeCode",
        'direction', deal."CRMOppty_DirectionCode",
        'tradeLane', deal."CRMOppty_TradeLane",
        'serviceInterest', deal."CRMOppty_ServiceInterest",
        'expectedCloseDate', deal."CRMOppty_ExpectedCloseDate",
        'probabilityPct', deal."CRMOppty_ProbabilityPct",
        'expectedValue', deal."CRMOppty_ExpectedValueAmount",
        'expectedMargin', deal."CRMOppty_ExpectedMarginAmount",
        'weightedValue', deal."CRMOppty_WeightedValueAmount",
        'currency', deal."CRMOppty_CurrencyCode",
        'nextActionDueAt', deal."CRMOppty_NextActionDueAt",
        'lastActivityAt', deal."CRMOppty_LastActivityAt"
      ) as row_data,
      deal."CRMOppty_ExpectedCloseDate" as sort_close,
      deal."CRMOppty_CreatedAt" as sort_created
    from public."CRM_Opportunities" deal
    join public."CRM_Pipelines" pipeline
      on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
     and pipeline."Company_ID" = p_company_id
     and not pipeline."Is_Deleted"
    left join public."CRM_PipelineStages" stage
      on stage."CRMPipelineStage_ID" = deal."CRMOppty_PipelineStageID"
     and not stage."Is_Deleted"
    where not deal."CRMOppty_IsDeleted"
      and (
        nullif(btrim(p_search), '') is null
        or deal."CRMOppty_Name" ilike '%' || btrim(p_search) || '%'
        or deal."CRMOppty_TradeLane" ilike '%' || btrim(p_search) || '%'
        or deal."CRMOppty_ServiceInterest" ilike '%' || btrim(p_search) || '%'
        or pipeline."CRMPipeline_Name" ilike '%' || btrim(p_search) || '%'
        or stage."CRMPipelineStage_Name" ilike '%' || btrim(p_search) || '%'
      )
    order by deal."CRMOppty_ExpectedCloseDate" nulls last, deal."CRMOppty_CreatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) rows;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_deals"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_leads"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(row_data order by sort_due nulls last, sort_created desc), '[]'::jsonb)
  from (
    select
      jsonb_build_object(
        'recordId', lead."CRMLead_ID",
        'companyName', lead."CRMLead_CompanyName",
        'contactName', lead."CRMLead_PersonName",
        'contactEmail', lead."CRMLead_Email",
        'status', lead."CRMLead_StatusCode",
        'rating', lead."CRMLead_RatingCode",
        'source', lead."CRMLead_SourceCode",
        'owner', nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
        'mode', lead."CRMLead_ModeCode",
        'direction', lead."CRMLead_DirectionCode",
        'tradeLane', lead."CRMLead_TradeLane",
        'serviceInterest', lead."CRMLead_ServiceInterest",
        'estimatedValue', lead."CRMLead_EstimatedValueAmount",
        'currency', lead."CRMLead_EstimatedValueCurrencyCode",
        'urgency', lead."CRMLead_UrgencyCode",
        'score', lead."CRMLead_Score",
        'conversionProbability', lead."CRMLead_AIProbabilityToConvert",
        'nextActionDueAt', lead."CRMLead_NextActionDueAt",
        'lastInteractionAt', lead."CRMLead_LastInteractionAt"
      ) as row_data,
      lead."CRMLead_NextActionDueAt" as sort_due,
      lead."CRMLead_CreatedAt" as sort_created
    from public."CRM_Leads" lead
    left join public."cmp_Users" owner on owner."User_ID" = lead."CRMLead_OwnerUserID"
    left join public."cmp_Users" creator on creator."User_ID" = lead."CRMLead_CreatedBy"
    where not lead."CRMLead_IsDeleted"
      and (owner."Company_ID" = p_company_id or creator."Company_ID" = p_company_id)
      and (
        nullif(btrim(p_search), '') is null
        or lead."CRMLead_CompanyName" ilike '%' || btrim(p_search) || '%'
        or lead."CRMLead_PersonName" ilike '%' || btrim(p_search) || '%'
        or lead."CRMLead_Email" ilike '%' || btrim(p_search) || '%'
        or lead."CRMLead_TradeLane" ilike '%' || btrim(p_search) || '%'
        or lead."CRMLead_ServiceInterest" ilike '%' || btrim(p_search) || '%'
      )
    order by lead."CRMLead_NextActionDueAt" nulls last, lead."CRMLead_CreatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) rows;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_leads"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quotes"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(row_data order by sort_edited desc), '[]'::jsonb)
  from (
    select
      jsonb_build_object(
        'recordId', quote."CusQuoteHeader_ID",
        'quoteNumber', quote."CusQuoteHeader_Number",
        'type', quote."CusQuoteHeader_Type",
        'status', quote."CusQuoteHeader_Status",
        'deadline', quote."CusQuoteHeader_Deadline",
        'mode', quote."CusQuoteHeader_ModeCode",
        'shipmentType', quote."CusQuoteHeader_ShipmentTypeCode",
        'serviceLevel', quote."CusQuoteHeader_ServiceLevel",
        'currency', quote."CusQuoteHeader_CurrencyCode",
        'origin', quote."CusQuoteHeader_OriginExtra",
        'destination', quote."CusQuoteHeader_DestinationExtra",
        'direction', quote."CusQuoteHeader_Direction",
        'incoterm', quote."CusQuoteHeader_Incoterm",
        'validFrom', quote."CusQuoteHeader_ValidFrom",
        'validTo', quote."CusQuoteHeader_ValidTo",
        'lastEditedAt', quote."CusQuoteHeader_LastEditedDate"
      ) as row_data,
      quote."CusQuoteHeader_LastEditedDate" as sort_edited
    from public."CusQuote_Header" quote
    left join public."cmp_Offices" office
      on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
    where not quote."CusQuoteHeader_IsDeleted"
      and (quote."Org_ID" = p_company_id or office."Company_ID" = p_company_id)
      and (
        nullif(btrim(p_search), '') is null
        or quote."CusQuoteHeader_Number"::text ilike '%' || btrim(p_search) || '%'
        or quote."CusQuoteHeader_ModeCode" ilike '%' || btrim(p_search) || '%'
        or quote."CusQuoteHeader_OriginExtra" ilike '%' || btrim(p_search) || '%'
        or quote."CusQuoteHeader_DestinationExtra" ilike '%' || btrim(p_search) || '%'
      )
    order by quote."CusQuoteHeader_LastEditedDate" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) rows;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quotes"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_warehouse"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with parameters as (
    select
      nullif(btrim(p_search), '') as search,
      greatest(1, least(coalesce(p_take, 10), 15)) as take
  ),
  company_facilities as (
    select facility.*
    from public."WMS_Facilities" facility
    join public."cmp_Offices" office
      on office."Office_ID" = facility."WMSFacility_OrgOfficeID"
     and office."Company_ID" = p_company_id
    where not facility."WMSFacility_IsDeleted"
  ),
  overview as (
    select jsonb_build_object(
      'activeFacilities', (select count(*) from company_facilities where "WMSFacility_IsActive"),
      'openOrders', (
        select count(*)
        from public."WMS_Orders" orders
        join company_facilities facility on facility."WMSFacility_ID" = orders."WMSOrder_FacilityID"
        join public."sys_WMSOrderStatuses" status on status."WMSOrderStatus_Code" = orders."WMSOrder_StatusCode"
        where not orders."WMSOrder_IsDeleted" and status."WMSOrderStatus_IsOpen"
      ),
      'openTasks', (
        select count(*)
        from public."WMS_Tasks" tasks
        join company_facilities facility on facility."WMSFacility_ID" = tasks."WMSTask_FacilityID"
        join public."sys_WMSTaskStatuses" status on status."WMSTaskStatus_Code" = tasks."WMSTask_StatusCode"
        where status."WMSTaskStatus_IsOpen"
      ),
      'openExceptions', (
        select count(*)
        from public."WMS_Exceptions" exception
        join company_facilities facility on facility."WMSFacility_ID" = exception."WMSException_FacilityID"
        where exception."WMSException_ResolvedAt" is null
      ),
      'heldStockQuantity', (
        select coalesce(sum(balance."WMSBalance_HeldQuantity"), 0)
        from public."WMS_InventoryBalances" balance
        join company_facilities facility on facility."WMSFacility_ID" = balance."WMSBalance_FacilityID"
      )
    ) as value
  ),
  order_rows as (
    select jsonb_build_object(
      'recordId', orders."WMSOrder_ID",
      'orderNumber', orders."WMSOrder_OrderNumber",
      'type', orders."WMSOrder_TypeCode",
      'status', orders."WMSOrder_StatusCode",
      'priority', orders."WMSOrder_PriorityCode",
      'facility', facility."WMSFacility_Code",
      'customerReference', orders."WMSOrder_CustomerReference",
      'requestedDate', orders."WMSOrder_RequestedDate",
      'containerNumber', orders."WMSOrder_ContainerNumber",
      'releaseGateStatus', orders."WMSOrder_ReleaseGateStatusCode"
    ) as value
    from public."WMS_Orders" orders
    join company_facilities facility on facility."WMSFacility_ID" = orders."WMSOrder_FacilityID"
    cross join parameters
    where not orders."WMSOrder_IsDeleted"
      and (
        parameters.search is null
        or orders."WMSOrder_OrderNumber" ilike '%' || parameters.search || '%'
        or orders."WMSOrder_CustomerReference" ilike '%' || parameters.search || '%'
        or orders."WMSOrder_ContainerNumber" ilike '%' || parameters.search || '%'
        or facility."WMSFacility_Code" ilike '%' || parameters.search || '%'
        or facility."WMSFacility_Name" ilike '%' || parameters.search || '%'
      )
    order by orders."WMSOrder_RequestedDate" nulls last, orders."WMSOrder_UpdatedAt" desc
    limit (select take from parameters)
  ),
  inventory_rows as (
    select jsonb_build_object(
      'sku', item."WMSItem_SKU",
      'description', item."WMSItem_Description",
      'facility', facility."WMSFacility_Code",
      'inventoryStatus', balance."WMSBalance_InventoryStatusCode",
      'customsStatus', balance."WMSBalance_CustomsStatusCode",
      'onHand', balance."WMSBalance_OnHandQuantity",
      'available', balance."WMSBalance_AvailableQuantity",
      'reserved', balance."WMSBalance_ReservedQuantity",
      'held', balance."WMSBalance_HeldQuantity",
      'uom', balance."WMSBalance_UOMCode",
      'isBonded', balance."WMSBalance_IsBonded",
      'lastMovementAt', balance."WMSBalance_LastMovementAt"
    ) as value
    from public."WMS_InventoryBalances" balance
    join company_facilities facility on facility."WMSFacility_ID" = balance."WMSBalance_FacilityID"
    join public."WMS_Items" item on item."WMSItem_ID" = balance."WMSBalance_ItemID"
    cross join parameters
    where not item."WMSItem_IsDeleted"
      and (
        parameters.search is null
        or item."WMSItem_SKU" ilike '%' || parameters.search || '%'
        or item."WMSItem_Description" ilike '%' || parameters.search || '%'
        or facility."WMSFacility_Code" ilike '%' || parameters.search || '%'
        or facility."WMSFacility_Name" ilike '%' || parameters.search || '%'
      )
    order by balance."WMSBalance_UpdatedAt" desc
    limit (select take from parameters)
  ),
  exception_rows as (
    select jsonb_build_object(
      'title', exception."WMSException_Title",
      'description', exception."WMSException_Description",
      'type', exception."WMSException_TypeCode",
      'status', exception."WMSException_StatusCode",
      'severity', exception."WMSException_SeverityCode",
      'facility', facility."WMSFacility_Code",
      'orderNumber', orders."WMSOrder_OrderNumber",
      'raisedAt', exception."WMSException_RaisedAt"
    ) as value
    from public."WMS_Exceptions" exception
    join company_facilities facility on facility."WMSFacility_ID" = exception."WMSException_FacilityID"
    left join public."WMS_Orders" orders on orders."WMSOrder_ID" = exception."WMSException_OrderID"
    cross join parameters
    where exception."WMSException_ResolvedAt" is null
      and (
        parameters.search is null
        or exception."WMSException_Title" ilike '%' || parameters.search || '%'
        or exception."WMSException_Description" ilike '%' || parameters.search || '%'
        or exception."WMSException_SeverityCode" ilike '%' || parameters.search || '%'
        or facility."WMSFacility_Code" ilike '%' || parameters.search || '%'
        or orders."WMSOrder_OrderNumber" ilike '%' || parameters.search || '%'
      )
    order by exception."WMSException_RaisedAt" desc
    limit (select take from parameters)
  )
  select jsonb_build_object(
    'overview', (select value from overview),
    'orders', coalesce((select jsonb_agg(value) from order_rows), '[]'::jsonb),
    'inventory', coalesce((select jsonb_agg(value) from inventory_rows), '[]'::jsonb),
    'exceptions', coalesce((select jsonb_agg(value) from exception_rows), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_warehouse"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_execute_action"("p_action" "text", "p_arguments" "jsonb", "p_access_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_context record;
  v_code text := lower(btrim(coalesce(p_action, '')));
  v_mode text := lower(btrim(coalesce(p_access_mode, '')));
  v_action_function text;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_can_manage(v_context.user_id) then
    raise exception 'You do not have permission to let Dexter change workspace data.'
      using errcode = '42501';
  end if;
  if v_mode not in ('approve', 'full') then
    raise exception 'Choose Approve or Full access before changing data.' using errcode = '22023';
  end if;

  select action."AIDexterAction_Function"
  into v_action_function
  from public."sys_AIDexterActions" action
  join public."sys_AIDexterDataDomains" domain
    on domain."AIDexterDomain_Code" = action."AIDexterAction_DomainCode"
   and domain."AIDexterDomain_IsActive"
  where action."AIDexterAction_Code" = v_code
    and action."AIDexterAction_IsActive";

  if v_action_function is null then
    raise exception 'That Dexter action is not available in this workspace.' using errcode = '22023';
  end if;

  execute format('select public.%I($1, $2, $3)', v_action_function)
  into v_result
  using v_context.company_id, v_context.user_id, coalesce(p_arguments, '{}'::jsonb);

  insert into public."AI_DexterActionAudit" (
    "AIDexterAudit_CompanyID",
    "AIDexterAudit_UserID",
    "AIDexterAudit_ActionCode",
    "AIDexterAudit_AccessMode",
    "AIDexterAudit_ArgumentsJSON",
    "AIDexterAudit_ResultJSON"
  ) values (
    v_context.company_id,
    v_context.user_id,
    v_code,
    v_mode,
    coalesce(p_arguments, '{}'::jsonb),
    coalesce(v_result, '{}'::jsonb)
  );

  return jsonb_build_object('action', v_code, 'updated', true, 'result', v_result);
end;
$_$;


ALTER FUNCTION "public"."multideck_dexter_execute_action"("p_action" "text", "p_arguments" "jsonb", "p_access_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_get_conversation"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_result jsonb;
begin
  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  select public._multideck_dexter_conversation_json(
    p_conversation_id,
    v_user_id,
    v_company_id
  ) into v_result;

  if v_result is null then
    raise exception 'This conversation does not exist or is outside your workspace.'
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_get_conversation"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_get_usage"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_now timestamptz := now();
  v_period_start timestamptz := date_trunc('month', now());
  v_period_end timestamptz := date_trunc('month', now()) + interval '1 month';
  v_trend_start date := (date_trunc('week', now()) - interval '5 weeks')::date;
  v_result jsonb;
begin
  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  with scoped_rows as (
    select
      message."AIMSG_ID" as id,
      coalesce(conversation."AICNV_Title", 'Dexter conversation') as title,
      case lower(coalesce(message."AIMSG_ContentJSON" ->> 'model', 'fast'))
        when 'smart' then 'smart'
        when 'worker' then 'worker'
        else 'fast'
      end as model,
      greatest(coalesce(message."AIMSG_PromptTokens", 0), 0) as input_tokens,
      greatest(coalesce(message."AIMSG_CompletionTokens", 0), 0) as output_tokens,
      message."AIMSG_ConversationID" as conversation_id,
      message."AIMSG_CreatedAt" as created_at
    from public."AI_Messages" message
    join public."AI_Conversations" conversation
      on conversation."AICNV_ID" = message."AIMSG_ConversationID"
    where message."AIMSG_Role" = 'assistant'
      and message."AIMSG_CreatedAt" >= least(v_period_start, v_trend_start::timestamptz)
      and message."AIMSG_CreatedAt" < v_period_end
      and conversation."AICNV_CompanyID" = v_company_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_DomainCode" in ('multideck', 'warehouse')
  ),
  month_rows as (
    select *
    from scoped_rows
    where created_at >= v_period_start
  ),
  trend as (
    select jsonb_agg(
      jsonb_build_object(
        'weekStart', week.week_start,
        'actions', (
          select count(*)
          from scoped_rows row_data
          where row_data.created_at >= week.week_start::timestamptz
            and row_data.created_at < (week.week_start + 7)::timestamptz
        ),
        'tokens', (
          select coalesce(sum(row_data.input_tokens + row_data.output_tokens), 0)
          from scoped_rows row_data
          where row_data.created_at >= week.week_start::timestamptz
            and row_data.created_at < (week.week_start + 7)::timestamptz
        )
      )
      order by week.week_start
    ) as value
    from (
      select v_trend_start + (series.index * 7) as week_start
      from generate_series(0, 5) series(index)
    ) week
  ),
  model_breakdown as (
    select jsonb_agg(
      jsonb_build_object(
        'model', lane.model,
        'inputTokens', coalesce(sum(month.input_tokens), 0),
        'outputTokens', coalesce(sum(month.output_tokens), 0),
        'totalTokens', coalesce(sum(month.input_tokens + month.output_tokens), 0)
      )
      order by lane.position
    ) as value
    from (values ('fast'::text, 1), ('smart', 2), ('worker', 3)) as lane(model, position)
    left join month_rows month on month.model = lane.model
    group by lane.model, lane.position
  ),
  recent as (
    select coalesce(jsonb_agg(item.value order by item.created_at desc), '[]'::jsonb) as value
    from (
      select
        jsonb_build_object(
          'id', month.id,
          'title', month.title,
          'inputTokens', month.input_tokens,
          'outputTokens', month.output_tokens,
          'totalTokens', month.input_tokens + month.output_tokens,
          'createdAt', month.created_at
        ) as value,
        month.created_at
      from month_rows month
      order by month.created_at desc
      limit 50
    ) item
  )
  select jsonb_build_object(
    'periodStart', v_period_start,
    'periodEnd', v_period_end,
    'includedActionsLimit', 10000,
    'actionsUsed', (select count(*) from month_rows),
    'trackedActions', (
      select count(*)
      from month_rows
      where input_tokens + output_tokens > 0
    ),
    'conversationCount', (
      select count(distinct conversation_id)
      from month_rows
    ),
    'inputTokens', coalesce((select sum(input_tokens) from month_rows), 0),
    'outputTokens', coalesce((select sum(output_tokens) from month_rows), 0),
    'totalTokens', coalesce((select sum(input_tokens + output_tokens) from month_rows), 0),
    'modelBreakdown', coalesce((select value from model_breakdown), '[]'::jsonb),
    'trend', coalesce((select value from trend), '[]'::jsonb),
    'recentEntries', coalesce((select value from recent), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_get_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_list_actions"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_can_manage(v_context.user_id) then
    return '[]'::jsonb;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'code', action."AIDexterAction_Code",
        'domain', action."AIDexterAction_DomainCode",
        'name', action."AIDexterAction_Name",
        'description', action."AIDexterAction_Description",
        'parameters', action."AIDexterAction_ParametersJSON"
      )
      order by action."AIDexterAction_SortOrder", action."AIDexterAction_Name"
    ),
    '[]'::jsonb
  )
  into v_result
  from public."sys_AIDexterActions" action
  join public."sys_AIDexterDataDomains" domain
    on domain."AIDexterDomain_Code" = action."AIDexterAction_DomainCode"
   and domain."AIDexterDomain_IsActive"
  where action."AIDexterAction_IsActive";

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_list_actions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_list_conversations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_result jsonb;
begin
  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  select coalesce(jsonb_agg(item.value order by item.updated_at desc), '[]'::jsonb)
  into v_result
  from (
    select
      jsonb_build_object(
        'id', conversation."AICNV_ID",
        'title', coalesce(conversation."AICNV_Title", 'Dexter conversation'),
        'summary', coalesce(conversation."AICNV_SummaryText", ''),
        'updatedAt', conversation."AICNV_UpdatedAt"
      ) as value,
      conversation."AICNV_UpdatedAt" as updated_at
    from public."AI_Conversations" conversation
    where conversation."AICNV_CompanyID" = v_company_id
      and conversation."AICNV_OwnerUserID" = v_user_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_EndedAt" is null
      and conversation."AICNV_DomainCode" in ('multideck', 'warehouse')
    order by conversation."AICNV_UpdatedAt" desc
    limit 50
  ) item;

  return v_result;
end;
$$;


