    "e"."AuditEvent_RecordID",
    "e"."AuditEvent_RecordKeyJSON",
    "e"."AuditEvent_UserID",
    "u"."User_Email" AS "AuditEvent_UserEmail",
    "e"."AuditEvent_OccurredAt",
    "fc"."AuditFieldChange_ColumnName",
    "fc"."AuditFieldChange_DataType",
    "fc"."AuditFieldChange_OldValueJSON",
    "fc"."AuditFieldChange_NewValueJSON",
    "fc"."AuditFieldChange_IsRedacted",
    "fc"."AuditFieldChange_IsSensitive",
    "fc"."AuditFieldChange_SensitivityCode"
   FROM (("public"."Audit_FieldChanges" "fc"
     JOIN "public"."Audit_Events" "e" ON (("e"."AuditEvent_ID" = "fc"."AuditFieldChange_EventID")))
     LEFT JOIN "public"."cmp_Users" "u" ON (("u"."User_ID" = "e"."AuditEvent_UserID")));


