    "AuditPolicy_TableName" character varying(180) NOT NULL,
    "AuditPolicy_RecordTypeCode" character varying(60),
    "AuditPolicy_ModeCode" character varying(40) DEFAULT 'all_changes'::character varying NOT NULL,
    "AuditPolicy_RetentionClassCode" character varying(60) DEFAULT 'standard_7y'::character varying NOT NULL,
    "AuditPolicy_SensitivityCode" character varying(40) DEFAULT 'normal'::character varying NOT NULL,
    "AuditPolicy_TrackInserts" boolean DEFAULT true NOT NULL,
    "AuditPolicy_TrackUpdates" boolean DEFAULT true NOT NULL,
    "AuditPolicy_TrackDeletes" boolean DEFAULT true NOT NULL,
    "AuditPolicy_TrackFieldChanges" boolean DEFAULT true NOT NULL,
    "AuditPolicy_TrackRowSnapshots" boolean DEFAULT false NOT NULL,
    "AuditPolicy_TrackUnchangedUpdates" boolean DEFAULT false NOT NULL,
    "AuditPolicy_FailClosed" boolean DEFAULT true NOT NULL,
    "AuditPolicy_KeyColumnsJSON" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "AuditPolicy_IncludeColumnsJSON" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "AuditPolicy_IgnoreColumnsJSON" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "AuditPolicy_RedactColumnsJSON" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "AuditPolicy_MetadataJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "AuditPolicy_IsEnabled" boolean DEFAULT true NOT NULL,
