    "e"."AuditEvent_UserID",
    "u"."User_Email" AS "AuditEvent_UserEmail",
    "e"."AuditEvent_OccurredAt",
    "e"."AuditEvent_ChangedFieldCount",
    "e"."AuditEvent_Reason",
    "e"."AuditEvent_MetadataJSON",
    "e"."AuditEvent_RequestID",
    "e"."AuditEvent_CorrelationID"
   FROM ("public"."Audit_Events" "e"
     LEFT JOIN "public"."cmp_Users" "u" ON (("u"."User_ID" = "e"."AuditEvent_UserID")))
  WHERE (("e"."AuditEvent_RecordID" IS NOT NULL) OR ("e"."AuditEvent_RecordKeyJSON" <> '{}'::"jsonb"));


