CREATE OR REPLACE VIEW "public"."BL_PrintSummary" AS
 SELECT "BL_id",
    "BL_JobID",
    "BL_Number",
    "BL_Status",
    "BL_DocumentDate",
    "BL_IssueDateTime",
    "BL_NumberOfOriginals",
    "BL_NumberOfCopies",
    "BL_Negotiable",
    "BL_ToOrder",
    ( SELECT "p"."BLP_DisplayNameSnapshot"
           FROM "public"."BL_Parties" "p"
          WHERE (("p"."BLP_BL_id" = "h"."BL_id") AND (("p"."BLP_Role")::"text" = 'consignor'::"text"))
          ORDER BY "p"."BLP_Sequence"
         LIMIT 1) AS "BL_Consignor",
    ( SELECT "p"."BLP_DisplayNameSnapshot"
           FROM "public"."BL_Parties" "p"
          WHERE (("p"."BLP_BL_id" = "h"."BL_id") AND (("p"."BLP_Role")::"text" = 'consignee'::"text"))
          ORDER BY "p"."BLP_Sequence"
         LIMIT 1) AS "BL_Consignee",
    ( SELECT "string_agg"(("p"."BLP_DisplayNameSnapshot")::"text", '; '::"text" ORDER BY "p"."BLP_Sequence") AS "string_agg"
           FROM "public"."BL_Parties" "p"
          WHERE (("p"."BLP_BL_id" = "h"."BL_id") AND (("p"."BLP_Role")::"text" = 'notify_party'::"text"))) AS "BL_NotifyParties",
    ( SELECT "l"."BLL_NameSnapshot"
           FROM "public"."BL_Locations" "l"
          WHERE (("l"."BLL_BL_id" = "h"."BL_id") AND (("l"."BLL_Role")::"text" = 'place_of_receipt'::"text"))
          ORDER BY "l"."BLL_Sequence"
         LIMIT 1) AS "BL_PlaceOfReceipt",
    ( SELECT "l"."BLL_NameSnapshot"
           FROM "public"."BL_Locations" "l"
          WHERE (("l"."BLL_BL_id" = "h"."BL_id") AND (("l"."BLL_Role")::"text" = 'port_of_loading'::"text"))
          ORDER BY "l"."BLL_Sequence"
         LIMIT 1) AS "BL_PortOfLoading",
    ( SELECT "l"."BLL_NameSnapshot"
           FROM "public"."BL_Locations" "l"
          WHERE (("l"."BLL_BL_id" = "h"."BL_id") AND (("l"."BLL_Role")::"text" = 'port_of_discharge'::"text"))
          ORDER BY "l"."BLL_Sequence"
         LIMIT 1) AS "BL_PortOfDischarge",
    ( SELECT "l"."BLL_NameSnapshot"
           FROM "public"."BL_Locations" "l"
          WHERE (("l"."BLL_BL_id" = "h"."BL_id") AND (("l"."BLL_Role")::"text" = 'place_of_delivery'::"text"))
          ORDER BY "l"."BLL_Sequence"
         LIMIT 1) AS "BL_PlaceOfDelivery",
    ( SELECT COALESCE("sum"("g"."BLG_PackageQuantity"), (0)::numeric) AS "coalesce"
           FROM "public"."BL_GoodsItems" "g"
          WHERE ("g"."BLG_BL_id" = "h"."BL_id")) AS "BL_TotalPackages",
    ( SELECT COALESCE("sum"("g"."BLG_GrossWeight"), (0)::numeric) AS "coalesce"
           FROM "public"."BL_GoodsItems" "g"
          WHERE ("g"."BLG_BL_id" = "h"."BL_id")) AS "BL_TotalGrossWeight"
   FROM "public"."BL_Header" "h";


ALTER VIEW "public"."BL_PrintSummary" OWNER TO "postgres";


