CREATE OR REPLACE VIEW "public"."CDS_PrintSummary" AS
 SELECT "d"."CDS_id",
    "d"."CDS_JobID",
    "d"."CDS_Direction",
    "d"."CDS_DeclarationKind",
    "d"."CDS_DeclarationCategory",
    "d"."CDS_Status",
    "d"."CDS_LRN",
    "d"."CDS_MRN",
    "d"."CDS_DUCR",
    "d"."CDS_MUCR",
    "d"."CDS_OrgOfficeID",
    "d"."CDS_OfficeCodeSnapshot",
    "importer"."CDSP_NameSnapshot" AS "CDS_ImporterNameSnapshot",
    "exporter"."CDSP_NameSnapshot" AS "CDS_ExporterNameSnapshot",
    COALESCE("items"."CDS_ItemCount", 0) AS "CDS_ItemCount",
    COALESCE("items"."CDS_TotalGrossMass", (0)::numeric) AS "CDS_TotalGrossMass",
    COALESCE("items"."CDS_TotalStatisticalValue", (0)::numeric) AS "CDS_TotalStatisticalValue",
    "d"."CDS_InvoiceCurrencyCodeSnapshot",
    "d"."CDS_iCustomsStatusSnapshot"
   FROM ((("public"."CDS_Declarations" "d"
     LEFT JOIN LATERAL ( SELECT "p"."CDSP_NameSnapshot"
           FROM "public"."CDS_Parties" "p"
          WHERE (("p"."CDSP_CDSID" = "d"."CDS_id") AND (("p"."CDSP_Role")::"text" = 'importer'::"text"))
          ORDER BY "p"."CDSP_SortOrder", "p"."CDSP_CreatedAt"
         LIMIT 1) "importer" ON (true))
     LEFT JOIN LATERAL ( SELECT "p"."CDSP_NameSnapshot"
           FROM "public"."CDS_Parties" "p"
          WHERE (("p"."CDSP_CDSID" = "d"."CDS_id") AND (("p"."CDSP_Role")::"text" = 'exporter'::"text"))
          ORDER BY "p"."CDSP_SortOrder", "p"."CDSP_CreatedAt"
         LIMIT 1) "exporter" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "CDS_ItemCount",
            "sum"(COALESCE("i"."CDSI_GrossMass", (0)::numeric)) AS "CDS_TotalGrossMass",
            "sum"(COALESCE("i"."CDSI_StatisticalValueAmount", (0)::numeric)) AS "CDS_TotalStatisticalValue"
           FROM "public"."CDS_Items" "i"
          WHERE ("i"."CDSI_CDSID" = "d"."CDS_id")) "items" ON (true));


ALTER VIEW "public"."CDS_PrintSummary" OWNER TO "postgres";


