CREATE OR REPLACE VIEW "public"."CLM_ClaimsDashboard" AS
 SELECT "claim"."CLMClaim_OrgOfficeID",
    "claim"."CLMClaim_LegalEntityID",
    "claim"."CLMClaim_BrandID",
    "claim"."CLMClaim_StatusCode",
    "status"."CLMClaimStatus_Name",
    "status"."CLMClaimStatus_IsOpen",
    "claim"."CLMClaim_TypeCode",
    "type"."CLMClaimType_Name",
    "claim"."CLMClaim_CurrencyCodeSnapshot",
    ("count"(*))::integer AS "CLMClaims_Count",
    (COALESCE("sum"("claim"."CLMClaim_ClaimedAmount"), (0)::numeric))::numeric(18,4) AS "CLMClaims_ClaimedAmount",
    (COALESCE("sum"("claim"."CLMClaim_ReserveAmount"), (0)::numeric))::numeric(18,4) AS "CLMClaims_ReserveAmount",
    (COALESCE("sum"("claim"."CLMClaim_SettlementAmount"), (0)::numeric))::numeric(18,4) AS "CLMClaims_SettlementAmount",
    (COALESCE("sum"("claim"."CLMClaim_RecoveryExpectedAmount"), (0)::numeric))::numeric(18,4) AS "CLMClaims_RecoveryExpectedAmount",
    (COALESCE("sum"("claim"."CLMClaim_RecoveryReceivedAmount"), (0)::numeric))::numeric(18,4) AS "CLMClaims_RecoveryReceivedAmount",
    ("avg"(
        CASE
            WHEN ("claim"."CLMClaim_ClosedAt" IS NOT NULL) THEN (EXTRACT(epoch FROM ("claim"."CLMClaim_ClosedAt" - "claim"."CLMClaim_CreatedAt")) / 86400.0)
            ELSE NULL::numeric
        END))::numeric(18,4) AS "CLMClaims_AverageClosedDays"
   FROM (("public"."CLM_Claims" "claim"
     LEFT JOIN "public"."sys_CLMClaimStatuses" "status" ON ((("status"."CLMClaimStatus_Code")::"text" = ("claim"."CLMClaim_StatusCode")::"text")))
     LEFT JOIN "public"."sys_CLMClaimTypes" "type" ON ((("type"."CLMClaimType_Code")::"text" = ("claim"."CLMClaim_TypeCode")::"text")))
  GROUP BY "claim"."CLMClaim_OrgOfficeID", "claim"."CLMClaim_LegalEntityID", "claim"."CLMClaim_BrandID", "claim"."CLMClaim_StatusCode", "status"."CLMClaimStatus_Name", "status"."CLMClaimStatus_IsOpen", "claim"."CLMClaim_TypeCode", "type"."CLMClaimType_Name", "claim"."CLMClaim_CurrencyCodeSnapshot";


ALTER VIEW "public"."CLM_ClaimsDashboard" OWNER TO "postgres";


