CREATE OR REPLACE VIEW "public"."CLM_PolicyRenewalQueue" AS
 SELECT "renewal"."CLMRenewal_ID",
    "renewal"."CLMRenewal_PolicyID",
    "policy"."CLMPolicy_Number",
    "policy"."CLMPolicy_Name",
    "policy"."CLMPolicy_TypeCode",
    "policy"."CLMPolicy_StatusCode",
    "renewal"."CLMRenewal_StatusCode",
    "approval_status"."CLMApprovalStatus_Name" AS "CLMRenewal_StatusName",
    "renewal"."CLMRenewal_DueDate",
    "renewal"."CLMRenewal_CurrentExpiryDate",
    "renewal"."CLMRenewal_ProposedInceptionDate",
    "renewal"."CLMRenewal_ProposedExpiryDate",
    "renewal"."CLMRenewal_QuotedPremiumAmount",
    "renewal"."CLMRenewal_CurrencyCodeSnapshot",
    "renewal"."CLMRenewal_AssignedUserID",
    "renewal"."CLMRenewal_WorkflowTaskID"
   FROM (("public"."CLM_PolicyRenewals" "renewal"
     JOIN "public"."CLM_InsurancePolicies" "policy" ON (("policy"."CLMPolicy_ID" = "renewal"."CLMRenewal_PolicyID")))
     LEFT JOIN "public"."sys_CLMApprovalStatuses" "approval_status" ON ((("approval_status"."CLMApprovalStatus_Code")::"text" = ("renewal"."CLMRenewal_StatusCode")::"text")));


