CREATE OR REPLACE VIEW "public"."CLM_RecoveryQueue" AS
 SELECT "recovery"."CLMRecovery_ID",
    "recovery"."CLMRecovery_ClaimID",
    "claim"."CLMClaim_Number",
    "claim"."CLMClaim_Title",
    "recovery"."CLMRecovery_StatusCode",
    "rstatus"."CLMRecoveryStatus_Name",
    "recovery"."CLMRecovery_TargetOrgID",
    "target_org"."Org_Name" AS "CLMRecovery_TargetOrgName",
    "recovery"."CLMRecovery_TargetRoleCode",
    "recovery"."CLMRecovery_ClaimedAmount",
    "recovery"."CLMRecovery_ExpectedAmount",
    "recovery"."CLMRecovery_RecoveredAmount",
    "recovery"."CLMRecovery_CurrencyCodeSnapshot",
    "recovery"."CLMRecovery_NoticeSentAt",
    "recovery"."CLMRecovery_DueDate",
    "recovery"."CLMRecovery_WorkflowTaskID"
   FROM ((("public"."CLM_ClaimRecoveries" "recovery"
     LEFT JOIN "public"."CLM_Claims" "claim" ON (("claim"."CLMClaim_ID" = "recovery"."CLMRecovery_ClaimID")))
     LEFT JOIN "public"."sys_CLMRecoveryStatuses" "rstatus" ON ((("rstatus"."CLMRecoveryStatus_Code")::"text" = ("recovery"."CLMRecovery_StatusCode")::"text")))
     LEFT JOIN "public"."Org_Master" "target_org" ON (("target_org"."Org_id" = "recovery"."CLMRecovery_TargetOrgID")));


