CREATE OR REPLACE VIEW "public"."CLM_SurveyQueue" AS
 SELECT "survey"."CLMSurvey_ID",
    "survey"."CLMSurvey_IncidentID",
    "incident"."CLMIncident_Number",
    "survey"."CLMSurvey_ClaimID",
    "claim"."CLMClaim_Number",
    "survey"."CLMSurvey_SurveyorOrgID",
    "surveyor"."Org_Name" AS "CLMSurvey_SurveyorName",
    "survey"."CLMSurvey_StatusCode",
    "status"."CLMNotificationStatus_Name" AS "CLMSurvey_StatusName",
    "survey"."CLMSurvey_LocationName",
    "survey"."CLMSurvey_RequestedAt",
    "survey"."CLMSurvey_AppointmentAt",
    "survey"."CLMSurvey_ReportDueAt",
    "survey"."CLMSurvey_ReportReceivedAt",
    "survey"."CLMSurvey_CostAmount",
    "survey"."CLMSurvey_CurrencyCodeSnapshot",
    "survey"."CLMSurvey_WorkflowTaskID"
   FROM (((("public"."CLM_SurveyAppointments" "survey"
     LEFT JOIN "public"."CLM_Incidents" "incident" ON (("incident"."CLMIncident_ID" = "survey"."CLMSurvey_IncidentID")))
     LEFT JOIN "public"."CLM_Claims" "claim" ON (("claim"."CLMClaim_ID" = "survey"."CLMSurvey_ClaimID")))
     LEFT JOIN "public"."Org_Master" "surveyor" ON (("surveyor"."Org_id" = "survey"."CLMSurvey_SurveyorOrgID")))
     LEFT JOIN "public"."sys_CLMNotificationStatuses" "status" ON ((("status"."CLMNotificationStatus_Code")::"text" = ("survey"."CLMSurvey_StatusCode")::"text")));


