CREATE OR REPLACE VIEW "public"."CRM_AIFocusAreaQueue" AS
 SELECT "focus"."CRMFocus_ID",
    "focus"."CRMFocus_StatusCode",
    "focus"."CRMFocus_TargetUserID",
    "userx"."User_Email" AS "CRMFocus_TargetUserEmail",
    "focus"."CRMFocus_AccountID",
    "org"."Org_Name" AS "CRMFocus_AccountName",
    "focus"."CRMFocus_LeadID",
    "focus"."CRMFocus_OpportunityID",
    "focus"."CRMFocus_Title",
    "focus"."CRMFocus_Reason",
    "focus"."CRMFocus_RecommendedActionCode",
    "focus"."CRMFocus_PriorityScore",
    "focus"."CRMFocus_DueAt",
    "focus"."CRMFocus_CreatedAt"
   FROM (((("public"."CRM_AIFocusAreas" "focus"
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "focus"."CRMFocus_TargetUserID")))
     LEFT JOIN "public"."CRM_AccountProfiles" "ap" ON (("ap"."CRMAccount_ID" = "focus"."CRMFocus_AccountID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "ap"."CRMAccount_OrgID")))
     LEFT JOIN "public"."sys_CRMFocusAreaStatuses" "status" ON ((("status"."CRMFocusStatus_Code")::"text" = ("focus"."CRMFocus_StatusCode")::"text")))
  WHERE ("status"."CRMFocusStatus_IsClosed" = false);


ALTER VIEW "public"."CRM_AIFocusAreaQueue" OWNER TO "postgres";


