CREATE OR REPLACE VIEW "public"."CRM_FieldUpdateReviewQueue" AS
 SELECT "upd"."CRMFieldUpdate_ID",
    "upd"."CRMFieldUpdate_StatusCode",
    "upd"."CRMFieldUpdate_RunID",
    "upd"."CRMFieldUpdate_DataRequestID",
    "upd"."CRMFieldUpdate_TargetRecordTypeCode",
    "upd"."CRMFieldUpdate_TargetTable",
    "upd"."CRMFieldUpdate_TargetPKColumn",
    "upd"."CRMFieldUpdate_TargetColumn",
    "upd"."CRMFieldUpdate_TargetID",
    "upd"."CRMFieldUpdate_FieldTypeCode",
    "upd"."CRMFieldUpdate_OldValueText",
    "upd"."CRMFieldUpdate_NewValueText",
    "upd"."CRMFieldUpdate_NewValueJSON",
    "upd"."CRMFieldUpdate_ConfidenceScore",
    "upd"."CRMFieldUpdate_RequiresApproval",
    "field"."CRMAutoField_Label",
    "field"."CRMAutoField_QuestionText",
    "run"."CRMAutoRun_AssignedUserID",
    "userx"."User_Email" AS "CRMAutoRun_AssignedUserEmail",
    "run"."CRMAutoRun_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "upd"."CRMFieldUpdate_CreatedAt"
   FROM ((((("public"."CRM_FieldUpdateQueue" "upd"
     LEFT JOIN "public"."CRM_AutomationFieldDefinitions" "field" ON (("field"."CRMAutoField_ID" = "upd"."CRMFieldUpdate_FieldDefID")))
     LEFT JOIN "public"."CRM_AutomationRuns" "run" ON (("run"."CRMAutoRun_ID" = "upd"."CRMFieldUpdate_RunID")))
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "run"."CRMAutoRun_AssignedUserID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "run"."CRMAutoRun_CustomerOrgID")))
     LEFT JOIN "public"."sys_CRMFieldUpdateStatuses" "status" ON ((("status"."CRMFieldUpdateStatus_Code")::"text" = ("upd"."CRMFieldUpdate_StatusCode")::"text")))
  WHERE ("status"."CRMFieldUpdateStatus_IsOpen" = true);


ALTER VIEW "public"."CRM_FieldUpdateReviewQueue" OWNER TO "postgres";


