CREATE OR REPLACE VIEW "public"."CRM_NextBestActionQueue" AS
 SELECT "nba"."CRMNBA_ID",
    "nba"."CRMNBA_ActionTypeCode",
    "atype"."CRMNBAType_Name",
    "nba"."CRMNBA_Title",
    "nba"."CRMNBA_Reason",
    "nba"."CRMNBA_AssignedUserID",
    "userx"."User_Email" AS "CRMNBA_AssignedUserEmail",
    "nba"."CRMNBA_AccountID",
    "org"."Org_Name" AS "CRMNBA_AccountName",
    "nba"."CRMNBA_LeadID",
    "nba"."CRMNBA_OpportunityID",
    "nba"."CRMNBA_QuoteFollowupID",
    "nba"."CRMNBA_DueAt",
    "nba"."CRMNBA_ConfidenceScore",
    "nba"."CRMNBA_Status",
    "nba"."CRMNBA_WorkflowTaskID",
    "nba"."CRMNBA_CreatedAt"
   FROM (((("public"."CRM_NextBestActions" "nba"
     LEFT JOIN "public"."sys_CRMNextBestActionTypes" "atype" ON ((("atype"."CRMNBAType_Code")::"text" = ("nba"."CRMNBA_ActionTypeCode")::"text")))
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "nba"."CRMNBA_AssignedUserID")))
     LEFT JOIN "public"."CRM_AccountProfiles" "ap" ON (("ap"."CRMAccount_ID" = "nba"."CRMNBA_AccountID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "ap"."CRMAccount_OrgID")))
  WHERE (("nba"."CRMNBA_Status")::"text" = ANY ((ARRAY['pending'::character varying, 'accepted'::character varying, 'new'::character varying])::"text"[]));


