CREATE OR REPLACE VIEW "public"."CRM_PersonalMessageDraftQueue" AS
 SELECT "msg"."CRMPMsg_ID",
    "msg"."CRMPMsg_RunID",
    "msg"."CRMPMsg_QuickTaskID",
    "qt"."CRMQuickTask_Title",
    "msg"."CRMPMsg_MessageIntentCode",
    "intent"."CRMMsgIntent_Name",
    "msg"."CRMPMsg_ChannelCode",
    "msg"."CRMPMsg_PersonalisationModeCode",
    "msg"."CRMPMsg_DecisionStatusCode",
    "msg"."CRMPMsg_CustomerOrgID",
    "org"."Org_Name" AS "CRMPMsg_CustomerName",
    "msg"."CRMPMsg_AssignedUserID",
    "userx"."User_Email" AS "CRMPMsg_AssignedUserEmail",
    "msg"."CRMPMsg_Subject",
    "msg"."CRMPMsg_BodyText",
    "msg"."CRMPMsg_RepeatRiskScore",
    "msg"."CRMPMsg_IsTemplateBased",
    "msg"."CRMPMsg_CreatedAt"
   FROM (((("public"."CRM_PersonalMessageDrafts" "msg"
     LEFT JOIN "public"."CRM_QuickTasks" "qt" ON (("qt"."CRMQuickTask_ID" = "msg"."CRMPMsg_QuickTaskID")))
     LEFT JOIN "public"."sys_CRMMessageIntentTypes" "intent" ON ((("intent"."CRMMsgIntent_Code")::"text" = ("msg"."CRMPMsg_MessageIntentCode")::"text")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "msg"."CRMPMsg_CustomerOrgID")))
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "msg"."CRMPMsg_AssignedUserID")))
  WHERE (("msg"."CRMPMsg_DecisionStatusCode")::"text" = ANY ((ARRAY['pending'::character varying, 'snoozed'::character varying])::"text"[]));


