CREATE OR REPLACE VIEW "public"."Comm_AIDraftReviewQueue" AS
 SELECT "draft"."CommAIDraft_ID",
    "draft"."CommAIDraft_ThreadID",
    "thread"."CommThread_Subject",
    "draft"."CommAIDraft_SourceMessageID",
    "draft"."CommAIDraft_StatusCode",
    "draft"."CommAIDraft_ChannelCode",
    "draft"."CommAIDraft_Subject",
    "draft"."CommAIDraft_BodyText",
    "draft"."CommAIDraft_Confidence",
    "draft"."CommAIDraft_ReviewRequired",
    "draft"."CommAIDraft_AutoSendEligible",
    "policy"."CommAIPolicy_Code",
    "policy"."CommAIPolicy_Name",
    "policy"."CommAIPolicy_AutoSendEnabled",
    "policy"."CommAIPolicy_MinConfidence",
    "draft"."CommAIDraft_CreatedAt",
    "draft"."CommAIDraft_ExpiresAt"
   FROM (("public"."Comm_AIDraftResponses" "draft"
     JOIN "public"."Comm_Threads" "thread" ON (("thread"."CommThread_ID" = "draft"."CommAIDraft_ThreadID")))
     LEFT JOIN "public"."Comm_AIAutomationPolicies" "policy" ON (("policy"."CommAIPolicy_ID" = "draft"."CommAIDraft_PolicyID")))
  WHERE (("draft"."CommAIDraft_StatusCode")::"text" = ANY ((ARRAY['drafted'::character varying, 'review_required'::character varying, 'approved'::character varying])::"text"[]))
  ORDER BY "draft"."CommAIDraft_ReviewRequired" DESC, "draft"."CommAIDraft_CreatedAt" DESC;


ALTER VIEW "public"."Comm_AIDraftReviewQueue" OWNER TO "postgres";


