    "org"."Org_Name" AS "CommPeer_LocalOrgName",
    "peer"."CommPeer_LastHandshakeAt",
    "peer"."CommPeer_LastMessageAt",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."Comm_FederationEnvelopes" "env"
          WHERE ("env"."CommFedEnv_PeerID" = "peer"."CommPeer_ID")) AS "CommPeer_EnvelopeCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."Comm_FederationSubscriptions" "sub"
          WHERE (("sub"."CommFedSub_PeerID" = "peer"."CommPeer_ID") AND (("sub"."CommFedSub_StatusCode")::"text" = 'active'::"text"))) AS "CommPeer_ActiveSubscriptionCount"
   FROM ("public"."Comm_FederationPeers" "peer"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "peer"."CommPeer_LocalOrgID")))
  WHERE ("peer"."CommPeer_IsDeleted" = false);


