CREATE OR REPLACE VIEW "public"."Comm_ThreadSummary" WITH ("security_invoker"='true') AS
 SELECT "thread"."CommThread_ID",
    "thread"."CommThread_Subject",
    "thread"."CommThread_StatusCode",
    "thread"."CommThread_PrimaryChannelCode",
    "thread"."CommThread_PriorityCode",
    "thread"."CommThread_SensitivityCode",
    "thread"."CommThread_OrgOfficeID",
    "thread"."CommThread_LegalEntityID",
    "thread"."CommThread_BrandID",
    "thread"."CommThread_CustomerOrgID",
    "thread"."CommThread_AssignedUserID",
    "au"."User_Email" AS "CommThread_AssignedUserEmail",
    "thread"."CommThread_AssignedGroupID",
    "thread"."CommThread_PrimaryTargetTable",
    "thread"."CommThread_PrimaryTargetID",
    "thread"."CommThread_LastMessageAt",
    "thread"."CommThread_FirstResponseDueAt",
    "thread"."CommThread_NextActionDueAt",
    "thread"."CommThread_AIIntent",
    "thread"."CommThread_AISummary",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."Comm_Messages" "msg"
          WHERE (("msg"."CommMessage_ThreadID" = "thread"."CommThread_ID") AND ("msg"."CommMessage_IsDeleted" = false))) AS "CommThread_MessageCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."Comm_ThreadParticipants" "part"
          WHERE ("part"."CommThreadPart_ThreadID" = "thread"."CommThread_ID")) AS "CommThread_ParticipantCount",
    ( SELECT "max"("msg"."CommMessage_ReceivedAt") AS "max"
           FROM "public"."Comm_Messages" "msg"
          WHERE (("msg"."CommMessage_ThreadID" = "thread"."CommThread_ID") AND (("msg"."CommMessage_DirectionCode")::"text" = 'inbound'::"text") AND ("msg"."CommMessage_IsDeleted" = false))) AS "CommThread_LastInboundAt",
    ( SELECT "max"("msg"."CommMessage_SentAt") AS "max"
           FROM "public"."Comm_Messages" "msg"
          WHERE (("msg"."CommMessage_ThreadID" = "thread"."CommThread_ID") AND (("msg"."CommMessage_DirectionCode")::"text" = 'outbound'::"text") AND ("msg"."CommMessage_IsDeleted" = false))) AS "CommThread_LastOutboundAt"
   FROM ("public"."Comm_Threads" "thread"
     LEFT JOIN "public"."cmp_Users" "au" ON (("au"."User_ID" = "thread"."CommThread_AssignedUserID")))
  WHERE ("thread"."CommThread_IsDeleted" = false);


ALTER VIEW "public"."Comm_ThreadSummary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."Comm_InboxWorklist" WITH ("security_invoker"='true') AS
 SELECT "CommThread_ID",
    "CommThread_Subject",
    "CommThread_StatusCode",
    "CommThread_PrimaryChannelCode",
    "CommThread_PriorityCode",
    "CommThread_SensitivityCode",
    "CommThread_OrgOfficeID",
    "CommThread_LegalEntityID",
    "CommThread_BrandID",
    "CommThread_CustomerOrgID",
    "CommThread_AssignedUserID",
    "CommThread_AssignedUserEmail",
    "CommThread_AssignedGroupID",
    "CommThread_PrimaryTargetTable",
    "CommThread_PrimaryTargetID",
    "CommThread_LastMessageAt",
    "CommThread_FirstResponseDueAt",
    "CommThread_NextActionDueAt",
    "CommThread_AIIntent",
    "CommThread_AISummary",
    "CommThread_MessageCount",
    "CommThread_ParticipantCount",
    "CommThread_LastInboundAt",
    "CommThread_LastOutboundAt",
        CASE
            WHEN (("CommThread_NextActionDueAt" IS NOT NULL) AND ("CommThread_NextActionDueAt" < "now"())) THEN true
            ELSE false
        END AS "CommThread_IsOverdue"
   FROM "public"."Comm_ThreadSummary" "summary"
  WHERE (("CommThread_StatusCode")::"text" <> ALL ((ARRAY['closed'::character varying, 'archived'::character varying, 'resolved'::character varying])::"text"[]))
  ORDER BY "CommThread_NextActionDueAt", "CommThread_LastMessageAt" DESC NULLS LAST;


ALTER VIEW "public"."Comm_InboxWorklist" OWNER TO "postgres";


