    "CommMailboxAccess_CanSendAs" boolean DEFAULT false NOT NULL,
    "CommMailboxAccess_CanManage" boolean DEFAULT false NOT NULL,
    "CommMailboxAccess_GrantedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "CommMailboxAccess_ExpiresAt" timestamp with time zone,
    "CommMailboxAccess_RevokedAt" timestamp with time zone,
    "CommMailboxAccess_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "CommMailboxAccess_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "CK_Comm_MailboxAccess_any_capability" CHECK (("CommMailboxAccess_CanRead" OR "CommMailboxAccess_CanSend" OR "CommMailboxAccess_CanSendAs" OR "CommMailboxAccess_CanManage")),
    CONSTRAINT "CK_Comm_MailboxAccess_expiry" CHECK ((("CommMailboxAccess_ExpiresAt" IS NULL) OR ("CommMailboxAccess_ExpiresAt" > "CommMailboxAccess_GrantedAt"))),
    CONSTRAINT "CK_Comm_MailboxAccess_revocation" CHECK ((("CommMailboxAccess_RevokedAt" IS NULL) OR ("CommMailboxAccess_RevokedAt" >= "CommMailboxAccess_GrantedAt"))),
    CONSTRAINT "CK_Comm_MailboxAccess_scope" CHECK ((("CommMailboxAccess_ScopeCode")::"text" = ANY ((ARRAY['personal'::character varying, 'shared'::character varying, 'group'::character varying])::"text"[]))),
    CONSTRAINT "CK_Comm_MailboxAccess_send_as" CHECK (((NOT "CommMailboxAccess_CanSendAs") OR "CommMailboxAccess_CanSend"))
);


