    "notif"."CommNotif_StatusCode",
    "notif"."CommNotif_PriorityCode",
    "notif"."CommNotif_UserID",
    "u"."User_Email" AS "CommNotif_UserEmail",
    "notif"."CommNotif_GroupID",
    "notif"."CommNotif_RoleID",
    "notif"."CommNotif_Title",
    "notif"."CommNotif_Body",
    "notif"."CommNotif_TargetTable",
    "notif"."CommNotif_TargetID",
    "notif"."CommNotif_LinkTypeCode",
    "notif"."CommNotif_ThreadID",
    "notif"."CommNotif_MessageID",
    "notif"."CommNotif_WorkflowTaskID",
    "notif"."CommNotif_DueAt",
    "notif"."CommNotif_ReadAt",
    "notif"."CommNotif_CreatedAt"
   FROM ("public"."Comm_Notifications" "notif"
     LEFT JOIN "public"."cmp_Users" "u" ON (("u"."User_ID" = "notif"."CommNotif_UserID")))
  WHERE (("notif"."CommNotif_StatusCode")::"text" = ANY ((ARRAY['unread'::character varying, 'read'::character varying])::"text"[]))
  ORDER BY "notif"."CommNotif_DueAt", "notif"."CommNotif_CreatedAt" DESC;


