    "CommOAuthState_ConsumedAt" timestamp with time zone,
    "CommOAuthState_FailedAt" timestamp with time zone,
    "CommOAuthState_FailureCode" character varying(80),
    CONSTRAINT "CK_Comm_OAuthStates_expiry" CHECK (("CommOAuthState_ExpiresAt" > "CommOAuthState_CreatedAt")),
    CONSTRAINT "CK_Comm_OAuthStates_pkce_ref" CHECK ((("CommOAuthState_PKCEVerifierSecretRef" IS NULL) OR (("CommOAuthState_PKCEVerifierSecretRef")::"text" ~ '^supabase-vault:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::"text"))),
    CONSTRAINT "CK_Comm_OAuthStates_provider" CHECK ((("CommOAuthState_ProviderCode")::"text" = ANY ((ARRAY['gmail'::character varying, 'outlook'::character varying])::"text"[]))),
    CONSTRAINT "CK_Comm_OAuthStates_return_path" CHECK ((("CommOAuthState_ReturnPath" ~ '^/[^/].*'::"text") AND ("CommOAuthState_ReturnPath" !~ '[[:cntrl:]]'::"text"))),
    CONSTRAINT "CK_Comm_OAuthStates_scopes" CHECK (("jsonb_typeof"("CommOAuthState_RequestedScopes") = 'array'::"text")),
    CONSTRAINT "CK_Comm_OAuthStates_state_hash" CHECK ((("length"("btrim"(("CommOAuthState_StateHash")::"text")) >= 32) AND ("length"("btrim"(("CommOAuthState_StateHash")::"text")) <= 128))),
    CONSTRAINT "CK_Comm_OAuthStates_terminal_state" CHECK ((("CommOAuthState_ConsumedAt" IS NULL) OR ("CommOAuthState_FailedAt" IS NULL)))
