CREATE OR REPLACE VIEW "public"."DOCB_GeneratedDocumentSummary" AS
 SELECT "generated"."DOCBGD_ID",
    "generated"."DOCBGD_RenderJobID",
    "generated"."DOCBGD_TemplateID",
    "template"."DOCBT_Code" AS "TemplateCode",
    "template"."DOCBT_Name" AS "TemplateName",
    "generated"."DOCBGD_TemplateVersionID",
    "template_version"."DOCBTV_VersionNo" AS "TemplateVersionNo",
    "generated"."DOCBGD_JobDocumentID",
    "job_doc"."JobDoc_JobID" AS "JobID",
    "job_doc"."JobDoc_Title" AS "JobDocumentTitle",
    "generated"."DOCBGD_OutputFormatCode",
    "output_format"."DOCBOF_Name" AS "OutputFormatName",
    "output_format"."DOCBOF_MimeType" AS "OutputMimeType",
    "generated"."DOCBGD_FileName",
    "generated"."DOCBGD_StorageBucket",
    "generated"."DOCBGD_StoragePath",
    "generated"."DOCBGD_FileURL",
    "generated"."DOCBGD_MimeType",
    "generated"."DOCBGD_FileSizeBytes",
    "generated"."DOCBGD_SHA256",
    "generated"."DOCBGD_VersionNo",
    "generated"."DOCBGD_IsCurrentVersion",
    "generated"."DOCBGD_CreatedAt"
   FROM (((("public"."DOCB_GeneratedDocuments" "generated"
     JOIN "public"."DOCB_DocumentTemplates" "template" ON (("template"."DOCBT_ID" = "generated"."DOCBGD_TemplateID")))
     LEFT JOIN "public"."DOCB_TemplateVersions" "template_version" ON (("template_version"."DOCBTV_ID" = "generated"."DOCBGD_TemplateVersionID")))
     LEFT JOIN "public"."Job_Documents" "job_doc" ON (("job_doc"."JobDoc_ID" = "generated"."DOCBGD_JobDocumentID")))
     LEFT JOIN "public"."sys_DocBuilderOutputFormats" "output_format" ON ((("output_format"."DOCBOF_Code")::"text" = ("generated"."DOCBGD_OutputFormatCode")::"text")));


