CREATE OR REPLACE VIEW "public"."DOCB_LibraryDocumentSummary" AS
 SELECT "library_document"."DOCBLD_ID",
    "library_document"."DOCBLD_Code",
    "library_document"."DOCBLD_Name",
    "library_document"."DOCBLD_Category",
    "library_document"."DOCBLD_DataScopeCode",
    "scope"."DOCBSC_Name" AS "DataScopeName",
    "library_document"."DOCBLD_DocTypeID",
    "doc_type"."DocTypes_DocType" AS "DocTypeCode",
    "doc_type"."DocTypes_Desc" AS "DocTypeName",
    "library_document"."DOCBLD_DefaultRenderEngineCode",
    "render_engine"."DOCBRE_Name" AS "DefaultRenderEngineName",
    "library_document"."DOCBLD_DefaultOutputFormatCode",
    "output_format"."DOCBOF_Name" AS "DefaultOutputFormatName",
    "output_format"."DOCBOF_MimeType" AS "DefaultOutputMimeType",
    "library_document"."DOCBLD_StatusCode",
    "status"."DOCBST_Name" AS "StatusName",
    "library_document"."DOCBLD_Purpose",
    "library_document"."DOCBLD_SourceTablesJSON",
    "library_document"."DOCBLD_StandardSectionCodesJSON",
    "library_document"."DOCBLD_SupportedModeCodesJSON",
    "library_document"."DOCBLD_SupportedDirectionCodesJSON",
    "library_document"."DOCBLD_CountryCodesJSON",
    "library_document"."DOCBLD_IsLegalDocument",
    "library_document"."DOCBLD_RequiresJobDocumentLink",
    "library_document"."DOCBLD_RetentionCategory",
    "library_document"."DOCBLD_IsSystem",
    "library_document"."DOCBLD_IsUserEditable",
    "library_document"."DOCBLD_IsActive",
    "library_document"."DOCBLD_CreatedAt",
    "library_document"."DOCBLD_UpdatedAt",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_DocumentTemplates" "template"
          WHERE (("template"."DOCBT_LibraryDocumentID" = "library_document"."DOCBLD_ID") OR (("template"."DOCBT_LibraryDocumentCode")::"text" = ("library_document"."DOCBLD_Code")::"text"))) AS "TemplateCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_LibraryPackItems" "pack_item"
          WHERE (("pack_item"."DOCBLPI_LibraryDocumentID" = "library_document"."DOCBLD_ID") OR (("pack_item"."DOCBLPI_DocumentCode")::"text" = ("library_document"."DOCBLD_Code")::"text"))) AS "PackItemCount"
   FROM ((((("public"."DOCB_LibraryDocuments" "library_document"
     LEFT JOIN "public"."sys_DocBuilderDataScopes" "scope" ON ((("scope"."DOCBSC_Code")::"text" = ("library_document"."DOCBLD_DataScopeCode")::"text")))
     LEFT JOIN "public"."sys_DocTypes" "doc_type" ON (("doc_type"."DocTypes_PK" = "library_document"."DOCBLD_DocTypeID")))
     LEFT JOIN "public"."sys_DocBuilderRenderEngines" "render_engine" ON ((("render_engine"."DOCBRE_Code")::"text" = ("library_document"."DOCBLD_DefaultRenderEngineCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderOutputFormats" "output_format" ON ((("output_format"."DOCBOF_Code")::"text" = ("library_document"."DOCBLD_DefaultOutputFormatCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderStatuses" "status" ON ((("status"."DOCBST_Code")::"text" = ("library_document"."DOCBLD_StatusCode")::"text")));


ALTER VIEW "public"."DOCB_LibraryDocumentSummary" OWNER TO "postgres";


