CREATE OR REPLACE VIEW "public"."DOCB_LibraryPackItemSummary" AS
 SELECT "pack"."DOCBLP_ID",
    "pack"."DOCBLP_Code",
    "pack"."DOCBLP_Name",
    "item"."DOCBLPI_ID",
    "item"."DOCBLPI_LibraryDocumentID",
    "item"."DOCBLPI_DocumentCode",
    "item"."DOCBLPI_DocumentName",
    "library_document"."DOCBLD_Name" AS "LibraryDocumentName",
    "library_document"."DOCBLD_Category" AS "LibraryDocumentCategory",
    "item"."DOCBLPI_DataScopeCode",
    "scope"."DOCBSC_Name" AS "DataScopeName",
    "item"."DOCBLPI_TemplateID",
    "template"."DOCBT_Code" AS "TemplateCode",
    "template"."DOCBT_Name" AS "TemplateName",
    "item"."DOCBLPI_DocTypeID",
    "doc_type"."DocTypes_DocType" AS "DocTypeCode",
    "doc_type"."DocTypes_Desc" AS "DocTypeName",
    "item"."DOCBLPI_DefaultOutputFormatCode",
    "output_format"."DOCBOF_Name" AS "DefaultOutputFormatName",
    "output_format"."DOCBOF_MimeType" AS "DefaultOutputMimeType",
    "item"."DOCBLPI_IsRequired",
    "item"."DOCBLPI_IsGeneratedByDefault",
    "item"."DOCBLPI_SortOrder",
    "item"."DOCBLPI_ModeCodesJSON",
    "item"."DOCBLPI_DirectionCodesJSON",
    "item"."DOCBLPI_ConditionJSON",
    "item"."DOCBLPI_MetadataJSON"
   FROM (((((("public"."DOCB_LibraryPackItems" "item"
     JOIN "public"."DOCB_LibraryPacks" "pack" ON (("pack"."DOCBLP_ID" = "item"."DOCBLPI_LibraryPackID")))
     LEFT JOIN "public"."DOCB_LibraryDocuments" "library_document" ON ((("library_document"."DOCBLD_ID" = "item"."DOCBLPI_LibraryDocumentID") OR (("item"."DOCBLPI_LibraryDocumentID" IS NULL) AND (("library_document"."DOCBLD_Code")::"text" = ("item"."DOCBLPI_DocumentCode")::"text")))))
     LEFT JOIN "public"."sys_DocBuilderDataScopes" "scope" ON ((("scope"."DOCBSC_Code")::"text" = ("item"."DOCBLPI_DataScopeCode")::"text")))
     LEFT JOIN "public"."DOCB_DocumentTemplates" "template" ON (("template"."DOCBT_ID" = "item"."DOCBLPI_TemplateID")))
     LEFT JOIN "public"."sys_DocTypes" "doc_type" ON (("doc_type"."DocTypes_PK" = "item"."DOCBLPI_DocTypeID")))
     LEFT JOIN "public"."sys_DocBuilderOutputFormats" "output_format" ON ((("output_format"."DOCBOF_Code")::"text" = ("item"."DOCBLPI_DefaultOutputFormatCode")::"text")));


