CREATE OR REPLACE VIEW "public"."DOCB_RenderJobSummary" AS
 SELECT "render_job"."DOCBRJ_ID",
    "render_job"."DOCBRJ_TemplateID",
    "template"."DOCBT_Code" AS "TemplateCode",
    "template"."DOCBT_Name" AS "TemplateName",
    "render_job"."DOCBRJ_TemplateVersionID",
    "template_version"."DOCBTV_VersionNo" AS "TemplateVersionNo",
    "render_job"."DOCBRJ_StatusCode",
    "render_status"."DOCBRS_Name" AS "RenderStatusName",
    "render_status"."DOCBRS_IsFinal" AS "RenderStatusIsFinal",
    "render_job"."DOCBRJ_RenderEngineCode",
    "render_engine"."DOCBRE_Name" AS "RenderEngineName",
    "render_job"."DOCBRJ_OutputFormatCode",
    "output_format"."DOCBOF_Name" AS "OutputFormatName",
    "output_format"."DOCBOF_MimeType" AS "OutputMimeType",
    "render_job"."DOCBRJ_TargetTable",
    "render_job"."DOCBRJ_TargetID",
    "render_job"."DOCBRJ_JobID",
    "job"."Job_Number" AS "JobNumber",
    "render_job"."DOCBRJ_JobDocumentID",
    "job_doc"."JobDoc_Title" AS "JobDocumentTitle",
    "job_doc"."JobDoc_FileName" AS "JobDocumentFileName",
    "render_job"."DOCBRJ_StartedAt",
    "render_job"."DOCBRJ_CompletedAt",
    "render_job"."DOCBRJ_ErrorMessage",
    "render_job"."DOCBRJ_CreatedAt",
    "latest_document"."DOCBGD_ID" AS "LatestGeneratedDocumentID",
    "latest_document"."DOCBGD_FileName" AS "LatestGeneratedFileName",
    "latest_document"."DOCBGD_FileURL" AS "LatestGeneratedFileURL",
    "latest_document"."DOCBGD_StorageBucket" AS "LatestGeneratedStorageBucket",
    "latest_document"."DOCBGD_StoragePath" AS "LatestGeneratedStoragePath",
    "latest_document"."DOCBGD_FileSizeBytes" AS "LatestGeneratedFileSizeBytes",
    "latest_document"."DOCBGD_VersionNo" AS "LatestGeneratedVersionNo",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_GeneratedDocuments" "generated"
          WHERE ("generated"."DOCBGD_RenderJobID" = "render_job"."DOCBRJ_ID")) AS "GeneratedDocumentCount"
   FROM (((((((("public"."DOCB_RenderJobs" "render_job"
     JOIN "public"."DOCB_DocumentTemplates" "template" ON (("template"."DOCBT_ID" = "render_job"."DOCBRJ_TemplateID")))
     LEFT JOIN "public"."DOCB_TemplateVersions" "template_version" ON (("template_version"."DOCBTV_ID" = "render_job"."DOCBRJ_TemplateVersionID")))
     LEFT JOIN "public"."sys_DocBuilderRenderStatuses" "render_status" ON ((("render_status"."DOCBRS_Code")::"text" = ("render_job"."DOCBRJ_StatusCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderRenderEngines" "render_engine" ON ((("render_engine"."DOCBRE_Code")::"text" = ("render_job"."DOCBRJ_RenderEngineCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderOutputFormats" "output_format" ON ((("output_format"."DOCBOF_Code")::"text" = ("render_job"."DOCBRJ_OutputFormatCode")::"text")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "render_job"."DOCBRJ_JobID")))
     LEFT JOIN "public"."Job_Documents" "job_doc" ON (("job_doc"."JobDoc_ID" = "render_job"."DOCBRJ_JobDocumentID")))
     LEFT JOIN LATERAL ( SELECT "generated"."DOCBGD_ID",
            "generated"."DOCBGD_RenderJobID",
            "generated"."DOCBGD_TemplateID",
            "generated"."DOCBGD_TemplateVersionID",
            "generated"."DOCBGD_JobDocumentID",
            "generated"."DOCBGD_OutputFormatCode",
            "generated"."DOCBGD_FileName",
            "generated"."DOCBGD_StorageBucket",
            "generated"."DOCBGD_StoragePath",
            "generated"."DOCBGD_FileURL",
            "generated"."DOCBGD_MimeType",
            "generated"."DOCBGD_FileSizeBytes",
            "generated"."DOCBGD_SHA256",
            "generated"."DOCBGD_VersionNo",
            "generated"."DOCBGD_IsCurrentVersion",
            "generated"."DOCBGD_MetadataJSON",
            "generated"."DOCBGD_CreatedAt",
            "generated"."DOCBGD_CreatedBy"
           FROM "public"."DOCB_GeneratedDocuments" "generated"
          WHERE ("generated"."DOCBGD_RenderJobID" = "render_job"."DOCBRJ_ID")
          ORDER BY "generated"."DOCBGD_IsCurrentVersion" DESC, "generated"."DOCBGD_VersionNo" DESC, "generated"."DOCBGD_CreatedAt" DESC
         LIMIT 1) "latest_document" ON (true));


ALTER VIEW "public"."DOCB_RenderJobSummary" OWNER TO "postgres";


