CREATE OR REPLACE VIEW "public"."DOCB_TemplatePageSummary" AS
 SELECT "template"."DOCBT_ID",
    "template"."DOCBT_Code",
    "template"."DOCBT_Name",
    "template_version"."DOCBTV_ID",
    "template_version"."DOCBTV_VersionNo",
    "page"."DOCBPG_ID",
    "page"."DOCBPG_PageTypeCode",
    "page_type"."DOCBPT_Name" AS "PageTypeName",
    "page"."DOCBPG_SortOrder",
    "page"."DOCBPG_PageName",
    "page"."DOCBPG_WidthMM",
    "page"."DOCBPG_HeightMM",
    "page"."DOCBPG_Orientation",
    "page"."DOCBPG_MarginsJSON",
    "header_section"."DOCBS_Code" AS "HeaderSectionCode",
    "footer_section"."DOCBS_Code" AS "FooterSectionCode",
    "background_asset"."DOCBAS_Code" AS "BackgroundAssetCode",
    "watermark_asset"."DOCBAS_Code" AS "WatermarkAssetCode",
    "page"."DOCBPG_SettingsJSON"
   FROM ((((((("public"."DOCB_TemplatePages" "page"
     JOIN "public"."DOCB_TemplateVersions" "template_version" ON (("template_version"."DOCBTV_ID" = "page"."DOCBPG_TemplateVersionID")))
     JOIN "public"."DOCB_DocumentTemplates" "template" ON (("template"."DOCBT_ID" = "template_version"."DOCBTV_TemplateID")))
     LEFT JOIN "public"."sys_DocBuilderPageTypes" "page_type" ON ((("page_type"."DOCBPT_Code")::"text" = ("page"."DOCBPG_PageTypeCode")::"text")))
     LEFT JOIN "public"."DOCB_SectionDefinitions" "header_section" ON (("header_section"."DOCBS_ID" = "page"."DOCBPG_HeaderSectionID")))
     LEFT JOIN "public"."DOCB_SectionDefinitions" "footer_section" ON (("footer_section"."DOCBS_ID" = "page"."DOCBPG_FooterSectionID")))
     LEFT JOIN "public"."DOCB_AssetLibrary" "background_asset" ON (("background_asset"."DOCBAS_ID" = "page"."DOCBPG_BackgroundAssetID")))
     LEFT JOIN "public"."DOCB_AssetLibrary" "watermark_asset" ON (("watermark_asset"."DOCBAS_ID" = "page"."DOCBPG_WatermarkAssetID")));


