CREATE OR REPLACE VIEW "public"."DOCB_TemplateQAIssueSummary" AS
 SELECT "qa_run"."DOCBQA_ID",
    "qa_run"."DOCBQA_TemplateID",
    "template"."DOCBT_Code",
    "template"."DOCBT_Name",
    "qa_run"."DOCBQA_TemplateVersionID",
    "template_version"."DOCBTV_VersionNo",
    "qa_run"."DOCBQA_StatusCode",
    "qa_issue"."DOCBQAI_ID",
    "qa_issue"."DOCBQAI_IssueTypeCode",
    "issue_type"."DOCBQAIT_Name" AS "IssueTypeName",
    "qa_issue"."DOCBQAI_SeverityCode",
    "severity"."DOCBQAS_Name" AS "SeverityName",
    "severity"."DOCBQAS_IsBlocking" AS "SeverityIsBlocking",
    "qa_issue"."DOCBQAI_Message",
    "qa_issue"."DOCBQAI_FixSuggestion",
    "qa_issue"."DOCBQAI_PageNo",
    "qa_issue"."DOCBQAI_FieldPath",
    "qa_issue"."DOCBQAI_IsResolved",
    "qa_issue"."DOCBQAI_CreatedAt"
   FROM ((((("public"."DOCB_TemplateQAIssues" "qa_issue"
     JOIN "public"."DOCB_TemplateQARuns" "qa_run" ON (("qa_run"."DOCBQA_ID" = "qa_issue"."DOCBQAI_QARunID")))
     JOIN "public"."DOCB_DocumentTemplates" "template" ON (("template"."DOCBT_ID" = "qa_run"."DOCBQA_TemplateID")))
     LEFT JOIN "public"."DOCB_TemplateVersions" "template_version" ON (("template_version"."DOCBTV_ID" = "qa_run"."DOCBQA_TemplateVersionID")))
     LEFT JOIN "public"."sys_DocBuilderQAIssueTypes" "issue_type" ON ((("issue_type"."DOCBQAIT_Code")::"text" = ("qa_issue"."DOCBQAI_IssueTypeCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderQASeverities" "severity" ON ((("severity"."DOCBQAS_Code")::"text" = ("qa_issue"."DOCBQAI_SeverityCode")::"text")));


