CREATE OR REPLACE VIEW "public"."DOCB_TemplateSummary" AS
 SELECT "template"."DOCBT_ID",
    "template"."DOCBT_Code",
    "template"."DOCBT_Name",
    "template"."DOCBT_LibraryDocumentID",
    "template"."DOCBT_LibraryDocumentCode",
    "library_document"."DOCBLD_Name" AS "LibraryDocumentName",
    "library_document"."DOCBLD_Category" AS "LibraryDocumentCategory",
    "template"."DOCBT_DocTypeID",
    "doc_type"."DocTypes_DocType" AS "DocTypeCode",
    "doc_type"."DocTypes_Desc" AS "DocTypeName",
    "template"."DOCBT_DocTypeCodeSnapshot",
    "template"."DOCBT_DataScopeCode",
    "scope"."DOCBSC_Name" AS "DataScopeName",
    "template"."DOCBT_DefaultDataSourceID",
    "data_source"."DOCBDS_Code" AS "DefaultDataSourceCode",
    "data_source"."DOCBDS_Name" AS "DefaultDataSourceName",
    "template"."DOCBT_StatusCode",
    "status"."DOCBST_Name" AS "StatusName",
    "status"."DOCBST_IsFinal" AS "StatusIsFinal",
    "template"."DOCBT_CurrentVersionNo",
    "current_version"."DOCBTV_ID" AS "CurrentTemplateVersionID",
    "current_version"."DOCBTV_StatusCode" AS "CurrentVersionStatusCode",
    "current_version"."DOCBTV_PublishedAt" AS "CurrentVersionPublishedAt",
    "template"."DOCBT_DefaultRenderEngineCode",
    "render_engine"."DOCBRE_Name" AS "DefaultRenderEngineName",
    "template"."DOCBT_DefaultOutputFormatCode",
    "output_format"."DOCBOF_Name" AS "DefaultOutputFormatName",
    "output_format"."DOCBOF_MimeType" AS "DefaultOutputMimeType",
    "template"."DOCBT_ThemeID",
    "theme"."DOCBTH_Name" AS "ThemeName",
    "template"."DOCBT_OrgOfficeID",
    "office"."Office_Code" AS "OrgOfficeCode",
    "office"."Office_Name" AS "OrgOfficeName",
    "template"."DOCBT_LegalEntityID",
    "legal_entity"."LegalEntity_Name" AS "LegalEntityName",
    "legal_entity"."LegalEntity_TradingName" AS "LegalEntityTradingName",
    "template"."DOCBT_BrandID",
    "brand"."Brand_Name" AS "BrandName",
    "brand"."Brand_DisplayName" AS "BrandDisplayName",
    "template"."DOCBT_CustomerOrgID",
    "customer"."Org_Name" AS "CustomerOrgName",
    "template"."DOCBT_LanguageCode",
    "template"."DOCBT_Description",
    "template"."DOCBT_IsSystem",
    "template"."DOCBT_IsUserEditable",
    "template"."DOCBT_IsActive",
    "template"."DOCBT_CreatedAt",
    "template"."DOCBT_UpdatedAt",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_TemplateSections" "section"
          WHERE ("section"."DOCBTS_TemplateVersionID" = "current_version"."DOCBTV_ID")) AS "SectionCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_LibraryPackItems" "pack_item"
          WHERE ("pack_item"."DOCBLPI_TemplateID" = "template"."DOCBT_ID")) AS "LibraryPackItemCount",
    ( SELECT "max"("render_job"."DOCBRJ_CreatedAt") AS "max"
           FROM "public"."DOCB_RenderJobs" "render_job"
          WHERE ("render_job"."DOCBRJ_TemplateID" = "template"."DOCBT_ID")) AS "LastRenderedAt"
   FROM ((((((((((((("public"."DOCB_DocumentTemplates" "template"
     LEFT JOIN "public"."DOCB_LibraryDocuments" "library_document" ON ((("library_document"."DOCBLD_ID" = "template"."DOCBT_LibraryDocumentID") OR (("template"."DOCBT_LibraryDocumentID" IS NULL) AND (("library_document"."DOCBLD_Code")::"text" = ("template"."DOCBT_LibraryDocumentCode")::"text")))))
     LEFT JOIN "public"."sys_DocTypes" "doc_type" ON (("doc_type"."DocTypes_PK" = "template"."DOCBT_DocTypeID")))
     LEFT JOIN "public"."sys_DocBuilderDataScopes" "scope" ON ((("scope"."DOCBSC_Code")::"text" = ("template"."DOCBT_DataScopeCode")::"text")))
     LEFT JOIN "public"."DOCB_DataSources" "data_source" ON (("data_source"."DOCBDS_ID" = "template"."DOCBT_DefaultDataSourceID")))
     LEFT JOIN "public"."sys_DocBuilderStatuses" "status" ON ((("status"."DOCBST_Code")::"text" = ("template"."DOCBT_StatusCode")::"text")))
     LEFT JOIN "public"."DOCB_TemplateVersions" "current_version" ON ((("current_version"."DOCBTV_TemplateID" = "template"."DOCBT_ID") AND ("current_version"."DOCBTV_VersionNo" = "template"."DOCBT_CurrentVersionNo"))))
     LEFT JOIN "public"."sys_DocBuilderRenderEngines" "render_engine" ON ((("render_engine"."DOCBRE_Code")::"text" = ("template"."DOCBT_DefaultRenderEngineCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderOutputFormats" "output_format" ON ((("output_format"."DOCBOF_Code")::"text" = ("template"."DOCBT_DefaultOutputFormatCode")::"text")))
     LEFT JOIN "public"."DOCB_Themes" "theme" ON (("theme"."DOCBTH_ID" = "template"."DOCBT_ThemeID")))
     LEFT JOIN "public"."cmp_Offices" "office" ON (("office"."Office_ID" = "template"."DOCBT_OrgOfficeID")))
     LEFT JOIN "public"."cmp_LegalEntities" "legal_entity" ON (("legal_entity"."LegalEntity_ID" = "template"."DOCBT_LegalEntityID")))
     LEFT JOIN "public"."cmp_Brands" "brand" ON (("brand"."Brand_ID" = "template"."DOCBT_BrandID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "template"."DOCBT_CustomerOrgID")));


ALTER VIEW "public"."DOCB_TemplateSummary" OWNER TO "postgres";


