    "DOCSECVE_VerificationTokenID" "uuid",
    "DOCSECVE_PublicCodeSnapshot" character varying(80),
    "DOCSECVE_StatusCode" character varying(60) NOT NULL,
    "DOCSECVE_RiskLevelCode" character varying(40) DEFAULT 'none'::character varying NOT NULL,
    "DOCSECVE_VerifiedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "DOCSECVE_VerificationMethod" character varying(40) DEFAULT 'scan'::character varying NOT NULL,
    "DOCSECVE_DocumentHashSubmittedSHA256" character varying(64),
    "DOCSECVE_MatchedFingerprintID" "uuid",
    "DOCSECVE_IPAddressHashSHA256" character varying(64),
    "DOCSECVE_UserAgent" "text",
    "DOCSECVE_CountryCode" character varying(2),
    "DOCSECVE_RefererHost" character varying(255),
    "DOCSECVE_ResultMessage" "text",
    "DOCSECVE_MetadataJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "DOCSEC_VerificationEvents_doc_hash_check" CHECK ((("DOCSECVE_DocumentHashSubmittedSHA256" IS NULL) OR (("DOCSECVE_DocumentHashSubmittedSHA256")::"text" ~ '^[a-fA-F0-9]{64}$'::"text"))),
    CONSTRAINT "DOCSEC_VerificationEvents_ip_hash_check" CHECK ((("DOCSECVE_IPAddressHashSHA256" IS NULL) OR (("DOCSECVE_IPAddressHashSHA256")::"text" ~ '^[a-fA-F0-9]{64}$'::"text")))
);


