    "BLNumber",
    "BLStatus",
    "DOCSECF_FileSHA256",
    "DOCSECF_CanonicalPayloadSHA256",
    "SignatureIsValid",
    "DOCSECVT_ValidFrom",
    "DOCSECVT_ExpiresAt",
    "DOCSECVT_RevokedAt",
    "DOCSECVT_VerificationCount",
    "DOCSECVT_LastVerifiedAt",
    "OpenIssueCount"
   FROM "public"."DOCSEC_VerificationSummary" "summary";


