CREATE OR REPLACE VIEW "public"."EDI_MessageWorkQueue" AS
 SELECT "msg"."EDIMessage_ID",
    "msg"."EDIMessage_StatusCode",
    "msg"."EDIMessage_AcknowledgementStatusCode",
    "msg"."EDIMessage_DirectionCode",
    "msg"."EDIMessage_MessageTypeCode",
    "mt"."EDIMT_Name",
    "msg"."EDIMessage_StandardCode",
    "msg"."EDIMessage_TradingPartnerID",
    "tp"."EDITP_Name",
    "msg"."EDIMessage_ConnectionID",
    "conn"."EDIC_Name",
    "msg"."EDIMessage_JobID",
    "job"."Job_Number",
    "msg"."EDIMessage_DocumentReference",
    "msg"."EDIMessage_ControlNumber",
    "msg"."EDIMessage_ReceivedAt",
    "msg"."EDIMessage_SentAt",
    "msg"."EDIMessage_AckDueAt",
    "msg"."EDIMessage_RetryCount",
    "msg"."EDIMessage_LastErrorText",
    "msg"."EDIMessage_CreatedAt"
   FROM ((((("public"."EDI_Messages" "msg"
     LEFT JOIN "public"."sys_EDIMessageTypes" "mt" ON ((("mt"."EDIMT_Code")::"text" = ("msg"."EDIMessage_MessageTypeCode")::"text")))
     LEFT JOIN "public"."EDI_TradingPartners" "tp" ON (("tp"."EDITP_ID" = "msg"."EDIMessage_TradingPartnerID")))
     LEFT JOIN "public"."EDI_Connections" "conn" ON (("conn"."EDIC_ID" = "msg"."EDIMessage_ConnectionID")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "msg"."EDIMessage_JobID")))
     LEFT JOIN "public"."sys_EDIMessageStatuses" "status" ON ((("status"."EDIMS_Code")::"text" = ("msg"."EDIMessage_StatusCode")::"text")))
  WHERE ("status"."EDIMS_IsOpen" = true);


ALTER VIEW "public"."EDI_MessageWorkQueue" OWNER TO "postgres";


