CREATE OR REPLACE VIEW "public"."FIN_APAgeingSummary" AS
 SELECT "d"."FINDoc_PartyOrgID" AS "FINAge_SupplierOrgID",
    "org"."Org_Name" AS "FINAge_SupplierName",
    "d"."FINDoc_LegalEntityID",
    "d"."FINDoc_OrgOfficeID",
    "d"."FINDoc_CurrencyCodeSnapshot",
    ("count"(*))::integer AS "FINAge_DocumentCount",
    "sum"("d"."FINDoc_OutstandingAmount") AS "FINAge_TotalOutstanding",
    "sum"(
        CASE
            WHEN ("d"."FINDoc_DueDate" >= CURRENT_DATE) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_Current",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND (((CURRENT_DATE - "d"."FINDoc_DueDate") >= 1) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") <= 30))) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_1To30",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND (((CURRENT_DATE - "d"."FINDoc_DueDate") >= 31) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") <= 60))) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_31To60",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND (((CURRENT_DATE - "d"."FINDoc_DueDate") >= 61) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") <= 90))) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_61To90",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") > 90)) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_Over90"
   FROM ("public"."FIN_Documents" "d"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "d"."FINDoc_PartyOrgID")))
  WHERE ((("d"."FINDoc_TypeCode")::"text" = 'pl_invoice'::"text") AND ("d"."FINDoc_OutstandingAmount" <> (0)::numeric))
  GROUP BY "d"."FINDoc_PartyOrgID", "org"."Org_Name", "d"."FINDoc_LegalEntityID", "d"."FINDoc_OrgOfficeID", "d"."FINDoc_CurrencyCodeSnapshot";


ALTER VIEW "public"."FIN_APAgeingSummary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."FIN_ARAgeingSummary" AS
 SELECT "d"."FINDoc_PartyOrgID" AS "FINAge_CustomerOrgID",
    "org"."Org_Name" AS "FINAge_CustomerName",
    "d"."FINDoc_LegalEntityID",
    "d"."FINDoc_OrgOfficeID",
    "d"."FINDoc_CurrencyCodeSnapshot",
    ("count"(*))::integer AS "FINAge_DocumentCount",
    "sum"("d"."FINDoc_OutstandingAmount") AS "FINAge_TotalOutstanding",
    "sum"(
        CASE
            WHEN ("d"."FINDoc_DueDate" >= CURRENT_DATE) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_Current",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND (((CURRENT_DATE - "d"."FINDoc_DueDate") >= 1) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") <= 30))) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_1To30",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND (((CURRENT_DATE - "d"."FINDoc_DueDate") >= 31) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") <= 60))) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_31To60",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND (((CURRENT_DATE - "d"."FINDoc_DueDate") >= 61) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") <= 90))) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_61To90",
    "sum"(
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND ((CURRENT_DATE - "d"."FINDoc_DueDate") > 90)) THEN "d"."FINDoc_OutstandingAmount"
            ELSE (0)::numeric
        END) AS "FINAge_Over90"
   FROM ("public"."FIN_Documents" "d"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "d"."FINDoc_PartyOrgID")))
  WHERE ((("d"."FINDoc_TypeCode")::"text" = ANY ((ARRAY['sl_invoice'::character varying, 'debit_note'::character varying])::"text"[])) AND ("d"."FINDoc_OutstandingAmount" <> (0)::numeric))
  GROUP BY "d"."FINDoc_PartyOrgID", "org"."Org_Name", "d"."FINDoc_LegalEntityID", "d"."FINDoc_OrgOfficeID", "d"."FINDoc_CurrencyCodeSnapshot";


ALTER VIEW "public"."FIN_ARAgeingSummary" OWNER TO "postgres";


