CREATE OR REPLACE VIEW "public"."FIN_DocumentBalanceSummary" AS
 SELECT "d"."FINDoc_ID",
    "d"."FINDoc_Number",
    "d"."FINDoc_TypeCode",
    "d"."FINDoc_StatusCode",
    "d"."FINDoc_PartyOrgID",
    "org"."Org_Name" AS "FINDoc_PartyName",
    "d"."FINDoc_DocumentDate",
    "d"."FINDoc_AccountingDate",
    "d"."FINDoc_DueDate",
    "d"."FINDoc_CurrencyCodeSnapshot",
    "d"."FINDoc_GrossAmount",
    "d"."FINDoc_OutstandingAmount",
    ("d"."FINDoc_GrossAmount" - "d"."FINDoc_OutstandingAmount") AS "FINDoc_PaidOrAllocatedAmount",
        CASE
            WHEN (("d"."FINDoc_DueDate" < CURRENT_DATE) AND ("d"."FINDoc_OutstandingAmount" > (0)::numeric)) THEN true
            ELSE false
        END AS "FINDoc_IsOverdue",
        CASE
            WHEN ("d"."FINDoc_DueDate" < CURRENT_DATE) THEN (CURRENT_DATE - "d"."FINDoc_DueDate")
            ELSE 0
        END AS "FINDoc_DaysOverdue"
   FROM ("public"."FIN_Documents" "d"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "d"."FINDoc_PartyOrgID")));


