CREATE OR REPLACE VIEW "public"."FIN_JobFinanceSummary" AS
 SELECT "j"."Job_ID",
    "j"."Job_Number",
    "j"."Job_Customer",
    "cust"."Org_Name" AS "Job_CustomerName",
    COALESCE("sum"(
        CASE
            WHEN (("d"."FINDoc_TypeCode")::"text" = ANY ((ARRAY['sl_invoice'::character varying, 'debit_note'::character varying])::"text"[])) THEN "l"."FINDocLineJob_LocalNetAmount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "FINJob_LocalRevenue",
    COALESCE("sum"(
        CASE
            WHEN (("d"."FINDoc_TypeCode")::"text" = 'pl_invoice'::"text") THEN "l"."FINDocLineJob_LocalNetAmount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "FINJob_LocalCost",
    COALESCE(( SELECT "sum"(("w"."FINWIP_LocalWIPAmount" - "w"."FINWIP_RelievedAmount")) AS "sum"
           FROM "public"."FIN_WIPItems" "w"
          WHERE ("w"."FINWIP_JobID" = "j"."Job_ID")), (0)::numeric) AS "FINJob_LocalWIP",
    COALESCE(( SELECT "sum"(("a"."FINAccrual_LocalAccruedAmount" - "a"."FINAccrual_RelievedAmount")) AS "sum"
           FROM "public"."FIN_Accruals" "a"
          WHERE ("a"."FINAccrual_JobID" = "j"."Job_ID")), (0)::numeric) AS "FINJob_LocalAccrual",
    COALESCE("sum"(
        CASE
            WHEN (("d"."FINDoc_TypeCode")::"text" = ANY ((ARRAY['sl_invoice'::character varying, 'debit_note'::character varying])::"text"[])) THEN "l"."FINDocLineJob_LocalNetAmount"
            ELSE (- "l"."FINDocLineJob_LocalNetAmount")
        END), (0)::numeric) AS "FINJob_LocalMargin"
   FROM ((("public"."Job_Header" "j"
     LEFT JOIN "public"."Org_Master" "cust" ON (("cust"."Org_id" = "j"."Job_Customer")))
     LEFT JOIN "public"."FIN_DocumentLineJobLinks" "l" ON (("l"."FINDocLineJob_JobID" = "j"."Job_ID")))
     LEFT JOIN "public"."FIN_Documents" "d" ON (("d"."FINDoc_ID" = "l"."FINDocLineJob_DocumentID")))
  GROUP BY "j"."Job_ID", "j"."Job_Number", "j"."Job_Customer", "cust"."Org_Name";


