CREATE OR REPLACE VIEW "public"."FIN_ProfitShareSummary" AS
 SELECT "i"."FINPSItem_PartnerOrgID",
    "r"."FINPSRun_PeriodID",
    "i"."FINPSItem_StatusCode",
    ("count"(*))::integer AS "FINPS_ItemCount",
    "sum"("i"."FINPSItem_ShareAmount") AS "FINPS_TotalShareAmount"
   FROM ("public"."FIN_ProfitShareItems" "i"
     JOIN "public"."FIN_ProfitShareRuns" "r" ON (("r"."FINPSRun_ID" = "i"."FINPSItem_RunID")))
  GROUP BY "i"."FINPSItem_PartnerOrgID", "r"."FINPSRun_PeriodID", "i"."FINPSItem_StatusCode";


