CREATE OR REPLACE VIEW "public"."FIN_WIPAccrualSummary" AS
 SELECT 'wip'::"text" AS "FINWA_TypeCode",
    "w"."FINWIP_ID" AS "FINWA_SourceID",
    "w"."FINWIP_JobID" AS "FINWA_JobID",
    "w"."FINWIP_PeriodID" AS "FINWA_PeriodID",
    "w"."FINWIP_StatusCode" AS "FINWA_StatusCode",
    "w"."FINWIP_AccountingDate" AS "FINWA_AccountingDate",
    "w"."FINWIP_CurrencyCodeSnapshot" AS "FINWA_CurrencyCodeSnapshot",
    "w"."FINWIP_WIPAmount" AS "FINWA_Amount",
    "w"."FINWIP_LocalWIPAmount" AS "FINWA_LocalAmount"
   FROM "public"."FIN_WIPItems" "w"
UNION ALL
 SELECT 'accrual'::"text" AS "FINWA_TypeCode",
    "a"."FINAccrual_ID" AS "FINWA_SourceID",
    "a"."FINAccrual_JobID" AS "FINWA_JobID",
    "a"."FINAccrual_PeriodID" AS "FINWA_PeriodID",
    "a"."FINAccrual_StatusCode" AS "FINWA_StatusCode",
    "a"."FINAccrual_AccountingDate" AS "FINWA_AccountingDate",
    "a"."FINAccrual_CurrencyCodeSnapshot" AS "FINWA_CurrencyCodeSnapshot",
    "a"."FINAccrual_AccruedAmount" AS "FINWA_Amount",
    "a"."FINAccrual_LocalAccruedAmount" AS "FINWA_LocalAmount"
   FROM "public"."FIN_Accruals" "a";


ALTER VIEW "public"."FIN_WIPAccrualSummary" OWNER TO "postgres";


