    "JobTrackConn_ClientID" character varying(180),
    "JobTrackConn_SecretRef" character varying(240),
    "JobTrackConn_WebhookSecretRef" character varying(240),
    "JobTrackConn_DefaultForOffice" boolean DEFAULT false NOT NULL,
    "JobTrackConn_IsActive" boolean DEFAULT true NOT NULL,
