    CONSTRAINT "Job_TrackingApiConnections_auth_check" CHECK ((("JobTrackConn_AuthType")::"text" = ANY ((ARRAY['api_key'::character varying, 'oauth2_client_credentials'::character varying, 'bearer_token'::character varying, 'mutual_tls'::character varying, 'webhook_only'::character varying, 'other'::character varying])::"text"[])))
);


