     LEFT JOIN "public"."sys_LOCDateFormats" "df" ON ((("df"."LOCDateFormat_Code")::"text" = ("p"."LOCProfile_DateFormatCode")::"text")))
     LEFT JOIN "public"."sys_LOCTimeFormats" "tf" ON ((("tf"."LOCTimeFormat_Code")::"text" = ("p"."LOCProfile_TimeFormatCode")::"text")))
     LEFT JOIN "public"."sys_LOCNumberFormats" "nf" ON ((("nf"."LOCNumberFormat_Code")::"text" = ("p"."LOCProfile_NumberFormatCode")::"text")));


