CREATE OR REPLACE VIEW "public"."MDX_ConflictSummary" AS
 SELECT "conflict"."MDXConflict_ID",
    "conflict"."MDXConflict_SharedJobID",
    "sj"."MDXSharedJob_LocalJobNumberSnapshot",
    "sj"."MDXSharedJob_RemoteJobNumber",
    "peer"."CommPeer_DisplayName" AS "MDXConflict_PeerName",
    "conflict"."MDXConflict_StatusCode",
    "conflict"."MDXConflict_DataScopeCode",
    "conflict"."MDXConflict_FieldPath",
    "conflict"."MDXConflict_Title",
    "conflict"."MDXConflict_AssignedUserID",
    "u"."User_Email" AS "MDXConflict_AssignedUserEmail",
    "conflict"."MDXConflict_ResolvedAt",
    "conflict"."MDXConflict_CreatedAt"
   FROM ((("public"."MDX_ConflictCases" "conflict"
     JOIN "public"."MDX_SharedJobs" "sj" ON (("sj"."MDXSharedJob_ID" = "conflict"."MDXConflict_SharedJobID")))
     JOIN "public"."Comm_FederationPeers" "peer" ON (("peer"."CommPeer_ID" = "sj"."MDXSharedJob_PeerID")))
     LEFT JOIN "public"."cmp_Users" "u" ON (("u"."User_ID" = "conflict"."MDXConflict_AssignedUserID")));


