CREATE OR REPLACE VIEW "public"."MDX_InboundReviewQueue" AS
 SELECT "review"."MDXReview_ID",
    "review"."MDXReview_SharedJobID",
    "sj"."MDXSharedJob_LocalJobNumberSnapshot",
    "sj"."MDXSharedJob_RemoteJobNumber",
    "peer"."CommPeer_DisplayName" AS "MDXReview_PeerName",
    "review"."MDXReview_EventID",
    "review"."MDXReview_DataScopeCode",
    "review"."MDXReview_StatusCode",
    "review"."MDXReview_Title",
    "review"."MDXReview_Description",
    "review"."MDXReview_TargetTable",
    "review"."MDXReview_TargetID",
    "review"."MDXReview_AssignedUserID",
    "u"."User_Email" AS "MDXReview_AssignedUserEmail",
    "review"."MDXReview_CreatedAt"
   FROM ((("public"."MDX_InboundReviewItems" "review"
     JOIN "public"."MDX_SharedJobs" "sj" ON (("sj"."MDXSharedJob_ID" = "review"."MDXReview_SharedJobID")))
     JOIN "public"."Comm_FederationPeers" "peer" ON (("peer"."CommPeer_ID" = "sj"."MDXSharedJob_PeerID")))
     LEFT JOIN "public"."cmp_Users" "u" ON (("u"."User_ID" = "review"."MDXReview_AssignedUserID")))
  WHERE (("review"."MDXReview_StatusCode")::"text" = 'pending'::"text")
  ORDER BY "review"."MDXReview_CreatedAt" DESC;


