    "sj"."MDXSharedJob_RemoteJobNumber",
    "sj"."MDXSharedJob_StatusCode",
    "sj"."MDXSharedJob_DirectionCode",
    "sj"."MDXSharedJob_LocalRoleCode",
    "sj"."MDXSharedJob_RemoteRoleCode",
    "sj"."MDXSharedJob_PrimaryReference",
    "sj"."MDXSharedJob_TransportModeCode",
    "sj"."MDXSharedJob_OriginUNLocode",
    "sj"."MDXSharedJob_OriginNameSnapshot",
    "sj"."MDXSharedJob_DestinationUNLocode",
    "sj"."MDXSharedJob_DestinationNameSnapshot",
    "sj"."MDXSharedJob_CurrentLocationUNLocode",
    "sj"."MDXSharedJob_CurrentLocationNameSnapshot",
    "sj"."MDXSharedJob_PredictedDeliveryAt",
    "sj"."MDXSharedJob_TrackingStatus",
    "sj"."MDXSharedJob_LastOutboundSyncAt",
    "sj"."MDXSharedJob_LastInboundSyncAt",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."MDX_SharedRouteLegs" "r"
          WHERE ("r"."MDXRoute_SharedJobID" = "sj"."MDXSharedJob_ID")) AS "MDXSharedJob_RouteLegCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."MDX_SharedMilestones" "m"
          WHERE ("m"."MDXMilestone_SharedJobID" = "sj"."MDXSharedJob_ID")) AS "MDXSharedJob_MilestoneCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."MDX_InboundReviewItems" "rv"
          WHERE (("rv"."MDXReview_SharedJobID" = "sj"."MDXSharedJob_ID") AND (("rv"."MDXReview_StatusCode")::"text" = 'pending'::"text"))) AS "MDXSharedJob_PendingReviewCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."MDX_ConflictCases" "c"
          WHERE (("c"."MDXConflict_SharedJobID" = "sj"."MDXSharedJob_ID") AND (("c"."MDXConflict_StatusCode")::"text" = ANY ((ARRAY['open'::character varying, 'reviewing'::character varying])::"text"[])))) AS "MDXSharedJob_OpenConflictCount"
   FROM (("public"."MDX_SharedJobs" "sj"
     JOIN "public"."MDX_ShareAgreements" "agreement" ON (("agreement"."MDXAgreement_ID" = "sj"."MDXSharedJob_AgreementID")))
     JOIN "public"."Comm_FederationPeers" "peer" ON (("peer"."CommPeer_ID" = "sj"."MDXSharedJob_PeerID")))
  WHERE ("sj"."MDXSharedJob_IsDeleted" = false);


