CREATE OR REPLACE VIEW "public"."MIG_OpenValidationIssues" AS
 SELECT "i"."MIGIssue_ID" AS "IssueID",
    "i"."MIGIssue_BatchID" AS "BatchID",
    "b"."MIGBatch_Code" AS "BatchCode",
    "b"."MIGBatch_EntityTypeCode" AS "EntityTypeCode",
    "i"."MIGIssue_RowID" AS "RowID",
    "r"."MIGRow_RowNumber" AS "RowNumber",
    "i"."MIGIssue_SeverityCode" AS "SeverityCode",
    "i"."MIGIssue_FieldName" AS "FieldName",
    "i"."MIGIssue_IssueCode" AS "IssueCode",
    "i"."MIGIssue_Message" AS "Message",
    "i"."MIGIssue_CreatedAt" AS "CreatedAt"
   FROM (("public"."MIG_ValidationIssues" "i"
     JOIN "public"."MIG_ImportBatches" "b" ON (("b"."MIGBatch_ID" = "i"."MIGIssue_BatchID")))
     LEFT JOIN "public"."MIG_ImportRows" "r" ON (("r"."MIGRow_ID" = "i"."MIGIssue_RowID")))
  WHERE ("i"."MIGIssue_IsResolved" = false);


