 SELECT "OBSRetry_ID" AS "RetryID",
    "OBSRetry_ModuleCode" AS "ModuleCode",
    "OBSRetry_SourceTable" AS "SourceTable",
    "OBSRetry_SourceID" AS "SourceID",
    "OBSRetry_StatusCode" AS "StatusCode",
    "OBSRetry_AttemptCount" AS "AttemptCount",
    "OBSRetry_MaxAttempts" AS "MaxAttempts",
    "OBSRetry_NextAttemptAt" AS "NextAttemptAt",
    "OBSRetry_LastErrorMessage" AS "LastErrorMessage",
    "OBSRetry_CorrelationID" AS "CorrelationID"
   FROM "public"."OBS_RetryQueue" "r"
  WHERE ((("OBSRetry_StatusCode")::"text" = ANY ((ARRAY['queued'::character varying, 'open'::character varying, 'waiting'::character varying])::"text"[])) AND ("OBSRetry_NextAttemptAt" <= "now"()) AND ("OBSRetry_AttemptCount" < "OBSRetry_MaxAttempts"));


ALTER VIEW "public"."OBS_RetryQueueDue" OWNER TO "postgres";


