CREATE OR REPLACE VIEW "public"."Portal_AuditEventSummary" AS
 SELECT "ae"."PortalAudit_ID",
    "ae"."PortalAudit_EventTypeCode",
    "ev"."PortalEventType_IsSecurityRelevant",
    "ae"."PortalAudit_SiteID",
    "site"."PortalSite_Name",
    "ae"."PortalAudit_PortalUserID",
    "pu"."PortalUser_DisplayName",
    "pu"."PortalUser_Email",
    "ae"."PortalAudit_APIClientID",
    "api"."PortalAPIClient_Name",
    "ae"."PortalAudit_OrgID",
    "org"."Org_Name" AS "PortalAudit_OrgName",
    "ae"."PortalAudit_ResourceTypeCode",
    "ae"."PortalAudit_TargetTable",
    "ae"."PortalAudit_TargetID",
    "ae"."PortalAudit_ResultCode",
    "ae"."PortalAudit_Message",
    "ae"."PortalAudit_CreatedAt"
   FROM ((((("public"."Portal_AuditEvents" "ae"
     LEFT JOIN "public"."sys_PortalEventTypes" "ev" ON ((("ev"."PortalEventType_Code")::"text" = ("ae"."PortalAudit_EventTypeCode")::"text")))
     LEFT JOIN "public"."Portal_Sites" "site" ON (("site"."PortalSite_ID" = "ae"."PortalAudit_SiteID")))
     LEFT JOIN "public"."Portal_Users" "pu" ON (("pu"."PortalUser_ID" = "ae"."PortalAudit_PortalUserID")))
     LEFT JOIN "public"."Portal_APIClients" "api" ON (("api"."PortalAPIClient_ID" = "ae"."PortalAudit_APIClientID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "ae"."PortalAudit_OrgID")));


