CREATE OR REPLACE VIEW "public"."Portal_DocumentShareSummary" AS
 SELECT "ds"."PortalDocShare_ID",
    "ds"."PortalDocShare_RecordShareID",
    "ds"."PortalDocShare_SiteID",
    "site"."PortalSite_Name",
    "ds"."PortalDocShare_JobDocumentID",
    "jd"."JobDoc_JobID",
    "jd"."JobDoc_Title" AS "JobDocument_Title",
    "jd"."JobDoc_Status",
    "ds"."PortalDocShare_GeneratedDocumentID",
    "ds"."PortalDocShare_VerificationTokenID",
    "vt"."DOCSECVT_PublicCode" AS "VerificationPublicCode",
    "ds"."PortalDocShare_Title",
    "ds"."PortalDocShare_StatusCode",
    "ds"."PortalDocShare_CanDownload",
    "ds"."PortalDocShare_CanViewOnly",
    "ds"."PortalDocShare_WatermarkRequired",
    "ds"."PortalDocShare_DownloadCount",
    "ds"."PortalDocShare_LastDownloadedAt",
    "ds"."PortalDocShare_ValidUntil"
   FROM ((("public"."Portal_DocumentShares" "ds"
     LEFT JOIN "public"."Portal_Sites" "site" ON (("site"."PortalSite_ID" = "ds"."PortalDocShare_SiteID")))
     LEFT JOIN "public"."Job_Documents" "jd" ON (("jd"."JobDoc_ID" = "ds"."PortalDocShare_JobDocumentID")))
     LEFT JOIN "public"."DOCSEC_VerificationTokens" "vt" ON (("vt"."DOCSECVT_ID" = "ds"."PortalDocShare_VerificationTokenID")));


