CREATE OR REPLACE VIEW "public"."Portal_PendingActionQueue" AS
 SELECT "a"."PortalAction_ID",
    "a"."PortalAction_SiteID",
    "site"."PortalSite_Name",
    "a"."PortalAction_ActionTypeCode",
    "a"."PortalAction_StatusCode",
    "a"."PortalAction_ResourceTypeCode",
    "a"."PortalAction_TargetTable",
    "a"."PortalAction_TargetID",
    "a"."PortalAction_JobID",
    "job"."Job_Number" AS "PortalAction_JobNumber",
    "a"."PortalAction_WorkflowTaskID",
    "a"."PortalAction_AssignedPortalUserID",
    "pu"."PortalUser_DisplayName",
    "pu"."PortalUser_Email",
    "a"."PortalAction_AssignedOrgID",
    "org"."Org_Name" AS "PortalAction_AssignedOrgName",
    "a"."PortalAction_Title",
    "a"."PortalAction_DueAt",
    "a"."PortalAction_ExpiresAt",
    "a"."PortalAction_RequiresInternalReview",
    "a"."PortalAction_CreatedAt"
   FROM (((("public"."Portal_ActionRequests" "a"
     LEFT JOIN "public"."Portal_Sites" "site" ON (("site"."PortalSite_ID" = "a"."PortalAction_SiteID")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "a"."PortalAction_JobID")))
     LEFT JOIN "public"."Portal_Users" "pu" ON (("pu"."PortalUser_ID" = "a"."PortalAction_AssignedPortalUserID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "a"."PortalAction_AssignedOrgID")))
  WHERE (("a"."PortalAction_StatusCode")::"text" = ANY ((ARRAY['requested'::character varying, 'viewed'::character varying, 'responded'::character varying, 'internal_review'::character varying])::"text"[]));


ALTER VIEW "public"."Portal_PendingActionQueue" OWNER TO "postgres";


