    "PortalLink_URL" "text",
    "PortalLink_ExpiresAt" timestamp with time zone,
    "PortalLink_MaxUseCount" integer,
    "PortalLink_UseCount" integer DEFAULT 0 NOT NULL,
    "PortalLink_LastUsedAt" timestamp with time zone,
    "PortalLink_RevokedAt" timestamp with time zone,
    "PortalLink_RevokedBy" "uuid",
    "PortalLink_RevocationReason" "text",
    "PortalLink_FieldPolicyJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
