    CONSTRAINT "Portal_PublicLinks_token_hash_check" CHECK ((("PortalLink_TokenHashSHA256")::"text" ~ '^[a-fA-F0-9]{64}$'::"text")),
    CONSTRAINT "Portal_PublicLinks_use_count_check" CHECK ((("PortalLink_MaxUseCount" IS NULL) OR ("PortalLink_MaxUseCount" > 0)))
);


