CREATE OR REPLACE VIEW "public"."RATE_ActiveRateLineSummary" AS
 SELECT "rl"."RATELine_ID",
    "c"."RATEContract_ID",
    "c"."RATEContract_Code",
    "c"."RATEContract_Name",
    "c"."RATEContract_TypeCode",
    "v"."RATEContractVer_ID",
    "v"."RATEContractVer_VersionNo",
    "s"."RATESheet_ID",
    "s"."RATESheet_Code",
    "s"."RATESheet_Name",
    "s"."RATESheet_ApplicabilityCode",
    "s"."RATESheet_ModeCode",
    "s"."RATESheet_ShipmentTypeCode",
    "s"."RATESheet_LaneID",
    "lane"."RATELane_Name",
    "rl"."RATELine_LineNo",
    "rl"."RATELine_ChargeID",
    "ch"."RATECharge_Code",
    "ch"."RATECharge_Name",
    "ch"."RATECharge_CategoryCode",
    "rl"."RATELine_BasisCode",
    "rl"."RATELine_CalculationMethodCode",
    "rl"."RATELine_CurrencyCodeSnapshot",
    "rl"."RATELine_UnitRate",
    "rl"."RATELine_MinimumAmount",
    "rl"."RATELine_MaximumAmount",
    "rl"."RATELine_EquipmentTypeCode",
    COALESCE("rl"."RATELine_ValidFrom", "s"."RATESheet_ValidFrom", "v"."RATEContractVer_EffectiveFrom", "c"."RATEContract_ValidFrom") AS "EffectiveFrom",
    COALESCE("rl"."RATELine_ValidTo", "s"."RATESheet_ValidTo", "v"."RATEContractVer_EffectiveTo", "c"."RATEContract_ValidTo") AS "EffectiveTo"
   FROM ((((("public"."RATE_RateLines" "rl"
     JOIN "public"."RATE_RateSheets" "s" ON (("s"."RATESheet_ID" = "rl"."RATELine_SheetID")))
     JOIN "public"."RATE_ContractVersions" "v" ON (("v"."RATEContractVer_ID" = "s"."RATESheet_ContractVerID")))
     JOIN "public"."RATE_Contracts" "c" ON (("c"."RATEContract_ID" = "v"."RATEContractVer_ContractID")))
     JOIN "public"."RATE_ChargeCodes" "ch" ON (("ch"."RATECharge_ID" = "rl"."RATELine_ChargeID")))
     LEFT JOIN "public"."RATE_Lanes" "lane" ON (("lane"."RATELane_ID" = "s"."RATESheet_LaneID")))
  WHERE ((("rl"."RATELine_StatusCode")::"text" = 'active'::"text") AND (("s"."RATESheet_StatusCode")::"text" = 'active'::"text") AND (("v"."RATEContractVer_StatusCode")::"text" = ANY ((ARRAY['active'::character varying, 'approved'::character varying])::"text"[])) AND (("c"."RATEContract_StatusCode")::"text" = ANY ((ARRAY['active'::character varying, 'approved'::character varying])::"text"[])) AND ("c"."RATEContract_IsDeleted" = false));


