CREATE OR REPLACE VIEW "public"."RATE_JobCostingLinkSummary" AS
 SELECT "jl"."RATEJobCostLink_ID",
    "jl"."RATEJobCostLink_RequestID",
    "req"."RATERequest_Code",
    "jl"."RATEJobCostLink_ResultID",
    "jl"."RATEJobCostLink_ResultLineID",
    "jl"."RATEJobCostLink_JobID",
    "job"."Job_Number",
    "jl"."RATEJobCostLink_ChargeInID",
    "jl"."RATEJobCostLink_ChargeOutID",
    "jl"."RATEJobCostLink_LinkType",
    "line"."RATEResultLine_ApplicabilityCode",
    "line"."RATEResultLine_ChargeCodeSnapshot",
    "line"."RATEResultLine_TotalAmount",
    "line"."RATEResultLine_CurrencyCodeSnapshot",
    "jl"."RATEJobCostLink_CreatedAt"
   FROM (((("public"."RATE_JobCostingLinks" "jl"
     LEFT JOIN "public"."RATE_RateRequests" "req" ON (("req"."RATERequest_ID" = "jl"."RATEJobCostLink_RequestID")))
     JOIN "public"."RATE_RateResults" "res" ON (("res"."RATEResult_ID" = "jl"."RATEJobCostLink_ResultID")))
     LEFT JOIN "public"."RATE_RateResultLines" "line" ON (("line"."RATEResultLine_ID" = "jl"."RATEJobCostLink_ResultLineID")))
     JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "jl"."RATEJobCostLink_JobID")));


