CREATE OR REPLACE VIEW "public"."RATE_TariffAssignmentSummary" AS
 SELECT "a"."RATETariffAssign_ID",
    "a"."RATETariffAssign_ContractID",
    "c"."RATEContract_Code",
    "c"."RATEContract_Name",
    "c"."RATEContract_TypeCode",
    "a"."RATETariffAssign_CustomerOrgID",
    "customer"."Org_Name" AS "CustomerName",
    "a"."RATETariffAssign_CarrierOrgID",
    "carrier"."Org_Name" AS "CarrierName",
    "a"."RATETariffAssign_OrgOfficeID",
    "office"."Office_Name" AS "OfficeName",
    "a"."RATETariffAssign_ModeCode",
    "a"."RATETariffAssign_LaneID",
    "lane"."RATELane_Name",
    "a"."RATETariffAssign_Priority",
    "a"."RATETariffAssign_ValidFrom",
    "a"."RATETariffAssign_ValidTo",
    "a"."RATETariffAssign_IsActive"
   FROM ((((("public"."RATE_TariffAssignments" "a"
     JOIN "public"."RATE_Contracts" "c" ON (("c"."RATEContract_ID" = "a"."RATETariffAssign_ContractID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "a"."RATETariffAssign_CustomerOrgID")))
     LEFT JOIN "public"."Org_Master" "carrier" ON (("carrier"."Org_id" = "a"."RATETariffAssign_CarrierOrgID")))
     LEFT JOIN "public"."cmp_Offices" "office" ON (("office"."Office_ID" = "a"."RATETariffAssign_OrgOfficeID")))
     LEFT JOIN "public"."RATE_Lanes" "lane" ON (("lane"."RATELane_ID" = "a"."RATETariffAssign_LaneID")));


