    "SECCred_VaultProvider" character varying(120) DEFAULT 'external_vault'::character varying NOT NULL,
    "SECCred_VaultPathRef" character varying(400) NOT NULL,
    "SECCred_SecretVersionRef" character varying(160),
    "SECCred_PublicFingerprint" character varying(240),
    "SECCred_ExpiresAt" timestamp with time zone,
