CREATE OR REPLACE VIEW "public"."SUB_EntitlementSummary" AS
 SELECT "e"."SUBEntitlement_ID" AS "EntitlementID",
    "env"."SUBEnv_Code" AS "EnvironmentCode",
    "s"."SUBSubscription_StatusCode" AS "SubscriptionStatusCode",
    "e"."SUBEntitlement_ModuleCode" AS "ModuleCode",
    "m"."SUBModule_Name" AS "ModuleName",
    "e"."SUBEntitlement_StatusCode" AS "EntitlementStatusCode",
    "e"."SUBEntitlement_IsEnabled" AS "IsEnabled",
    "e"."SUBEntitlement_UserLimit" AS "UserLimit",
    "e"."SUBEntitlement_RecordLimit" AS "RecordLimit"
   FROM ((("public"."SUB_ModuleEntitlements" "e"
     LEFT JOIN "public"."SUB_Subscriptions" "s" ON (("s"."SUBSubscription_ID" = "e"."SUBEntitlement_SubscriptionID")))
     LEFT JOIN "public"."SUB_ClientEnvironments" "env" ON (("env"."SUBEnv_ID" = "s"."SUBSubscription_EnvironmentID")))
     LEFT JOIN "public"."sys_SUBModuleCodes" "m" ON ((("m"."SUBModule_Code")::"text" = ("e"."SUBEntitlement_ModuleCode")::"text")));


