CREATE OR REPLACE VIEW "public"."T1_PrintSummary" AS
 SELECT "t"."T1_id",
    "t"."T1_JobID",
    "t"."T1_DeclarationType",
    "t"."T1_Status",
    "t"."T1_LRN",
    "t"."T1_MRN",
    "t"."T1_OrgOfficeID",
    "t"."T1_OfficeCodeSnapshot",
    "t"."T1_DepartureOfficeCode",
    "t"."T1_DestinationOfficeCode",
    "holder"."T1P_NameSnapshot" AS "T1_HolderNameSnapshot",
    "consignee"."T1P_NameSnapshot" AS "T1_ConsigneeNameSnapshot",
    COALESCE("items"."T1_ItemCount", 0) AS "T1_ItemCount",
    COALESCE("items"."T1_TotalGrossMass", (0)::numeric) AS "T1_TotalGrossMass",
    "t"."T1_TotalPackages",
    "t"."T1_iCustomsStatusSnapshot"
   FROM ((("public"."T1_Declarations" "t"
     LEFT JOIN LATERAL ( SELECT "p"."T1P_NameSnapshot"
           FROM "public"."T1_Parties" "p"
          WHERE (("p"."T1P_T1ID" = "t"."T1_id") AND (("p"."T1P_Role")::"text" = 'holder_transit'::"text"))
          ORDER BY "p"."T1P_SortOrder", "p"."T1P_CreatedAt"
         LIMIT 1) "holder" ON (true))
     LEFT JOIN LATERAL ( SELECT "p"."T1P_NameSnapshot"
           FROM "public"."T1_Parties" "p"
          WHERE (("p"."T1P_T1ID" = "t"."T1_id") AND (("p"."T1P_Role")::"text" = 'consignee'::"text"))
          ORDER BY "p"."T1P_SortOrder", "p"."T1P_CreatedAt"
         LIMIT 1) "consignee" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "T1_ItemCount",
            "sum"(COALESCE("i"."T1I_GrossMass", (0)::numeric)) AS "T1_TotalGrossMass"
           FROM "public"."T1_Items" "i"
          WHERE ("i"."T1I_T1ID" = "t"."T1_id")) "items" ON (true));


