CREATE OR REPLACE VIEW "public"."TCE_ComplianceDashboard" AS
 SELECT "run"."TCERun_OrgOfficeID",
    "run"."TCERun_RunTypeCode",
    "run"."TCERun_StatusCode",
    "run"."TCERun_HighestRiskLevelCode",
    ("date_trunc"('day'::"text", "run"."TCERun_TriggeredAt"))::"date" AS "TCE_Day",
    ("count"(DISTINCT "run"."TCERun_ID"))::integer AS "TCE_RunCount",
    ("count"(DISTINCT "subject"."TCESubject_ID"))::integer AS "TCE_SubjectCount",
    ("count"(DISTINCT "match"."TCEMatch_ID"))::integer AS "TCE_MatchCount",
    ("count"(DISTINCT "case_row"."TCECase_ID"))::integer AS "TCE_CaseCount",
    ("count"(DISTINCT "hold"."TCEHold_ID"))::integer AS "TCE_HoldCount",
    "max"("run"."TCERun_HighestScore") AS "TCE_MaxScore"
   FROM (((("public"."TCE_ScreeningRuns" "run"
     LEFT JOIN "public"."TCE_ScreeningSubjects" "subject" ON (("subject"."TCESubject_RunID" = "run"."TCERun_ID")))
     LEFT JOIN "public"."TCE_ScreeningMatches" "match" ON (("match"."TCEMatch_RunID" = "run"."TCERun_ID")))
     LEFT JOIN "public"."TCE_ComplianceCases" "case_row" ON (("case_row"."TCECase_RunID" = "run"."TCERun_ID")))
     LEFT JOIN "public"."TCE_ComplianceHolds" "hold" ON (("hold"."TCEHold_RunID" = "run"."TCERun_ID")))
  GROUP BY "run"."TCERun_OrgOfficeID", "run"."TCERun_RunTypeCode", "run"."TCERun_StatusCode", "run"."TCERun_HighestRiskLevelCode", (("date_trunc"('day'::"text", "run"."TCERun_TriggeredAt"))::"date");


ALTER VIEW "public"."TCE_ComplianceDashboard" OWNER TO "postgres";


