CREATE OR REPLACE VIEW "public"."TCE_IntegrationEventQueue" AS
 SELECT "event"."TCEEvent_ID",
    "event"."TCEEvent_StatusCode",
    "status"."TCEEventStatus_Name",
    "event"."TCEEvent_TouchpointTypeCode",
    "event"."TCEEvent_PolicyID",
    "event"."TCEEvent_JobID",
    "job"."Job_Number",
    "event"."TCEEvent_CustomerOrgID",
    "customer"."Org_Name" AS "TCEEvent_CustomerName",
    "event"."TCEEvent_OrgOfficeID",
    "event"."TCEEvent_SourceRecordTypeCode",
    "event"."TCEEvent_SourceTable",
    "event"."TCEEvent_SourceID",
    "event"."TCEEvent_EventKey",
    "event"."TCEEvent_RetryCount",
    "event"."TCEEvent_NextAttemptAt",
    "event"."TCEEvent_ProcessedAt",
    "event"."TCEEvent_CreatedAt"
   FROM ((("public"."TCE_IntegrationEvents" "event"
     LEFT JOIN "public"."sys_TCEEventStatuses" "status" ON ((("status"."TCEEventStatus_Code")::"text" = ("event"."TCEEvent_StatusCode")::"text")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "event"."TCEEvent_JobID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "event"."TCEEvent_CustomerOrgID")))
  WHERE (COALESCE("status"."TCEEventStatus_IsOpen", true) = true);


