CREATE OR REPLACE VIEW "public"."WMS_Dashboard" AS
 SELECT "f"."WMSFacility_ID",
    "f"."WMSFacility_Code",
    "f"."WMSFacility_Name",
    COALESCE("o"."OpenOrderCount", 0) AS "OpenOrderCount",
    COALESCE("t"."OpenTaskCount", 0) AS "OpenTaskCount",
    COALESCE("e"."OpenExceptionCount", 0) AS "OpenExceptionCount",
    COALESCE("h"."OpenHoldCount", 0) AS "OpenHoldCount",
    COALESCE("b"."TotalOnHandQuantity", (0)::numeric) AS "TotalOnHandQuantity",
    COALESCE("b"."TotalAvailableQuantity", (0)::numeric) AS "TotalAvailableQuantity",
    COALESCE("b"."TotalHeldQuantity", (0)::numeric) AS "TotalHeldQuantity"
   FROM ((((("public"."WMS_Facilities" "f"
     LEFT JOIN ( SELECT "WMS_Orders"."WMSOrder_FacilityID",
            ("count"(*))::integer AS "OpenOrderCount"
           FROM "public"."WMS_Orders"
          WHERE ((("WMS_Orders"."WMSOrder_StatusCode")::"text" <> ALL ((ARRAY['complete'::character varying, 'cancelled'::character varying])::"text"[])) AND ("WMS_Orders"."WMSOrder_IsDeleted" = false))
          GROUP BY "WMS_Orders"."WMSOrder_FacilityID") "o" ON (("o"."WMSOrder_FacilityID" = "f"."WMSFacility_ID")))
     LEFT JOIN ( SELECT "WMS_Tasks"."WMSTask_FacilityID",
            ("count"(*))::integer AS "OpenTaskCount"
           FROM "public"."WMS_Tasks"
          WHERE (("WMS_Tasks"."WMSTask_StatusCode")::"text" <> ALL ((ARRAY['complete'::character varying, 'cancelled'::character varying])::"text"[]))
          GROUP BY "WMS_Tasks"."WMSTask_FacilityID") "t" ON (("t"."WMSTask_FacilityID" = "f"."WMSFacility_ID")))
     LEFT JOIN ( SELECT "WMS_Exceptions"."WMSException_FacilityID",
            ("count"(*))::integer AS "OpenExceptionCount"
           FROM "public"."WMS_Exceptions"
          WHERE (("WMS_Exceptions"."WMSException_StatusCode")::"text" <> 'resolved'::"text")
          GROUP BY "WMS_Exceptions"."WMSException_FacilityID") "e" ON (("e"."WMSException_FacilityID" = "f"."WMSFacility_ID")))
     LEFT JOIN ( SELECT "WMS_InventoryHolds"."WMSHold_FacilityID",
            ("count"(*))::integer AS "OpenHoldCount"
           FROM "public"."WMS_InventoryHolds"
          WHERE (("WMS_InventoryHolds"."WMSHold_StatusCode")::"text" = 'open'::"text")
          GROUP BY "WMS_InventoryHolds"."WMSHold_FacilityID") "h" ON (("h"."WMSHold_FacilityID" = "f"."WMSFacility_ID")))
     LEFT JOIN ( SELECT "WMS_InventoryBalances"."WMSBalance_FacilityID",
            "sum"("WMS_InventoryBalances"."WMSBalance_OnHandQuantity") AS "TotalOnHandQuantity",
            "sum"("WMS_InventoryBalances"."WMSBalance_AvailableQuantity") AS "TotalAvailableQuantity",
            "sum"("WMS_InventoryBalances"."WMSBalance_HeldQuantity") AS "TotalHeldQuantity"
           FROM "public"."WMS_InventoryBalances"
          GROUP BY "WMS_InventoryBalances"."WMSBalance_FacilityID") "b" ON (("b"."WMSBalance_FacilityID" = "f"."WMSFacility_ID")));


ALTER VIEW "public"."WMS_Dashboard" OWNER TO "postgres";


