CREATE OR REPLACE VIEW "public"."WMS_InventorySummary" AS
 SELECT "b"."WMSBalance_ID",
    "b"."WMSBalance_FacilityID",
    "f"."WMSFacility_Code",
    "f"."WMSFacility_Name",
    "b"."WMSBalance_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "b"."WMSBalance_ItemID",
    "i"."WMSItem_SKU",
    "i"."WMSItem_Description",
    "b"."WMSBalance_LocationID",
    "l"."WMSLocation_Code",
    "b"."WMSBalance_LotID",
    "lot"."WMSLot_LotNumber",
    "b"."WMSBalance_HU_ID",
    "hu"."WMSHU_Code",
    "b"."WMSBalance_InventoryStatusCode",
    "b"."WMSBalance_CustomsStatusCode",
    "b"."WMSBalance_UOMCode",
    "b"."WMSBalance_OnHandQuantity",
    "b"."WMSBalance_ReservedQuantity",
    "b"."WMSBalance_AllocatedQuantity",
    "b"."WMSBalance_HeldQuantity",
    "b"."WMSBalance_AvailableQuantity",
    "b"."WMSBalance_IsBonded",
    "b"."WMSBalance_FirstReceiptAt",
    "b"."WMSBalance_LastMovementAt"
   FROM (((((("public"."WMS_InventoryBalances" "b"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "b"."WMSBalance_FacilityID")))
     JOIN "public"."WMS_Items" "i" ON (("i"."WMSItem_ID" = "b"."WMSBalance_ItemID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "b"."WMSBalance_CustomerOrgID")))
     LEFT JOIN "public"."WMS_Locations" "l" ON (("l"."WMSLocation_ID" = "b"."WMSBalance_LocationID")))
     LEFT JOIN "public"."WMS_InventoryLots" "lot" ON (("lot"."WMSLot_ID" = "b"."WMSBalance_LotID")))
     LEFT JOIN "public"."WMS_HandlingUnits" "hu" ON (("hu"."WMSHU_ID" = "b"."WMSBalance_HU_ID")));


