CREATE OR REPLACE VIEW "public"."WMS_TaskQueue" AS
 SELECT "t"."WMSTask_ID",
    "t"."WMSTask_FacilityID",
    "f"."WMSFacility_Name",
    "t"."WMSTask_TypeCode",
    "t"."WMSTask_StatusCode",
    "t"."WMSTask_PriorityCode",
    "t"."WMSTask_Title",
    "t"."WMSTask_OrderID",
    "o"."WMSOrder_OrderNumber",
    "t"."WMSTask_JobID",
    "t"."WMSTask_SourceLocationID",
    "sl"."WMSLocation_Code" AS "SourceLocationCode",
    "t"."WMSTask_TargetLocationID",
    "tl"."WMSLocation_Code" AS "TargetLocationCode",
    "t"."WMSTask_DueAt",
    "t"."WMSTask_CreatedAt"
   FROM (((("public"."WMS_Tasks" "t"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "t"."WMSTask_FacilityID")))
     LEFT JOIN "public"."WMS_Orders" "o" ON (("o"."WMSOrder_ID" = "t"."WMSTask_OrderID")))
     LEFT JOIN "public"."WMS_Locations" "sl" ON (("sl"."WMSLocation_ID" = "t"."WMSTask_SourceLocationID")))
     LEFT JOIN "public"."WMS_Locations" "tl" ON (("tl"."WMSLocation_ID" = "t"."WMSTask_TargetLocationID")))
  WHERE (("t"."WMSTask_StatusCode")::"text" <> ALL ((ARRAY['complete'::character varying, 'cancelled'::character varying])::"text"[]));


