    CONSTRAINT "Workflow_Handoffs_to_check" CHECK ((("WorkflowHandoff_ToUserID" IS NOT NULL) OR ("WorkflowHandoff_ToQueueID" IS NOT NULL) OR ("WorkflowHandoff_ToOrgOfficeID" IS NOT NULL)))
);


