CREATE OR REPLACE VIEW "public"."Workflow_HandoffSummary" AS
 SELECT "h"."WorkflowHandoff_ID",
    "h"."WorkflowHandoff_InstanceID",
    "h"."WorkflowHandoff_TaskID",
    "h"."WorkflowHandoff_RecordTypeCode",
    "h"."WorkflowHandoff_RecordID",
    "h"."WorkflowHandoff_StatusCode",
    "hs"."WorkflowHandoffStatus_IsOpen",
    "h"."WorkflowHandoff_Title",
    "h"."WorkflowHandoff_FromUserID",
    "fu"."User_Email" AS "WorkflowHandoff_FromUserEmail",
    "h"."WorkflowHandoff_FromQueueID",
    "fq"."WorkflowQueue_Name" AS "WorkflowHandoff_FromQueueName",
    "h"."WorkflowHandoff_FromOrgOfficeID",
    "fo"."Office_Name" AS "WorkflowHandoff_FromOfficeName",
    "h"."WorkflowHandoff_ToUserID",
    "tu"."User_Email" AS "WorkflowHandoff_ToUserEmail",
    "h"."WorkflowHandoff_ToQueueID",
    "tq"."WorkflowQueue_Name" AS "WorkflowHandoff_ToQueueName",
    "h"."WorkflowHandoff_ToOrgOfficeID",
    "too"."Office_Name" AS "WorkflowHandoff_ToOfficeName",
    "h"."WorkflowHandoff_OpenTaskCount",
    "h"."WorkflowHandoff_SentAt",
    "h"."WorkflowHandoff_AcceptedAt",
    "h"."WorkflowHandoff_RejectedAt",
    "h"."WorkflowHandoff_CreatedAt"
   FROM ((((((("public"."Workflow_Handoffs" "h"
     LEFT JOIN "public"."sys_WorkflowHandoffStatuses" "hs" ON ((("hs"."WorkflowHandoffStatus_Code")::"text" = ("h"."WorkflowHandoff_StatusCode")::"text")))
     LEFT JOIN "public"."cmp_Users" "fu" ON (("fu"."User_ID" = "h"."WorkflowHandoff_FromUserID")))
     LEFT JOIN "public"."Workflow_WorkQueues" "fq" ON (("fq"."WorkflowQueue_ID" = "h"."WorkflowHandoff_FromQueueID")))
     LEFT JOIN "public"."cmp_Offices" "fo" ON (("fo"."Office_ID" = "h"."WorkflowHandoff_FromOrgOfficeID")))
     LEFT JOIN "public"."cmp_Users" "tu" ON (("tu"."User_ID" = "h"."WorkflowHandoff_ToUserID")))
     LEFT JOIN "public"."Workflow_WorkQueues" "tq" ON (("tq"."WorkflowQueue_ID" = "h"."WorkflowHandoff_ToQueueID")))
     LEFT JOIN "public"."cmp_Offices" "too" ON (("too"."Office_ID" = "h"."WorkflowHandoff_ToOrgOfficeID")));


