CREATE OR REPLACE VIEW "public"."Audit_RetentionJobSummary" AS
 SELECT "j"."AuditRetentionJob_ID",
    "j"."AuditRetentionJob_StatusCode",
    "j"."AuditRetentionJob_RetentionClassCode",
    "j"."AuditRetentionJob_CutoffAt",
    "j"."AuditRetentionJob_Action",
    "j"."AuditRetentionJob_StartedAt",
    "j"."AuditRetentionJob_CompletedAt",
    "j"."AuditRetentionJob_ProcessedCount",
    "j"."AuditRetentionJob_ArchivedCount",
    "j"."AuditRetentionJob_DeletedCount",
    ("count"("i"."AuditRetentionJobItem_ID"))::integer AS "AuditRetentionJob_ItemCount",
    "j"."AuditRetentionJob_ErrorMessage",
    "j"."AuditRetentionJob_CreatedAt"
   FROM ("public"."Audit_RetentionJobs" "j"
     LEFT JOIN "public"."Audit_RetentionJobItems" "i" ON (("i"."AuditRetentionJobItem_JobID" = "j"."AuditRetentionJob_ID")))
  GROUP BY "j"."AuditRetentionJob_ID";



CREATE OR REPLACE VIEW "public"."CLM_ClaimFinancialSummary" AS
 SELECT "claim"."CLMClaim_ID",
    "claim"."CLMClaim_Number",
    "claim"."CLMClaim_StatusCode",
    "claim"."CLMClaim_CurrencyCodeSnapshot",
    "claim"."CLMClaim_ClaimedAmount",
    (COALESCE("sum"("line"."CLMClaimLine_ClaimedAmount"), (0)::numeric))::numeric(18,4) AS "CLMClaim_LineClaimedAmount",
    "claim"."CLMClaim_ReserveAmount",
    "claim"."CLMClaim_ExpenseReserveAmount",
    "claim"."CLMClaim_DeductibleAmount",
    "claim"."CLMClaim_SettlementAmount",
    "claim"."CLMClaim_RecoveryExpectedAmount",
    "claim"."CLMClaim_RecoveryReceivedAmount",
    (COALESCE("sum"("fin"."CLMFinLink_Amount") FILTER (WHERE (("fin"."CLMFinLink_LinkTypeCode")::"text" = ANY ((ARRAY['customer_credit'::character varying, 'settlement_payment'::character varying])::"text"[]))), (0)::numeric))::numeric(18,4) AS "CLMClaim_LinkedSettlementAmount",
    (COALESCE("sum"("fin"."CLMFinLink_Amount") FILTER (WHERE (("fin"."CLMFinLink_LinkTypeCode")::"text" = ANY ((ARRAY['insurer_recovery'::character varying, 'carrier_recovery'::character varying, 'supplier_debit'::character varying])::"text"[]))), (0)::numeric))::numeric(18,4) AS "CLMClaim_LinkedRecoveryAmount",
    ((("claim"."CLMClaim_ClaimedAmount" - "claim"."CLMClaim_SettlementAmount") - "claim"."CLMClaim_RecoveryReceivedAmount"))::numeric(18,4) AS "CLMClaim_NetExposureAmount"
   FROM (("public"."CLM_Claims" "claim"
     LEFT JOIN "public"."CLM_ClaimLines" "line" ON (("line"."CLMClaimLine_ClaimID" = "claim"."CLMClaim_ID")))
     LEFT JOIN "public"."CLM_ClaimFinancialLinks" "fin" ON (("fin"."CLMFinLink_ClaimID" = "claim"."CLMClaim_ID")))
  GROUP BY "claim"."CLMClaim_ID";



CREATE OR REPLACE VIEW "public"."CLM_ClaimWorklist" AS
 SELECT "claim"."CLMClaim_ID",
    "claim"."CLMClaim_Number",
    "claim"."CLMClaim_Title",
    "claim"."CLMClaim_IncidentID",
    "incident"."CLMIncident_Number",
    "claim"."CLMClaim_JobID",
    "job"."Job_Number",
    "claim"."CLMClaim_CustomerOrgID",
    "customer"."Org_Name" AS "CLMClaim_CustomerName",
    "claim"."CLMClaim_OrgOfficeID",
    "claim"."CLMClaim_TypeCode",
    "ctype"."CLMClaimType_Name",
    "claim"."CLMClaim_StatusCode",
    "cstatus"."CLMClaimStatus_Name",
    "cstatus"."CLMClaimStatus_IsOpen",
    "claim"."CLMClaim_LiabilityStatusCode",
    "liability"."CLMLiabilityStatus_Name",
    "claim"."CLMClaim_CurrencyCodeSnapshot",
    "claim"."CLMClaim_ClaimedAmount",
    "claim"."CLMClaim_ReserveAmount",
    "claim"."CLMClaim_ExpenseReserveAmount",
    "claim"."CLMClaim_RecoveryExpectedAmount",
    "claim"."CLMClaim_RecoveryReceivedAmount",
    "claim"."CLMClaim_SettlementAmount",
    "claim"."CLMClaim_LimitationDate",
    "claim"."CLMClaim_OwnerUserID",
    "claim"."CLMClaim_CreatedAt",
    ("count"(DISTINCT "evidence"."CLMEvidence_ID"))::integer AS "CLMClaim_EvidenceCount",
    ("count"(DISTINCT "task"."CLMTask_ID") FILTER (WHERE (("task"."CLMTask_StatusCode")::"text" <> 'completed'::"text")))::integer AS "CLMClaim_OpenTaskCount"
   FROM (((((((("public"."CLM_Claims" "claim"
     LEFT JOIN "public"."CLM_Incidents" "incident" ON (("incident"."CLMIncident_ID" = "claim"."CLMClaim_IncidentID")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "claim"."CLMClaim_JobID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "claim"."CLMClaim_CustomerOrgID")))
     LEFT JOIN "public"."sys_CLMClaimTypes" "ctype" ON ((("ctype"."CLMClaimType_Code")::"text" = ("claim"."CLMClaim_TypeCode")::"text")))
     LEFT JOIN "public"."sys_CLMClaimStatuses" "cstatus" ON ((("cstatus"."CLMClaimStatus_Code")::"text" = ("claim"."CLMClaim_StatusCode")::"text")))
     LEFT JOIN "public"."sys_CLMLiabilityStatuses" "liability" ON ((("liability"."CLMLiabilityStatus_Code")::"text" = ("claim"."CLMClaim_LiabilityStatusCode")::"text")))
     LEFT JOIN "public"."CLM_EvidenceItems" "evidence" ON (("evidence"."CLMEvidence_ClaimID" = "claim"."CLMClaim_ID")))
     LEFT JOIN "public"."CLM_ClaimTasks" "task" ON (("task"."CLMTask_ClaimID" = "claim"."CLMClaim_ID")))
  GROUP BY "claim"."CLMClaim_ID", "incident"."CLMIncident_Number", "job"."Job_Number", "customer"."Org_Name", "ctype"."CLMClaimType_Name", "cstatus"."CLMClaimStatus_Name", "cstatus"."CLMClaimStatus_IsOpen", "liability"."CLMLiabilityStatus_Name";



CREATE OR REPLACE VIEW "public"."CLM_IncidentWorklist" AS
 SELECT "inc"."CLMIncident_ID",
    "inc"."CLMIncident_Number",
    "inc"."CLMIncident_Title",
    "inc"."CLMIncident_JobID",
    "job"."Job_Number",
    "inc"."CLMIncident_CustomerOrgID",
    "customer"."Org_Name" AS "CLMIncident_CustomerName",
    "inc"."CLMIncident_OrgOfficeID",
    "inc"."CLMIncident_TypeCode",
    "itype"."CLMIncidentType_Name",
    "inc"."CLMIncident_StatusCode",
    "istatus"."CLMIncidentStatus_Name",
    "inc"."CLMIncident_SeverityCode",
    "sev"."CLMSeverity_Name",
    "sev"."CLMSeverity_Weight",
    "inc"."CLMIncident_ReportedAt",
    "inc"."CLMIncident_OccurredAt",
    "inc"."CLMIncident_OwnerUserID",
    "inc"."CLMIncident_PotentialClaimAmount",
    "inc"."CLMIncident_EstimatedLossAmount",
    "inc"."CLMIncident_CurrencyCodeSnapshot",
    "inc"."CLMIncident_HasClaim",
    ("count"(DISTINCT "evidence"."CLMEvidence_ID"))::integer AS "CLMIncident_EvidenceCount",
    ("count"(DISTINCT "claim"."CLMClaim_ID"))::integer AS "CLMIncident_ClaimCount"
   FROM ((((((("public"."CLM_Incidents" "inc"
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "inc"."CLMIncident_JobID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "inc"."CLMIncident_CustomerOrgID")))
     LEFT JOIN "public"."sys_CLMIncidentTypes" "itype" ON ((("itype"."CLMIncidentType_Code")::"text" = ("inc"."CLMIncident_TypeCode")::"text")))
     LEFT JOIN "public"."sys_CLMIncidentStatuses" "istatus" ON ((("istatus"."CLMIncidentStatus_Code")::"text" = ("inc"."CLMIncident_StatusCode")::"text")))
     LEFT JOIN "public"."sys_CLMSeverityLevels" "sev" ON ((("sev"."CLMSeverity_Code")::"text" = ("inc"."CLMIncident_SeverityCode")::"text")))
     LEFT JOIN "public"."CLM_EvidenceItems" "evidence" ON (("evidence"."CLMEvidence_IncidentID" = "inc"."CLMIncident_ID")))
     LEFT JOIN "public"."CLM_Claims" "claim" ON (("claim"."CLMClaim_IncidentID" = "inc"."CLMIncident_ID")))
  GROUP BY "inc"."CLMIncident_ID", "job"."Job_Number", "customer"."Org_Name", "itype"."CLMIncidentType_Name", "istatus"."CLMIncidentStatus_Name", "sev"."CLMSeverity_Name", "sev"."CLMSeverity_Weight";



CREATE OR REPLACE VIEW "public"."CLM_InsurancePolicySummary" AS
 SELECT "policy"."CLMPolicy_ID",
    "policy"."CLMPolicy_Number",
    "policy"."CLMPolicy_Name",
    "policy"."CLMPolicy_TypeCode",
    "ptype"."CLMPolicyType_Name",
    "policy"."CLMPolicy_StatusCode",
    "pstatus"."CLMPolicyStatus_Name",
    "policy"."CLMPolicy_OrgOfficeID",
    "policy"."CLMPolicy_LegalEntityID",
    "policy"."CLMPolicy_InsurerOrgID",
    "insurer"."Org_Name" AS "CLMPolicy_InsurerName",
    "policy"."CLMPolicy_BrokerOrgID",
    "broker"."Org_Name" AS "CLMPolicy_BrokerName",
    "policy"."CLMPolicy_CurrencyCodeSnapshot",
    "policy"."CLMPolicy_PerClaimLimitAmount",
    "policy"."CLMPolicy_AggregateLimitAmount",
    "policy"."CLMPolicy_DeductibleAmount",
    "policy"."CLMPolicy_InceptionDate",
    "policy"."CLMPolicy_ExpiryDate",
    "policy"."CLMPolicy_RenewalNoticeDate",
    ("count"(DISTINCT "cover"."CLMCover_ID"))::integer AS "CLMPolicy_CoverageCount",
    ("count"(DISTINCT "claim"."CLMClaim_ID") FILTER (WHERE ("cstatus"."CLMClaimStatus_IsOpen" = true)))::integer AS "CLMPolicy_OpenClaimCount"
   FROM ((((((("public"."CLM_InsurancePolicies" "policy"
     LEFT JOIN "public"."sys_CLMPolicyTypes" "ptype" ON ((("ptype"."CLMPolicyType_Code")::"text" = ("policy"."CLMPolicy_TypeCode")::"text")))
     LEFT JOIN "public"."sys_CLMPolicyStatuses" "pstatus" ON ((("pstatus"."CLMPolicyStatus_Code")::"text" = ("policy"."CLMPolicy_StatusCode")::"text")))
     LEFT JOIN "public"."Org_Master" "insurer" ON (("insurer"."Org_id" = "policy"."CLMPolicy_InsurerOrgID")))
     LEFT JOIN "public"."Org_Master" "broker" ON (("broker"."Org_id" = "policy"."CLMPolicy_BrokerOrgID")))
     LEFT JOIN "public"."CLM_PolicyCoverages" "cover" ON ((("cover"."CLMCover_PolicyID" = "policy"."CLMPolicy_ID") AND ("cover"."CLMCover_IsActive" = true))))
     LEFT JOIN "public"."CLM_Claims" "claim" ON (("claim"."CLMClaim_PolicyID" = "policy"."CLMPolicy_ID")))
     LEFT JOIN "public"."sys_CLMClaimStatuses" "cstatus" ON (((("cstatus"."CLMClaimStatus_Code")::"text" = ("claim"."CLMClaim_StatusCode")::"text") AND ("cstatus"."CLMClaimStatus_IsOpen" = true))))
  GROUP BY "policy"."CLMPolicy_ID", "ptype"."CLMPolicyType_Name", "pstatus"."CLMPolicyStatus_Name", "insurer"."Org_Name", "broker"."Org_Name";



CREATE OR REPLACE VIEW "public"."CRM_AccountSalesSummary" AS
 SELECT "ap"."CRMAccount_ID",
    "ap"."CRMAccount_OrgID",
    "org"."Org_Name" AS "CRMAccount_OrgName",
    "ap"."CRMAccount_RelationshipStatusCode",
    "ap"."CRMAccount_OwnerUserID",
    "owner"."User_Email" AS "CRMAccount_OwnerEmail",
    "ap"."CRMAccount_OrgOfficeID",
    "ap"."CRMAccount_Tier",
    "ap"."CRMAccount_Segment",
    "ap"."CRMAccount_Vertical",
    "ap"."CRMAccount_HealthScore",
    "ap"."CRMAccount_ChurnRiskScore",
    "count"(DISTINCT "lead"."CRMLead_ID") AS "CRMAccount_OpenLeadCount",
    "count"(DISTINCT "oppty"."CRMOppty_ID") FILTER (WHERE (("oppty"."CRMOppty_StatusCode")::"text" = ANY ((ARRAY['open'::character varying, 'on_hold'::character varying, 'dormant'::character varying])::"text"[]))) AS "CRMAccount_OpenOpportunityCount",
    "count"(DISTINCT "qf"."CRMQF_ID") FILTER (WHERE ("qfs"."CRMQFStatus_IsOpen" = true)) AS "CRMAccount_OpenQuoteFollowupCount",
    "max"("act"."CRMActivity_ActivityAt") AS "CRMAccount_LastActivityAt",
    "min"("qf"."CRMQF_NextActionDueAt") FILTER (WHERE ("qfs"."CRMQFStatus_IsOpen" = true)) AS "CRMAccount_NextQuoteActionDueAt"
   FROM ((((((("public"."CRM_AccountProfiles" "ap"
     JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "ap"."CRMAccount_OrgID")))
     LEFT JOIN "public"."cmp_Users" "owner" ON (("owner"."User_ID" = "ap"."CRMAccount_OwnerUserID")))
     LEFT JOIN "public"."CRM_Leads" "lead" ON ((("lead"."CRMLead_OrgID" = "ap"."CRMAccount_OrgID") AND ("lead"."CRMLead_IsDeleted" = false))))
     LEFT JOIN "public"."CRM_Opportunities" "oppty" ON ((("oppty"."CRMOppty_AccountID" = "ap"."CRMAccount_ID") AND ("oppty"."CRMOppty_IsDeleted" = false))))
     LEFT JOIN "public"."CRM_QuoteFollowups" "qf" ON ((("qf"."CRMQF_CustomerOrgID" = "ap"."CRMAccount_OrgID") AND ("qf"."CRMQF_IsDeleted" = false))))
     LEFT JOIN "public"."sys_CRMQuoteFollowupStatuses" "qfs" ON ((("qfs"."CRMQFStatus_Code")::"text" = ("qf"."CRMQF_StatusCode")::"text")))
     LEFT JOIN "public"."CRM_Activities" "act" ON ((("act"."CRMActivity_AccountID" = "ap"."CRMAccount_ID") AND ("act"."CRMActivity_IsDeleted" = false))))
  WHERE ("ap"."CRMAccount_IsDeleted" = false)
  GROUP BY "ap"."CRMAccount_ID", "org"."Org_Name", "owner"."User_Email";



CREATE OR REPLACE VIEW "public"."CRM_ActivityWorkflowRunSummary" AS
 SELECT "run"."CRMAWRun_ID",
    "run"."CRMAWRun_TriggerTypeCode",
    "trig"."CRMActTrig_Name",
    "run"."CRMAWRun_SourceTable",
    "run"."CRMAWRun_SourceID",
    "run"."CRMAWRun_CustomerOrgID",
    "org"."Org_Name" AS "CRMAWRun_CustomerName",
    "run"."CRMAWRun_OwnerUserID",
    "userx"."User_Email" AS "CRMAWRun_OwnerEmail",
    "run"."CRMAWRun_StatusCode",
    "run"."CRMAWRun_GeneratedQuickTaskCount",
    "run"."CRMAWRun_GeneratedMessageDraftCount",
    "count"("qt"."CRMQuickTask_ID") AS "CRMAWRun_QuickTaskCount",
    "count"("msg"."CRMPMsg_ID") AS "CRMAWRun_MessageDraftCount",
    "run"."CRMAWRun_CreatedAt"
   FROM ((((("public"."CRM_ActivityWorkflowRuns" "run"
     LEFT JOIN "public"."sys_CRMActivityTriggerTypes" "trig" ON ((("trig"."CRMActTrig_Code")::"text" = ("run"."CRMAWRun_TriggerTypeCode")::"text")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "run"."CRMAWRun_CustomerOrgID")))
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "run"."CRMAWRun_OwnerUserID")))
     LEFT JOIN "public"."CRM_QuickTasks" "qt" ON (("qt"."CRMQuickTask_RunID" = "run"."CRMAWRun_ID")))
     LEFT JOIN "public"."CRM_PersonalMessageDrafts" "msg" ON (("msg"."CRMPMsg_RunID" = "run"."CRMAWRun_ID")))
  GROUP BY "run"."CRMAWRun_ID", "trig"."CRMActTrig_Name", "org"."Org_Name", "userx"."User_Email";



CREATE OR REPLACE VIEW "public"."CRM_AutomationActionQueue" AS
 SELECT "run"."CRMAutoRun_ID",
    "run"."CRMAutoRun_StatusCode",
    "pb"."CRMAutoPlaybook_Code",
    "pb"."CRMAutoPlaybook_Name",
    "pb"."CRMAutoPlaybook_ActionTypeCode",
    "run"."CRMAutoRun_AssignedUserID",
    "userx"."User_Email" AS "CRMAutoRun_AssignedUserEmail",
    "run"."CRMAutoRun_CustomerOrgID",
    "org"."Org_Name" AS "CRMAutoRun_CustomerName",
    "run"."CRMAutoRun_TargetTable",
    "run"."CRMAutoRun_TargetID",
    "run"."CRMAutoRun_QuickTaskID",
    "run"."CRMAutoRun_JobID",
    "count"(DISTINCT "req"."CRMDataReq_ID") AS "CRMAutoRun_DataRequestCount",
    "count"(DISTINCT "upd"."CRMFieldUpdate_ID") FILTER (WHERE (("upd"."CRMFieldUpdate_StatusCode")::"text" = ANY ((ARRAY['pending'::character varying, 'ready'::character varying, 'needs_review'::character varying, 'approved'::character varying])::"text"[]))) AS "CRMAutoRun_OpenFieldUpdateCount",
    "run"."CRMAutoRun_StartedAt"
   FROM (((((("public"."CRM_AutomationRuns" "run"
     JOIN "public"."CRM_AutomationPlaybooks" "pb" ON (("pb"."CRMAutoPlaybook_ID" = "run"."CRMAutoRun_PlaybookID")))
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "run"."CRMAutoRun_AssignedUserID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "run"."CRMAutoRun_CustomerOrgID")))
     LEFT JOIN "public"."CRM_DataRequests" "req" ON (("req"."CRMDataReq_RunID" = "run"."CRMAutoRun_ID")))
     LEFT JOIN "public"."CRM_FieldUpdateQueue" "upd" ON (("upd"."CRMFieldUpdate_RunID" = "run"."CRMAutoRun_ID")))
     LEFT JOIN "public"."sys_CRMAutomationRunStatuses" "status" ON ((("status"."CRMAutoRunStatus_Code")::"text" = ("run"."CRMAutoRun_StatusCode")::"text")))
  WHERE ("status"."CRMAutoRunStatus_IsOpen" = true)
  GROUP BY "run"."CRMAutoRun_ID", "pb"."CRMAutoPlaybook_ID", "userx"."User_Email", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."CRM_AutomationPlaybookSummary" AS
 SELECT "pb"."CRMAutoPlaybook_ID",
    "pb"."CRMAutoPlaybook_Code",
    "pb"."CRMAutoPlaybook_Name",
    "pb"."CRMAutoPlaybook_ActionTypeCode",
    "action"."CRMAutoActionType_Name",
    "pb"."CRMAutoPlaybook_TriggerTypeCode",
    "pb"."CRMAutoPlaybook_TargetRecordTypeCode",
    "pb"."CRMAutoPlaybook_TargetTable",
    "pb"."CRMAutoPlaybook_RequiresWizard",
    "pb"."CRMAutoPlaybook_RequiresExternalRequest",
    "pb"."CRMAutoPlaybook_AutoApplyAllowed",
    "pb"."CRMAutoPlaybook_RequireApprovalBeforeApply",
    "count"(DISTINCT "field"."CRMAutoField_ID") AS "CRMAutoPlaybook_FieldCount",
    "count"(DISTINCT "step"."CRMAutoStep_ID") AS "CRMAutoPlaybook_StepCount",
    "pb"."CRMAutoPlaybook_IsActive"
   FROM ((("public"."CRM_AutomationPlaybooks" "pb"
     LEFT JOIN "public"."sys_CRMAutomationActionTypes" "action" ON ((("action"."CRMAutoActionType_Code")::"text" = ("pb"."CRMAutoPlaybook_ActionTypeCode")::"text")))
     LEFT JOIN "public"."CRM_AutomationFieldDefinitions" "field" ON (("field"."CRMAutoField_PlaybookID" = "pb"."CRMAutoPlaybook_ID")))
     LEFT JOIN "public"."CRM_AutomationPlaybookSteps" "step" ON (("step"."CRMAutoStep_PlaybookID" = "pb"."CRMAutoPlaybook_ID")))
  GROUP BY "pb"."CRMAutoPlaybook_ID", "action"."CRMAutoActionType_Name";



CREATE OR REPLACE VIEW "public"."CRM_BookingEngagementQueue" AS
 SELECT "qt"."CRMQuickTask_ID",
    "qt"."CRMQuickTask_JobID",
    "job"."Job_Number",
    "qt"."CRMQuickTask_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "qt"."CRMQuickTask_AssignedUserID",
    "qt"."CRMQuickTask_Title",
    "qt"."CRMQuickTask_DueAt",
    "count"("msg"."CRMPMsg_ID") AS "DraftCount",
    "count"("opt"."CRMQuickOpt_ID") AS "OptionCount"
   FROM (((("public"."CRM_QuickTasks" "qt"
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "qt"."CRMQuickTask_JobID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "qt"."CRMQuickTask_CustomerOrgID")))
     LEFT JOIN "public"."CRM_PersonalMessageDrafts" "msg" ON (("msg"."CRMPMsg_QuickTaskID" = "qt"."CRMQuickTask_ID")))
     LEFT JOIN "public"."CRM_QuickTaskOptions" "opt" ON (("opt"."CRMQuickOpt_QuickTaskID" = "qt"."CRMQuickTask_ID")))
  WHERE ((("qt"."CRMQuickTask_TaskTypeCode")::"text" = ANY ((ARRAY['send_personal_booking_thanks'::character varying, 'confirm_booking_details'::character varying])::"text"[])) AND (("qt"."CRMQuickTask_StatusCode")::"text" = ANY ((ARRAY['pending'::character varying, 'in_progress'::character varying, 'snoozed'::character varying])::"text"[])))
  GROUP BY "qt"."CRMQuickTask_ID", "job"."Job_Number", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."CRM_CallReviewTodoQueue" AS
 SELECT "qt"."CRMQuickTask_ID",
    "qt"."CRMQuickTask_CallReviewID",
    "cr"."CRMCallReview_CommCallID",
    "call"."CommCall_ProviderCallID",
    "call"."CommCall_StartedAt",
    "call"."CommCall_AISummary",
    "cr"."CRMCallReview_AISummary",
    "qt"."CRMQuickTask_AssignedUserID",
    "qt"."CRMQuickTask_Title",
    "qt"."CRMQuickTask_DueAt",
    "count"("opt"."CRMQuickOpt_ID") AS "OptionCount"
   FROM ((("public"."CRM_QuickTasks" "qt"
     LEFT JOIN "public"."CRM_CallReviews" "cr" ON (("cr"."CRMCallReview_ID" = "qt"."CRMQuickTask_CallReviewID")))
     LEFT JOIN "public"."Comm_CallLogs" "call" ON (("call"."CommCall_ID" = "cr"."CRMCallReview_CommCallID")))
     LEFT JOIN "public"."CRM_QuickTaskOptions" "opt" ON (("opt"."CRMQuickOpt_QuickTaskID" = "qt"."CRMQuickTask_ID")))
  WHERE ((("qt"."CRMQuickTask_TaskTypeCode")::"text" = 'review_call_summary'::"text") AND (("qt"."CRMQuickTask_StatusCode")::"text" = ANY ((ARRAY['pending'::character varying, 'in_progress'::character varying, 'snoozed'::character varying])::"text"[])))
  GROUP BY "qt"."CRMQuickTask_ID", "cr"."CRMCallReview_ID", "call"."CommCall_ID";



CREATE OR REPLACE VIEW "public"."CRM_DataCaptureWizardQueue" AS
 SELECT "sess"."CRMDataCapSession_ID",
    "sess"."CRMDataCapSession_RunID",
    "run"."CRMAutoRun_AssignedUserID",
    "pb"."CRMAutoPlaybook_Code",
    "pb"."CRMAutoPlaybook_Name",
    "run"."CRMAutoRun_TargetTable",
    "run"."CRMAutoRun_TargetID",
    "run"."CRMAutoRun_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "sess"."CRMDataCapSession_StatusCode",
    "count"("field"."CRMAutoField_ID") AS "FieldCount",
    "count"("resp"."CRMDataCapResp_ID") AS "CapturedCount",
    "sess"."CRMDataCapSession_StartedAt"
   FROM ((((("public"."CRM_DataCaptureSessions" "sess"
     JOIN "public"."CRM_AutomationRuns" "run" ON (("run"."CRMAutoRun_ID" = "sess"."CRMDataCapSession_RunID")))
     JOIN "public"."CRM_AutomationPlaybooks" "pb" ON (("pb"."CRMAutoPlaybook_ID" = "run"."CRMAutoRun_PlaybookID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "run"."CRMAutoRun_CustomerOrgID")))
     LEFT JOIN "public"."CRM_AutomationFieldDefinitions" "field" ON ((("field"."CRMAutoField_PlaybookID" = "pb"."CRMAutoPlaybook_ID") AND ("field"."CRMAutoField_IsActive" = true))))
     LEFT JOIN "public"."CRM_DataCaptureResponses" "resp" ON ((("resp"."CRMDataCapResp_SessionID" = "sess"."CRMDataCapSession_ID") AND ("resp"."CRMDataCapResp_FieldDefID" = "field"."CRMAutoField_ID"))))
  GROUP BY "sess"."CRMDataCapSession_ID", "run"."CRMAutoRun_ID", "pb"."CRMAutoPlaybook_ID", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."CRM_DataRequestQueue" AS
 SELECT "req"."CRMDataReq_ID",
    "req"."CRMDataReq_RunID",
    "req"."CRMDataReq_StatusCode",
    "req"."CRMDataReq_MethodCode",
    "req"."CRMDataReq_ChannelCode",
    "req"."CRMDataReq_CustomerOrgID",
    "org"."Org_Name" AS "CRMDataReq_CustomerName",
    "req"."CRMDataReq_AssignedUserID",
    "userx"."User_Email" AS "CRMDataReq_AssignedUserEmail",
    "req"."CRMDataReq_Subject",
    "req"."CRMDataReq_RequestText",
    "req"."CRMDataReq_DueAt",
    "count"("field"."CRMDataReqField_ID") AS "CRMDataReq_FieldCount",
    "count"("field"."CRMDataReqField_ID") FILTER (WHERE (("field"."CRMDataReqField_StatusCode")::"text" = 'received'::"text")) AS "CRMDataReq_ReceivedFieldCount",
    "req"."CRMDataReq_CreatedAt"
   FROM (((("public"."CRM_DataRequests" "req"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "req"."CRMDataReq_CustomerOrgID")))
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "req"."CRMDataReq_AssignedUserID")))
     LEFT JOIN "public"."CRM_DataRequestFields" "field" ON (("field"."CRMDataReqField_RequestID" = "req"."CRMDataReq_ID")))
     LEFT JOIN "public"."sys_CRMDataRequestStatuses" "status" ON ((("status"."CRMDataReqStatus_Code")::"text" = ("req"."CRMDataReq_StatusCode")::"text")))
  WHERE ("status"."CRMDataReqStatus_IsOpen" = true)
  GROUP BY "req"."CRMDataReq_ID", "org"."Org_Name", "userx"."User_Email";



CREATE OR REPLACE VIEW "public"."CRM_DataRequestResponseSummary" AS
 SELECT "req"."CRMDataReq_ID",
    "req"."CRMDataReq_StatusCode",
    "req"."CRMDataReq_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "req"."CRMDataReq_ChannelCode",
    "count"(DISTINCT "field"."CRMDataReqField_ID") AS "RequestedFieldCount",
    "count"(DISTINCT "field"."CRMDataReqField_ID") FILTER (WHERE (("field"."CRMDataReqField_StatusCode")::"text" = 'received'::"text")) AS "ReceivedFieldCount",
    "count"(DISTINCT "resp"."CRMDataReqResp_ID") AS "ResponseCount",
    "count"(DISTINCT "upd"."CRMFieldUpdate_ID") AS "FieldUpdateCount",
    "count"(DISTINCT "upd"."CRMFieldUpdate_ID") FILTER (WHERE (("upd"."CRMFieldUpdate_StatusCode")::"text" = 'applied'::"text")) AS "AppliedFieldUpdateCount",
    "max"("resp"."CRMDataReqResp_ReceivedAt") AS "LastResponseAt"
   FROM (((("public"."CRM_DataRequests" "req"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "req"."CRMDataReq_CustomerOrgID")))
     LEFT JOIN "public"."CRM_DataRequestFields" "field" ON (("field"."CRMDataReqField_RequestID" = "req"."CRMDataReq_ID")))
     LEFT JOIN "public"."CRM_DataRequestResponses" "resp" ON (("resp"."CRMDataReqResp_RequestID" = "req"."CRMDataReq_ID")))
     LEFT JOIN "public"."CRM_FieldUpdateQueue" "upd" ON (("upd"."CRMFieldUpdate_DataRequestID" = "req"."CRMDataReq_ID")))
  GROUP BY "req"."CRMDataReq_ID", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."CRM_OnboardingWorklist" AS
 SELECT "run"."CRMOnboardRun_ID",
    "run"."CRMOnboardRun_AccountID",
    "org"."Org_Name" AS "CRMOnboardRun_AccountName",
    "run"."CRMOnboardRun_OpportunityID",
    "oppty"."CRMOppty_Name",
    "run"."CRMOnboardRun_StatusCode",
    "status"."CRMOnboardStatus_Name",
    "run"."CRMOnboardRun_OwnerUserID",
    "owner"."User_Email" AS "CRMOnboardRun_OwnerEmail",
    "run"."CRMOnboardRun_StartedAt",
    "run"."CRMOnboardRun_TargetCompleteAt",
    "count"("task"."CRMOnboardTask_ID") AS "CRMOnboardRun_TaskCount",
    "count"("task"."CRMOnboardTask_ID") FILTER (WHERE ("task"."CRMOnboardTask_CompletedAt" IS NOT NULL)) AS "CRMOnboardRun_CompletedTaskCount",
    "min"("task"."CRMOnboardTask_DueAt") FILTER (WHERE ("task"."CRMOnboardTask_CompletedAt" IS NULL)) AS "CRMOnboardRun_NextTaskDueAt"
   FROM (((((("public"."CRM_OnboardingRuns" "run"
     JOIN "public"."CRM_AccountProfiles" "ap" ON (("ap"."CRMAccount_ID" = "run"."CRMOnboardRun_AccountID")))
     JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "ap"."CRMAccount_OrgID")))
     LEFT JOIN "public"."CRM_Opportunities" "oppty" ON (("oppty"."CRMOppty_ID" = "run"."CRMOnboardRun_OpportunityID")))
     LEFT JOIN "public"."sys_CRMOnboardingStatuses" "status" ON ((("status"."CRMOnboardStatus_Code")::"text" = ("run"."CRMOnboardRun_StatusCode")::"text")))
     LEFT JOIN "public"."cmp_Users" "owner" ON (("owner"."User_ID" = "run"."CRMOnboardRun_OwnerUserID")))
     LEFT JOIN "public"."CRM_OnboardingTasks" "task" ON (("task"."CRMOnboardTask_RunID" = "run"."CRMOnboardRun_ID")))
  WHERE ("status"."CRMOnboardStatus_IsOpen" = true)
  GROUP BY "run"."CRMOnboardRun_ID", "org"."Org_Name", "oppty"."CRMOppty_Name", "status"."CRMOnboardStatus_Name", "owner"."User_Email";



CREATE OR REPLACE VIEW "public"."CRM_PipelineSummary" AS
 SELECT "oppty"."CRMOppty_ID",
    "oppty"."CRMOppty_Name",
    "oppty"."CRMOppty_OrgID",
    "org"."Org_Name" AS "CRMOppty_OrgName",
    "oppty"."CRMOppty_AccountID",
    "oppty"."CRMOppty_OwnerUserID",
    "owner"."User_Email" AS "CRMOppty_OwnerEmail",
    "oppty"."CRMOppty_OrgOfficeID",
    "office"."Office_Name" AS "CRMOppty_OfficeName",
    "oppty"."CRMOppty_TypeCode",
    "oppty"."CRMOppty_StageCode",
    "stage"."CRMStage_Name" AS "CRMOppty_StageName",
    "oppty"."CRMOppty_StatusCode",
    "oppty"."CRMOppty_ForecastCategoryCode",
    "oppty"."CRMOppty_ModeCode",
    "oppty"."CRMOppty_TradeLane",
    "oppty"."CRMOppty_ExpectedCloseDate",
    "oppty"."CRMOppty_ProbabilityPct",
    "oppty"."CRMOppty_ExpectedValueAmount",
    "oppty"."CRMOppty_ExpectedMarginAmount",
    "oppty"."CRMOppty_CurrencyCode",
    COALESCE("oppty"."CRMOppty_WeightedValueAmount", (("oppty"."CRMOppty_ExpectedValueAmount" * COALESCE("oppty"."CRMOppty_ProbabilityPct", "stage"."CRMStage_DefaultProbabilityPct", (0)::numeric)) / 100.0)) AS "CRMOppty_WeightedValueAmount",
    "oppty"."CRMOppty_NextActionDueAt",
    "count"(DISTINCT "ql"."CRMOpptyQuote_ID") AS "CRMOppty_LinkedQuoteCount",
    "count"(DISTINCT "jl"."CRMOpptyJob_ID") AS "CRMOppty_LinkedJobCount"
   FROM (((((("public"."CRM_Opportunities" "oppty"
     JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "oppty"."CRMOppty_OrgID")))
     LEFT JOIN "public"."cmp_Users" "owner" ON (("owner"."User_ID" = "oppty"."CRMOppty_OwnerUserID")))
     LEFT JOIN "public"."cmp_Offices" "office" ON (("office"."Office_ID" = "oppty"."CRMOppty_OrgOfficeID")))
     LEFT JOIN "public"."sys_CRMOpportunityStages" "stage" ON ((("stage"."CRMStage_Code")::"text" = ("oppty"."CRMOppty_StageCode")::"text")))
     LEFT JOIN "public"."CRM_OpportunityQuoteLinks" "ql" ON (("ql"."CRMOpptyQuote_OpportunityID" = "oppty"."CRMOppty_ID")))
     LEFT JOIN "public"."CRM_OpportunityJobLinks" "jl" ON (("jl"."CRMOpptyJob_OpportunityID" = "oppty"."CRMOppty_ID")))
  WHERE ("oppty"."CRMOppty_IsDeleted" = false)
  GROUP BY "oppty"."CRMOppty_ID", "org"."Org_Name", "owner"."User_Email", "office"."Office_Name", "stage"."CRMStage_Name", "stage"."CRMStage_DefaultProbabilityPct";



CREATE OR REPLACE VIEW "public"."CRM_PostCallReviewQueue" AS
 SELECT "cr"."CRMCallReview_ID",
    "cr"."CRMCallReview_CommCallID",
    "call"."CommCall_ProviderCallID",
    "call"."CommCall_DirectionCode",
    "call"."CommCall_StatusCode",
    "call"."CommCall_FromNumber",
    "call"."CommCall_ToNumber",
    "call"."CommCall_StartedAt",
    "call"."CommCall_DurationSeconds",
    "cr"."CRMCallReview_StatusCode",
    "cr"."CRMCallReview_AccountID",
    "org"."Org_Name" AS "CRMCallReview_AccountName",
    "cr"."CRMCallReview_LeadID",
    "cr"."CRMCallReview_OpportunityID",
    "cr"."CRMCallReview_QuoteFollowupID",
    "cr"."CRMCallReview_OwnerUserID",
    "owner"."User_Email" AS "CRMCallReview_OwnerEmail",
    "cr"."CRMCallReview_AISentimentCode",
    "cr"."CRMCallReview_AIUrgencyScore",
    "count"("ca"."CRMCallAction_ID") FILTER (WHERE (("ca"."CRMCallAction_DecisionStatus")::"text" = 'pending'::"text")) AS "CRMCallReview_PendingActionCount",
    "count"("ca"."CRMCallAction_ID") FILTER (WHERE (("ca"."CRMCallAction_DecisionStatus")::"text" = 'accepted'::"text")) AS "CRMCallReview_AcceptedActionCount",
    "cr"."CRMCallReview_CreatedAt"
   FROM (((((("public"."CRM_CallReviews" "cr"
     JOIN "public"."Comm_CallLogs" "call" ON (("call"."CommCall_ID" = "cr"."CRMCallReview_CommCallID")))
     LEFT JOIN "public"."CRM_AccountProfiles" "ap" ON (("ap"."CRMAccount_ID" = "cr"."CRMCallReview_AccountID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "ap"."CRMAccount_OrgID")))
     LEFT JOIN "public"."cmp_Users" "owner" ON (("owner"."User_ID" = "cr"."CRMCallReview_OwnerUserID")))
     LEFT JOIN "public"."CRM_CallActionCandidates" "ca" ON (("ca"."CRMCallAction_CallReviewID" = "cr"."CRMCallReview_ID")))
     LEFT JOIN "public"."sys_CRMCallReviewStatuses" "status" ON ((("status"."CRMCallReviewStatus_Code")::"text" = ("cr"."CRMCallReview_StatusCode")::"text")))
  WHERE ("status"."CRMCallReviewStatus_IsClosed" = false)
  GROUP BY "cr"."CRMCallReview_ID", "call"."CommCall_ID", "org"."Org_Name", "owner"."User_Email";



CREATE OR REPLACE VIEW "public"."CRM_UserTodoQueue" AS
 SELECT "qt"."CRMQuickTask_ID",
    "qt"."CRMQuickTask_TaskTypeCode",
    "qtt"."CRMQuickTaskType_Name",
    "qt"."CRMQuickTask_StatusCode",
    "qt"."CRMQuickTask_DecisionStatusCode",
    "qt"."CRMQuickTask_AssignedUserID",
    "userx"."User_Email" AS "CRMQuickTask_AssignedUserEmail",
    "qt"."CRMQuickTask_Title",
    "qt"."CRMQuickTask_Description",
    "qt"."CRMQuickTask_PriorityCode",
    "qt"."CRMQuickTask_DueAt",
    "qt"."CRMQuickTask_SnoozedUntil",
    "qt"."CRMQuickTask_CustomerOrgID",
    "org"."Org_Name" AS "CRMQuickTask_CustomerName",
    "qt"."CRMQuickTask_AccountID",
    "qt"."CRMQuickTask_LeadID",
    "qt"."CRMQuickTask_OpportunityID",
    "qt"."CRMQuickTask_QuoteFollowupID",
    "qt"."CRMQuickTask_CallReviewID",
    "qt"."CRMQuickTask_JobID",
    "qt"."CRMQuickTask_WorkflowTaskID",
    "count"("opt"."CRMQuickOpt_ID") AS "CRMQuickTask_OptionCount",
    "count"("msg"."CRMPMsg_ID") FILTER (WHERE (("msg"."CRMPMsg_DecisionStatusCode")::"text" = 'pending'::"text")) AS "CRMQuickTask_PendingDraftCount",
    "qt"."CRMQuickTask_CreatedAt"
   FROM (((((("public"."CRM_QuickTasks" "qt"
     LEFT JOIN "public"."sys_CRMQuickTaskTypes" "qtt" ON ((("qtt"."CRMQuickTaskType_Code")::"text" = ("qt"."CRMQuickTask_TaskTypeCode")::"text")))
     LEFT JOIN "public"."cmp_Users" "userx" ON (("userx"."User_ID" = "qt"."CRMQuickTask_AssignedUserID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "qt"."CRMQuickTask_CustomerOrgID")))
     LEFT JOIN "public"."CRM_QuickTaskOptions" "opt" ON (("opt"."CRMQuickOpt_QuickTaskID" = "qt"."CRMQuickTask_ID")))
     LEFT JOIN "public"."CRM_PersonalMessageDrafts" "msg" ON (("msg"."CRMPMsg_QuickTaskID" = "qt"."CRMQuickTask_ID")))
     LEFT JOIN "public"."sys_CRMQuickTaskStatuses" "status" ON ((("status"."CRMQuickTaskStatus_Code")::"text" = ("qt"."CRMQuickTask_StatusCode")::"text")))
  WHERE ("status"."CRMQuickTaskStatus_IsOpen" = true)
  GROUP BY "qt"."CRMQuickTask_ID", "qtt"."CRMQuickTaskType_Name", "userx"."User_Email", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."EDI_AcknowledgementQueue" AS
 SELECT "msg"."EDIMessage_ID",
    "msg"."EDIMessage_MessageTypeCode",
    "msg"."EDIMessage_TradingPartnerID",
    "tp"."EDITP_Name",
    "msg"."EDIMessage_ControlNumber",
    "msg"."EDIMessage_DocumentReference",
    "msg"."EDIMessage_AcknowledgementStatusCode",
    "msg"."EDIMessage_AckDueAt",
    "msg"."EDIMessage_SentAt",
    "count"("ack"."EDIAck_ID") AS "EDIAcknowledgementCount"
   FROM (("public"."EDI_Messages" "msg"
     LEFT JOIN "public"."EDI_TradingPartners" "tp" ON (("tp"."EDITP_ID" = "msg"."EDIMessage_TradingPartnerID")))
     LEFT JOIN "public"."EDI_Acknowledgements" "ack" ON (("ack"."EDIAck_OriginalMessageID" = "msg"."EDIMessage_ID")))
  WHERE (("msg"."EDIMessage_AcknowledgementStatusCode")::"text" = 'pending'::"text")
  GROUP BY "msg"."EDIMessage_ID", "tp"."EDITP_Name";



CREATE OR REPLACE VIEW "public"."EDI_ConnectionSummary" AS
 SELECT "conn"."EDIC_ID",
    "conn"."EDIC_Name",
    "conn"."EDIC_TradingPartnerID",
    "tp"."EDITP_Name",
    "conn"."EDIC_ServiceProviderID",
    "sp"."EDISP_Name",
    "conn"."EDIC_TransportMethodCode",
    "tm"."EDITM_Name",
    "conn"."EDIC_StatusCode",
    "conn"."EDIC_DirectionCode",
    "conn"."EDIC_OrgOfficeID",
    "office"."Office_Name",
    "conn"."EDIC_Environment",
    "conn"."EDIC_LastTestAt",
    "conn"."EDIC_LastSuccessAt",
    "conn"."EDIC_LastErrorText",
    "count"(DISTINCT "profile"."EDIMP_ID") AS "EDIProfileCount",
    "count"(DISTINCT "msg"."EDIMessage_ID") FILTER (WHERE (("msg"."EDIMessage_StatusCode")::"text" = ANY ((ARRAY['queued'::character varying, 'received'::character varying, 'failed'::character varying, 'rejected'::character varying])::"text"[]))) AS "EDIOpenMessageCount"
   FROM (((((("public"."EDI_Connections" "conn"
     LEFT JOIN "public"."EDI_TradingPartners" "tp" ON (("tp"."EDITP_ID" = "conn"."EDIC_TradingPartnerID")))
     LEFT JOIN "public"."EDI_ServiceProviders" "sp" ON (("sp"."EDISP_ID" = "conn"."EDIC_ServiceProviderID")))
     LEFT JOIN "public"."sys_EDITransportMethods" "tm" ON ((("tm"."EDITM_Code")::"text" = ("conn"."EDIC_TransportMethodCode")::"text")))
     LEFT JOIN "public"."cmp_Offices" "office" ON (("office"."Office_ID" = "conn"."EDIC_OrgOfficeID")))
     LEFT JOIN "public"."EDI_MessageProfiles" "profile" ON (("profile"."EDIMP_ConnectionID" = "conn"."EDIC_ID")))
     LEFT JOIN "public"."EDI_Messages" "msg" ON (("msg"."EDIMessage_ConnectionID" = "conn"."EDIC_ID")))
  GROUP BY "conn"."EDIC_ID", "tp"."EDITP_Name", "sp"."EDISP_Name", "tm"."EDITM_Name", "office"."Office_Name";



CREATE OR REPLACE VIEW "public"."EDI_MessageTrace" AS
 SELECT "msg"."EDIMessage_ID",
    "msg"."EDIMessage_StatusCode",
    "msg"."EDIMessage_AcknowledgementStatusCode",
    "msg"."EDIMessage_DirectionCode",
    "msg"."EDIMessage_MessageTypeCode",
    "msg"."EDIMessage_ControlNumber",
    "msg"."EDIMessage_DocumentReference",
    "tp"."EDITP_Name",
    "conn"."EDIC_Name",
    "count"(DISTINCT "event"."EDIEvent_ID") AS "EDIEventCount",
    "max"("event"."EDIEvent_CreatedAt") AS "EDILastEventAt",
    "count"(DISTINCT "issue"."EDIVI_ID") FILTER (WHERE (("issue"."EDIVI_StatusCode")::"text" = 'open'::"text")) AS "EDIOpenIssueCount",
    "count"(DISTINCT "ack"."EDIAck_ID") AS "EDIAcknowledgementCount"
   FROM ((((("public"."EDI_Messages" "msg"
     LEFT JOIN "public"."EDI_TradingPartners" "tp" ON (("tp"."EDITP_ID" = "msg"."EDIMessage_TradingPartnerID")))
     LEFT JOIN "public"."EDI_Connections" "conn" ON (("conn"."EDIC_ID" = "msg"."EDIMessage_ConnectionID")))
     LEFT JOIN "public"."EDI_ProcessingEvents" "event" ON (("event"."EDIEvent_MessageID" = "msg"."EDIMessage_ID")))
     LEFT JOIN "public"."EDI_ValidationIssues" "issue" ON (("issue"."EDIVI_MessageID" = "msg"."EDIMessage_ID")))
     LEFT JOIN "public"."EDI_Acknowledgements" "ack" ON (("ack"."EDIAck_OriginalMessageID" = "msg"."EDIMessage_ID")))
  GROUP BY "msg"."EDIMessage_ID", "tp"."EDITP_Name", "conn"."EDIC_Name";



CREATE OR REPLACE VIEW "public"."EDI_ProfileSummary" AS
 SELECT "profile"."EDIMP_ID",
    "profile"."EDIMP_Code",
    "profile"."EDIMP_Name",
    "profile"."EDIMP_TradingPartnerID",
    "tp"."EDITP_Name",
    "profile"."EDIMP_ConnectionID",
    "conn"."EDIC_Name",
    "profile"."EDIMP_MessageTypeCode",
    "mt"."EDIMT_Name",
    "profile"."EDIMP_DirectionCode",
    "profile"."EDIMP_StandardCode",
    "profile"."EDIMP_StandardVersion",
    "profile"."EDIMP_RequiresAcknowledgement",
    "profile"."EDIMP_AutoProcessInbound",
    "profile"."EDIMP_AutoSendOutbound",
    "count"(DISTINCT "map"."EDIMAP_ID") AS "EDIMappingProfileCount",
    "count"(DISTINCT "mv"."EDIMV_ID") FILTER (WHERE (("mv"."EDIMV_StatusCode")::"text" = ANY ((ARRAY['active'::character varying, 'certified'::character varying])::"text"[]))) AS "EDIUsableMappingVersionCount",
    "profile"."EDIMP_IsActive"
   FROM ((((("public"."EDI_MessageProfiles" "profile"
     JOIN "public"."EDI_TradingPartners" "tp" ON (("tp"."EDITP_ID" = "profile"."EDIMP_TradingPartnerID")))
     LEFT JOIN "public"."EDI_Connections" "conn" ON (("conn"."EDIC_ID" = "profile"."EDIMP_ConnectionID")))
     LEFT JOIN "public"."sys_EDIMessageTypes" "mt" ON ((("mt"."EDIMT_Code")::"text" = ("profile"."EDIMP_MessageTypeCode")::"text")))
     LEFT JOIN "public"."EDI_MappingProfiles" "map" ON (("map"."EDIMAP_MessageProfileID" = "profile"."EDIMP_ID")))
     LEFT JOIN "public"."EDI_MappingVersions" "mv" ON (("mv"."EDIMV_MappingProfileID" = "map"."EDIMAP_ID")))
  GROUP BY "profile"."EDIMP_ID", "tp"."EDITP_Name", "conn"."EDIC_Name", "mt"."EDIMT_Name";



CREATE OR REPLACE VIEW "public"."EDI_TradingPartnerSummary" AS
 SELECT "tp"."EDITP_ID",
    "tp"."EDITP_Code",
    "tp"."EDITP_Name",
    "tp"."EDITP_OrgID",
    "org"."Org_Name",
    "tp"."EDITP_StatusCode",
    "tp"."EDITP_DefaultStandardCode",
    "tp"."EDITP_DefaultTransportMethodCode",
    "tp"."EDITP_RequiresCertification",
    "count"(DISTINCT "conn"."EDIC_ID") AS "EDIConnectionCount",
    "count"(DISTINCT "profile"."EDIMP_ID") AS "EDIMessageProfileCount",
    "count"(DISTINCT "cert"."EDICert_ID") FILTER (WHERE (("cert"."EDICert_StatusCode")::"text" = ANY ((ARRAY['active'::character varying, 'certification'::character varying])::"text"[]))) AS "EDIOpenCertificationCount",
    "tp"."EDITP_IsActive"
   FROM (((("public"."EDI_TradingPartners" "tp"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "tp"."EDITP_OrgID")))
     LEFT JOIN "public"."EDI_Connections" "conn" ON (("conn"."EDIC_TradingPartnerID" = "tp"."EDITP_ID")))
     LEFT JOIN "public"."EDI_MessageProfiles" "profile" ON (("profile"."EDIMP_TradingPartnerID" = "tp"."EDITP_ID")))
     LEFT JOIN "public"."EDI_Certifications" "cert" ON (("cert"."EDICert_TradingPartnerID" = "tp"."EDITP_ID")))
  GROUP BY "tp"."EDITP_ID", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."FIN_AIInsightQueue" AS
 SELECT "i"."FINAIInsight_ID",
    "i"."FINAIInsight_InsightTypeCode",
    "i"."FINAIInsight_StatusCode",
    "i"."FINAIInsight_SeverityCode",
    "i"."FINAIInsight_Title",
    "i"."FINAIInsight_CustomerOrgID",
    "org"."Org_Name" AS "FINAIInsight_CustomerName",
    "i"."FINAIInsight_JobID",
    "i"."FINAIInsight_DocumentID",
    "i"."FINAIInsight_AmountAtRisk",
    "i"."FINAIInsight_AdditionalCostRiskAmount",
    "i"."FINAIInsight_ConfidenceScore",
    "i"."FINAIInsight_RiskScore",
    "i"."FINAIInsight_CreatedAt",
    ("count"("a"."FINAIAct_ID"))::integer AS "FINAIInsight_ActionCount"
   FROM (("public"."FIN_AIInsights" "i"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "i"."FINAIInsight_CustomerOrgID")))
     LEFT JOIN "public"."FIN_AIInsightActions" "a" ON (("a"."FINAIAct_InsightID" = "i"."FINAIInsight_ID")))
  WHERE (("i"."FINAIInsight_StatusCode")::"text" = ANY ((ARRAY['candidate'::character varying, 'active'::character varying, 'snoozed'::character varying])::"text"[]))
  GROUP BY "i"."FINAIInsight_ID", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."FIN_CashAllocationSummary" AS
 SELECT "c"."FINCash_ID",
    "c"."FINCash_TypeCode",
    "c"."FINCash_StatusCode",
    "c"."FINCash_PartyOrgID",
    "c"."FINCash_TransactionDate",
    "c"."FINCash_CurrencyCodeSnapshot",
    "c"."FINCash_Amount",
    "c"."FINCash_UnallocatedAmount",
    ("count"("a"."FINCashAlloc_ID"))::integer AS "FINCash_AllocationCount",
    COALESCE("sum"("a"."FINCashAlloc_AllocatedAmount"), (0)::numeric) AS "FINCash_AllocatedAmount",
    COALESCE("sum"("a"."FINCashAlloc_FXGainLossAmount"), (0)::numeric) AS "FINCash_FXGainLossAmount"
   FROM ("public"."FIN_CashTransactions" "c"
     LEFT JOIN "public"."FIN_CashAllocations" "a" ON (("a"."FINCashAlloc_CashID" = "c"."FINCash_ID")))
  GROUP BY "c"."FINCash_ID";



CREATE OR REPLACE VIEW "public"."FIN_CutoffRunSummary" AS
 SELECT "r"."FINCutoff_ID",
    "r"."FINCutoff_RunTypeCode",
    "r"."FINCutoff_StatusCode",
    "r"."FINCutoff_PeriodID",
    "r"."FINCutoff_LegalEntityID",
    "r"."FINCutoff_OrgOfficeID",
    "r"."FINCutoff_AccountingDateFrom",
    "r"."FINCutoff_AccountingDateTo",
    ("count"("i"."FINCutoffItem_ID"))::integer AS "FINCutoff_ItemCount",
    "sum"(
        CASE
            WHEN (("i"."FINCutoffItem_ItemTypeCode")::"text" = 'wip'::"text") THEN "i"."FINCutoffItem_LocalAmount"
            ELSE (0)::numeric
        END) AS "FINCutoff_LocalWIPAmount",
    "sum"(
        CASE
            WHEN (("i"."FINCutoffItem_ItemTypeCode")::"text" = 'accrual'::"text") THEN "i"."FINCutoffItem_LocalAmount"
            ELSE (0)::numeric
        END) AS "FINCutoff_LocalAccrualAmount",
    ("sum"(
        CASE
            WHEN (("i"."FINCutoffItem_StatusCode")::"text" = ANY ((ARRAY['exception'::character varying, 'blocked'::character varying])::"text"[])) THEN 1
            ELSE 0
        END))::integer AS "FINCutoff_ExceptionItemCount"
   FROM ("public"."FIN_CutoffRuns" "r"
     LEFT JOIN "public"."FIN_CutoffRunItems" "i" ON (("i"."FINCutoffItem_CutoffID" = "r"."FINCutoff_ID")))
  GROUP BY "r"."FINCutoff_ID";



CREATE OR REPLACE VIEW "public"."FIN_DebtChasingQueue" AS
 SELECT "dc"."FINDebtCase_ID",
    "dc"."FINDebtCase_CustomerOrgID",
    "org"."Org_Name" AS "FINDebtCase_CustomerName",
    "dc"."FINDebtCase_DocumentID",
    "dc"."FINDebtCase_StatusCode",
    "dc"."FINDebtCase_SeverityCode",
    "dc"."FINDebtCase_OverdueAmount",
    "dc"."FINDebtCase_OldestDueDate",
    "dc"."FINDebtCase_NextActionDueAt",
    "cp"."FINCreditProfile_OnStop",
    "cp"."FINCreditProfile_FlexibilityLevelCode",
    "max"("da"."FINDebtAction_ActionAt") AS "FINDebtCase_LastActionAt"
   FROM ((("public"."FIN_DebtCases" "dc"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "dc"."FINDebtCase_CustomerOrgID")))
     LEFT JOIN "public"."FIN_CreditProfiles" "cp" ON (("cp"."FINCreditProfile_CustomerOrgID" = "dc"."FINDebtCase_CustomerOrgID")))
     LEFT JOIN "public"."FIN_DebtActions" "da" ON (("da"."FINDebtAction_CaseID" = "dc"."FINDebtCase_ID")))
  GROUP BY "dc"."FINDebtCase_ID", "org"."Org_Name", "cp"."FINCreditProfile_OnStop", "cp"."FINCreditProfile_FlexibilityLevelCode";



CREATE OR REPLACE VIEW "public"."FIN_DisruptionCostRiskSummary" AS
 SELECT "d"."FINDisrupt_ID",
    "d"."FINDisrupt_CustomerOrgID",
    "org"."Org_Name" AS "FINDisrupt_CustomerName",
    "d"."FINDisrupt_JobID",
    "d"."FINDisrupt_SeverityCode",
    "d"."FINDisrupt_PaymentRequiredAmount",
    "d"."FINDisrupt_DisruptionDescription",
    "d"."FINDisrupt_RecommendedActionCode",
    COALESCE("sum"("c"."FINCostRisk_LocalEstimatedAmount"), (0)::numeric) AS "FINDisrupt_LocalAdditionalCostRisk",
    ("count"("c"."FINCostRisk_ID"))::integer AS "FINDisrupt_AdditionalCostRiskCount"
   FROM (("public"."FIN_DisruptionRiskCases" "d"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "d"."FINDisrupt_CustomerOrgID")))
     LEFT JOIN "public"."FIN_AdditionalCostRisks" "c" ON ((("c"."FINCostRisk_JobID" = "d"."FINDisrupt_JobID") AND (("c"."FINCostRisk_StatusCode")::"text" = 'open'::"text"))))
  GROUP BY "d"."FINDisrupt_ID", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."FIN_JobChargeFinanceSummary" AS
 SELECT "s"."FINChargeState_ID",
    "s"."FINChargeState_JobID",
    "s"."FINChargeState_ChargeInID",
    "s"."FINChargeState_ChargeOutID",
    "s"."FINChargeState_LedgerTypeCode",
    "s"."FINChargeState_StatusCode",
    "s"."FINChargeState_ExpectedAmount",
    "s"."FINChargeState_InvoicedAmount",
    "s"."FINChargeState_CreditedAmount",
    "s"."FINChargeState_PaidAmount",
    "s"."FINChargeState_OutstandingAmount",
    "s"."FINChargeState_CurrencyCodeSnapshot",
    ("count"("a"."FINChargeAlloc_ID"))::integer AS "FINChargeState_AllocationCount"
   FROM ("public"."FIN_JobChargeStates" "s"
     LEFT JOIN "public"."FIN_JobChargeAllocations" "a" ON (("a"."FINChargeAlloc_ChargeStateID" = "s"."FINChargeState_ID")))
  GROUP BY "s"."FINChargeState_ID";



CREATE OR REPLACE VIEW "public"."FIN_JobROESummary" AS
 SELECT "s"."FINJobROE_ID",
    "s"."FINJobROE_JobID",
    "s"."FINJobROE_StatusCode",
    "s"."FINJobROE_EffectiveDate",
    "s"."FINJobROE_UsageTypeCode",
    ("count"("l"."FINJobROELine_ID"))::integer AS "FINJobROE_LineCount",
    ("count"("vs"."FINVesselROE_ID"))::integer AS "FINJobROE_VesselROESetCount"
   FROM (("public"."FIN_JobROESets" "s"
     LEFT JOIN "public"."FIN_JobROELines" "l" ON (("l"."FINJobROELine_SetID" = "s"."FINJobROE_ID")))
     LEFT JOIN "public"."FIN_VesselROESets" "vs" ON (("vs"."FINVesselROE_JobID" = "s"."FINJobROE_JobID")))
  GROUP BY "s"."FINJobROE_ID";



CREATE OR REPLACE VIEW "public"."MIG_ImportBatchSummary" AS
 SELECT "b"."MIGBatch_ID" AS "BatchID",
    "b"."MIGBatch_Code" AS "BatchCode",
    "b"."MIGBatch_Name" AS "BatchName",
    "b"."MIGBatch_EntityTypeCode" AS "EntityTypeCode",
    "b"."MIGBatch_StatusCode" AS "StatusCode",
    "b"."MIGBatch_RowCount" AS "RowCount",
    "b"."MIGBatch_ValidRowCount" AS "ValidRowCount",
    "b"."MIGBatch_ErrorRowCount" AS "ErrorRowCount",
    "count"("i"."MIGIssue_ID") FILTER (WHERE ("i"."MIGIssue_IsResolved" = false)) AS "OpenIssueCount",
    "count"("i"."MIGIssue_ID") FILTER (WHERE (("i"."MIGIssue_IsResolved" = false) AND ("s"."MIGIssueSeverity_BlocksLoad" = true))) AS "BlockingIssueCount",
    "b"."MIGBatch_CreatedAt" AS "CreatedAt"
   FROM (("public"."MIG_ImportBatches" "b"
     LEFT JOIN "public"."MIG_ValidationIssues" "i" ON (("i"."MIGIssue_BatchID" = "b"."MIGBatch_ID")))
     LEFT JOIN "public"."sys_MIGIssueSeverities" "s" ON ((("s"."MIGIssueSeverity_Code")::"text" = ("i"."MIGIssue_SeverityCode")::"text")))
  GROUP BY "b"."MIGBatch_ID";



CREATE OR REPLACE VIEW "public"."Portal_UserAccessSummary" AS
 SELECT "u"."PortalUser_ID",
    "u"."PortalUser_DisplayName",
    "u"."PortalUser_Email",
    "u"."PortalUser_AudienceTypeCode",
    "u"."PortalUser_StatusCode",
    "u"."PortalUser_PrimaryOrgID",
    "org"."Org_Name" AS "PortalUser_PrimaryOrgName",
    "u"."PortalUser_DefaultSiteID",
    "site"."PortalSite_Name",
    "u"."PortalUser_MFARequired",
    "u"."PortalUser_EmailVerifiedAt",
    "u"."PortalUser_LastLoginAt",
    "count"(DISTINCT "ur"."PortalUserRole_ID") AS "PortalUser_RoleCount",
    "count"(DISTINCT "rs"."PortalShare_ID") AS "PortalUser_DirectShareCount"
   FROM (((("public"."Portal_Users" "u"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "u"."PortalUser_PrimaryOrgID")))
     LEFT JOIN "public"."Portal_Sites" "site" ON (("site"."PortalSite_ID" = "u"."PortalUser_DefaultSiteID")))
     LEFT JOIN "public"."Portal_UserRoles" "ur" ON ((("ur"."PortalUserRole_PortalUserID" = "u"."PortalUser_ID") AND (("ur"."PortalUserRole_StatusCode")::"text" = 'active'::"text"))))
     LEFT JOIN "public"."Portal_RecordShares" "rs" ON ((("rs"."PortalShare_PortalUserID" = "u"."PortalUser_ID") AND (("rs"."PortalShare_StatusCode")::"text" = 'active'::"text"))))
  WHERE ("u"."PortalUser_IsDeleted" = false)
  GROUP BY "u"."PortalUser_ID", "org"."Org_Name", "site"."PortalSite_Name";



CREATE OR REPLACE VIEW "public"."RATE_ContractSummary" AS
 SELECT "c"."RATEContract_ID",
    "c"."RATEContract_Code",
    "c"."RATEContract_Name",
    "c"."RATEContract_TypeCode",
    "c"."RATEContract_StatusCode",
    "c"."RATEContract_OrgOfficeID",
    "o"."Office_Name" AS "RATEContract_OfficeName",
    "c"."RATEContract_CarrierOrgID",
    "carrier"."Org_Name" AS "RATEContract_CarrierName",
    "c"."RATEContract_CustomerOrgID",
    "customer"."Org_Name" AS "RATEContract_CustomerName",
    "c"."RATEContract_CurrencyCodeSnapshot",
    "c"."RATEContract_ValidFrom",
    "c"."RATEContract_ValidTo",
    "c"."RATEContract_CurrentVersionID",
    "cv"."RATEContractVer_VersionNo" AS "RATEContract_CurrentVersionNo",
    "count"(DISTINCT "v"."RATEContractVer_ID") AS "RATEContract_VersionCount",
    "count"(DISTINCT "s"."RATESheet_ID") AS "RATEContract_SheetCount",
    "count"(DISTINCT "rl"."RATELine_ID") AS "RATEContract_RateLineCount"
   FROM ((((((("public"."RATE_Contracts" "c"
     LEFT JOIN "public"."cmp_Offices" "o" ON (("o"."Office_ID" = "c"."RATEContract_OrgOfficeID")))
     LEFT JOIN "public"."Org_Master" "carrier" ON (("carrier"."Org_id" = "c"."RATEContract_CarrierOrgID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "c"."RATEContract_CustomerOrgID")))
     LEFT JOIN "public"."RATE_ContractVersions" "cv" ON (("cv"."RATEContractVer_ID" = "c"."RATEContract_CurrentVersionID")))
     LEFT JOIN "public"."RATE_ContractVersions" "v" ON (("v"."RATEContractVer_ContractID" = "c"."RATEContract_ID")))
     LEFT JOIN "public"."RATE_RateSheets" "s" ON (("s"."RATESheet_ContractVerID" = "v"."RATEContractVer_ID")))
     LEFT JOIN "public"."RATE_RateLines" "rl" ON (("rl"."RATELine_SheetID" = "s"."RATESheet_ID")))
  WHERE ("c"."RATEContract_IsDeleted" = false)
  GROUP BY "c"."RATEContract_ID", "o"."Office_Name", "carrier"."Org_Name", "customer"."Org_Name", "cv"."RATEContractVer_VersionNo";



CREATE OR REPLACE VIEW "public"."RATE_RateResultSummary" AS
 SELECT "res"."RATEResult_ID",
    "res"."RATEResult_RequestID",
    "req"."RATERequest_Code",
    "res"."RATEResult_StatusCode",
    "res"."RATEResult_SourceTypeCode",
    "res"."RATEResult_ContractID",
    "contract"."RATEContract_Code",
    "contract"."RATEContract_Name",
    "res"."RATEResult_CarrierOrgID",
    "carrier"."Org_Name" AS "RATEResult_CarrierOrgName",
    "res"."RATEResult_CarrierNameSnapshot",
    "res"."RATEResult_ServiceLevel",
    "res"."RATEResult_TransitDays",
    "res"."RATEResult_Direct",
    "res"."RATEResult_CurrencyCodeSnapshot",
    "res"."RATEResult_BuyTotal",
    "res"."RATEResult_SellTotal",
    "res"."RATEResult_MarginAmount",
    "res"."RATEResult_MarginPercent",
    "count"(DISTINCT "line"."RATEResultLine_ID") AS "RATEResult_LineCount",
    "sum"(
        CASE
            WHEN (("line"."RATEResultLine_ApplicabilityCode")::"text" = ANY ((ARRAY['buy'::character varying, 'both'::character varying])::"text"[])) THEN "line"."RATEResultLine_TotalAmount"
            ELSE (0)::numeric
        END) AS "RATEResult_BuyLineTotal",
    "sum"(
        CASE
            WHEN (("line"."RATEResultLine_ApplicabilityCode")::"text" = ANY ((ARRAY['sell'::character varying, 'both'::character varying])::"text"[])) THEN "line"."RATEResultLine_TotalAmount"
            ELSE (0)::numeric
        END) AS "RATEResult_SellLineTotal",
    "res"."RATEResult_CreatedAt"
   FROM (((("public"."RATE_RateResults" "res"
     JOIN "public"."RATE_RateRequests" "req" ON (("req"."RATERequest_ID" = "res"."RATEResult_RequestID")))
     LEFT JOIN "public"."RATE_Contracts" "contract" ON (("contract"."RATEContract_ID" = "res"."RATEResult_ContractID")))
     LEFT JOIN "public"."Org_Master" "carrier" ON (("carrier"."Org_id" = "res"."RATEResult_CarrierOrgID")))
     LEFT JOIN "public"."RATE_RateResultLines" "line" ON (("line"."RATEResultLine_ResultID" = "res"."RATEResult_ID")))
  GROUP BY "res"."RATEResult_ID", "req"."RATERequest_Code", "contract"."RATEContract_Code", "contract"."RATEContract_Name", "carrier"."Org_Name";



CREATE OR REPLACE VIEW "public"."TCE_ChecklistSummary" AS
 SELECT "checklist"."TCEChecklist_ID",
    "checklist"."TCEChecklist_Number",
    "checklist"."TCEChecklist_StatusCode",
    "status"."TCECheckStatus_Name",
    "status"."TCECheckStatus_IsOpen",
    "status"."TCECheckStatus_IsBlocking",
    "checklist"."TCEChecklist_TouchpointTypeCode",
    "checklist"."TCEChecklist_PolicyID",
    "checklist"."TCEChecklist_JobID",
    "job"."Job_Number",
    "checklist"."TCEChecklist_CustomerOrgID",
    "customer"."Org_Name" AS "TCEChecklist_CustomerName",
    "checklist"."TCEChecklist_OrgOfficeID",
    "checklist"."TCEChecklist_SourceTable",
    "checklist"."TCEChecklist_SourceID",
    "checklist"."TCEChecklist_RequiredBy",
    "checklist"."TCEChecklist_CompletedAt",
    ("count"(DISTINCT "item"."TCECheckItem_ID"))::integer AS "TCEChecklist_ItemRows",
    ("count"(DISTINCT "item"."TCECheckItem_ID") FILTER (WHERE "item_status"."TCECheckStatus_IsOpen"))::integer AS "TCEChecklist_OpenItemRows",
    ("count"(DISTINCT "item"."TCECheckItem_ID") FILTER (WHERE (("item"."TCECheckItem_StatusCode")::"text" = 'blocked'::"text")))::integer AS "TCEChecklist_BlockedItemRows",
    ("count"(DISTINCT "gate"."TCEGate_ID") FILTER (WHERE ("gate_status"."TCECheckStatus_IsOpen" AND "gate"."TCEGate_IsBlocking")))::integer AS "TCEChecklist_BlockingGateRows",
    "checklist"."TCEChecklist_CreatedAt"
   FROM ((((((("public"."TCE_ComplianceChecklists" "checklist"
     LEFT JOIN "public"."sys_TCECheckStatuses" "status" ON ((("status"."TCECheckStatus_Code")::"text" = ("checklist"."TCEChecklist_StatusCode")::"text")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "checklist"."TCEChecklist_JobID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "checklist"."TCEChecklist_CustomerOrgID")))
     LEFT JOIN "public"."TCE_ComplianceCheckItems" "item" ON (("item"."TCECheckItem_ChecklistID" = "checklist"."TCEChecklist_ID")))
     LEFT JOIN "public"."sys_TCECheckStatuses" "item_status" ON ((("item_status"."TCECheckStatus_Code")::"text" = ("item"."TCECheckItem_StatusCode")::"text")))
     LEFT JOIN "public"."TCE_ReleaseGates" "gate" ON (("gate"."TCEGate_ChecklistID" = "checklist"."TCEChecklist_ID")))
     LEFT JOIN "public"."sys_TCECheckStatuses" "gate_status" ON ((("gate_status"."TCECheckStatus_Code")::"text" = ("gate"."TCEGate_StatusCode")::"text")))
  GROUP BY "checklist"."TCEChecklist_ID", "status"."TCECheckStatus_Name", "status"."TCECheckStatus_IsOpen", "status"."TCECheckStatus_IsBlocking", "job"."Job_Number", "customer"."Org_Name";



CREATE OR REPLACE VIEW "public"."TCE_ComplianceCaseQueue" AS
 SELECT "case_row"."TCECase_ID",
    "case_row"."TCECase_Number",
    "case_row"."TCECase_StatusCode",
    "status"."TCECaseStatus_Name",
    "status"."TCECaseStatus_IsBlocking",
    "case_row"."TCECase_RiskLevelCode",
    "case_row"."TCECase_RunID",
    "run"."TCERun_Number",
    "case_row"."TCECase_SubjectID",
    "subject"."TCESubject_RoleCode",
    "subject"."TCESubject_Name",
    "case_row"."TCECase_JobID",
    "job"."Job_Number",
    "case_row"."TCECase_CustomerOrgID",
    "customer"."Org_Name" AS "TCECase_CustomerName",
    "case_row"."TCECase_Title",
    "case_row"."TCECase_AssignedUserID",
    "case_row"."TCECase_DueAt",
    "case_row"."TCECase_CreatedAt",
    ("count"("match"."TCEMatch_ID"))::integer AS "TCECase_MatchCount"
   FROM (((((("public"."TCE_ComplianceCases" "case_row"
     LEFT JOIN "public"."sys_TCECaseStatuses" "status" ON ((("status"."TCECaseStatus_Code")::"text" = ("case_row"."TCECase_StatusCode")::"text")))
     LEFT JOIN "public"."TCE_ScreeningRuns" "run" ON (("run"."TCERun_ID" = "case_row"."TCECase_RunID")))
     LEFT JOIN "public"."TCE_ScreeningSubjects" "subject" ON (("subject"."TCESubject_ID" = "case_row"."TCECase_SubjectID")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "case_row"."TCECase_JobID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "case_row"."TCECase_CustomerOrgID")))
     LEFT JOIN "public"."TCE_ScreeningMatches" "match" ON (("match"."TCEMatch_CaseID" = "case_row"."TCECase_ID")))
  GROUP BY "case_row"."TCECase_ID", "status"."TCECaseStatus_Name", "status"."TCECaseStatus_IsBlocking", "run"."TCERun_Number", "subject"."TCESubject_RoleCode", "subject"."TCESubject_Name", "job"."Job_Number", "customer"."Org_Name";



CREATE OR REPLACE VIEW "public"."TCE_HSClassificationQueue" AS
 SELECT "class"."TCEClass_ID",
    "class"."TCEClass_StatusCode",
    "status"."TCEClassStatus_Name",
    "class"."TCEClass_JobID",
    "job"."Job_Number",
    "class"."TCEClass_JobCargoID",
    "class"."TCEClass_CustomerOrgID",
    "customer"."Org_Name" AS "TCEClass_CustomerName",
    "class"."TCEClass_GoodsDescription",
    "class"."TCEClass_HSCode",
    "class"."TCEClass_ECCNCode",
    "class"."TCEClass_ControlCode",
    "class"."TCEClass_ConfidenceScore",
    "class"."TCEClass_ReviewedBy",
    "class"."TCEClass_ReviewedAt",
    "class"."TCEClass_CreatedAt",
    ("count"("candidate"."TCEClassCand_ID"))::integer AS "TCEClass_CandidateCount"
   FROM (((("public"."TCE_HSClassifications" "class"
     LEFT JOIN "public"."sys_TCEClassificationStatuses" "status" ON ((("status"."TCEClassStatus_Code")::"text" = ("class"."TCEClass_StatusCode")::"text")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "class"."TCEClass_JobID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "class"."TCEClass_CustomerOrgID")))
     LEFT JOIN "public"."TCE_HSClassificationCandidates" "candidate" ON (("candidate"."TCEClassCand_ClassificationID" = "class"."TCEClass_ID")))
  GROUP BY "class"."TCEClass_ID", "status"."TCEClassStatus_Name", "job"."Job_Number", "customer"."Org_Name";



CREATE OR REPLACE VIEW "public"."TCE_JobComplianceSummary" AS
 SELECT "job"."Job_ID",
    "job"."Job_Number",
    "job"."Job_Customer",
    "customer"."Org_Name" AS "Job_CustomerName",
    ("count"(DISTINCT "run"."TCERun_ID"))::integer AS "TCEJob_ScreeningRunCount",
    ("count"(DISTINCT "run"."TCERun_ID") FILTER (WHERE (("run"."TCERun_StatusCode")::"text" = ANY ((ARRAY['review_required'::character varying, 'possible_match'::character varying, 'strong_match'::character varying, 'blocked'::character varying])::"text"[]))))::integer AS "TCEJob_RiskyRunCount",
    ("count"(DISTINCT "case_row"."TCECase_ID") FILTER (WHERE "case_status"."TCECaseStatus_IsOpen"))::integer AS "TCEJob_OpenCaseCount",
    ("count"(DISTINCT "hold"."TCEHold_ID") FILTER (WHERE "hold_status"."TCEHoldStatus_IsOpen"))::integer AS "TCEJob_ActiveHoldCount",
    ("count"(DISTINCT "class"."TCEClass_ID"))::integer AS "TCEJob_ClassificationCount",
    ("count"(DISTINCT "pref"."TCEPref_ID"))::integer AS "TCEJob_PreferenceClaimCount",
    ("count"(DISTINCT "checklist"."TCEChecklist_ID") FILTER (WHERE "checklist_status"."TCECheckStatus_IsOpen"))::integer AS "TCEJob_OpenChecklistCount",
    ("count"(DISTINCT "item"."TCECheckItem_ID") FILTER (WHERE "item_status"."TCECheckStatus_IsOpen"))::integer AS "TCEJob_OpenCheckItemCount",
    ("count"(DISTINCT "gate"."TCEGate_ID") FILTER (WHERE ("gate_status"."TCECheckStatus_IsOpen" AND "gate"."TCEGate_IsBlocking")))::integer AS "TCEJob_BlockingGateCount",
    "max"("run"."TCERun_HighestScore") AS "TCEJob_HighestScreeningScore"
   FROM (((((((((((((("public"."Job_Header" "job"
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "job"."Job_Customer")))
     LEFT JOIN "public"."TCE_ScreeningRuns" "run" ON (("run"."TCERun_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."TCE_ComplianceCases" "case_row" ON (("case_row"."TCECase_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."sys_TCECaseStatuses" "case_status" ON ((("case_status"."TCECaseStatus_Code")::"text" = ("case_row"."TCECase_StatusCode")::"text")))
     LEFT JOIN "public"."TCE_ComplianceHolds" "hold" ON (("hold"."TCEHold_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."sys_TCEHoldStatuses" "hold_status" ON ((("hold_status"."TCEHoldStatus_Code")::"text" = ("hold"."TCEHold_StatusCode")::"text")))
     LEFT JOIN "public"."TCE_HSClassifications" "class" ON (("class"."TCEClass_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."TCE_PreferenceClaims" "pref" ON (("pref"."TCEPref_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."TCE_ComplianceChecklists" "checklist" ON (("checklist"."TCEChecklist_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."sys_TCECheckStatuses" "checklist_status" ON ((("checklist_status"."TCECheckStatus_Code")::"text" = ("checklist"."TCEChecklist_StatusCode")::"text")))
     LEFT JOIN "public"."TCE_ComplianceCheckItems" "item" ON (("item"."TCECheckItem_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."sys_TCECheckStatuses" "item_status" ON ((("item_status"."TCECheckStatus_Code")::"text" = ("item"."TCECheckItem_StatusCode")::"text")))
     LEFT JOIN "public"."TCE_ReleaseGates" "gate" ON (("gate"."TCEGate_JobID" = "job"."Job_ID")))
     LEFT JOIN "public"."sys_TCECheckStatuses" "gate_status" ON ((("gate_status"."TCECheckStatus_Code")::"text" = ("gate"."TCEGate_StatusCode")::"text")))
  GROUP BY "job"."Job_ID", "customer"."Org_Name";



CREATE OR REPLACE VIEW "public"."TCE_LicenseUsageSummary" AS
 SELECT "license"."TCELicense_ID",
    "license"."TCELicense_Number",
    "license"."TCELicense_TypeCode",
    "license"."TCELicense_StatusCode",
    "license"."TCELicense_CustomerOrgID",
    "customer"."Org_Name" AS "TCELicense_CustomerName",
    "license"."TCELicense_JurisdictionCode",
    "license"."TCELicense_ExpiryDate",
    "license"."TCELicense_CurrencyCodeSnapshot",
    "license"."TCELicense_ValueLimitAmount",
    "license"."TCELicense_ValueUsedAmount",
    ((COALESCE("license"."TCELicense_ValueLimitAmount", (0)::numeric) - "license"."TCELicense_ValueUsedAmount"))::numeric(18,4) AS "TCELicense_ValueRemainingAmount",
    "license"."TCELicense_QuantityLimit",
    "license"."TCELicense_QuantityUsed",
    ((COALESCE("license"."TCELicense_QuantityLimit", (0)::numeric) - "license"."TCELicense_QuantityUsed"))::numeric(18,4) AS "TCELicense_QuantityRemaining",
    ("count"("usage"."TCELicUse_ID"))::integer AS "TCELicense_UsageCount"
   FROM (("public"."TCE_Licenses" "license"
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "license"."TCELicense_CustomerOrgID")))
     LEFT JOIN "public"."TCE_LicenseUsages" "usage" ON (("usage"."TCELicUse_LicenseID" = "license"."TCELicense_ID")))
  GROUP BY "license"."TCELicense_ID", "customer"."Org_Name";



CREATE OR REPLACE VIEW "public"."TCE_OperationalReleaseQueue" AS
 SELECT "gate"."TCEGate_ID",
    "gate"."TCEGate_StatusCode",
    "status"."TCECheckStatus_Name",
    "status"."TCECheckStatus_IsOpen",
    "status"."TCECheckStatus_IsBlocking",
    "gate"."TCEGate_GateCode",
    "gate"."TCEGate_Name",
    "gate"."TCEGate_ActionCode",
    "gate"."TCEGate_IsBlocking",
    "gate"."TCEGate_JobID",
    "job"."Job_Number",
    "checklist"."TCEChecklist_ID",
    "checklist"."TCEChecklist_Number",
    "checklist"."TCEChecklist_TouchpointTypeCode",
    "checklist"."TCEChecklist_CustomerOrgID",
    "customer"."Org_Name" AS "TCEGate_CustomerName",
    "gate"."TCEGate_SourceTable",
    "gate"."TCEGate_SourceID",
    "gate"."TCEGate_HoldID",
    "hold"."TCEHold_Reason",
    "gate"."TCEGate_BlockReason",
    "gate"."TCEGate_RequiredClearanceAt",
    "gate"."TCEGate_ClearedAt",
    ("count"("item"."TCECheckItem_ID") FILTER (WHERE (("item"."TCECheckItem_StatusCode")::"text" = 'blocked'::"text")))::integer AS "TCEGate_BlockedItemCount",
    ("count"("item"."TCECheckItem_ID") FILTER (WHERE "item_status"."TCECheckStatus_IsOpen"))::integer AS "TCEGate_OpenItemCount",
    "gate"."TCEGate_CreatedAt"
   FROM ((((((("public"."TCE_ReleaseGates" "gate"
     LEFT JOIN "public"."sys_TCECheckStatuses" "status" ON ((("status"."TCECheckStatus_Code")::"text" = ("gate"."TCEGate_StatusCode")::"text")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "gate"."TCEGate_JobID")))
     LEFT JOIN "public"."TCE_ComplianceChecklists" "checklist" ON (("checklist"."TCEChecklist_ID" = "gate"."TCEGate_ChecklistID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "checklist"."TCEChecklist_CustomerOrgID")))
     LEFT JOIN "public"."TCE_ComplianceHolds" "hold" ON (("hold"."TCEHold_ID" = "gate"."TCEGate_HoldID")))
     LEFT JOIN "public"."TCE_ComplianceCheckItems" "item" ON (("item"."TCECheckItem_ChecklistID" = "checklist"."TCEChecklist_ID")))
     LEFT JOIN "public"."sys_TCECheckStatuses" "item_status" ON ((("item_status"."TCECheckStatus_Code")::"text" = ("item"."TCECheckItem_StatusCode")::"text")))
  WHERE (COALESCE("status"."TCECheckStatus_IsOpen", true) = true)
  GROUP BY "gate"."TCEGate_ID", "status"."TCECheckStatus_Name", "status"."TCECheckStatus_IsOpen", "status"."TCECheckStatus_IsBlocking", "job"."Job_Number", "checklist"."TCEChecklist_ID", "customer"."Org_Name", "hold"."TCEHold_Reason";



CREATE OR REPLACE VIEW "public"."TCE_ScreeningRunSummary" AS
 SELECT "run"."TCERun_ID",
    "run"."TCERun_Number",
    "run"."TCERun_RunTypeCode",
    "run"."TCERun_StatusCode",
    "run"."TCERun_JobID",
    "job"."Job_Number",
    "run"."TCERun_CustomerOrgID",
    "customer"."Org_Name" AS "TCERun_CustomerName",
    "run"."TCERun_OrgOfficeID",
    "run"."TCERun_TriggeredAt",
    "run"."TCERun_CompletedAt",
    "run"."TCERun_SubjectCount",
    ("count"(DISTINCT "subject"."TCESubject_ID"))::integer AS "TCERun_SubjectRows",
    ("count"(DISTINCT "match"."TCEMatch_ID"))::integer AS "TCERun_MatchRows",
    ("count"(DISTINCT "case_row"."TCECase_ID") FILTER (WHERE "case_status"."TCECaseStatus_IsOpen"))::integer AS "TCERun_OpenCases",
    "run"."TCERun_HighestScore",
    "run"."TCERun_HighestRiskLevelCode"
   FROM (((((("public"."TCE_ScreeningRuns" "run"
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "run"."TCERun_JobID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "run"."TCERun_CustomerOrgID")))
     LEFT JOIN "public"."TCE_ScreeningSubjects" "subject" ON (("subject"."TCESubject_RunID" = "run"."TCERun_ID")))
     LEFT JOIN "public"."TCE_ScreeningMatches" "match" ON (("match"."TCEMatch_RunID" = "run"."TCERun_ID")))
     LEFT JOIN "public"."TCE_ComplianceCases" "case_row" ON (("case_row"."TCECase_RunID" = "run"."TCERun_ID")))
     LEFT JOIN "public"."sys_TCECaseStatuses" "case_status" ON ((("case_status"."TCECaseStatus_Code")::"text" = ("case_row"."TCECase_StatusCode")::"text")))
  GROUP BY "run"."TCERun_ID", "job"."Job_Number", "customer"."Org_Name";



CREATE OR REPLACE VIEW "public"."TCE_SourceHealth" AS
 SELECT "source"."TCESource_ID",
    "source"."TCESource_Code",
    "source"."TCESource_Name",
    "source"."TCESource_SourceTypeCode",
    "source"."TCESource_ListTypeCode",
    "source"."TCESource_StatusCode",
    "source"."TCESource_IsOfficial",
    "source"."TCESource_LastRefreshAt",
    "source"."TCESource_NextRefreshAt",
    ("count"("entry"."TCEEntry_ID") FILTER (WHERE "entry"."TCEEntry_IsActive"))::integer AS "TCESource_ActiveEntryCount",
    "max"("file"."TCESourceFile_DownloadedAt") AS "TCESource_LastFileDownloadedAt",
    "max"("file"."TCESourceFile_ErrorCount") AS "TCESource_LastErrorCount"
   FROM (("public"."TCE_DataSources" "source"
     LEFT JOIN "public"."TCE_WatchlistEntries" "entry" ON (("entry"."TCEEntry_SourceID" = "source"."TCESource_ID")))
     LEFT JOIN "public"."TCE_SourceFiles" "file" ON (("file"."TCESourceFile_SourceID" = "source"."TCESource_ID")))
  GROUP BY "source"."TCESource_ID";



CREATE OR REPLACE VIEW "public"."WMS_BondedReleaseQueue" AS
 SELECT "r"."WMSBondRemoval_ID",
    "r"."WMSBondRemoval_FacilityID",
    "f"."WMSFacility_Name",
    "r"."WMSBondRemoval_OrderID",
    "o"."WMSOrder_OrderNumber",
    "r"."WMSBondRemoval_JobID",
    "r"."WMSBondRemoval_RemovalNumber",
    "r"."WMSBondRemoval_RemovalTypeCode",
    "r"."WMSBondRemoval_StatusCode",
    "r"."WMSBondRemoval_DeclarationReference",
    "r"."WMSBondRemoval_CustomsReleaseReference",
    "r"."WMSBondRemoval_RequiresFinanceRelease",
    "r"."WMSBondRemoval_RequiresComplianceRelease",
    ("count"("rl"."WMSBondRemovalLine_ID"))::integer AS "LineCount",
    COALESCE("sum"("rl"."WMSBondRemovalLine_Quantity"), (0)::numeric) AS "RemovalQuantity",
    COALESCE("sum"("rl"."WMSBondRemovalLine_DutyDueAmount"), (0)::numeric) AS "DutyDueAmount",
    COALESCE("sum"("rl"."WMSBondRemovalLine_TaxDueAmount"), (0)::numeric) AS "TaxDueAmount"
   FROM ((("public"."WMS_BondedRemovals" "r"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "r"."WMSBondRemoval_FacilityID")))
     LEFT JOIN "public"."WMS_Orders" "o" ON (("o"."WMSOrder_ID" = "r"."WMSBondRemoval_OrderID")))
     LEFT JOIN "public"."WMS_BondedRemovalLines" "rl" ON (("rl"."WMSBondRemovalLine_RemovalID" = "r"."WMSBondRemoval_ID")))
  WHERE (("r"."WMSBondRemoval_StatusCode")::"text" <> ALL ((ARRAY['complete'::character varying, 'cancelled'::character varying])::"text"[]))
  GROUP BY "r"."WMSBondRemoval_ID", "f"."WMSFacility_Name", "o"."WMSOrder_OrderNumber";



CREATE OR REPLACE VIEW "public"."WMS_InboundQueue" AS
 SELECT "o"."WMSOrder_ID",
    "o"."WMSOrder_FacilityID",
    "f"."WMSFacility_Name",
    "o"."WMSOrder_OrderNumber",
    "o"."WMSOrder_TypeCode",
    "o"."WMSOrder_StatusCode",
    "o"."WMSOrder_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "o"."WMSOrder_JobID",
    "o"."WMSOrder_AppointmentStartAt",
    ("count"("ol"."WMSOrderLine_ID"))::integer AS "LineCount",
    COALESCE("sum"("ol"."WMSOrderLine_OrderedQuantity"), (0)::numeric) AS "ExpectedQuantity",
    COALESCE("sum"("ol"."WMSOrderLine_ReceivedQuantity"), (0)::numeric) AS "ReceivedQuantity"
   FROM ((("public"."WMS_Orders" "o"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "o"."WMSOrder_FacilityID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "o"."WMSOrder_CustomerOrgID")))
     LEFT JOIN "public"."WMS_OrderLines" "ol" ON (("ol"."WMSOrderLine_OrderID" = "o"."WMSOrder_ID")))
  WHERE ((("o"."WMSOrder_TypeCode")::"text" = ANY ((ARRAY['inbound'::character varying, 'return'::character varying, 'crossdock'::character varying, 'bonded_admission'::character varying])::"text"[])) AND ("o"."WMSOrder_IsDeleted" = false))
  GROUP BY "o"."WMSOrder_ID", "f"."WMSFacility_Name", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."WMS_LocationUtilisation" AS
 SELECT "l"."WMSLocation_ID",
    "l"."WMSLocation_FacilityID",
    "f"."WMSFacility_Name",
    "z"."WMSZone_Code",
    "l"."WMSLocation_Code",
    "l"."WMSLocation_TypeCode",
    "l"."WMSLocation_StatusCode",
    "l"."WMSLocation_MaxWeightKG",
    "l"."WMSLocation_MaxVolumeCBM",
    COALESCE("sum"("b"."WMSBalance_OnHandQuantity"), (0)::numeric) AS "OnHandQuantity",
    ("count"(DISTINCT "b"."WMSBalance_ItemID"))::integer AS "ItemCount",
    ("count"(DISTINCT "b"."WMSBalance_HU_ID"))::integer AS "HandlingUnitCount"
   FROM ((("public"."WMS_Locations" "l"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "l"."WMSLocation_FacilityID")))
     LEFT JOIN "public"."WMS_Zones" "z" ON (("z"."WMSZone_ID" = "l"."WMSLocation_ZoneID")))
     LEFT JOIN "public"."WMS_InventoryBalances" "b" ON (("b"."WMSBalance_LocationID" = "l"."WMSLocation_ID")))
  GROUP BY "l"."WMSLocation_ID", "f"."WMSFacility_Name", "z"."WMSZone_Code";



CREATE OR REPLACE VIEW "public"."WMS_OutboundQueue" AS
 SELECT "o"."WMSOrder_ID",
    "o"."WMSOrder_FacilityID",
    "f"."WMSFacility_Name",
    "o"."WMSOrder_OrderNumber",
    "o"."WMSOrder_TypeCode",
    "o"."WMSOrder_StatusCode",
    "o"."WMSOrder_ReleaseGateStatusCode",
    "o"."WMSOrder_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "o"."WMSOrder_JobID",
    "o"."WMSOrder_AppointmentStartAt",
    ("count"("ol"."WMSOrderLine_ID"))::integer AS "LineCount",
    COALESCE("sum"("ol"."WMSOrderLine_OrderedQuantity"), (0)::numeric) AS "OrderedQuantity",
    COALESCE("sum"("ol"."WMSOrderLine_AllocatedQuantity"), (0)::numeric) AS "AllocatedQuantity",
    COALESCE("sum"("ol"."WMSOrderLine_PickedQuantity"), (0)::numeric) AS "PickedQuantity",
    COALESCE("sum"("ol"."WMSOrderLine_DispatchedQuantity"), (0)::numeric) AS "DispatchedQuantity"
   FROM ((("public"."WMS_Orders" "o"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "o"."WMSOrder_FacilityID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "o"."WMSOrder_CustomerOrgID")))
     LEFT JOIN "public"."WMS_OrderLines" "ol" ON (("ol"."WMSOrderLine_OrderID" = "o"."WMSOrder_ID")))
  WHERE ((("o"."WMSOrder_TypeCode")::"text" = ANY ((ARRAY['outbound'::character varying, 'bonded_removal'::character varying, 'temporary_removal'::character varying, 'destruction'::character varying])::"text"[])) AND ("o"."WMSOrder_IsDeleted" = false))
  GROUP BY "o"."WMSOrder_ID", "f"."WMSFacility_Name", "org"."Org_Name";



CREATE OR REPLACE VIEW "public"."Workflow_ApprovalSummary" AS
 SELECT "a"."WorkflowApproval_ID",
    "a"."WorkflowApproval_InstanceID",
    "a"."WorkflowApproval_TaskID",
    "a"."WorkflowApproval_RecordTypeCode",
    "a"."WorkflowApproval_RecordID",
    "a"."WorkflowApproval_Title",
    "a"."WorkflowApproval_StatusCode",
    "aps"."WorkflowApprovalStatus_IsOpen",
    "a"."WorkflowApproval_PriorityCode",
    "a"."WorkflowApproval_RequestedBy",
    "req"."User_Email" AS "WorkflowApproval_RequestedByEmail",
    "a"."WorkflowApproval_RequestedAt",
    "a"."WorkflowApproval_DueAt",
    "a"."WorkflowApproval_CurrentApproverUserID",
    "appr"."User_Email" AS "WorkflowApproval_CurrentApproverEmail",
    "a"."WorkflowApproval_CurrentApproverRoleID",
    ("count"("d"."WorkflowApprovalDecision_ID"))::integer AS "WorkflowApproval_DecisionCount",
    "max"("d"."WorkflowApprovalDecision_DecidedAt") AS "WorkflowApproval_LastDecisionAt",
    "a"."WorkflowApproval_FinalDecisionAt"
   FROM (((("public"."Workflow_Approvals" "a"
     LEFT JOIN "public"."sys_WorkflowApprovalStatuses" "aps" ON ((("aps"."WorkflowApprovalStatus_Code")::"text" = ("a"."WorkflowApproval_StatusCode")::"text")))
     LEFT JOIN "public"."cmp_Users" "req" ON (("req"."User_ID" = "a"."WorkflowApproval_RequestedBy")))
     LEFT JOIN "public"."cmp_Users" "appr" ON (("appr"."User_ID" = "a"."WorkflowApproval_CurrentApproverUserID")))
     LEFT JOIN "public"."Workflow_ApprovalDecisions" "d" ON (("d"."WorkflowApprovalDecision_ApprovalID" = "a"."WorkflowApproval_ID")))
  GROUP BY "a"."WorkflowApproval_ID", "aps"."WorkflowApprovalStatus_IsOpen", "req"."User_Email", "appr"."User_Email";



CREATE OR REPLACE VIEW "public"."Workflow_DefinitionSummary" AS
 SELECT "d"."WorkflowDef_ID",
    "d"."WorkflowDef_Code",
    "d"."WorkflowDef_Name",
    "d"."WorkflowDef_RecordTypeCode",
    "d"."WorkflowDef_StatusCode",
    "d"."WorkflowDef_OrgOfficeID",
    "o"."Office_Name" AS "WorkflowDef_OfficeName",
    "d"."WorkflowDef_LegalEntityID",
    "le"."LegalEntity_Name" AS "WorkflowDef_LegalEntityName",
    "d"."WorkflowDef_BrandID",
    "b"."Brand_Name" AS "WorkflowDef_BrandName",
    "d"."WorkflowDef_CustomerOrgID",
    "d"."WorkflowDef_ModeCode",
    "d"."WorkflowDef_DirectionCode",
    "d"."WorkflowDef_CurrentVersionID",
    "cv"."WorkflowDefVer_VersionNo" AS "WorkflowDef_CurrentVersionNo",
    "cv"."WorkflowDefVer_StatusCode" AS "WorkflowDef_CurrentVersionStatus",
    ("count"(DISTINCT "s"."WorkflowStep_ID"))::integer AS "WorkflowDef_StepCount",
    "d"."WorkflowDef_IsDefault",
    "d"."WorkflowDef_IsActive",
    "d"."WorkflowDef_UpdatedAt"
   FROM ((((("public"."Workflow_Definitions" "d"
     LEFT JOIN "public"."cmp_Offices" "o" ON (("o"."Office_ID" = "d"."WorkflowDef_OrgOfficeID")))
     LEFT JOIN "public"."cmp_LegalEntities" "le" ON (("le"."LegalEntity_ID" = "d"."WorkflowDef_LegalEntityID")))
     LEFT JOIN "public"."cmp_Brands" "b" ON (("b"."Brand_ID" = "d"."WorkflowDef_BrandID")))
     LEFT JOIN "public"."Workflow_DefinitionVersions" "cv" ON (("cv"."WorkflowDefVer_ID" = "d"."WorkflowDef_CurrentVersionID")))
     LEFT JOIN "public"."Workflow_Steps" "s" ON (("s"."WorkflowStep_DefinitionVersionID" = "cv"."WorkflowDefVer_ID")))
  WHERE ("d"."WorkflowDef_IsDeleted" = false)
  GROUP BY "d"."WorkflowDef_ID", "o"."Office_Name", "le"."LegalEntity_Name", "b"."Brand_Name", "cv"."WorkflowDefVer_VersionNo", "cv"."WorkflowDefVer_StatusCode";



CREATE OR REPLACE VIEW "public"."Workflow_InstanceSummary" AS
 SELECT "i"."WorkflowInst_ID",
    "i"."WorkflowInst_Name",
    "i"."WorkflowInst_StatusCode",
    "i"."WorkflowInst_PrimaryRecordTypeCode",
    "i"."WorkflowInst_PrimaryRecordID",
    "i"."WorkflowInst_OrgOfficeID",
    "o"."Office_Name" AS "WorkflowInst_OfficeName",
    "i"."WorkflowInst_PriorityCode",
    "i"."WorkflowInst_StartedAt",
    "i"."WorkflowInst_DueAt",
    "i"."WorkflowInst_CompletedAt",
    "i"."WorkflowInst_DefinitionID",
    "d"."WorkflowDef_Code",
    "d"."WorkflowDef_Name",
    ("count"(DISTINCT "t"."WorkflowTask_ID"))::integer AS "WorkflowInst_TaskCount",
    ("count"(DISTINCT "t"."WorkflowTask_ID") FILTER (WHERE "ts"."WorkflowTaskStatus_IsOpen"))::integer AS "WorkflowInst_OpenTaskCount",
    ("count"(DISTINCT "a"."WorkflowApproval_ID") FILTER (WHERE "aps"."WorkflowApprovalStatus_IsOpen"))::integer AS "WorkflowInst_OpenApprovalCount",
    ("count"(DISTINCT "e"."WorkflowEsc_ID") FILTER (WHERE "es"."WorkflowEscStatus_IsOpen"))::integer AS "WorkflowInst_OpenEscalationCount",
    "min"("t"."WorkflowTask_DueAt") FILTER (WHERE "ts"."WorkflowTaskStatus_IsOpen") AS "WorkflowInst_NextTaskDueAt",
    "i"."WorkflowInst_UpdatedAt"
   FROM (((((((("public"."Workflow_Instances" "i"
     LEFT JOIN "public"."Workflow_Definitions" "d" ON (("d"."WorkflowDef_ID" = "i"."WorkflowInst_DefinitionID")))
     LEFT JOIN "public"."cmp_Offices" "o" ON (("o"."Office_ID" = "i"."WorkflowInst_OrgOfficeID")))
     LEFT JOIN "public"."Workflow_Tasks" "t" ON ((("t"."WorkflowTask_InstanceID" = "i"."WorkflowInst_ID") AND ("t"."WorkflowTask_IsDeleted" = false))))
     LEFT JOIN "public"."sys_WorkflowTaskStatuses" "ts" ON ((("ts"."WorkflowTaskStatus_Code")::"text" = ("t"."WorkflowTask_StatusCode")::"text")))
     LEFT JOIN "public"."Workflow_Approvals" "a" ON (("a"."WorkflowApproval_InstanceID" = "i"."WorkflowInst_ID")))
     LEFT JOIN "public"."sys_WorkflowApprovalStatuses" "aps" ON ((("aps"."WorkflowApprovalStatus_Code")::"text" = ("a"."WorkflowApproval_StatusCode")::"text")))
     LEFT JOIN "public"."Workflow_Escalations" "e" ON (("e"."WorkflowEsc_InstanceID" = "i"."WorkflowInst_ID")))
     LEFT JOIN "public"."sys_WorkflowEscalationStatuses" "es" ON ((("es"."WorkflowEscStatus_Code")::"text" = ("e"."WorkflowEsc_StatusCode")::"text")))
  WHERE ("i"."WorkflowInst_IsDeleted" = false)
  GROUP BY "i"."WorkflowInst_ID", "o"."Office_Name", "d"."WorkflowDef_Code", "d"."WorkflowDef_Name";



CREATE OR REPLACE VIEW "public"."Workflow_SLATimerSummary" AS
 SELECT "s"."WorkflowSLATimer_ID",
    "s"."WorkflowSLATimer_InstanceID",
    "s"."WorkflowSLATimer_TaskID",
    "s"."WorkflowSLATimer_ApprovalID",
    "s"."WorkflowSLATimer_RecordTypeCode",
    "s"."WorkflowSLATimer_RecordID",
    "s"."WorkflowSLATimer_StatusCode",
    "s"."WorkflowSLATimer_StartAt",
    "s"."WorkflowSLATimer_WarningAt",
    "s"."WorkflowSLATimer_DueAt",
    "s"."WorkflowSLATimer_CompletedAt",
    "s"."WorkflowSLATimer_BreachedAt",
    "s"."WorkflowSLATimer_PausedAt",
    "s"."WorkflowSLATimer_PausedSeconds",
    "p"."WorkflowSLAProfile_Code",
    "p"."WorkflowSLAProfile_Name",
    "r"."WorkflowSLARule_Code",
    "r"."WorkflowSLARule_Name",
        CASE
            WHEN ("s"."WorkflowSLATimer_CompletedAt" IS NOT NULL) THEN (0)::bigint
            ELSE ("floor"(EXTRACT(epoch FROM ("s"."WorkflowSLATimer_DueAt" - "now"()))))::bigint
        END AS "WorkflowSLATimer_SecondsRemaining",
    ("count"("b"."WorkflowSLABreach_ID"))::integer AS "WorkflowSLATimer_BreachCount",
    ("count"("pa"."WorkflowSLAPause_ID") FILTER (WHERE ("pa"."WorkflowSLAPause_EndedAt" IS NULL)))::integer AS "WorkflowSLATimer_OpenPauseCount"
   FROM (((("public"."Workflow_SLATimers" "s"
     LEFT JOIN "public"."Workflow_SLAProfiles" "p" ON (("p"."WorkflowSLAProfile_ID" = "s"."WorkflowSLATimer_ProfileID")))
     LEFT JOIN "public"."Workflow_SLARules" "r" ON (("r"."WorkflowSLARule_ID" = "s"."WorkflowSLATimer_RuleID")))
     LEFT JOIN "public"."Workflow_SLABreaches" "b" ON (("b"."WorkflowSLABreach_TimerID" = "s"."WorkflowSLATimer_ID")))
     LEFT JOIN "public"."Workflow_SLAPauses" "pa" ON (("pa"."WorkflowSLAPause_TimerID" = "s"."WorkflowSLATimer_ID")))
  GROUP BY "s"."WorkflowSLATimer_ID", "p"."WorkflowSLAProfile_Code", "p"."WorkflowSLAProfile_Name", "r"."WorkflowSLARule_Code", "r"."WorkflowSLARule_Name";



CREATE OR REPLACE VIEW "public"."Workflow_TaskWorklist" AS
 SELECT "t"."WorkflowTask_ID",
    "t"."WorkflowTask_InstanceID",
    "i"."WorkflowInst_Name",
    "t"."WorkflowTask_Title",
    "t"."WorkflowTask_TypeCode",
    "t"."WorkflowTask_StatusCode",
    "ts"."WorkflowTaskStatus_IsOpen",
    "t"."WorkflowTask_PriorityCode",
    "p"."WorkflowPriority_Weight",
    "t"."WorkflowTask_RecordTypeCode",
    "t"."WorkflowTask_RecordID",
    "t"."WorkflowTask_OrgOfficeID",
    "o"."Office_Name" AS "WorkflowTask_OfficeName",
    "t"."WorkflowTask_WorkQueueID",
    "q"."WorkflowQueue_Name",
    "t"."WorkflowTask_AssignedUserID",
    "u"."User_Email" AS "WorkflowTask_AssignedUserEmail",
    "t"."WorkflowTask_AssignedRoleID",
    "t"."WorkflowTask_AssignedGroupID",
    "t"."WorkflowTask_DueAt",
    "t"."WorkflowTask_WarningAt",
    "t"."WorkflowTask_StartedAt",
    "t"."WorkflowTask_CompletedAt",
    ("count"(DISTINCT "td"."WorkflowTaskDep_ID") FILTER (WHERE "dep_status"."WorkflowTaskStatus_IsOpen"))::integer AS "WorkflowTask_OpenBlockingDependencyCount",
    ("count"(DISTINCT "sla"."WorkflowSLATimer_ID") FILTER (WHERE (("sla"."WorkflowSLATimer_StatusCode")::"text" = ANY ((ARRAY['running'::character varying, 'warning'::character varying, 'paused'::character varying, 'breached'::character varying])::"text"[]))))::integer AS "WorkflowTask_ActiveSLACount",
    "max"(("sla"."WorkflowSLATimer_StatusCode")::"text") FILTER (WHERE (("sla"."WorkflowSLATimer_StatusCode")::"text" = ANY ((ARRAY['warning'::character varying, 'breached'::character varying])::"text"[]))) AS "WorkflowTask_WorstSLAStatus",
    "t"."WorkflowTask_UpdatedAt"
   FROM (((((((((("public"."Workflow_Tasks" "t"
     LEFT JOIN "public"."Workflow_Instances" "i" ON (("i"."WorkflowInst_ID" = "t"."WorkflowTask_InstanceID")))
     LEFT JOIN "public"."sys_WorkflowTaskStatuses" "ts" ON ((("ts"."WorkflowTaskStatus_Code")::"text" = ("t"."WorkflowTask_StatusCode")::"text")))
     LEFT JOIN "public"."sys_WorkflowPriorities" "p" ON ((("p"."WorkflowPriority_Code")::"text" = ("t"."WorkflowTask_PriorityCode")::"text")))
     LEFT JOIN "public"."cmp_Offices" "o" ON (("o"."Office_ID" = "t"."WorkflowTask_OrgOfficeID")))
     LEFT JOIN "public"."Workflow_WorkQueues" "q" ON (("q"."WorkflowQueue_ID" = "t"."WorkflowTask_WorkQueueID")))
     LEFT JOIN "public"."cmp_Users" "u" ON (("u"."User_ID" = "t"."WorkflowTask_AssignedUserID")))
     LEFT JOIN "public"."Workflow_TaskDependencies" "td" ON ((("td"."WorkflowTaskDep_TaskID" = "t"."WorkflowTask_ID") AND ("td"."WorkflowTaskDep_IsBlocking" = true))))
     LEFT JOIN "public"."Workflow_Tasks" "dep" ON (("dep"."WorkflowTask_ID" = "td"."WorkflowTaskDep_DependsOnTaskID")))
     LEFT JOIN "public"."sys_WorkflowTaskStatuses" "dep_status" ON ((("dep_status"."WorkflowTaskStatus_Code")::"text" = ("dep"."WorkflowTask_StatusCode")::"text")))
     LEFT JOIN "public"."Workflow_SLATimers" "sla" ON (("sla"."WorkflowSLATimer_TaskID" = "t"."WorkflowTask_ID")))
  WHERE ("t"."WorkflowTask_IsDeleted" = false)
  GROUP BY "t"."WorkflowTask_ID", "i"."WorkflowInst_Name", "ts"."WorkflowTaskStatus_IsOpen", "p"."WorkflowPriority_Weight", "o"."Office_Name", "q"."WorkflowQueue_Name", "u"."User_Email";



CREATE OR REPLACE VIEW "public"."Workflow_WorkQueueSummary" AS
 SELECT "q"."WorkflowQueue_ID",
    "q"."WorkflowQueue_Code",
    "q"."WorkflowQueue_Name",
    "q"."WorkflowQueue_TypeCode",
    "q"."WorkflowQueue_OrgOfficeID",
    "o"."Office_Name" AS "WorkflowQueue_OfficeName",
    "q"."WorkflowQueue_ManagerUserID",
    "m"."User_Email" AS "WorkflowQueue_ManagerEmail",
    "q"."WorkflowQueue_IsActive",
    ("count"(DISTINCT "mem"."WorkflowQueueMember_ID") FILTER (WHERE "mem"."WorkflowQueueMember_IsActive"))::integer AS "WorkflowQueue_ActiveMemberCount",
    ("count"(DISTINCT "t"."WorkflowTask_ID") FILTER (WHERE "ts"."WorkflowTaskStatus_IsOpen"))::integer AS "WorkflowQueue_OpenTaskCount",
    "min"("t"."WorkflowTask_DueAt") FILTER (WHERE "ts"."WorkflowTaskStatus_IsOpen") AS "WorkflowQueue_NextTaskDueAt"
   FROM ((((("public"."Workflow_WorkQueues" "q"
     LEFT JOIN "public"."cmp_Offices" "o" ON (("o"."Office_ID" = "q"."WorkflowQueue_OrgOfficeID")))
     LEFT JOIN "public"."cmp_Users" "m" ON (("m"."User_ID" = "q"."WorkflowQueue_ManagerUserID")))
     LEFT JOIN "public"."Workflow_WorkQueueMembers" "mem" ON (("mem"."WorkflowQueueMember_QueueID" = "q"."WorkflowQueue_ID")))
     LEFT JOIN "public"."Workflow_Tasks" "t" ON ((("t"."WorkflowTask_WorkQueueID" = "q"."WorkflowQueue_ID") AND ("t"."WorkflowTask_IsDeleted" = false))))
     LEFT JOIN "public"."sys_WorkflowTaskStatuses" "ts" ON ((("ts"."WorkflowTaskStatus_Code")::"text" = ("t"."WorkflowTask_StatusCode")::"text")))
  GROUP BY "q"."WorkflowQueue_ID", "o"."Office_Name", "m"."User_Email";



CREATE OR REPLACE TRIGGER "TR_Comm_MessageRecipients_dexter_email_search" AFTER INSERT OR DELETE OR UPDATE OF "CommRecipient_MessageID", "CommRecipient_Address", "CommRecipient_NormalizedAddress", "CommRecipient_DisplayNameSnapshot" ON "public"."Comm_MessageRecipients" FOR EACH ROW EXECUTE FUNCTION "public"."_multideck_refresh_dexter_email_search_from_recipient"();



CREATE OR REPLACE TRIGGER "TR_Comm_Messages_dexter_email_search" AFTER INSERT OR UPDATE OF "CommMessage_Subject", "CommMessage_BodyPreview", "CommMessage_BodyText" ON "public"."Comm_Messages" FOR EACH ROW EXECUTE FUNCTION "public"."_multideck_refresh_dexter_email_search_from_message"();



