CREATE POLICY "Authenticated can update matching Currency_ID" ON "public"."sys_Currency" FOR UPDATE TO "authenticated" USING (((( SELECT "auth"."uid"() AS "uid") IS NOT NULL) AND (( SELECT "auth"."uid"() AS "uid") = "Currency_ID"))) WITH CHECK (((( SELECT "auth"."uid"() AS "uid") IS NOT NULL) AND (( SELECT "auth"."uid"() AS "uid") = "Currency_ID")));



CREATE POLICY "Authenticated staff can read active Customs form options" ON "public"."sys_CustomsFormOptions" FOR SELECT TO "authenticated" USING (((( SELECT "auth"."uid"() AS "uid") IS NOT NULL) AND "CFO_IsActive"));



CREATE POLICY "Authenticated staff can read active countries" ON "public"."RefCountry" FOR SELECT TO "authenticated" USING (((( SELECT "auth"."uid"() AS "uid") IS NOT NULL) AND ("RN_IsActive" = true)));



CREATE POLICY "Authenticated staff can read customs transport modes" ON "public"."sys_CustomsTransportModes" FOR SELECT TO "authenticated" USING ((( SELECT "auth"."uid"() AS "uid") IS NOT NULL));



CREATE POLICY "Authenticated staff can read declaration categories" ON "public"."sys_CDSDeclarationCategories" FOR SELECT TO "authenticated" USING ((( SELECT "auth"."uid"() AS "uid") IS NOT NULL));



