CREATE POLICY "Internal users can manage company customer facility access" ON "public"."WMS_CustomerFacilityAccess" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM (("public"."WMS_Facilities" "facility"
     JOIN "public"."cmp_Offices" "office" ON (("office"."Office_ID" = "facility"."WMSFacility_OrgOfficeID")))
     JOIN "public"."cmp_Users" "app_user" ON (("app_user"."Company_ID" = "office"."Company_ID")))
  WHERE (("facility"."WMSFacility_ID" = "WMS_CustomerFacilityAccess"."WMSCustomerFacilityAccess_FacilityID") AND ("app_user"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid")))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM (("public"."WMS_Facilities" "facility"
     JOIN "public"."cmp_Offices" "office" ON (("office"."Office_ID" = "facility"."WMSFacility_OrgOfficeID")))
     JOIN "public"."cmp_Users" "app_user" ON (("app_user"."Company_ID" = "office"."Company_ID")))
  WHERE (("facility"."WMSFacility_ID" = "WMS_CustomerFacilityAccess"."WMSCustomerFacilityAccess_FacilityID") AND ("app_user"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid"))))));



