CREATE POLICY "Users can create items on their Customs declarations" ON "public"."Customs_Items" FOR INSERT TO "authenticated" WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."Customs_Declarations" "declaration"
  WHERE (("declaration"."CUST_id" = "Customs_Items"."CUSTI_CustomsID") AND ("declaration"."CUST_CreatedBy" = ( SELECT "auth"."uid"() AS "uid")) AND (NOT "declaration"."CUST_IsDeleted")))));



CREATE POLICY "Users can create their Customs declarations" ON "public"."Customs_Declarations" FOR INSERT TO "authenticated" WITH CHECK ((("CUST_CreatedBy" = ( SELECT "auth"."uid"() AS "uid")) AND ("CUST_UpdatedBy" = ( SELECT "auth"."uid"() AS "uid")) AND (NOT "CUST_IsDeleted")));



CREATE POLICY "Users can create their notification preferences" ON "public"."Comm_UserNotificationPreferences" FOR INSERT TO "authenticated" WITH CHECK (((("CommNotifPref_ChannelCode")::"text" = 'email'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."cmp_Users" "workspace_user"
  WHERE (("workspace_user"."User_ID" = "Comm_UserNotificationPreferences"."CommNotifPref_UserID") AND ("workspace_user"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid")))))));



CREATE POLICY "Users can delete items on their Customs declarations" ON "public"."Customs_Items" FOR DELETE TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."Customs_Declarations" "declaration"
  WHERE (("declaration"."CUST_id" = "Customs_Items"."CUSTI_CustomsID") AND ("declaration"."CUST_CreatedBy" = ( SELECT "auth"."uid"() AS "uid")) AND (NOT "declaration"."CUST_IsDeleted")))));



CREATE POLICY "Users can delete their notification preferences" ON "public"."Comm_UserNotificationPreferences" FOR DELETE TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."cmp_Users" "workspace_user"
  WHERE (("workspace_user"."User_ID" = "Comm_UserNotificationPreferences"."CommNotifPref_UserID") AND ("workspace_user"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "Users can read enabled company modules" ON "public"."cmp_Company_Modules" FOR SELECT TO "authenticated" USING (("Company_ID" IN ( SELECT "cmp_Users"."Company_ID"
   FROM "public"."cmp_Users"
  WHERE ("cmp_Users"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid")))));



CREATE POLICY "Users can read items on their Customs declarations" ON "public"."Customs_Items" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."Customs_Declarations" "declaration"
  WHERE (("declaration"."CUST_id" = "Customs_Items"."CUSTI_CustomsID") AND ("declaration"."CUST_CreatedBy" = ( SELECT "auth"."uid"() AS "uid")) AND (NOT "declaration"."CUST_IsDeleted")))));



CREATE POLICY "Users can read their Customs declarations" ON "public"."Customs_Declarations" FOR SELECT TO "authenticated" USING ((("CUST_CreatedBy" = ( SELECT "auth"."uid"() AS "uid")) AND (NOT "CUST_IsDeleted")));



