-- Dexter personal email writing profile snapshot. Operational Vault secret
-- creation and schedule activation remain migration-time concerns.
+
-- A compact, operator-owned style profile. Raw sent-email bodies are selected
-- only inside the bounded generation call and are never persisted here.
create table if not exists public."AI_DexterWritingProfiles" (
  "AIDexterWritingProfile_ID" uuid primary key default gen_random_uuid(),
  "AIDexterWritingProfile_CompanyID" uuid not null references public."cmp_Company"("Company_ID") on delete cascade,
  "AIDexterWritingProfile_UserID" uuid not null references public."cmp_Users"("User_ID") on delete cascade,
  "AIDexterWritingProfile_IsEnabled" boolean not null default false,
  "AIDexterWritingProfile_StatusCode" varchar(24) not null default 'not_started',
  "AIDexterWritingProfile_ProfileText" text not null default '',
  "AIDexterWritingProfile_ProfileJSON" jsonb not null default '{}'::jsonb,
  "AIDexterWritingProfile_EligibleMessageCount" integer not null default 0,
  "AIDexterWritingProfile_AnalysedMessageCount" integer not null default 0,
  "AIDexterWritingProfile_ConsentAt" timestamptz,
  "AIDexterWritingProfile_LastSourceMessageAt" timestamptz,
  "AIDexterWritingProfile_LastCheckedAt" timestamptz,
  "AIDexterWritingProfile_LastGeneratedAt" timestamptz,
  "AIDexterWritingProfile_NextRefreshAt" timestamptz,
  "AIDexterWritingProfile_LastError" varchar(500),
  "AIDexterWritingProfile_GeneratorModel" varchar(120),
  "AIDexterWritingProfile_GeneratorVersion" varchar(120),
  "AIDexterWritingProfile_CreatedAt" timestamptz not null default now(),
  "AIDexterWritingProfile_UpdatedAt" timestamptz not null default now(),
  constraint "UX_AI_DexterWritingProfiles_owner" unique (
    "AIDexterWritingProfile_CompanyID",
    "AIDexterWritingProfile_UserID"
  ),
  constraint "CK_AI_DexterWritingProfiles_status" check (
    "AIDexterWritingProfile_StatusCode" in ('not_started','processing','ready','insufficient','error')
  ),
  constraint "CK_AI_DexterWritingProfiles_text" check (
    char_length("AIDexterWritingProfile_ProfileText") <= 2400
  ),
  constraint "CK_AI_DexterWritingProfiles_profile_object" check (
    jsonb_typeof("AIDexterWritingProfile_ProfileJSON") = 'object'
  ),
  constraint "CK_AI_DexterWritingProfiles_counts" check (
    "AIDexterWritingProfile_EligibleMessageCount" >= 0
    and "AIDexterWritingProfile_AnalysedMessageCount" >= 0
  )
);

create index if not exists "IX_AI_DexterWritingProfiles_due"
  on public."AI_DexterWritingProfiles" (
    "AIDexterWritingProfile_StatusCode",
    "AIDexterWritingProfile_IsEnabled",
    "AIDexterWritingProfile_NextRefreshAt"
  )
  where "AIDexterWritingProfile_IsEnabled";

create table if not exists public."AI_DexterWritingProfileAudit" (
  "AIDexterWritingAudit_ID" uuid primary key default gen_random_uuid(),
  "AIDexterWritingAudit_ProfileID" uuid references public."AI_DexterWritingProfiles"("AIDexterWritingProfile_ID") on delete set null,
  "AIDexterWritingAudit_CompanyID" uuid not null,
  "AIDexterWritingAudit_UserID" uuid not null references public."cmp_Users"("User_ID") on delete cascade,
  "AIDexterWritingAudit_EventCode" varchar(40) not null,
  "AIDexterWritingAudit_StatusCode" varchar(24),
  "AIDexterWritingAudit_MessageCount" integer not null default 0,
  "AIDexterWritingAudit_CreatedAt" timestamptz not null default now(),
  constraint "CK_AI_DexterWritingProfileAudit_event" check (
    "AIDexterWritingAudit_EventCode" in ('consented','generated','refreshed','edited','enabled','disabled','reset','generation_failed','draft_prepared','email_sent','email_queued','email_failed')
  ),
  constraint "CK_AI_DexterWritingProfileAudit_count" check (
    "AIDexterWritingAudit_MessageCount" >= 0
  )
);

create index if not exists "IX_AI_DexterWritingProfileAudit_owner_created"
  on public."AI_DexterWritingProfileAudit" (
    "AIDexterWritingAudit_CompanyID",
    "AIDexterWritingAudit_UserID",
    "AIDexterWritingAudit_CreatedAt" desc
  );

alter table public."AI_DexterWritingProfiles" enable row level security;
alter table public."AI_DexterWritingProfileAudit" enable row level security;
revoke all on table public."AI_DexterWritingProfiles", public."AI_DexterWritingProfileAudit"
  from public, anon, authenticated;
grant all on table public."AI_DexterWritingProfiles", public."AI_DexterWritingProfileAudit"
  to service_role;

create or replace function public._multideck_dexter_writing_profile_audit(
  p_profile_id uuid,
  p_company_id uuid,
  p_user_id uuid,
  p_event text,
  p_status text default null,
  p_message_count integer default 0
)
returns void
language sql
volatile
security definer
set search_path = pg_catalog, public
as $$
  insert into public."AI_DexterWritingProfileAudit" (
    "AIDexterWritingAudit_ProfileID",
    "AIDexterWritingAudit_CompanyID",
    "AIDexterWritingAudit_UserID",
    "AIDexterWritingAudit_EventCode",
    "AIDexterWritingAudit_StatusCode",
    "AIDexterWritingAudit_MessageCount"
  ) values (
    p_profile_id,
    p_company_id,
    p_user_id,
    left(btrim(coalesce(p_event, '')), 40),
    nullif(left(btrim(coalesce(p_status, '')), 24), ''),
    greatest(coalesce(p_message_count, 0), 0)
  );
$$;

revoke all on function public._multideck_dexter_writing_profile_audit(uuid, uuid, uuid, text, text, integer)
  from public, anon, authenticated;
grant execute on function public._multideck_dexter_writing_profile_audit(uuid, uuid, uuid, text, text, integer)
  to service_role;

create or replace function public._multideck_dexter_writing_profile_source_for(
  p_company_id uuid,
  p_user_id uuid,
  p_take integer default 40,
  p_after timestamptz default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  v_take integer := least(greatest(coalesce(p_take, 40), 1), 40);
  v_result jsonb;
begin
  if not public._multideck_dexter_has_permission(p_user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(p_user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public."cmp_Users" profile
    where profile."User_ID" = p_user_id
      and profile."Company_ID" = p_company_id
  ) then
    raise exception 'This operator is outside the tenant workspace.' using errcode = '42501';
  end if;

  with permitted_mailboxes as materialized (
    select permitted.mailbox_id
    from public._multideck_dexter_email_mailboxes(p_user_id, p_company_id) permitted
  ),
  eligible as materialized (
    select
      message."CommMessage_ID" as message_id,
      message."CommMessage_ThreadID" as thread_id,
      message."CommMessage_BodyText" as body_text,
      coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") as occurred_at,
      coalesce(recipients.recipient_key, message."CommMessage_ThreadID"::text) as recipient_key,
      row_number() over (
        partition by message."CommMessage_ThreadID"
        order by coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") desc,
          message."CommMessage_ID" desc
      ) as thread_rank
    from public."Comm_Messages" message
    join permitted_mailboxes permitted on permitted.mailbox_id = message."CommMessage_MailboxID"
    join public."Comm_Mailboxes" mailbox on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
    join public."Comm_ProviderConnections" connection on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
    left join lateral (
      select min(recipient."CommRecipient_NormalizedAddress") as recipient_key
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'to'
        and recipient."CommRecipient_IsExternal"
        and not recipient."CommRecipient_IsSuppressed"
    ) recipients on true
    where message."CommMessage_DirectionCode" = 'outbound'
      and not message."CommMessage_IsInbound"
      and message."CommMessage_StatusCode" in ('sent','delivered')
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsBodyRedacted"
      and nullif(btrim(message."CommMessage_BodyText"), '') is not null
      and char_length(btrim(message."CommMessage_BodyText")) between 40 and 12000
      and coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '12 months'
      and (p_after is null or coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") > p_after)
      and (
        (
          mailbox."CommMailbox_TypeCode" = 'personal'
          and mailbox."CommMailbox_UserID" = p_user_id
          and connection."CommConn_UserID" = p_user_id
        )
        or message."CommMessage_CreatedBy" = p_user_id
      )
      and lower(coalesce(message."CommMessage_Subject", '') || ' ' || left(message."CommMessage_BodyText", 800)) !~
        '(automatic reply|auto.?reply|out of office|undeliverable|delivery status|mail delivery|do.?not.?reply|no.?reply|newsletter|unsubscribe|password reset|verification code|support ticket)'
  ),
  diversified as materialized (
    select eligible.*,
      row_number() over (
        partition by eligible.recipient_key
        order by eligible.occurred_at desc, eligible.message_id desc
      ) as recipient_rank
    from eligible
    where thread_rank = 1
  ),
  selected as (
    select * from diversified
    order by recipient_rank, occurred_at desc, message_id desc
    limit v_take
  )
  select jsonb_build_object(
    'eligibleCount', (select count(*) from diversified),
    'messages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'messageId', selected.message_id,
          'bodyText', selected.body_text,
          'occurredAt', selected.occurred_at
        ) order by selected.occurred_at desc, selected.message_id desc
      ) from selected
    ), '[]'::jsonb),
    'latestMessageAt', (select max(occurred_at) from diversified)
  ) into v_result;

  return coalesce(v_result, jsonb_build_object('eligibleCount', 0, 'messages', '[]'::jsonb, 'latestMessageAt', null));
end;
$$;

revoke all on function public._multideck_dexter_writing_profile_source_for(uuid, uuid, integer, timestamptz)
  from public, anon, authenticated;
grant execute on function public._multideck_dexter_writing_profile_source_for(uuid, uuid, integer, timestamptz)
  to service_role;

-- Raw source samples are available only to the privileged profile generator.
-- Browser roles manage the derived profile through the owner-scoped RPCs below.

create or replace function public.multideck_dexter_get_writing_profile()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_profile public."AI_DexterWritingProfiles";
  v_source jsonb;
  v_exists boolean := false;
begin
  select * into v_context from public._multideck_dexter_context();
  select * into v_profile
  from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id;
  v_exists := found;

  begin
    v_source := public._multideck_dexter_writing_profile_source_for(v_context.company_id, v_context.user_id, 1, null);
  exception when insufficient_privilege then
    v_source := jsonb_build_object('eligibleCount', 0, 'messages', '[]'::jsonb, 'latestMessageAt', null);
  end;

  return jsonb_build_object(
    'exists', v_exists,
    'enabled', coalesce(v_profile."AIDexterWritingProfile_IsEnabled", false),
    'status', coalesce(v_profile."AIDexterWritingProfile_StatusCode", 'not_started'),
    'profileText', coalesce(v_profile."AIDexterWritingProfile_ProfileText", ''),
    'eligibleMessageCount', greatest(coalesce((v_source ->> 'eligibleCount')::integer, v_profile."AIDexterWritingProfile_EligibleMessageCount", 0), 0),
    'analysedMessageCount', coalesce(v_profile."AIDexterWritingProfile_AnalysedMessageCount", 0),
    'consentedAt', v_profile."AIDexterWritingProfile_ConsentAt",
    'lastGeneratedAt', v_profile."AIDexterWritingProfile_LastGeneratedAt",
    'nextRefreshAt', v_profile."AIDexterWritingProfile_NextRefreshAt",
    'lastError', v_profile."AIDexterWritingProfile_LastError"
  );
end;
$$;

revoke all on function public.multideck_dexter_get_writing_profile() from public, anon;
grant execute on function public.multideck_dexter_get_writing_profile() to authenticated;

create or replace function public.multideck_dexter_begin_writing_profile()
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_profile_id uuid;
  v_already_consented boolean := false;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select profile."AIDexterWritingProfile_ConsentAt" is not null
  into v_already_consented
  from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id;

  insert into public."AI_DexterWritingProfiles" (
    "AIDexterWritingProfile_CompanyID",
    "AIDexterWritingProfile_UserID",
    "AIDexterWritingProfile_IsEnabled",
    "AIDexterWritingProfile_StatusCode",
    "AIDexterWritingProfile_ConsentAt",
    "AIDexterWritingProfile_LastError",
    "AIDexterWritingProfile_UpdatedAt"
  ) values (
    v_context.company_id,
    v_context.user_id,
    true,
    'processing',
    now(),
    null,
    now()
  )
  on conflict ("AIDexterWritingProfile_CompanyID", "AIDexterWritingProfile_UserID") do update
  set "AIDexterWritingProfile_IsEnabled" = true,
      "AIDexterWritingProfile_StatusCode" = 'processing',
      "AIDexterWritingProfile_ConsentAt" = coalesce(public."AI_DexterWritingProfiles"."AIDexterWritingProfile_ConsentAt", now()),
      "AIDexterWritingProfile_LastError" = null,
      "AIDexterWritingProfile_UpdatedAt" = now()
  returning "AIDexterWritingProfile_ID" into v_profile_id;

  if not coalesce(v_already_consented, false) then
    perform public._multideck_dexter_writing_profile_audit(
      v_profile_id, v_context.company_id, v_context.user_id, 'consented', 'processing', 0
    );
  end if;
  return public.multideck_dexter_get_writing_profile();
end;
$$;

revoke all on function public.multideck_dexter_begin_writing_profile() from public, anon;
grant execute on function public.multideck_dexter_begin_writing_profile() to authenticated;

create or replace function public.multideck_dexter_update_writing_profile(
  p_enabled boolean,
  p_profile_text text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_profile_id uuid;
  v_profile_text text := btrim(coalesce(p_profile_text, ''));
  v_event text;
begin
  select * into v_context from public._multideck_dexter_context();
  if char_length(v_profile_text) > 2400 then
    raise exception 'Keep the writing profile within 2,400 characters.' using errcode = '22023';
  end if;

  update public."AI_DexterWritingProfiles" profile
  set "AIDexterWritingProfile_IsEnabled" = coalesce(p_enabled, false),
      "AIDexterWritingProfile_ProfileText" = v_profile_text,
      "AIDexterWritingProfile_StatusCode" = case
        when v_profile_text = '' then 'not_started'
        else 'ready'
      end,
      "AIDexterWritingProfile_LastError" = null,
      "AIDexterWritingProfile_UpdatedAt" = now()
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id
  returning profile."AIDexterWritingProfile_ID" into v_profile_id;

  if not found then
    raise exception 'Create your writing profile before editing it.' using errcode = 'P0002';
  end if;

  v_event := case when not coalesce(p_enabled, false) then 'disabled' else 'edited' end;
  perform public._multideck_dexter_writing_profile_audit(
    v_profile_id, v_context.company_id, v_context.user_id, v_event,
    case when v_profile_text = '' then 'not_started' else 'ready' end, 0
  );
  return public.multideck_dexter_get_writing_profile();
end;
$$;

revoke all on function public.multideck_dexter_update_writing_profile(boolean, text) from public, anon;
grant execute on function public.multideck_dexter_update_writing_profile(boolean, text) to authenticated;

create or replace function public.multideck_dexter_reset_writing_profile()
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_profile_id uuid;
begin
  select * into v_context from public._multideck_dexter_context();
  delete from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id
  returning profile."AIDexterWritingProfile_ID" into v_profile_id;
  if v_profile_id is not null then
    perform public._multideck_dexter_writing_profile_audit(
      null, v_context.company_id, v_context.user_id, 'reset', 'not_started', 0
    );
  end if;
  return public.multideck_dexter_get_writing_profile();
end;
$$;

revoke all on function public.multideck_dexter_reset_writing_profile() from public, anon;
grant execute on function public.multideck_dexter_reset_writing_profile() to authenticated;

-- Narrow compose context for server-confirmed reply and reply-all fields. This
-- deliberately excludes message bodies; Dexter's existing email tools provide
-- content only when the operator has selected or searched for it.
create or replace function public.multideck_dexter_resolve_email_draft_source(
  p_message_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'messageId', message."CommMessage_ID",
    'threadId', message."CommMessage_ThreadID",
    'mailboxId', message."CommMessage_MailboxID",
    'mailboxAddress', coalesce(mailbox."CommMailbox_NormalizedAddress", mailbox."CommMailbox_Address", ''),
    'direction', message."CommMessage_DirectionCode",
    'subject', coalesce(message."CommMessage_Subject", ''),
    'from', coalesce((
      select jsonb_agg(jsonb_build_object(
        'address', recipient."CommRecipient_Address",
        'displayName', recipient."CommRecipient_DisplayNameSnapshot"
      ) order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID")
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'from'
        and not recipient."CommRecipient_IsSuppressed"
    ), '[]'::jsonb),
    'to', coalesce((
      select jsonb_agg(jsonb_build_object(
        'address', recipient."CommRecipient_Address",
        'displayName', recipient."CommRecipient_DisplayNameSnapshot"
      ) order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID")
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'to'
        and not recipient."CommRecipient_IsSuppressed"
    ), '[]'::jsonb),
    'cc', coalesce((
      select jsonb_agg(jsonb_build_object(
        'address', recipient."CommRecipient_Address",
        'displayName', recipient."CommRecipient_DisplayNameSnapshot"
      ) order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID")
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'cc'
        and not recipient."CommRecipient_IsSuppressed"
    ), '[]'::jsonb)
  ) into v_result
  from public."Comm_Messages" message
  join public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id) permitted
    on permitted.mailbox_id = message."CommMessage_MailboxID"
  join public."Comm_Mailboxes" mailbox
    on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
  where message."CommMessage_ID" = p_message_id
    and not message."CommMessage_IsDeleted"
    and not message."CommMessage_IsDraft"
    and not message."CommMessage_IsSpam"
    and not exists (
      select 1
      from public."Comm_MessageFolders" membership
      join public."Comm_MailFolders" folder
        on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
        and folder."CommMailFolder_RoleCode" in ('drafts','spam','trash')
    );

  if v_result is null then
    raise exception 'This email update was not found.' using errcode = 'P0002';
  end if;
  return v_result;
end;
$$;

revoke all on function public.multideck_dexter_resolve_email_draft_source(uuid)
  from public, anon;
grant execute on function public.multideck_dexter_resolve_email_draft_source(uuid)
  to authenticated;

create or replace function public.multideck_dexter_record_writing_profile_event(
  p_event text
)
returns void
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_profile_id uuid;
begin
  if p_event <> 'draft_prepared' then
    raise exception 'This writing-profile event is not supported.' using errcode = '22023';
  end if;
  select * into v_context from public._multideck_dexter_context();
  select profile."AIDexterWritingProfile_ID" into v_profile_id
  from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id;
  perform public._multideck_dexter_writing_profile_audit(
    v_profile_id, v_context.company_id, v_context.user_id, p_event, null, 0
  );
end;
$$;

revoke all on function public.multideck_dexter_record_writing_profile_event(text)
  from public, anon;
grant execute on function public.multideck_dexter_record_writing_profile_event(text)
  to authenticated;

-- Extend the saved conversation payload with a structured email draft while
-- keeping all existing response-version, attachment and reasoning metadata.
create or replace function public._multideck_dexter_conversation_json(
  p_conversation_id uuid,
  p_user_id uuid,
  p_company_id uuid
)
returns jsonb
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select jsonb_build_object(
    'id', conversation."AICNV_ID",
    'title', coalesce(conversation."AICNV_Title", 'Dexter conversation'),
    'summary', coalesce(conversation."AICNV_SummaryText", ''),
    'updatedAt', conversation."AICNV_UpdatedAt",
    'messages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', message."AIMSG_ID",
          'role', message."AIMSG_Role",
          'content', message."AIMSG_ContentText",
          'createdAt', message."AIMSG_CreatedAt",
          'specialist', nullif(message."AIMSG_ContentJSON" ->> 'specialist', ''),
          'attachments', case when jsonb_typeof(message."AIMSG_ContentJSON" -> 'attachments') = 'array'
            then message."AIMSG_ContentJSON" -> 'attachments' else '[]'::jsonb end,
          'parentResponseMessageId', nullif(message."AIMSG_ContentJSON" #>> '{metadata,parentResponseMessageId}', ''),
          'pendingAction', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,pendingAction}') = 'object'
            then message."AIMSG_ContentJSON" #> '{metadata,pendingAction}' else null end,
          'reasoningSummary', nullif(message."AIMSG_ContentJSON" #>> '{metadata,reasoningSummary}', ''),
          'emailAttachments', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}') = 'array'
            then message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}' else '[]'::jsonb end,
          'emailDraft', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
            then message."AIMSG_ContentJSON" #> '{metadata,emailDraft}' else null end,
          'responseToUserMessageId', nullif(message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}', ''),
          'responseVersion', case when coalesce(message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}', '') ~ '^[1-9][0-9]*$'
            then (message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer else null end
        ) order by message."AIMSG_CreatedAt", message."AIMSG_ID"
      )
      from public."AI_Messages" message
      where message."AIMSG_ConversationID" = conversation."AICNV_ID"
        and message."AIMSG_ContentText" is not null
    ), '[]'::jsonb)
  )
  from public."AI_Conversations" conversation
  where conversation."AICNV_ID" = p_conversation_id
    and conversation."AICNV_CompanyID" = p_company_id
    and conversation."AICNV_OwnerUserID" = p_user_id
    and conversation."AICNV_Channel" = 'chat'
    and conversation."AICNV_EndedAt" is null
    and conversation."AICNV_DomainCode" in ('multideck', 'warehouse');
$$;

create or replace function public.multideck_dexter_record_email_draft_delivery(
  p_message_id uuid,
  p_send_request_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_message public."AI_Messages";
  v_send public."Comm_SendRequests";
  v_status text;
begin
  select * into v_context from public._multideck_dexter_context();
  select message.* into v_message
  from public."AI_Messages" message
  join public."AI_Conversations" conversation on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_ID" = p_message_id
    and message."AIMSG_Role" = 'assistant'
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
  for update;
  if not found then
    raise exception 'This Dexter email draft is unavailable.' using errcode = 'P0002';
  end if;

  select send.* into v_send
  from public."Comm_SendRequests" send
  where send."CommSend_ID" = p_send_request_id
    and send."CommSend_RequestedBy" = v_context.user_id;
  if not found then
    raise exception 'This email send receipt is unavailable.' using errcode = 'P0002';
  end if;

  v_status := case lower(v_send."CommSend_StatusCode")
    when 'sent' then 'sent'
    when 'delivered' then 'sent'
    when 'failed' then 'failed'
    else 'queued'
  end;

  update public."AI_Messages"
  set "AIMSG_ContentJSON" = jsonb_set(
    "AIMSG_ContentJSON",
    '{metadata,emailDraft,delivery}',
    jsonb_strip_nulls(jsonb_build_object(
      'status', v_status,
      'sendRequestId', v_send."CommSend_ID",
      'messageId', v_send."CommSend_MessageID",
      'threadId', v_send."CommSend_ThreadID",
      'updatedAt', v_send."CommSend_UpdatedAt"
    )),
    true
  )
  where "AIMSG_ID" = p_message_id;

  perform public._multideck_dexter_writing_profile_audit(
    null, v_context.company_id, v_context.user_id,
    case v_status when 'sent' then 'email_sent' when 'failed' then 'email_failed' else 'email_queued' end,
    v_status, 0
  );

  return jsonb_build_object(
    'status', v_status,
    'sendRequestId', v_send."CommSend_ID",
    'messageId', v_send."CommSend_MessageID",
    'threadId', v_send."CommSend_ThreadID",
    'updatedAt', v_send."CommSend_UpdatedAt"
  );
end;
$$;

revoke all on function public.multideck_dexter_record_email_draft_delivery(uuid, uuid)
  from public, anon;
grant execute on function public.multideck_dexter_record_email_draft_delivery(uuid, uuid)
  to authenticated;

create or replace function public.multideck_dexter_duplicate_sent_email_draft(
  p_message_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_message public."AI_Messages";
  v_new_message_id uuid := gen_random_uuid();
  v_new_draft jsonb;
  v_content jsonb;
  v_response_version integer;
begin
  select * into v_context from public._multideck_dexter_context();
  select message.* into v_message
  from public."AI_Messages" message
  join public."AI_Conversations" conversation
    on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_ID" = p_message_id
    and message."AIMSG_Role" = 'assistant'
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
  for update;
  if not found then
    raise exception 'This Dexter email draft is unavailable.' using errcode = 'P0002';
  end if;

  if coalesce(v_message."AIMSG_ContentJSON" #>> '{metadata,emailDraft,delivery,status}', 'draft') <> 'sent' then
    raise exception 'Only a sent email can be copied into a new draft.' using errcode = '22023';
  end if;

  v_new_draft := jsonb_set(
    jsonb_set(
      v_message."AIMSG_ContentJSON" #> '{metadata,emailDraft}',
      '{id}', to_jsonb(gen_random_uuid()::text), true
    ),
    '{delivery}', jsonb_build_object('status', 'draft'), true
  );
  v_response_version := greatest(
    coalesce((v_message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer, 1) + 1,
    2
  );
  v_content := jsonb_set(
    jsonb_set(v_message."AIMSG_ContentJSON", '{metadata,emailDraft}', v_new_draft, true),
    '{metadata,responseVersion}', to_jsonb(v_response_version), true
  );

  insert into public."AI_Messages" (
    "AIMSG_ID", "AIMSG_ConversationID", "AIMSG_ParentMessageID", "AIMSG_Role",
    "AIMSG_ModelID", "AIMSG_ContentText", "AIMSG_ContentJSON", "AIMSG_SecurityClass",
    "AIMSG_IsTrainingCandidate", "AIMSG_IsTrainingAllowed", "AIMSG_CreatedAt", "AIMSG_CreatedBy"
  ) values (
    v_new_message_id, v_message."AIMSG_ConversationID", v_message."AIMSG_ParentMessageID", 'assistant',
    v_message."AIMSG_ModelID", v_message."AIMSG_ContentText", v_content, v_message."AIMSG_SecurityClass",
    false, false, now(), v_context.user_id
  );

  return jsonb_build_object('messageId', v_new_message_id, 'draft', v_new_draft);
end;
$$;

revoke all on function public.multideck_dexter_duplicate_sent_email_draft(uuid)
  from public, anon;
grant execute on function public.multideck_dexter_duplicate_sent_email_draft(uuid)
  to authenticated;

create or replace function public.multideck_dexter_update_email_draft(
  p_message_id uuid,
  p_draft jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  v_context record;
  v_message public."AI_Messages";
  v_current_delivery jsonb;
  v_draft jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if jsonb_typeof(p_draft) <> 'object'
     or coalesce(p_draft ->> 'mode', '') not in ('new','reply','reply_all','forward')
     or jsonb_typeof(coalesce(p_draft -> 'to', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_draft -> 'cc', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_draft -> 'bcc', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_draft -> 'to', '[]'::jsonb)) > 50
     or jsonb_array_length(coalesce(p_draft -> 'cc', '[]'::jsonb)) > 50
     or jsonb_array_length(coalesce(p_draft -> 'bcc', '[]'::jsonb)) > 50
     or char_length(coalesce(p_draft ->> 'subject', '')) > 500
     or char_length(coalesce(p_draft ->> 'bodyText', '')) > 50000
     or pg_column_size(p_draft) > 100000 then
    raise exception 'This email draft is not valid.' using errcode = '22023';
  end if;

  select message.* into v_message
  from public."AI_Messages" message
  join public."AI_Conversations" conversation on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_ID" = p_message_id
    and message."AIMSG_Role" = 'assistant'
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
  for update;
  if not found then
    raise exception 'This Dexter email draft is unavailable.' using errcode = 'P0002';
  end if;

  v_current_delivery := coalesce(
    v_message."AIMSG_ContentJSON" #> '{metadata,emailDraft,delivery}',
    jsonb_build_object('status', 'draft')
  );
  if coalesce(v_current_delivery ->> 'status', 'draft') = 'sent' then
    raise exception 'A sent email cannot be edited.' using errcode = '22023';
  end if;

  v_draft := jsonb_strip_nulls(jsonb_build_object(
    'id', left(coalesce(p_draft ->> 'id', gen_random_uuid()::text), 80),
    'mode', p_draft ->> 'mode',
    'mailboxId', nullif(left(coalesce(p_draft ->> 'mailboxId', ''), 80), ''),
    'sourceMessageId', nullif(left(coalesce(p_draft ->> 'sourceMessageId', ''), 80), ''),
    'threadId', nullif(left(coalesce(p_draft ->> 'threadId', ''), 80), ''),
    'to', coalesce(p_draft -> 'to', '[]'::jsonb),
    'cc', coalesce(p_draft -> 'cc', '[]'::jsonb),
    'bcc', coalesce(p_draft -> 'bcc', '[]'::jsonb),
    'subject', left(coalesce(p_draft ->> 'subject', ''), 500),
    'bodyText', left(coalesce(p_draft ->> 'bodyText', ''), 50000),
    'trackOpens', coalesce((p_draft ->> 'trackOpens')::boolean, false),
    'delivery', v_current_delivery
  ));

  update public."AI_Messages"
  set "AIMSG_ContentJSON" = jsonb_set(
    "AIMSG_ContentJSON", '{metadata,emailDraft}', v_draft, true
  )
  where "AIMSG_ID" = p_message_id;
  return v_draft;
end;
$$;

revoke all on function public.multideck_dexter_update_email_draft(uuid, jsonb)
  from public, anon;
grant execute on function public.multideck_dexter_update_email_draft(uuid, jsonb)
  to authenticated;

create or replace function public."AI_GetDexterWritingProfileWorkerSecret"()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select decrypted_secret
  from vault.decrypted_secrets
  where name = 'multideck_dexter_writing_profile_worker_secret'
  limit 1;
$$;

revoke all on function public."AI_GetDexterWritingProfileWorkerSecret"()
  from public, anon, authenticated;
grant execute on function public."AI_GetDexterWritingProfileWorkerSecret"()
  to service_role;

create extension if not exists pg_cron;
create extension if not exists pg_net;

create or replace function public."AI_ConfigureDexterWritingProfileSchedule"()
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_endpoint text;
  v_job_id bigint;
begin
  select decrypted_secret into v_endpoint
  from vault.decrypted_secrets
  where name = 'multideck_dexter_writing_profile_worker_endpoint'
  limit 1;

  if nullif(btrim(v_endpoint), '') is null then
    return false;
  end if;

  for v_job_id in
    select jobid from cron.job
    where jobname = 'multideck-dexter-writing-profile-refresh'
  loop
    perform cron.unschedule(v_job_id);
  end loop;

  perform cron.schedule(
    'multideck-dexter-writing-profile-refresh',
    '15 3 * * *',
    format(
      $command$
        select net.http_post(
          url := %L,
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'x-multideck-writing-profile-secret', (
              select decrypted_secret
              from vault.decrypted_secrets
              where name = 'multideck_dexter_writing_profile_worker_secret'
              limit 1
            )
          ),
          body := jsonb_build_object('operation', 'monthly', 'requestedAt', now()),
          timeout_milliseconds := 55000
        );
      $command$,
      btrim(v_endpoint)
    )
  );

  return true;
end;
$$;

revoke all on function public."AI_ConfigureDexterWritingProfileSchedule"()
  from public, anon, authenticated, service_role;

-- Each tenant installs its own endpoint secret. The daily check performs work
-- only for profiles whose monthly refresh is due and have ten new messages.

comment on table public."AI_DexterWritingProfiles" is
  'Private, operator-owned email style guidance derived with explicit consent. Raw source emails are never stored here.';
comment on function public._multideck_dexter_writing_profile_source_for(uuid, uuid, integer, timestamptz) is
  'Selects bounded, provably authored sent email for one operator. Private preferences do not emit Watching for you signals.';

-- Warehouse purchase orders. Kept in the baseline so newly provisioned tenant
-- projects receive the same schema, Edge boundary, Dexter domain and watches.
-- Warehouse purchase orders: operator-entered and document-extracted headers and lines.
-- Browser clients use the authenticated Warehouse Edge Function. Header/line writes
-- remain atomic and service-role-only, with immutable events and deterministic watches.

create table if not exists public."WMS_PurchaseOrders" (
  "WMSPO_ID" uuid primary key default gen_random_uuid(),
  "WMSPO_FacilityID" uuid not null references public."WMS_Facilities"("WMSFacility_ID"),
  "WMSPO_CustomerOrgID" uuid not null references public."Org_Master"("Org_id"),
  "WMSPO_SupplierOrgID" uuid references public."Org_Master"("Org_id"),
  "WMSPO_WarehouseOrderID" uuid references public."WMS_Orders"("WMSOrder_ID"),
  "WMSPO_Number" varchar(120) not null,
  "WMSPO_StatusCode" varchar(30) not null default 'draft',
  "WMSPO_SupplierName" varchar(240) not null,
  "WMSPO_BuyerReference" varchar(160),
  "WMSPO_SupplierReference" varchar(160),
  "WMSPO_IssueDate" date,
  "WMSPO_ExpectedDeliveryDate" date,
  "WMSPO_CurrencyCode" varchar(3) not null default 'GBP',
  "WMSPO_DeliveryTerms" varchar(180),
  "WMSPO_PaymentTerms" varchar(180),
  "WMSPO_DeliveryAddress" text,
  "WMSPO_Notes" text,
  "WMSPO_NetAmount" numeric(18,4) not null default 0,
  "WMSPO_TaxAmount" numeric(18,4) not null default 0,
  "WMSPO_TotalAmount" numeric(18,4) not null default 0,
  "WMSPO_SourceFileName" varchar(240),
  "WMSPO_ExtractionModeCode" varchar(40),
  "WMSPO_ExtractionModel" varchar(120),
  "WMSPO_ExtractionMetadataJSON" jsonb not null default '{}'::jsonb,
  "WMSPO_Version" integer not null default 1,
  "WMSPO_CreatedAt" timestamptz not null default now(),
  "WMSPO_CreatedBy" uuid references public."cmp_Users"("User_ID"),
  "WMSPO_UpdatedAt" timestamptz not null default now(),
  "WMSPO_UpdatedBy" uuid references public."cmp_Users"("User_ID"),
  "WMSPO_IsDeleted" boolean not null default false,
  constraint "CK_WMS_PurchaseOrders_status" check ("WMSPO_StatusCode" in ('draft','issued','part_received','received','cancelled')),
  constraint "CK_WMS_PurchaseOrders_currency" check ("WMSPO_CurrencyCode" ~ '^[A-Z]{3}$'),
  constraint "CK_WMS_PurchaseOrders_amounts" check ("WMSPO_NetAmount" >= 0 and "WMSPO_TaxAmount" >= 0 and "WMSPO_TotalAmount" >= 0),
  constraint "CK_WMS_PurchaseOrders_extraction" check (jsonb_typeof("WMSPO_ExtractionMetadataJSON") = 'object')
);

create unique index if not exists "UX_WMS_PurchaseOrders_facility_number"
  on public."WMS_PurchaseOrders"("WMSPO_FacilityID", lower("WMSPO_Number")) where not "WMSPO_IsDeleted";
create index if not exists "IX_WMS_PurchaseOrders_facility_status"
  on public."WMS_PurchaseOrders"("WMSPO_FacilityID", "WMSPO_StatusCode", "WMSPO_UpdatedAt" desc);

create table if not exists public."WMS_PurchaseOrderLines" (
  "WMSPOLine_ID" uuid primary key default gen_random_uuid(),
  "WMSPOLine_PurchaseOrderID" uuid not null references public."WMS_PurchaseOrders"("WMSPO_ID") on delete cascade,
  "WMSPOLine_LineNo" integer not null,
  "WMSPOLine_ItemID" uuid references public."WMS_Items"("WMSItem_ID"),
  "WMSPOLine_SKU" varchar(120),
  "WMSPOLine_SupplierItemCode" varchar(120),
  "WMSPOLine_Description" varchar(800) not null,
  "WMSPOLine_OrderedQuantity" numeric(18,6) not null,
  "WMSPOLine_ReceivedQuantity" numeric(18,6) not null default 0,
  "WMSPOLine_UOMCode" varchar(20) not null default 'EA',
  "WMSPOLine_UnitPrice" numeric(18,6) not null default 0,
  "WMSPOLine_TaxRate" numeric(9,4) not null default 0,
  "WMSPOLine_NetAmount" numeric(18,4) not null default 0,
  "WMSPOLine_TaxAmount" numeric(18,4) not null default 0,
  "WMSPOLine_TotalAmount" numeric(18,4) not null default 0,
  "WMSPOLine_RequestedDeliveryDate" date,
  "WMSPOLine_MetadataJSON" jsonb not null default '{}'::jsonb,
  "WMSPOLine_CreatedAt" timestamptz not null default now(),
  constraint "UX_WMS_PurchaseOrderLines_order_line" unique ("WMSPOLine_PurchaseOrderID", "WMSPOLine_LineNo"),
  constraint "CK_WMS_PurchaseOrderLines_quantity" check ("WMSPOLine_OrderedQuantity" > 0 and "WMSPOLine_ReceivedQuantity" >= 0),
  constraint "CK_WMS_PurchaseOrderLines_money" check ("WMSPOLine_UnitPrice" >= 0 and "WMSPOLine_TaxRate" >= 0 and "WMSPOLine_NetAmount" >= 0 and "WMSPOLine_TaxAmount" >= 0 and "WMSPOLine_TotalAmount" >= 0),
  constraint "CK_WMS_PurchaseOrderLines_metadata" check (jsonb_typeof("WMSPOLine_MetadataJSON") = 'object')
);
create index if not exists "IX_WMS_PurchaseOrderLines_item" on public."WMS_PurchaseOrderLines"("WMSPOLine_ItemID");

create table if not exists public."WMS_PurchaseOrderEvents" (
  "WMSPOEvent_ID" uuid primary key default gen_random_uuid(),
  "WMSPOEvent_PurchaseOrderID" uuid not null references public."WMS_PurchaseOrders"("WMSPO_ID") on delete cascade,
  "WMSPOEvent_EventTypeCode" varchar(60) not null,
  "WMSPOEvent_EventAt" timestamptz not null default now(),
  "WMSPOEvent_FromStatusCode" varchar(30),
  "WMSPOEvent_ToStatusCode" varchar(30),
  "WMSPOEvent_Notes" text,
  "WMSPOEvent_MetadataJSON" jsonb not null default '{}'::jsonb,
  "WMSPOEvent_CreatedBy" uuid references public."cmp_Users"("User_ID"),
  constraint "CK_WMS_PurchaseOrderEvents_metadata" check (jsonb_typeof("WMSPOEvent_MetadataJSON") = 'object')
);
create index if not exists "IX_WMS_PurchaseOrderEvents_order_time" on public."WMS_PurchaseOrderEvents"("WMSPOEvent_PurchaseOrderID", "WMSPOEvent_EventAt" desc);

alter table public."WMS_PurchaseOrders" enable row level security;
alter table public."WMS_PurchaseOrderLines" enable row level security;
alter table public."WMS_PurchaseOrderEvents" enable row level security;
revoke all on public."WMS_PurchaseOrders", public."WMS_PurchaseOrderLines", public."WMS_PurchaseOrderEvents" from public, anon, authenticated;
grant select, insert, update, delete on public."WMS_PurchaseOrders", public."WMS_PurchaseOrderLines", public."WMS_PurchaseOrderEvents" to service_role;

create or replace function public.warehouse_edge_purchase_order_mutation(
  p_action text,
  p_purchase_order_id uuid,
  p_payload jsonb,
  p_actor_user_id uuid,
  p_allowed_facility_ids uuid[]
) returns uuid language plpgsql security definer set search_path = pg_catalog, public as $$
declare
  v_po public."WMS_PurchaseOrders"%rowtype;
  v_id uuid := coalesce(p_purchase_order_id, gen_random_uuid());
  v_facility_id uuid;
  v_customer_org_id uuid;
  v_supplier_org_id uuid;
  v_lines jsonb;
  v_line jsonb;
  v_item_id uuid;
  v_quantity numeric;
  v_unit_price numeric;
  v_tax_rate numeric;
  v_net numeric;
  v_tax numeric;
  v_total numeric;
  v_net_total numeric := 0;
  v_tax_total numeric := 0;
  v_grand_total numeric := 0;
  v_line_no integer := 0;
  v_office_id uuid;
  v_order_id uuid;
  v_order_number text;
begin
  if p_action not in ('create','update','issue','cancel','create_inbound') then raise exception 'WMS400: Unsupported purchase order action.'; end if;
  if p_action in ('update','issue','cancel','create_inbound') then
    select * into v_po from public."WMS_PurchaseOrders" where "WMSPO_ID"=p_purchase_order_id and not "WMSPO_IsDeleted" for update;
    if not found or not coalesce(v_po."WMSPO_FacilityID"=any(p_allowed_facility_ids),false) then raise exception 'WMS404: Purchase order not found.'; end if;
  end if;

  if p_action in ('create','update') then
    if p_action='update' and (v_po."WMSPO_StatusCode" not in ('draft','issued') or v_po."WMSPO_WarehouseOrderID" is not null) then raise exception 'WMS409: This purchase order can no longer be edited.'; end if;
    v_facility_id := nullif(p_payload->>'facilityId','')::uuid;
    v_customer_org_id := nullif(p_payload->>'customerOrgId','')::uuid;
    v_supplier_org_id := nullif(p_payload->>'supplierOrgId','')::uuid;
    if v_facility_id is null or not coalesce(v_facility_id=any(p_allowed_facility_ids),false) then raise exception 'WMS403: Choose a warehouse in your company.'; end if;
    if v_customer_org_id is null or not exists(select 1 from public."Org_Master" where "Org_id"=v_customer_org_id) then raise exception 'WMS400: Choose the stock owner.'; end if;
    if coalesce(nullif(btrim(p_payload->>'number'),''),'')='' then raise exception 'WMS400: Enter a purchase order number.'; end if;
    if upper(coalesce(nullif(btrim(p_payload->>'currencyCode'),''),'GBP')) !~ '^[A-Z]{3}$' then raise exception 'WMS400: Enter a three-letter currency code.'; end if;
    v_lines := p_payload->'lines';
    if v_lines is null or jsonb_typeof(v_lines) is distinct from 'array' or jsonb_array_length(v_lines)=0 then raise exception 'WMS400: Add at least one purchase order line.'; end if;

    if p_action='create' then
      insert into public."WMS_PurchaseOrders" (
        "WMSPO_ID","WMSPO_FacilityID","WMSPO_CustomerOrgID","WMSPO_SupplierOrgID","WMSPO_Number","WMSPO_StatusCode","WMSPO_SupplierName",
        "WMSPO_BuyerReference","WMSPO_SupplierReference","WMSPO_IssueDate","WMSPO_ExpectedDeliveryDate","WMSPO_CurrencyCode","WMSPO_DeliveryTerms",
        "WMSPO_PaymentTerms","WMSPO_DeliveryAddress","WMSPO_Notes","WMSPO_SourceFileName","WMSPO_ExtractionModeCode","WMSPO_ExtractionModel",
        "WMSPO_ExtractionMetadataJSON","WMSPO_CreatedBy","WMSPO_UpdatedBy"
      ) values (
        v_id,v_facility_id,v_customer_org_id,v_supplier_org_id,left(btrim(p_payload->>'number'),120),'draft',left(coalesce(btrim(p_payload->>'supplierName'),''),240),
        nullif(left(btrim(p_payload->>'buyerReference'),160),''),nullif(left(btrim(p_payload->>'supplierReference'),160),''),nullif(p_payload->>'issueDate','')::date,
        nullif(p_payload->>'expectedDeliveryDate','')::date,upper(coalesce(nullif(btrim(p_payload->>'currencyCode'),''),'GBP')),nullif(left(btrim(p_payload->>'deliveryTerms'),180),''),
        nullif(left(btrim(p_payload->>'paymentTerms'),180),''),nullif(btrim(p_payload->>'deliveryAddress'),''),nullif(btrim(p_payload->>'notes'),''),
        nullif(left(btrim(p_payload->>'sourceFileName'),240),''),nullif(left(btrim(p_payload->>'extractionMode'),40),''),nullif(left(btrim(p_payload->>'extractionModel'),120),''),
        coalesce(p_payload->'extractionMetadata','{}'::jsonb),p_actor_user_id,p_actor_user_id
      );
    else
      v_id := p_purchase_order_id;
      update public."WMS_PurchaseOrders" set
        "WMSPO_FacilityID"=v_facility_id,"WMSPO_CustomerOrgID"=v_customer_org_id,"WMSPO_SupplierOrgID"=v_supplier_org_id,
        "WMSPO_Number"=left(btrim(p_payload->>'number'),120),"WMSPO_SupplierName"=left(coalesce(btrim(p_payload->>'supplierName'),''),240),
        "WMSPO_BuyerReference"=nullif(left(btrim(p_payload->>'buyerReference'),160),''),"WMSPO_SupplierReference"=nullif(left(btrim(p_payload->>'supplierReference'),160),''),
        "WMSPO_IssueDate"=nullif(p_payload->>'issueDate','')::date,"WMSPO_ExpectedDeliveryDate"=nullif(p_payload->>'expectedDeliveryDate','')::date,
        "WMSPO_CurrencyCode"=upper(coalesce(nullif(btrim(p_payload->>'currencyCode'),''),'GBP')),"WMSPO_DeliveryTerms"=nullif(left(btrim(p_payload->>'deliveryTerms'),180),''),
        "WMSPO_PaymentTerms"=nullif(left(btrim(p_payload->>'paymentTerms'),180),''),"WMSPO_DeliveryAddress"=nullif(btrim(p_payload->>'deliveryAddress'),''),
        "WMSPO_Notes"=nullif(btrim(p_payload->>'notes'),''),"WMSPO_SourceFileName"=coalesce(nullif(left(btrim(p_payload->>'sourceFileName'),240),''),"WMSPO_SourceFileName"),
        "WMSPO_ExtractionModeCode"=coalesce(nullif(left(btrim(p_payload->>'extractionMode'),40),''),"WMSPO_ExtractionModeCode"),
        "WMSPO_ExtractionModel"=coalesce(nullif(left(btrim(p_payload->>'extractionModel'),120),''),"WMSPO_ExtractionModel"),
        "WMSPO_ExtractionMetadataJSON"=coalesce(p_payload->'extractionMetadata',"WMSPO_ExtractionMetadataJSON"),
        "WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id
      where "WMSPO_ID"=v_id;
      delete from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_id;
    end if;

    for v_line in select value from jsonb_array_elements(v_lines) loop
      v_line_no := v_line_no+1;
      v_item_id := nullif(v_line->>'itemId','')::uuid;
      if v_item_id is not null and not exists(select 1 from public."WMS_Items" where "WMSItem_ID"=v_item_id and "WMSItem_DefaultFacilityID"=v_facility_id and "WMSItem_CustomerOrgID"=v_customer_org_id and not "WMSItem_IsDeleted") then raise exception 'WMS400: A purchase order line uses an item outside this warehouse or stock owner.'; end if;
      v_quantity := coalesce(nullif(v_line->>'quantity','')::numeric,0);
      v_unit_price := greatest(coalesce(nullif(v_line->>'unitPrice','')::numeric,0),0);
      v_tax_rate := greatest(coalesce(nullif(v_line->>'taxRate','')::numeric,0),0);
      if v_quantity<=0 or coalesce(nullif(btrim(v_line->>'description'),''),'')='' or coalesce(nullif(btrim(v_line->>'uomCode'),''),'')='' then raise exception 'WMS400: Every line needs a description, quantity above zero and unit of measure.'; end if;
      v_net := round(v_quantity*v_unit_price,4); v_tax := round(v_net*v_tax_rate/100,4); v_total := v_net+v_tax;
      v_net_total := v_net_total+v_net; v_tax_total := v_tax_total+v_tax; v_grand_total := v_grand_total+v_total;
      insert into public."WMS_PurchaseOrderLines" (
        "WMSPOLine_PurchaseOrderID","WMSPOLine_LineNo","WMSPOLine_ItemID","WMSPOLine_SKU","WMSPOLine_SupplierItemCode","WMSPOLine_Description",
        "WMSPOLine_OrderedQuantity","WMSPOLine_UOMCode","WMSPOLine_UnitPrice","WMSPOLine_TaxRate","WMSPOLine_NetAmount","WMSPOLine_TaxAmount",
        "WMSPOLine_TotalAmount","WMSPOLine_RequestedDeliveryDate","WMSPOLine_MetadataJSON"
      ) values (
        v_id,v_line_no,v_item_id,nullif(left(btrim(v_line->>'sku'),120),''),nullif(left(btrim(v_line->>'supplierItemCode'),120),''),left(btrim(v_line->>'description'),800),
        v_quantity,upper(coalesce(nullif(btrim(v_line->>'uomCode'),''),'EA')),v_unit_price,v_tax_rate,v_net,v_tax,v_total,
        nullif(v_line->>'requestedDeliveryDate','')::date,coalesce(v_line->'metadata','{}'::jsonb)
      );
    end loop;
    update public."WMS_PurchaseOrders" set "WMSPO_NetAmount"=v_net_total,"WMSPO_TaxAmount"=v_tax_total,"WMSPO_TotalAmount"=v_grand_total where "WMSPO_ID"=v_id;
    insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_ToStatusCode","WMSPOEvent_MetadataJSON","WMSPOEvent_CreatedBy")
      values(v_id,case when p_action='create' then 'created' else 'updated' end,coalesce(v_po."WMSPO_StatusCode",'draft'),jsonb_build_object('lineCount',v_line_no,'sourceFileName',p_payload->>'sourceFileName'),p_actor_user_id);
    return v_id;
  end if;

  if p_action='issue' then
    if v_po."WMSPO_StatusCode"<>'draft' then raise exception 'WMS409: Only a draft purchase order can be issued.'; end if;
    if exists(select 1 from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_po."WMSPO_ID" and "WMSPOLine_ItemID" is null) then raise exception 'WMS409: Match every line to a warehouse item before issuing.'; end if;
    update public."WMS_PurchaseOrders" set "WMSPO_StatusCode"='issued',"WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id where "WMSPO_ID"=v_po."WMSPO_ID";
    insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_FromStatusCode","WMSPOEvent_ToStatusCode","WMSPOEvent_Notes","WMSPOEvent_CreatedBy") values(v_po."WMSPO_ID",'issued',v_po."WMSPO_StatusCode",'issued',nullif(btrim(p_payload->>'notes'),''),p_actor_user_id);
    return v_po."WMSPO_ID";
  end if;

  if p_action='cancel' then
    if v_po."WMSPO_StatusCode" in ('received','cancelled') or v_po."WMSPO_WarehouseOrderID" is not null then raise exception 'WMS409: This purchase order cannot be cancelled.'; end if;
    update public."WMS_PurchaseOrders" set "WMSPO_StatusCode"='cancelled',"WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id where "WMSPO_ID"=v_po."WMSPO_ID";
    insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_FromStatusCode","WMSPOEvent_ToStatusCode","WMSPOEvent_Notes","WMSPOEvent_CreatedBy") values(v_po."WMSPO_ID",'cancelled',v_po."WMSPO_StatusCode",'cancelled',nullif(btrim(p_payload->>'notes'),''),p_actor_user_id);
    return v_po."WMSPO_ID";
  end if;

  if v_po."WMSPO_StatusCode"<>'issued' or v_po."WMSPO_WarehouseOrderID" is not null then raise exception 'WMS409: This purchase order is not ready for a new goods-in order.'; end if;
  if exists(select 1 from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_po."WMSPO_ID" and "WMSPOLine_ItemID" is null) then raise exception 'WMS409: Match every line to a warehouse item before creating goods-in work.'; end if;
  select "WMSFacility_OrgOfficeID" into v_office_id from public."WMS_Facilities" where "WMSFacility_ID"=v_po."WMSPO_FacilityID";
  v_order_id := gen_random_uuid(); v_order_number := left('PO-'||v_po."WMSPO_Number",80);
  if exists(select 1 from public."WMS_Orders" where "WMSOrder_FacilityID"=v_po."WMSPO_FacilityID" and lower("WMSOrder_OrderNumber")=lower(v_order_number) and not "WMSOrder_IsDeleted") then v_order_number:=left(v_order_number||'-'||substr(v_order_id::text,1,6),80); end if;
  insert into public."WMS_Orders" ("WMSOrder_ID","WMSOrder_FacilityID","WMSOrder_OrgOfficeID","WMSOrder_CustomerOrgID","WMSOrder_OrderNumber","WMSOrder_TypeCode","WMSOrder_StatusCode","WMSOrder_CustomerReference","WMSOrder_SupplierReference","WMSOrder_InboundFromOrgID","WMSOrder_RequestedDate","WMSOrder_Instructions","WMSOrder_MetadataJSON","WMSOrder_CreatedBy","WMSOrder_UpdatedBy")
    values(v_order_id,v_po."WMSPO_FacilityID",v_office_id,v_po."WMSPO_CustomerOrgID",v_order_number,'inbound','draft',v_po."WMSPO_BuyerReference",v_po."WMSPO_SupplierReference",v_po."WMSPO_SupplierOrgID",v_po."WMSPO_ExpectedDeliveryDate",v_po."WMSPO_Notes",jsonb_build_object('purchaseOrderId',v_po."WMSPO_ID",'purchaseOrderNumber',v_po."WMSPO_Number"),p_actor_user_id,p_actor_user_id);
  insert into public."WMS_OrderLines" ("WMSOrderLine_OrderID","WMSOrderLine_LineNo","WMSOrderLine_ItemID","WMSOrderLine_OrderedQuantity","WMSOrderLine_UOMCode","WMSOrderLine_GoodsValue","WMSOrderLine_CurrencyCode","WMSOrderLine_Instructions","WMSOrderLine_MetadataJSON")
    select v_order_id,"WMSPOLine_LineNo","WMSPOLine_ItemID","WMSPOLine_OrderedQuantity","WMSPOLine_UOMCode","WMSPOLine_NetAmount",v_po."WMSPO_CurrencyCode","WMSPOLine_Description",jsonb_build_object('purchaseOrderLineId',"WMSPOLine_ID") from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_po."WMSPO_ID" order by "WMSPOLine_LineNo";
  update public."WMS_PurchaseOrders" set "WMSPO_WarehouseOrderID"=v_order_id,"WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id where "WMSPO_ID"=v_po."WMSPO_ID";
  insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_ToStatusCode","WMSPOEvent_MetadataJSON","WMSPOEvent_CreatedBy") values(v_po."WMSPO_ID",'goods_in_created','issued',jsonb_build_object('warehouseOrderId',v_order_id,'warehouseOrderNumber',v_order_number),p_actor_user_id);
  return v_po."WMSPO_ID";
exception when others then
  if sqlerrm like 'WMS%' then raise; end if;
  if sqlstate='23505' then raise exception 'WMS409: A purchase order with this number already exists in the warehouse.'; end if;
  raise exception 'WMS500: %',sqlerrm;
end; $$;

revoke all on function public.warehouse_edge_purchase_order_mutation(text,uuid,jsonb,uuid,uuid[]) from public,anon,authenticated;
grant execute on function public.warehouse_edge_purchase_order_mutation(text,uuid,jsonb,uuid,uuid[]) to service_role;

create or replace function public._warehouse_sync_purchase_order_receipt()
returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_line_id uuid; v_po_id uuid; v_previous text; v_next text;
begin
  if new."WMSOrderLine_MetadataJSON"->>'purchaseOrderLineId' is null then return new; end if;
  v_line_id := (new."WMSOrderLine_MetadataJSON"->>'purchaseOrderLineId')::uuid;
  update public."WMS_PurchaseOrderLines" set "WMSPOLine_ReceivedQuantity"=least("WMSPOLine_OrderedQuantity",new."WMSOrderLine_ReceivedQuantity") where "WMSPOLine_ID"=v_line_id returning "WMSPOLine_PurchaseOrderID" into v_po_id;
  if v_po_id is null then return new; end if;
  select "WMSPO_StatusCode" into v_previous from public."WMS_PurchaseOrders" where "WMSPO_ID"=v_po_id for update;
  select case when bool_and("WMSPOLine_ReceivedQuantity">="WMSPOLine_OrderedQuantity") then 'received' when sum("WMSPOLine_ReceivedQuantity")>0 then 'part_received' else v_previous end into v_next from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_po_id;
  if v_next is distinct from v_previous then
    update public."WMS_PurchaseOrders" set "WMSPO_StatusCode"=v_next,"WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now() where "WMSPO_ID"=v_po_id;
    insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_FromStatusCode","WMSPOEvent_ToStatusCode","WMSPOEvent_MetadataJSON") values(v_po_id,'receipt_progress',v_previous,v_next,jsonb_build_object('warehouseOrderLineId',new."WMSOrderLine_ID",'receivedQuantity',new."WMSOrderLine_ReceivedQuantity"));
  end if;
  return new;
end; $$;
drop trigger if exists "TR_WMS_OrderLines_purchase_order_receipt" on public."WMS_OrderLines";
create trigger "TR_WMS_OrderLines_purchase_order_receipt" after update of "WMSOrderLine_ReceivedQuantity" on public."WMS_OrderLines" for each row when (old."WMSOrderLine_ReceivedQuantity" is distinct from new."WMSOrderLine_ReceivedQuantity") execute function public._warehouse_sync_purchase_order_receipt();
revoke all on function public._warehouse_sync_purchase_order_receipt() from public,anon,authenticated;

create or replace function public._multideck_dexter_watch_purchase_order_change()
returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_company_id uuid; v_old jsonb:='{}'::jsonb; v_new jsonb:='{}'::jsonb;
begin
  select office."Company_ID" into v_company_id from public."WMS_Facilities" facility join public."cmp_Offices" office on office."Office_ID"=facility."WMSFacility_OrgOfficeID" where facility."WMSFacility_ID"=new."WMSPO_FacilityID";
  if tg_op='UPDATE' then v_old:=jsonb_build_object('status',old."WMSPO_StatusCode",'totalAmount',old."WMSPO_TotalAmount",'expectedDeliveryDate',old."WMSPO_ExpectedDeliveryDate"); end if;
  v_new:=jsonb_build_object('purchaseOrderNumber',new."WMSPO_Number",'supplierName',new."WMSPO_SupplierName",'status',new."WMSPO_StatusCode",'totalAmount',new."WMSPO_TotalAmount",'currency',new."WMSPO_CurrencyCode",'expectedDeliveryDate',new."WMSPO_ExpectedDeliveryDate",'warehouseOrderId',new."WMSPO_WarehouseOrderID");
  if v_company_id is not null and exists(select 1 from public."AI_DexterWatches" watch where watch."AIDexterWatch_CompanyID"=v_company_id and watch."AIDexterWatch_CapabilityCode"='purchase_orders' and watch."AIDexterWatch_StatusCode"='active' and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID"=new."WMSPO_ID")) then
    insert into public."AI_DexterWatchSignals" ("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON") values(v_company_id,'purchase_orders','WMS_PurchaseOrders',new."WMSPO_ID",v_old,v_new);
  end if;
  return new;
end; $$;
drop trigger if exists "TR_WMS_PurchaseOrders_dexter_watch" on public."WMS_PurchaseOrders";
create trigger "TR_WMS_PurchaseOrders_dexter_watch" after insert or update on public."WMS_PurchaseOrders" for each row execute function public._multideck_dexter_watch_purchase_order_change();
revoke all on function public._multideck_dexter_watch_purchase_order_change() from public,anon,authenticated;

insert into public."sys_AIDexterWatchCapabilities" ("AIDexterWatchCapability_Code","AIDexterWatchCapability_Name","AIDexterWatchCapability_Description","AIDexterWatchCapability_FieldsJSON","AIDexterWatchCapability_IsActive","AIDexterWatchCapability_SortOrder") values
('purchase_orders','Purchase orders','Purchase order status, supplier, value, expected delivery and linked goods-in changes.','["status","purchaseOrderNumber","supplierName","totalAmount","currency","expectedDeliveryDate","warehouseOrderId"]'::jsonb,true,45)
on conflict ("AIDexterWatchCapability_Code") do update set "AIDexterWatchCapability_Name"=excluded."AIDexterWatchCapability_Name","AIDexterWatchCapability_Description"=excluded."AIDexterWatchCapability_Description","AIDexterWatchCapability_FieldsJSON"=excluded."AIDexterWatchCapability_FieldsJSON","AIDexterWatchCapability_IsActive"=true,"AIDexterWatchCapability_SortOrder"=excluded."AIDexterWatchCapability_SortOrder";

create or replace function public.multideck_dexter_domain_purchase_orders(p_user_id uuid,p_search text default null,p_take integer default 10)
returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
with actor as (select "Company_ID" company_id from public."cmp_Users" where "User_ID"=p_user_id), facilities as (
  select facility."WMSFacility_ID" from public."WMS_Facilities" facility join public."cmp_Offices" office on office."Office_ID"=facility."WMSFacility_OrgOfficeID" join actor on actor.company_id=office."Company_ID" where not facility."WMSFacility_IsDeleted"
), rows as (
  select po.*,facility."WMSFacility_Code",customer."Org_Name" customer_name,
    (select jsonb_agg(jsonb_build_object('recordId',line."WMSPOLine_ID",'lineNumber',line."WMSPOLine_LineNo",'itemId',line."WMSPOLine_ItemID",'sku',line."WMSPOLine_SKU",'description',line."WMSPOLine_Description",'quantity',line."WMSPOLine_OrderedQuantity",'receivedQuantity',line."WMSPOLine_ReceivedQuantity",'uom',line."WMSPOLine_UOMCode",'unitPrice',line."WMSPOLine_UnitPrice",'totalAmount',line."WMSPOLine_TotalAmount") order by line."WMSPOLine_LineNo") from public."WMS_PurchaseOrderLines" line where line."WMSPOLine_PurchaseOrderID"=po."WMSPO_ID") lines
  from public."WMS_PurchaseOrders" po join facilities f on f."WMSFacility_ID"=po."WMSPO_FacilityID" join public."WMS_Facilities" facility on facility."WMSFacility_ID"=po."WMSPO_FacilityID" join public."Org_Master" customer on customer."Org_id"=po."WMSPO_CustomerOrgID"
  where not po."WMSPO_IsDeleted" and (coalesce(btrim(p_search),'')='' or concat_ws(' ',po."WMSPO_Number",po."WMSPO_SupplierName",po."WMSPO_BuyerReference",po."WMSPO_SupplierReference") ilike '%'||btrim(p_search)||'%') order by po."WMSPO_UpdatedAt" desc limit greatest(1,least(coalesce(p_take,10),25))
)
select coalesce(jsonb_agg(jsonb_build_object('recordId',"WMSPO_ID",'facilityId',"WMSPO_FacilityID",'facilityCode',"WMSFacility_Code",'customerOrgId',"WMSPO_CustomerOrgID",'customerName',customer_name,'purchaseOrderNumber',"WMSPO_Number",'supplierName',"WMSPO_SupplierName",'status',"WMSPO_StatusCode",'issueDate',"WMSPO_IssueDate",'expectedDeliveryDate',"WMSPO_ExpectedDeliveryDate",'currency',"WMSPO_CurrencyCode",'netAmount',"WMSPO_NetAmount",'taxAmount',"WMSPO_TaxAmount",'totalAmount',"WMSPO_TotalAmount",'warehouseOrderId',"WMSPO_WarehouseOrderID",'lines',coalesce(lines,'[]'::jsonb),'source',jsonb_build_object('table','WMS_PurchaseOrders','id',"WMSPO_ID",'observedAt',"WMSPO_UpdatedAt"))),'[]'::jsonb) from rows;
$$;
revoke all on function public.multideck_dexter_domain_purchase_orders(uuid,text,integer) from public,anon,authenticated;

